window.WPS = window.WPS || {};
WPS.TB_PAGES = WPS.TB_PAGES || {};
(function (P) { for (var k in P) WPS.TB_PAGES[k] = P[k]; })({"y_bc30": {"title": "前3000〜前1000年の世界", "span": "前3000年ごろ〜前1000年ごろ", "year": -1500, "lead": "大河の流域で農耕が発達し、メソポタミア・エジプト・インダス・中国に都市と国家が生まれた時代です。前2千年紀には馬と戦車、のちに鉄器を持つ人々が移動し、各地の国家の興亡を大きく動かしました。", "flow": ["前3000年ごろ メソポタミア南部でシュメール人の都市国家が発展→楔形文字が生まれる", "前3000年ごろ エジプトで上下エジプトが統一→ファラオによる統一国家", "前2600年ごろ インダス川流域でハラッパー・モエンジョ=ダーロなどの都市が栄える(インダス文明)", "前24世紀ごろ アッカド人のサルゴン1世がメソポタミアを統一", "前18世紀 バビロン第1王朝のハンムラビ王がメソポタミアを統一→ハンムラビ法典", "前17世紀ごろ 小アジアにヒッタイトが成立→鉄器と戦車で強大化し、のちバビロン第1王朝を滅ぼす", "前16世紀ごろ 中国で殷が栄える→甲骨文字による神権政治", "前16世紀 エジプト新王国が成立→前14世紀にアメンホテプ4世がアトン信仰の改革", "前1500年ごろ アーリヤ人が西北インドのパンジャーブ地方に進入→『リグ=ヴェーダ』", "前1200年ごろ 東地中海で「海の民」の活動→ヒッタイト滅亡・ミケーネ文明崩壊、鉄器が広まる", "前11世紀ごろ 周が殷を滅ぼす→封建制による支配"], "sync": [["西アジア", "シュメール人の都市国家→アッカド→バビロン第1王朝(ハンムラビ法典)→ヒッタイト・カッシート・ミタンニの分立"], ["エジプト", "統一王国の成立→古王国(ピラミッド)・中王国・ヒクソスの侵入・新王国(アマルナ改革・ラメセス2世)"], ["地中海", "クレタ文明(クノッソス)→ミケーネ文明(線文字B)→前1200年ごろ崩壊し暗黒時代へ"], ["南アジア", "インダス文明(ハラッパー・モエンジョ=ダーロ)→衰退→アーリヤ人の進入と『リグ=ヴェーダ』"], ["東アジア", "黄河流域の仰韶文化・竜山文化、長江流域の稲作→殷の成立→周による征服"], ["アメリカ", "メキシコ湾岸にオルメカ文明、アンデスにチャビン文化が現れる"]], "secs": [{"t": "文明の誕生:なぜ大河のほとりだったのか", "p": ["人類は長いあいだ狩猟・採集の生活を送っていましたが、西アジアでは早くからムギの栽培とヤギ・ヒツジなどの家畜の飼育が始まりました。この【農耕・牧畜の開始】によって食料を計画的に生産できるようになり、人々は定住して村をつくりました。道具も、打ち欠いてつくる打製石器から、磨いてつくる【磨製石器】へと変わっていきます。この変化は【新石器時代】の始まりとして説明されます。", "はじめの農耕は雨に頼る天水農業でしたが、やがて大河の水を引いて畑に流す【灌漑農業】が始まると、収穫は大きく増えました。灌漑には大勢の人を動員して水路をつくり、水を分ける仕組みが必要です。そのため人々をまとめる指導者や神官が力を持ち、余った食料をたくわえる神殿や倉庫を中心に【都市】が生まれました。記録のための【文字】、農作業の時期を知るための【暦】、武器や祭器のための【青銅器】も、この都市の中で発達します。", "こうして前3000年ごろから、メソポタミア(ティグリス川・ユーフラテス川)、エジプト(ナイル川)、インド(インダス川)、中国(黄河・長江)の流域に、ほぼ並行して都市文明が成立しました。地域ごとに文字や信仰は違いますが、「灌漑→余剰生産→身分の分化→都市と国家→文字と暦」という流れは共通しています。横の教科書では、この共通点と違いを意識して読んでいきましょう。"]}, {"t": "西アジア:開かれた土地メソポタミアの興亡", "p": ["メソポタミア南部では、前3000年ごろまでに【シュメール人】がウル・ウルクなどの【都市国家】を築きました。中心には【ジッグラト】とよばれる聖塔をそなえた神殿があり、王は神の代理として政治を行いました(神権政治)。シュメール人は粘土板に葦のペンで刻む【楔形文字】を生み出し、【六十進法】や月の満ち欠けにもとづく【太陰暦】を用いました。", "メソポタミアは周囲を山や砂漠に囲まれておらず、外から民族が入りやすい「開かれた」土地でした。そのため支配者がたびたび入れかわります。前24世紀ごろにはセム語系の【アッカド人】が【サルゴン1世】のもとで初めてメソポタミアを統一し、ついで前18世紀にはアムル人の【バビロン第1王朝】(古バビロニア)が【ハンムラビ王】のもとで全メソポタミアを支配しました。ハンムラビ王は【ハンムラビ法典】を定め、「目には目を、歯には歯を」で知られる【同害復讐法】の原則を示しました。ただし刑罰は身分によって差があり、王が法によって広い領域を治めようとした点が重要です。", "前2千年紀に入ると、北方から【インド=ヨーロッパ語系】の人々が移動してきます。小アジア(アナトリア)の【ヒッタイト】は、早くから【鉄器】を用い、馬に引かせる戦車を駆使して強大となり、前16世紀初めにバビロン第1王朝を滅ぼしました。その後のメソポタミアでは【カッシート】がバビロニアを、【ミタンニ】が北メソポタミアを支配し、ヒッタイトやエジプトと並んで国々が勢力を争う時代になります。この「列強の並び立つオリエント」が、前2千年紀後半の西アジアの姿です。"]}, {"t": "エジプト:ナイルの恵みと長く続いた王国", "p": ["ギリシアの歴史家【ヘロドトス】が「【エジプトはナイルの賜物】」と表現したように、エジプトでは毎年のナイル川の増水が肥えた土を運び、豊かな農業を支えました。増水の時期を正確に知る必要から、1年を365日とする【太陽暦】が生まれ、増水後に畑の境界を測り直すために【測地術】が発達しました。", "前3000年ごろに上エジプトと下エジプトが統一され、王【ファラオ】は生ける神として君臨しました。エジプトは砂漠と海に守られた「閉じた」地形のため、メソポタミアに比べて外敵の侵入が少なく、同じ性格の王国が長く続きます。都を【メンフィス】においた【古王国】の時代には、【クフ王】などの巨大な【ピラミッド】がつくられ、王の強大な権力を示しました。ついで都を【テーベ】に移した【中王国】の時代を経て、前17世紀ごろにはシリア方面から【ヒクソス】が侵入し、一時下エジプトを支配しました。", "ヒクソスを追い出して成立した【新王国】は、シリア方面へ積極的に進出し、ヒッタイトなどと争う大国になりました。前14世紀の【アメンホテプ4世】は、テーベの【アモン】神官団の力をおさえるため、唯一神【アトン】の信仰を強制し、都を【テル=エル=アマルナ】に移しました。このとき写実的な【アマルナ美術】が生まれます。しかし改革は王の死後に否定され、もとのアモン信仰にもどりました。のちの【ラメセス2世】はシリアをめぐってヒッタイトと戦い、和平を結んだことで知られます。", "エジプト人は霊魂の不滅を信じ、死後の世界への案内書である【死者の書】を残しました。文字は碑文などに使う【神聖文字(ヒエログリフ)】と、その簡略体である【民用文字(デモティック)】があり、【パピルス】に記されました。神聖文字は、19世紀にフランスの【シャンポリオン】が【ロゼッタ=ストーン】を手がかりに解読しました。"]}, {"t": "地中海:エーゲ文明の盛衰", "p": ["エーゲ海の周辺では、前2000年ごろから【エーゲ文明】とよばれる青銅器文明が栄えました。その前半を代表するのがクレタ島の【クレタ文明(ミノア文明)】です。中心の【クノッソス宮殿】は城壁を持たない開放的なつくりで、海の生き物を描いた明るい壁画が残っています。クノッソスを発掘したのはイギリスの【エヴァンズ】です。", "前16世紀ごろからは、ギリシア本土で、南下してきたギリシア人による【ミケーネ文明】が栄えました。ミケーネやティリンスには巨石を積んだ城壁があり、戦いを重視した性格がうかがえます。ミケーネ文明はクレタ島にも進出しました。その遺跡を発掘したのはドイツの【シュリーマン】で、トロイアの発掘でも知られます。ミケーネ文明の文字である【線文字B】は、イギリスの【ヴェントリス】によって解読され、ギリシア語を記したものであることがわかりました。", "ところが前1200年ごろ、ミケーネ文明の諸王国は急速に崩壊します。原因ははっきりしませんが、東地中海全体をおそった混乱、とくに【海の民】とよばれる集団の活動が関係していると考えられています。こののちギリシアは文字の記録がとだえる【暗黒時代】に入り、やがて前8世紀に【ポリス】が誕生する新しい段階へと進みます。"]}, {"t": "南アジア:インダス文明とアーリヤ人の到来", "p": ["インダス川の流域では、前2600年ごろから【インダス文明】が栄えました。代表的な都市は、インダス川中流の【ハラッパー】と下流の【モエンジョ=ダーロ】です。都市は碁盤目状の道路で区画され、焼きれんがの家や排水溝、大浴場などがそなわっており、計画的に建設されていたことがわかります。動物などを刻んだ【印章】には【インダス文字】が記されていますが、まだ解読されていません。", "インダス文明の印章はメソポタミアでも見つかっており、両地域のあいだに海を通じた交易があったと考えられます。しかしインダス文明は前1800年ごろまでに衰退しました。その理由は、河川の流路の変化や環境の悪化などがあげられていますが、はっきりとはわかっていません。", "前1500年ごろ、中央アジア方面からインド=ヨーロッパ語系の【アーリヤ人】が、カイバル峠を越えて西北インドの【パンジャーブ地方】に進入しました。彼らは牧畜を中心に生活し、雷や火などの自然を神々として崇拝しました。神々への賛歌をまとめたのが最古の文献【『リグ=ヴェーダ』】です。前1000年ごろになると、アーリヤ人は東方の【ガンジス川】流域へと移動し、鉄器を使って森林を切り開き、農耕社会を築いていきます。このときに生まれた身分制度【ヴァルナ制】や【バラモン教】については、次のページで扱います。"]}, {"t": "東アジア:黄河・長江の文明と殷・周", "p": ["中国では、黄河の中流域で、赤や黒の文様を描いた彩陶(彩文土器)で知られる【仰韶文化】が栄え、のちに黄河下流域を中心に、薄く黒光りする黒陶を特色とする【竜山文化】が広がりました。華北では主にアワ・キビが栽培されました。一方、長江の下流域では【河姆渡遺跡】などから古い稲作の跡が見つかっており、中国の文明が黄河流域だけでなく、長江流域にも広く根をもっていたことがわかってきました。", "前16世紀ごろ、黄河中流域に【殷(商)】が成立しました。殷の後期の都の跡は【殷墟】とよばれ、20世紀に発掘されました。殷王は、亀の甲や牛の骨を焼いてできたひび割れで神意をうかがう占いを行い、その結果を【甲骨文字】で刻みました。甲骨文字は現在の漢字の祖先にあたります。政治の重要事項を占いで決めるこのやり方は【神権政治】とよばれます。殷では祭祀に用いる精巧な【青銅器】も多くつくられました。", "前11世紀ごろ、渭水流域から起こった【周】が殷を滅ぼし、都を【鎬京】におきました。周王は一族や功臣に領地を与えて【諸侯】とし、そのかわりに軍役や貢納を義務づけました。これが周の【封建】で、血縁にもとづく【宗法】によって一族の結びつきを保ちました。ヨーロッパ中世の封建制が契約にもとづくのに対し、周の封建は血縁を基礎にしている点が対比のポイントです。"]}, {"t": "アメリカとアフリカ:独自に生まれた文明", "p": ["アメリカ大陸は、ユーラシアとは切りはなされた環境のなかで独自に文明を生み出しました。主食となったのは【トウモロコシ】やジャガイモで、牛や馬のような大型の家畜はいませんでした。前1200年ごろ、メキシコ湾岸には【オルメカ文明】が成立し、巨大な石の頭像や、ジャガーを信仰の対象とする文化を残しました。オルメカ文明は、のちのマヤ文明やテオティワカン文明など【メソアメリカ文明】の源流とされます。", "南アメリカのアンデス地方でも、前1000年ごろには【チャビン文化】が現れ、神殿を中心とした宗教文化が広がりました。アンデスの文明は、のちのインカ帝国につながる長い歴史の出発点にあたります。", "アフリカでは、ナイル川上流のヌビア地方に、エジプトの影響を受けた【クシュ王国】が成立し、のちにエジプトを支配するほどの力を持ちました。サハラ以南の各地では、農耕や牧畜がしだいに広がっていきました。"]}, {"t": "世界のつながり:馬・戦車・鉄器と民族移動", "p": ["この時代を横に見たとき、各地をつなぐ共通の動きとして、まず【青銅器】の普及があげられます。青銅は銅とすずの合金で、原料を遠くから運ぶ必要があったため、交易のネットワークを広げるきっかけになりました。インダスの印章がメソポタミアで見つかることも、そのあらわれです。", "次に重要なのが、前2千年紀の【民族移動】です。馬に引かせる【戦車】を持つ人々が、ユーラシアの各地で移動と征服をくり返しました。小アジアのヒッタイト、インドのアーリヤ人、ギリシア本土のギリシア人は、いずれも【インド=ヨーロッパ語系】の人々です。エジプトに侵入したヒクソスも馬と戦車をもたらしたとされます。このように、ユーラシア西部から南アジアにかけて、ほぼ同じころに新しい集団が古い文明の地に入りこんだことは、横の視点で押さえておきたい点です。", "そして前1200年ごろ、東地中海は大きな転換期を迎えます。「海の民」の活動のなかでヒッタイトが滅び、ミケーネ文明も崩壊しました。エジプト新王国も衰えに向かいます。ヒッタイトが独占していたとされる【製鉄技術】は、この混乱をきっかけに各地へ広まり、オリエントは青銅器時代から【鉄器時代】へと移っていきました。強大な国家がいったん後退したすきまに、シリア・パレスチナでは【アラム人】【フェニキア人】【ヘブライ人】など小さな民族が活躍するようになります。同じころ中国でも殷から周への王朝交代が起こっており、前1000年前後は、東西で新しい秩序が生まれる時期だったといえます。"]}], "points": ["シュメール人の都市国家・楔形文字・六十進法・太陰暦はセットで覚える", "ハンムラビ法典は同害復讐法だが、身分によって刑罰が異なる", "エジプトの太陽暦・測地術はナイル川の増水と結びつけて理解する", "アメンホテプ4世はアモン神官団に対抗してアトン一神教を強制し、テル=エル=アマルナに遷都した", "クレタ文明=エヴァンズ、ミケーネ文明=シュリーマン、線文字B=ヴェントリスの組み合わせ", "インダス文字は未解読、甲骨文字は漢字の祖先、神聖文字はシャンポリオンが解読", "ヒッタイトは鉄器を早くから使用し、その滅亡後に製鉄技術が広まった", "周の封建は血縁(宗法)にもとづき、ヨーロッパの封建制は契約にもとづく"], "check": [["メソポタミアで初めて統一国家を築いたアッカド人の王は?", "サルゴン1世"], ["「目には目を、歯には歯を」で知られる法典を定めた王は?", "ハンムラビ王"], ["小アジアに国を建て、早くから鉄器を用いた民族は?", "ヒッタイト"], ["アトン信仰を強制し、テル=エル=アマルナに都を移したエジプトの王は?", "アメンホテプ4世"], ["ミケーネ文明の文字で、ヴェントリスが解読したものは?", "線文字B"], ["インダス文明の都市で、インダス川下流にあるものは?", "モエンジョ=ダーロ"], ["アーリヤ人の神々への賛歌を集めた最古の文献は?", "『リグ=ヴェーダ』"], ["殷の後期の都の遺跡は?", "殷墟"], ["前1200年ごろメキシコ湾岸に成立し、巨石の頭像で知られる文明は?", "オルメカ文明"]], "related": ["y_bc10", "t_ori", "t_gr", "t_in", "t_cn", "t_af", "t_la", "j_jomon"], "n": 4658}, "y_bc10": {"title": "前10〜前7世紀の世界", "span": "前1000年ごろ〜前600年ごろ", "year": -800, "lead": "大国が後退したあとの東地中海では、アラム人・フェニキア人・ヘブライ人が交易と信仰で活躍し、やがてアッシリアがオリエントを初めて統一しました。ギリシアではポリスが生まれ、インドではガンジス川流域に農耕社会が広がり、中国では周の東遷によって春秋時代が始まります。", "flow": ["前10世紀ごろ ヘブライ王国がダヴィデ王・ソロモン王のもとで栄える→ソロモン王の死後に南北に分裂", "前1000年ごろ アーリヤ人がガンジス川流域へ進出→鉄器による開拓とヴァルナ制の形成", "前9世紀ごろ フェニキア人のティルスが北アフリカにカルタゴを建設したとされる", "前8世紀 ギリシア各地でポリスが成立→地中海・黒海沿岸に植民市を建設", "前770年 周が犬戎に攻められて都を洛邑に移す→東周・春秋時代の始まり", "前722年 アッシリアがイスラエル王国を滅ぼす", "前8世紀 クシュ王国がエジプトを支配", "前7世紀前半 アッシリアがエジプトを征服し、オリエントを初めて統一", "前7世紀 リディアで金属貨幣がつくられる", "前7世紀 斉の桓公が覇者となる→尊王攘夷を掲げる", "前612年 アッシリアが滅亡→エジプト・リディア・新バビロニア・メディアの4王国分立"], "sync": [["西アジア", "アラム人・フェニキア人・ヘブライ人の活動→アッシリアのオリエント統一→前612年滅亡と4王国分立"], ["エジプト・アフリカ", "エジプト新王国の衰退→クシュ王国の支配→アッシリアの征服→再独立"], ["ヨーロッパ", "ギリシアの暗黒時代からポリスの成立へ、植民活動、ホメロスの叙事詩/イタリアではエトルリア人が活動"], ["南アジア", "アーリヤ人がガンジス川流域に移動→ヴァルナ制とバラモン教の確立、ウパニシャッド哲学へ"], ["東アジア", "西周の封建→前770年の東遷→春秋時代(斉の桓公など覇者の時代)"], ["内陸アジア・アメリカ", "騎馬遊牧民スキタイの活動/メソアメリカのオルメカ文明、アンデスのチャビン文化"]], "secs": [{"t": "東地中海:小さな民族の活躍", "p": ["前1200年ごろの混乱でヒッタイトが滅び、エジプトも勢いを失うと、シリア・パレスチナには大国の支配がおよばない空白が生まれました。そこで活躍したのがセム語系の3つの民族です。", "【アラム人】はダマスクスを中心に、ラクダなどを使った【内陸交易】で活躍しました。彼らの言葉である【アラム語】はオリエントの国際共通語となり、【アラム文字】はのちに西アジア・中央アジアの多くの文字の源となりました。一方、【フェニキア人】は【シドン】や【ティルス】を拠点に【地中海交易】で活躍し、ティルスは北アフリカに【カルタゴ】を建設したとされます。フェニキア人が用いた表音文字は、ギリシア人に伝わって【アルファベット】の起源となりました。陸のアラム人、海のフェニキア人という対比で覚えておくとよいでしょう。", "【ヘブライ人】は、伝承では指導者モーセのもとでエジプトから脱出し(出エジプト)、パレスチナに定住しました。前10世紀ごろには【ダヴィデ王】と【ソロモン王】のもとで王国が栄え、【イェルサレム】に神殿が建てられました。しかしソロモン王の死後、王国は北の【イスラエル王国】と南の【ユダ王国】に分裂します。イスラエル王国は前722年にアッシリアに滅ぼされ、ユダ王国はのちに新バビロニアによって滅ぼされることになります(バビロン捕囚、次のページ)。ヘブライ人は苦難のなかで唯一神【ヤハウェ】への信仰を深め、自分たちだけが救われるという【選民思想】や【救世主(メシア)】を待ち望む信仰を育てました。これが【ユダヤ教】で、のちのキリスト教・イスラーム教にも大きな影響を与えます。"]}, {"t": "アッシリアのオリエント統一と崩壊", "p": ["北メソポタミアの【アッシリア】は、鉄製の武器と戦車・騎兵を備えた強力な軍隊によって勢力を広げ、前722年にはイスラエル王国を滅ぼしました。前7世紀前半にはエジプトも征服し、メソポタミア・シリア・エジプトにまたがる【オリエント初の統一】を実現しました。", "アッシリアは広い領土を治めるため、全国を【州】に分けて総督をおき、都と各地を結ぶ【駅伝制】を整えました。都【ニネヴェ】には、前7世紀の【アッシュルバニパル王】が各地の粘土板文書を集めた図書館がつくられたことで知られます。しかしアッシリアは、反抗する民族を強制的に移住させるなど【強圧的な支配】を行ったため、服属した民族の反発を招きました。", "その結果、アッシリアは各地の反乱によって急速に弱まり、前612年に都ニネヴェが攻め落とされて滅亡しました。その後のオリエントは、【エジプト】、小アジアの【リディア】、メソポタミアの【新バビロニア(カルデア)】、イラン高原の【メディア】の【4王国】が分立する時代となります。リディアは前7世紀ごろ、世界で最も早い時期に【金属貨幣】をつくったことで知られ、貨幣はその後ギリシアなどに広がりました。アッシリアの失敗は、次にオリエントを統一するアケメネス朝が「寛容な支配」をとる理由として、セットで理解しておきましょう。"]}, {"t": "ギリシア:暗黒時代からポリスの誕生へ", "p": ["ミケーネ文明の崩壊後、ギリシアは長い暗黒時代を経験しましたが、その間に鉄器が普及し、人々の生活は少しずつ回復していきました。前8世紀になると、各地の有力者が中心となって人々が一か所に集まり住む【集住(シノイキスモス)】が進み、【ポリス】とよばれる都市国家が誕生しました。ポリスには、守護神をまつる丘【アクロポリス】と、市場や集会の場となる広場【アゴラ】がありました。", "人口が増えて土地が不足すると、ギリシア人は地中海や黒海の沿岸に【植民市】を建設しました。現在のマルセイユにあたる【マッサリア】、ナポリにあたる【ネアポリス】、のちのイスタンブルにあたる【ビザンティオン】などは、この時代の植民市に起源をもちます。植民と交易の広がりは、オリエントの文化をギリシアに伝える役割も果たしました。フェニキア文字からアルファベットが生まれたのもこの流れのなかです。", "ポリスは政治的には互いに独立していましたが、ギリシア人は同じ言葉と神々を共有し、自分たちを【ヘレネス】、異民族を【バルバロイ】とよんで区別しました。オリンピアの祭典や【デルフォイの神託】は、ポリスをこえた同胞意識を支えました。文学では、【ホメロス】の叙事詩『イリアス』『オデュッセイア』、農民の生活を歌った【ヘシオドス】の『労働と日々』が生まれました。", "代表的なポリスとして、ドーリア人が建てた【スパルタ】では、少数の市民が多数の隷属農民【ヘイロータイ(ヘロット)】を支配するため、【リュクルゴスの制】とよばれる厳しい軍国主義的な体制がとられました。周辺には商工業に従事する【ペリオイコイ】もいました。一方、イオニア人の【アテネ】では、前7世紀後半に【ドラコン】が慣習法を成文化し、貴族の勝手な法の運用を制限しようとしました。アテネの民主政への歩みは次のページで扱います。", "イタリア半島では、先住の【エトルリア人】が都市を築いて栄えていました。ローマは伝承では前753年に建国されたとされ、のちにエトルリア人の王に支配されることになります。"]}, {"t": "南アジア:ガンジス川流域の開拓とヴァルナ制", "p": ["前1000年ごろ、アーリヤ人はパンジャーブ地方からガンジス川流域へと移動しました。この地域は森林におおわれていましたが、【鉄器】の使用によって開拓が進み、稲作を含む農耕社会が成立しました。生活が牧畜中心から農耕中心へと変わっていったことが、この時期の大きな変化です。", "社会が複雑になるなかで、身分を4つに分ける【ヴァルナ制】が形づくられました。祭祀をつかさどる【バラモン】、王侯・武人の【クシャトリヤ】、農民・牧畜民・商人などの【ヴァイシャ】、隷属民の【シュードラ】です。のちには、職業や出身にもとづく多くの集団【ジャーティ】と結びついて、いわゆる【カースト制度】へと発展していきます。", "宗教では、ヴェーダ聖典にもとづき、バラモンがおこなう複雑な祭式を重視する【バラモン教】が成立しました。しかし、祭式の形式ばかりが重んじられることへの反省から、内面的な思索を重視する【ウパニシャッド哲学】が生まれます。宇宙の根本原理【ブラフマン(梵)】と個人の本質【アートマン(我)】が一つであると悟ることで、生まれ変わりをくり返す【輪廻】から抜け出す【解脱】に至るという【梵我一如】の考えは、のちの仏教やジャイナ教にも影響を与えました。"]}, {"t": "東アジア:西周から春秋時代へ", "p": ["殷を倒した周は、都の鎬京を中心に封建によって広い地域を支配しました。周の封建は、王と諸侯が同じ一族であるという血縁の結びつきに頼るものでした。しかし代を重ねるにつれて血縁の意識は薄れ、諸侯は自立していきました。", "前770年、周は西方の異民族【犬戎】の攻撃を受けて、都を東の【洛邑】に移しました。これより前を【西周】、後を【東周】とよびます。東周の前半を【春秋時代】といい、この名は孔子が編集したとされる魯の年代記『春秋』に由来します。周王の権威はなお残っていましたが、実際の力は有力な諸侯に移っていきました。", "春秋時代には、有力な諸侯が周王を尊び、異民族をしりぞけるという【尊王攘夷】を掲げて諸侯の同盟を主導しました。こうした諸侯を【覇者】といい、とくに前7世紀の【斉の桓公】(宰相【管仲】が補佐)や、それに続く【晋の文公】が知られます。覇者たちは周王の権威を利用しながら、実際には自らの勢力を広げていきました。これが次の戦国時代につながる変化です。", "この時代の中国の周辺には、周の文化を共有しない人々が多く住んでおり、周の側は彼らを夷狄とよんで区別しました。一方で、南方の長江流域の【楚】や、のちに台頭する【呉】【越】のように、周の外側から起こった勢力も中原の争いに加わるようになります。中国という世界そのものが、春秋時代を通じて外側へと広がっていったのです。"]}, {"t": "アフリカ・内陸アジア・アメリカ", "p": ["ナイル川上流のヌビア地方では、【クシュ王国】が力をつけ、前8世紀にはエジプトを支配しました。しかし前7世紀にアッシリアがエジプトに進出すると、クシュはエジプトから退き、のちに南方の【メロエ】に中心を移して製鉄などで栄えました。エジプトとアフリカ内陸、そしてアッシリアの動きが連動していることに注目しましょう。", "ユーラシアの草原地帯では、馬に乗って家畜とともに移動する【騎馬遊牧民】が現れました。黒海北方の草原では、前7世紀ごろから【スキタイ】が強大になり、動物の姿を意匠にした金属工芸などの【スキタイ文化】を生み出しました。この文化は草原を通じて東方にも伝わり、のちの匈奴など東方の遊牧民にも影響を与えたと考えられています。騎馬の技術は、定住農耕民の国家にとって大きな脅威となり、その後のユーラシア史を動かす重要な要素となります。", "アメリカ大陸では、メキシコ湾岸のオルメカ文明や、アンデスのチャビン文化が引き続き栄え、のちの文明の基礎となる宗教や美術の伝統を育てていました。"]}, {"t": "世界のつながり:鉄・文字・貨幣の伝播", "p": ["この時代を横に見ると、まず【鉄器の普及】が各地の社会を変えたことがわかります。オリエントでは鉄製の武器が大帝国アッシリアの軍事力を支え、インドでは鉄の斧がガンジス川流域の森林の開拓を可能にし、ギリシアでも鉄器が暗黒時代からの回復を支えました。中国でも春秋時代のころから鉄器が使われ始め、次の時代の農業の発展につながります。", "次に、【文字と貨幣の伝播】です。フェニキア文字はギリシアのアルファベットとなり、のちにローマ字へと受けつがれました。アラム文字は西アジア・中央アジアへ広がりました。リディアで生まれた金属貨幣はギリシアへ伝わり、交易の発展を促しました。小さな民族の交易活動が、のちの世界に長く残る文化を広めたのです。", "最後に、【統一と分立のリズム】に注目しましょう。オリエントではアッシリアが初めて全域を統一しましたが、強圧的な支配のためにすぐ崩れ、4王国の分立に戻りました。中国では逆に、周王の統一的な支配がゆるみ、諸侯が並び立つ春秋時代に入りました。ギリシアは最初から多数のポリスに分かれていました。それぞれの地域が、次の時代にどのような統一を迎えるのか(アケメネス朝、秦、そしてローマ)を意識しながら読み進めると、世界史の流れがつかみやすくなります。"]}], "points": ["アラム人=内陸交易・アラム語、フェニキア人=地中海交易・カルタゴ・アルファベットの起源", "ヘブライ王国はソロモン王の死後に分裂し、イスラエル王国は前722年にアッシリアに滅ぼされた", "アッシリアは初めてオリエントを統一したが、強圧的な支配で前612年に滅亡し、4王国分立となった", "リディアは最初期の金属貨幣で知られる", "ポリスは集住によって成立し、アクロポリスとアゴラを持つ。ヘレネスとバルバロイの区別", "スパルタのヘイロータイ・ペリオイコイ・リュクルゴスの制", "ヴァルナ制の4身分と、ウパニシャッド哲学の梵我一如", "前770年の周の東遷で春秋時代が始まり、覇者が尊王攘夷を掲げた"], "check": [["ダマスクスを中心に内陸交易で活躍し、その言語がオリエントの共通語となった民族は?", "アラム人"], ["フェニキア人の都市ティルスが北アフリカに建設したとされる植民市は?", "カルタゴ"], ["前722年にイスラエル王国を滅ぼした国は?", "アッシリア"], ["アッシリア滅亡後に分立した4王国のうち、金属貨幣をつくったことで知られるのは?", "リディア"], ["ポリスの成立のもとになった、人々が一か所に集まり住むことを何という?", "集住(シノイキスモス)"], ["スパルタで市民に支配された隷属農民を何という?", "ヘイロータイ(ヘロット)"], ["ブラフマンとアートマンが一体であると説く考えは?", "梵我一如(ウパニシャッド哲学)"], ["前770年に周が都を移した都市は?", "洛邑"], ["春秋時代の最初の覇者とされる斉の君主は?", "斉の桓公"]], "related": ["y_bc30", "y_bc6", "t_ori", "t_ps", "t_gr", "t_in", "t_cn", "t_mn", "t_af"], "n": 4118}, "y_bc6": {"title": "前6〜前5世紀の世界", "span": "前600年ごろ〜前400年ごろ", "year": -500, "lead": "アケメネス朝がオリエントを再統一して寛容な大帝国を築き、それに挑んだペルシア戦争を経てアテネの民主政が完成しました。同じころ、インドでは仏教とジャイナ教、中国では孔子の儒家、ギリシアでは哲学が生まれ、世界各地で人間の生き方を問う思想が一斉に登場しました。", "flow": ["前594年 アテネでソロンの改革→財産政治と負債の帳消し", "前586年 新バビロニアのネブカドネザル2世がユダ王国を滅ぼす→バビロン捕囚", "前550年 キュロス2世がメディアから独立しアケメネス朝を建てる→前539年に新バビロニアを滅ぼし捕囚を解放", "前525年 カンビュセス2世がエジプトを征服→オリエント再統一", "前509年 ローマが王を追放して共和政を始める", "前508年 アテネでクレイステネスの改革→民主政の基礎、陶片追放", "前6世紀ごろ インドでガウタマ=シッダールタが仏教を、ヴァルダマーナがジャイナ教を開く", "前6〜前5世紀 中国で孔子が仁と礼を説く→儒家の成立", "前500年 イオニアの反乱→前490年マラトン、前480年サラミス、前479年プラタイアでギリシア側が勝利", "前478年ごろ デロス同盟の結成→アテネの海上支配とペリクレス時代の民主政", "前431年 ペロポネソス戦争が始まる→前404年スパルタの勝利", "前403年 晋が韓・魏・趙に分裂→中国は戦国時代へ"], "sync": [["西アジア", "新バビロニアのバビロン捕囚→アケメネス朝の成立とオリエント再統一、ダレイオス1世の中央集権、ゾロアスター教"], ["ヨーロッパ", "アテネ民主政の発展(ソロン→クレイステネス→ペリクレス)、ペルシア戦争、ペロポネソス戦争/ローマ共和政の成立"], ["南アジア", "十六大国の分立とコーサラ・マガダの台頭、仏教とジャイナ教の成立"], ["東アジア", "春秋時代後期、鉄製農具と牛耕の始まり、孔子と儒家、前403年から戦国時代"], ["アフリカ", "エジプトがアケメネス朝の支配下に、メロエの製鉄、カルタゴの西地中海支配"], ["世界のつながり", "アケメネス朝の「王の道」とギリシアとの接触、各地で同時に思想・宗教が誕生"]], "secs": [{"t": "西アジア:アケメネス朝による「寛容な」大帝国", "p": ["アッシリア滅亡後の4王国のうち、新バビロニアは【ネブカドネザル2世】のもとで栄え、前586年にユダ王国を滅ぼしてイェルサレムの住民をバビロンに連れ去りました。これが【バビロン捕囚】です。", "一方、イラン高原ではペルシア人の【キュロス2世】がメディアから独立し、前550年に【アケメネス朝】を建てました。キュロス2世はリディアを征服し、前539年には新バビロニアを滅ぼして、捕囚されていたユダヤ人を故郷に帰しました。その子【カンビュセス2世】が前525年にエジプトを征服したことで、オリエントは再び統一されました。", "帝国の最盛期を築いたのが【ダレイオス1世】です。彼は全国を約20の州に分けて知事【サトラップ】をおき、「【王の目】」「【王の耳】」とよばれる監察官を派遣して地方を監視しました。都【スサ】から小アジアのサルデスまで【王の道】とよばれる国道を整え、駅伝制によって命令と情報をすばやく伝えました。また金貨・銀貨を発行して税制を整え、新都【ペルセポリス】の造営も始めました。", "アケメネス朝の支配の特徴は、服属した諸民族にそれぞれの宗教や慣習を認めた【寛容な政策】です。強圧的なアッシリアがすぐ崩壊したことの反省に立つものといえます。交易では、陸上のアラム人やフェニキア人の活動を保護しました。宗教面では、世界を善神【アフラ=マズダ】と悪神【アーリマン】の戦いととらえる【ゾロアスター教】がペルシア人のあいだに広まりました。最後の審判などの考えは、ユダヤ教やキリスト教にも影響を与えたとされます。"]}, {"t": "ギリシア:アテネ民主政の歩みとペルシア戦争", "p": ["前7世紀ごろから、ギリシアでは商工業の発達によって富を得た平民が、武具を自分でそろえて【重装歩兵】として戦争に参加するようになりました。密集隊形で戦う重装歩兵が国防の主力になると、平民は政治参加を求めるようになります。これがアテネの民主政の出発点です。", "前594年、【ソロン】は市民を財産の額によって4等級に分けて参政権を定める【財産政治】を行い、借金のために市民が奴隷にされることを禁じて負債を帳消しにしました。しかし貴族と平民の対立は収まらず、平民の支持を背景に非合法に権力を握る【僭主】の【ペイシストラトス】が現れます。ついで前508年、【クレイステネス】は血縁にもとづく4部族を地縁にもとづく10部族に改め、貴族の影響力を弱めました。また僭主の出現を防ぐために、危険人物の名を陶片に書いて投票し国外に追放する【陶片追放(オストラキスモス)】の制度をつくったとされます。", "前500年、アケメネス朝の支配下にあった小アジアのイオニア地方のギリシア人ポリスが【イオニアの反乱】を起こし、アテネがこれを支援したことから【ペルシア戦争】が始まりました。前490年の【マラトンの戦い】ではアテネの重装歩兵がペルシア軍を破りました。前480年、ペルシア王【クセルクセス1世】の大軍が再び侵入すると、スパルタ王レオニダスの部隊は【テルモピレーの戦い】で全滅しましたが、【テミストクレス】の率いるアテネ海軍が【サラミスの海戦】で大勝し、翌前479年の【プラタイアの戦い】でギリシア連合軍の勝利が決定的になりました。", "サラミスの海戦では、軍船の漕ぎ手として、武具を買えない無産市民が活躍しました。これにより無産市民の発言力も高まり、民主政はさらに進みます。前5世紀半ばの【ペリクレス】の時代、18歳以上の成年男性市民が【民会】で直接国家の方針を決める【直接民主政】が完成しました。役人の多くは抽選で選ばれました。ただし、女性・奴隷・在留外人には参政権がなく、現代の民主政とは異なる点に注意が必要です。"]}, {"t": "ギリシア:デロス同盟からペロポネソス戦争へ", "p": ["ペルシアの再来に備えて、前478年ごろ、アテネを盟主とする【デロス同盟】が結成されました。しかしアテネは同盟の資金を自国のために流用するなど、しだいに他のポリスを支配する「帝国」のようにふるまうようになりました。アテネの繁栄を象徴するのが、ペリクレスのもとで再建されたアクロポリスの【パルテノン神殿】で、彫刻家【フェイディアス】が制作を監督しました。", "こうしたアテネの拡大に対し、スパルタは【ペロポネソス同盟】を率いて対抗し、前431年に【ペロポネソス戦争】が始まりました。アテネでは疫病が流行してペリクレスが亡くなり、その後は民衆を巧みな弁舌で扇動する【デマゴーゴス(扇動政治家)】が現れて政治が混乱しました。最終的に、ペルシアの支援を受けたスパルタが前404年に勝利しました。この戦争をきっかけにポリスどうしの争いが続き、ギリシア世界は衰退に向かいます。", "この時代のギリシアでは学問・文化も大きく発展しました。前6世紀には、イオニア地方の【タレス】が万物の根源を水と考えるなど、神話ではなく理性で自然を説明しようとする【イオニア自然哲学】が始まり、数学の【ピタゴラス】も活躍しました。前5世紀には、悲劇の【アイスキュロス】【ソフォクレス】【エウリピデス】、喜劇の【アリストファネス】が活躍し、歴史では、ペルシア戦争を物語的に描いた【ヘロドトス】と、ペロポネソス戦争を批判的・実証的に記した【トゥキディデス】が現れました。民主政のもとでは弁論が重視され、「万物の尺度は人間」と説いた【プロタゴラス】などの【ソフィスト】が弁論術を教えました。これに対して【ソクラテス】は、問答法によって客観的な真理を追究しました。"]}, {"t": "ローマ:共和政の始まりと身分闘争", "p": ["イタリア半島では、ラテン人の都市国家ローマが、前509年にエトルリア系の王を追放して【共和政】を始めました。共和政のローマでは、任期1年・定員2名の最高官職【コンスル(執政官)】が政治と軍事を指揮し、貴族(【パトリキ】)の会議である【元老院】が実質的な権力を握っていました。非常時には【独裁官(ディクタトル)】がおかれました。", "しかし、重装歩兵として国防を担う平民(【プレブス】)は、ギリシアと同じように政治的な権利を求めて貴族と争いました。これを【身分闘争】といいます。前5世紀前半には、平民を守る【護民官】と、平民だけの議会である【平民会】が設けられました。さらに前5世紀半ばには、慣習法を成文化した【十二表法】が定められ、貴族が法を独占する状態が改められたとされます。身分闘争のその後の展開(リキニウス・セクスティウス法など)は次のページで扱います。", "西地中海では、フェニキア人の植民市【カルタゴ】が強大になり、交易の拠点を広げていました。ギリシアとペルシアが東地中海で争っていたころ、西地中海ではカルタゴとギリシア人植民市が勢力を争っていました。のちにローマはこのカルタゴと対決することになります。"]}, {"t": "南アジア:都市の発展と新しい宗教", "p": ["前6世紀ごろのガンジス川流域では、農業の発展と商業の活発化によって都市が成長し、【十六大国】とよばれる多くの国が並び立ちました。そのなかで、【コーサラ国】と【マガダ国】が有力となり、とくにマガダ国がしだいに優位に立っていきます。", "都市の発展によって力をつけた【クシャトリヤ】や【ヴァイシャ】は、祭式を独占するバラモンの権威に不満をもつようになりました。こうした状況のなかで、新しい宗教が生まれます。シャカ族の王子【ガウタマ=シッダールタ】は、苦行ではなく正しい修行によって迷いを断ち切り、悟りに達することを説きました。彼は【ブッダ】(悟った者)とよばれ、その教えが【仏教】です。仏教は苦しみの原因と克服の道を示した【四諦】や、正しい修行の道である【八正道】を説き、ヴァルナ制の身分差別を否定しました。", "同じころ【ヴァルダマーナ】は、きびしい苦行と、あらゆる生き物を傷つけない【不殺生】を重んじる【ジャイナ教】を開きました。ジャイナ教はとくに商人(ヴァイシャ)のあいだに広まりました。仏教とジャイナ教は、いずれもバラモンの権威とヴァルナ制を批判し、クシャトリヤやヴァイシャの支持を集めた点が共通しています。"]}, {"t": "東アジア:春秋から戦国へ、孔子の登場", "p": ["春秋時代の後半になると、【鉄製農具】と、牛に犂を引かせる【牛耕】が始まり、農業の生産力が大きく高まりました。農地が広がると、それまでの氏族的な共同体が崩れ、家族単位で農業を営む農民が現れます。商業も活発になり、青銅の貨幣が使われ始めました。こうした経済の変化は、周王を中心とする血縁的な秩序をさらに弱めました。", "このような社会の変動期に、魯の国の【孔子】は、親子・兄弟などの家族の道徳を基礎とした思いやりの心【仁】と、社会の秩序を保つための規範【礼】を説きました。そして徳のある君主が人民を教え導く【徳治主義】によって、周の初めのような理想の秩序を取りもどそうとしました。孔子の言行は弟子たちによって【『論語』】にまとめられ、その学派は【儒家】とよばれます。", "前403年、有力な諸侯であった晋が、家臣の家によって【韓】【魏】【趙】の3国に分かれ、周王もこれを諸侯として認めました。これ以降を【戦国時代】とよびます。春秋時代の覇者がなお周王を尊んだのに対し、戦国時代の諸侯は自ら王を名乗り、実力で生き残りを争うようになりました。"]}, {"t": "世界のつながり:帝国の東西交流と思想の同時誕生", "p": ["この時代の世界で最も大きな国家は、エーゲ海からインダス川までを支配したアケメネス朝でした。アケメネス朝の領域は西でギリシア世界と、東でインド世界と接しており、「王の道」や海上交易を通じて、オリエント・ギリシア・インドの文化が行き来しました。インダス川流域の一部もアケメネス朝の支配下に入っています。ペルシア戦争は、東西の大国と小さなポリス群がぶつかった事件であると同時に、ギリシア人が自分たちの自由と民主政を意識するきっかけとなりました。", "横に並べて見ると、この時代の最大の特徴は、世界の離れた地域でほぼ同時に、人間の生き方や世界の成り立ちを根本から問う思想が生まれたことです。ギリシアでは自然哲学からソクラテスへ、インドではウパニシャッド哲学から仏教・ジャイナ教へ、中国では孔子の儒家が登場し、イランではゾロアスター教が広まり、ユダヤ教もバビロン捕囚の経験を通じて信仰を深めました。", "これらの思想が生まれた背景には、共通する社会の変化があります。鉄器による農業生産の向上と商業・都市の発展によって、古い血縁的な共同体や神官の権威が揺らぎ、個人として「どう生きるべきか」が問われるようになったのです。ギリシアのポリスで平民が政治に参加したこと、インドでクシャトリヤとヴァイシャが力をつけたこと、中国で諸侯が自立したことは、いずれもこの変化のあらわれといえます。", "一方、アメリカ大陸やサハラ以南のアフリカでは、ユーラシアとの直接の交流はありませんでしたが、メソアメリカではオルメカ文明の伝統が受けつがれ、ナイル川上流のメロエでは製鉄が盛んになるなど、それぞれの地域で独自の発展が続いていました。"]}], "points": ["バビロン捕囚(前586年)→キュロス2世による解放(前538年)の因果関係", "ダレイオス1世のサトラップ・王の目王の耳・王の道・ペルセポリス", "アケメネス朝の寛容政策とアッシリアの強圧支配の対比", "アテネ民主政:ソロン(財産政治)→ペイシストラトス(僭主)→クレイステネス(10部族・陶片追放)→ペリクレス(直接民主政)", "ペルシア戦争の戦い(マラトン・テルモピレー・サラミス・プラタイア)の順序と、サラミスで無産市民が活躍したことの意味", "ローマ共和政:コンスル・元老院・護民官・平民会・十二表法", "仏教とジャイナ教はバラモンの権威とヴァルナ制を批判し、クシャトリヤ・ヴァイシャに支持された", "前403年の晋の分裂で戦国時代へ。鉄製農具と牛耕が社会変化の背景"], "check": [["前586年にユダ王国を滅ぼし、住民をバビロンに連行した王は?", "ネブカドネザル2世"], ["前550年にアケメネス朝を建てた王は?", "キュロス2世"], ["ダレイオス1世が各州においた知事を何という?", "サトラップ"], ["前508年に10部族制と陶片追放を定めたアテネの改革者は?", "クレイステネス"], ["前480年、テミストクレスの率いるアテネ海軍がペルシア軍を破った戦いは?", "サラミスの海戦"], ["ペルシアの再来に備えて結成された、アテネを盟主とする同盟は?", "デロス同盟"], ["ローマで平民を守るために設けられた官職は?", "護民官"], ["不殺生と苦行を重んじる宗教を開いた人物は?", "ヴァルダマーナ"], ["孔子の言行を弟子がまとめた書物は?", "『論語』"], ["前403年に晋が分裂してできた3国は?", "韓・魏・趙"]], "related": ["y_bc10", "y_bc4", "t_ori", "t_ir", "t_ps", "t_gr", "t_ro", "t_in", "t_cn"], "n": 4347}, "y_bc4": {"title": "前4〜前3世紀の世界", "span": "前400年ごろ〜前200年ごろ", "year": -300, "lead": "アレクサンドロス大王の東方遠征によってギリシアとオリエントが一つの世界となり、ヘレニズム時代が始まりました。その刺激を受けてインドではマウリヤ朝が初めて広域を統一し、中国では戦国時代の競争のなかから秦が統一を果たし、地中海西部ではローマがカルタゴとの対決に勝ち抜いていきます。", "flow": ["前4世紀 秦で商鞅の変法→法家思想による富国強兵", "前371年 テーベがレウクトラの戦いでスパルタを破る→ポリス間の争いが続きギリシアは衰退", "前367年 ローマでリキニウス・セクスティウス法→コンスルの1人を平民から選ぶ", "前338年 マケドニアのフィリッポス2世がカイロネイアの戦いでアテネ・テーベ連合軍を破る→コリントス同盟", "前334年 アレクサンドロス大王の東方遠征→前330年アケメネス朝滅亡→前323年大王の死", "前4世紀末 チャンドラグプタがマウリヤ朝を建てる→インド初の広域統一", "前301年 イプソスの戦い→プトレマイオス朝・セレウコス朝・アンティゴノス朝の分立が固まる", "前287年 ホルテンシウス法→平民会の決議が国法に", "前3世紀 アショーカ王がダルマにもとづく政治と仏教保護", "前3世紀半ば セレウコス朝からバクトリアとパルティアが自立", "前264年 ポエニ戦争の開始→第2回でハンニバルが侵入、前202年ザマの戦いでローマ勝利", "前221年 秦王政が中国を統一し始皇帝となる→前206年秦滅亡、前202年劉邦が漢を建てる"], "sync": [["ヨーロッパ・地中海", "ポリスの衰退→マケドニアのギリシア支配→ヘレニズム諸国/ローマのイタリア半島統一とポエニ戦争"], ["西アジア・エジプト", "アケメネス朝の滅亡→セレウコス朝・プトレマイオス朝、アレクサンドリアの繁栄、バクトリア・パルティアの自立"], ["南アジア", "マウリヤ朝の成立、アショーカ王の統治と仏教の保護・布教"], ["東アジア", "戦国七雄の争い、諸子百家→秦の統一と郡県制→秦の滅亡と漢の成立"], ["内陸アジア", "匈奴が強大化し、冒頓単于のもとで月氏を攻撃"], ["世界のつながり", "ヘレニズム文化の東方への広がり、仏教のセイロン伝播、遊牧民と中国の対立"]], "secs": [{"t": "ギリシアの衰退とマケドニアの台頭", "p": ["ペロポネソス戦争に勝ったスパルタの覇権は長続きせず、前371年には【テーベ】が将軍【エパメイノンダス】のもとで【レウクトラの戦い】に勝ち、一時ギリシアの覇権を握りました。このようにポリス同士の争いが続くなかで、市民は戦争と重税に疲れ、土地を失う者も増えました。かつて市民自身が担っていた戦争は、お金でやとう【傭兵】に頼るようになり、市民が国を守るという民主政の基盤は崩れていきました。", "この時期にも学問は発展しました。ソクラテスは前399年に死刑となりましたが、弟子の【プラトン】は、永遠不変の真の実在である【イデア】を説き、哲学者が統治する理想国家を論じました。その弟子の【アリストテレス】は、論理学・自然科学・政治学など幅広い学問を体系化し、「万学の祖」とよばれます。", "ギリシアの北方にあった【マケドニア】は、【フィリッポス2世】のもとで軍制を整えて強大になり、前338年の【カイロネイアの戦い】でアテネ・テーベ連合軍を破りました。翌年、マケドニアはスパルタを除く全ギリシアのポリスを【コリントス同盟(ヘラス同盟)】に組みこみ、その盟主となりました。こうして独立したポリスが並び立つ時代は終わりを迎えました。"]}, {"t": "アレクサンドロス大王の東方遠征とヘレニズム世界", "p": ["フィリッポス2世が暗殺されると、その子【アレクサンドロス大王】が即位し、前334年にペルシアへの【東方遠征】を開始しました。大王は前333年の【イッソスの戦い】でアケメネス朝の王【ダレイオス3世】を破り、エジプトを征服したのち、前331年の【アルベラ(ガウガメラ)の戦い】で再び勝利しました。前330年にアケメネス朝は滅亡し、大王はさらに東へ進んでインダス川流域にまで達しました。", "大王は征服地に【アレクサンドリア】とよばれる都市を各地に建設し、ギリシア人を移住させました。また、自らペルシア風の儀礼を取り入れ、ペルシア人の女性と結婚するなど、東西の融合をはかったとされます。しかし前323年、大王はバビロンで急死し、帝国はその後継者【ディアドコイ】たちのあいだで争奪されました。前301年の【イプソスの戦い】をへて、帝国はおもにマケドニアの【アンティゴノス朝】、シリアを中心とする【セレウコス朝】、エジプトの【プトレマイオス朝】に分かれました。", "東方遠征からプトレマイオス朝が滅びる前30年までのおよそ300年間を【ヘレニズム時代】とよびます。この時代には、ギリシア語の共通語【コイネー】が広い地域で使われ、ギリシア文化とオリエント文化が融合した【ヘレニズム文化】が生まれました。プトレマイオス朝の都【アレクサンドリア】には王立研究所【ムセイオン】がおかれ、平面幾何学を大成した【エウクレイデス】、浮力の原理などで知られる【アルキメデス】、地球の周囲の長さを測定した【エラトステネス】などが活躍しました。", "哲学では、ポリスという枠が失われたなかで、個人の心の安らぎを求める思想が広まりました。理性によって欲望をおさえることを説く【ストア派】(【ゼノン】が創始)と、精神的な快楽を追求する【エピクロス派】です。ポリスをこえて全人類を同胞とみなす【世界市民主義(コスモポリタニズム)】の考え方も生まれ、のちのローマに受けつがれました。", "セレウコス朝の東方では、前3世紀半ばに、ギリシア人が自立して【バクトリア】を建て、イラン系の遊牧民が【パルティア】を建てました。パルティアはのちにイラン高原からメソポタミアまでを支配する大国となり、ローマと対立することになります。"]}, {"t": "ローマ:イタリア統一からポエニ戦争へ", "p": ["ローマでは身分闘争が続き、前367年の【リキニウス・セクスティウス法】によってコンスルの1人を平民から選ぶことが定められ、公有地の占有も制限されました。さらに前287年の【ホルテンシウス法】によって、平民会の決議が元老院の承認なしに国法となることが認められました。これで法のうえでは貴族と平民は平等になりましたが、実際には、有力な平民が貴族と結びついた【新貴族(ノビレス)】が元老院を支配し続けました。", "ローマは周辺の都市を征服し、前272年に南イタリアのギリシア人植民市【タレントゥム】を降伏させて、イタリア半島を統一しました。ローマは征服した都市に一律の権利を与えず、市民権を与える都市、自治を認める都市、同盟市などに分けて、互いに団結しないようにしました。これを【分割統治】といいます。", "イタリアを統一したローマは、西地中海の覇権をめぐってフェニキア人の植民市カルタゴと衝突しました。これが【ポエニ戦争】です。前264年に始まった第1回の戦争でローマはシチリアを獲得し、最初の【属州】としました。第2回の戦争では、カルタゴの名将【ハンニバル】がスペインからアルプスを越えてイタリアに侵入し、前216年の【カンネーの戦い】でローマ軍を包囲殲滅しました。しかしローマは粘り強く戦い、将軍【スキピオ】が北アフリカに上陸して、前202年の【ザマの戦い】でハンニバルを破りました。こうしてローマは西地中海の覇者となり、次の時代にはさらに東地中海へと進出していきます。"]}, {"t": "南アジア:マウリヤ朝とアショーカ王", "p": ["ガンジス川流域では、前4世紀にマガダ国の【ナンダ朝】が勢力を広げていました。アレクサンドロス大王の軍が西北インドに侵入して撤退したのち、混乱した状況のなかで【チャンドラグプタ】がナンダ朝を倒し、【マウリヤ朝】を建てました。都はガンジス川流域の【パータリプトラ】です。マウリヤ朝は西北インドからギリシア勢力を追い払い、インド亜大陸の大部分を初めて統一しました。外からの大きな衝撃が、インド内部の統一を促したという点で、東方遠征とマウリヤ朝の成立は横に結びつけて理解しましょう。", "マウリヤ朝の最盛期は、前3世紀の【アショーカ王】の時代です。アショーカ王は南東部の【カリンガ国】を征服しましたが、その戦争で多くの犠牲者が出たことを深く悔い、仏教に帰依したとされます。その後は武力ではなく、身分をこえて守るべき社会倫理である【ダルマ(法)】による統治をめざしました。王はダルマの内容を各地の岩や石柱に刻ませました(【磨崖碑】【石柱碑】)。", "アショーカ王は仏教を保護し、仏典の編集である【仏典結集】を支援し(第3回とされる)、各地に仏塔【ストゥーパ】を建てさせました。また、王子を【スリランカ(セイロン島)】に派遣して布教させたと伝えられます。スリランカに伝わった仏教は、のちに東南アジアへと広がる【上座部仏教】の源流となりました。しかしアショーカ王の死後、マウリヤ朝は財政難などから衰え、前2世紀初めごろに滅亡しました。"]}, {"t": "東アジア:戦国時代と諸子百家", "p": ["戦国時代には、【秦・楚・斉・燕・韓・魏・趙】の【戦国七雄】が激しく争いました。鉄製農具と牛耕によって農業生産が増え、商業もさかんになり、地域ごとに【刀銭】【布銭】【蟻鼻銭】【円銭(環銭)】などの青銅貨幣が流通しました。諸国は富国強兵のため、家柄にとらわれず有能な人材を求めたので、さまざまな思想家が現れ、自説を説いて各国をめぐりました。これを【諸子百家】といいます。", "儒家では、【孟子】が人間の本性は善であるという【性善説】を説き、徳による王道政治を主張しました。これに対し【荀子】は、人間の本性は悪であるという【性悪説】を唱え、礼による教化を重視しました。荀子の考えを受けつぎ、法と刑罰による厳格な統治を説いたのが【法家】で、【商鞅】や【韓非】、【李斯】が知られます。このほか、無差別の愛【兼愛】と侵略戦争の否定【非攻】を説いた【墨家】の【墨子】、人為を否定して自然のままに生きる【無為自然】を説いた【道家】の【老子】【荘子】、外交策を説いた【縦横家】の【蘇秦】【張儀】、自然現象と人間社会を陰陽と五行で説明する【陰陽家】の【鄒衍】などがいました。", "西方の秦は、前4世紀に【商鞅】を登用して法家思想にもとづく改革(【変法】)を進め、厳しい法による統治と、農業と戦争を奨励する政策で強国となりました。その後、秦は東方の諸国を次々と滅ぼし、前221年に秦王【政】が天下を統一して【始皇帝】と名乗りました。"]}, {"t": "秦の統一から漢の成立へ", "p": ["始皇帝は、全国を郡と県に分けて中央から官僚を派遣する【郡県制】を全国に施行し、強力な中央集権体制をつくりました。また、地域ごとに異なっていた【文字・度量衡・貨幣】を統一し、貨幣は【半両銭】に統一されました。思想の統制のために、医薬・占い・農業以外の書物を焼き、批判する儒者らを生き埋めにしたとされます(【焚書・坑儒】)。北方では遊牧民の【匈奴】を討ち、【万里の長城】を修築しました。南方では華南に軍を送り、南海郡などをおきました。", "しかし、急激な改革と大規模な土木工事や遠征のための重い負担は、人々の強い反発を招きました。始皇帝の死後、前209年に中国史上最初の農民反乱である【陳勝・呉広の乱】が起こると、各地で反乱が広がり、秦は前206年に滅びました。その後、楚の名門出身の【項羽】と、農民出身の【劉邦】が争い、前202年に劉邦が項羽を破って【漢】(前漢)を建て、都を【長安】におきました。", "劉邦(【高祖】)は、秦の急激な郡県制の失敗を反省し、都の周辺には郡県制をしき、地方には一族などを王として封じる【郡国制】を採用しました。中央集権と封建制を組み合わせた、ゆるやかな支配から出発したのです。", "北方の草原では、秦の圧迫を受けた匈奴が、【冒頓単于】のもとで遊牧民を統合して強大となり、西方の【月氏】を攻撃しました。匈奴は前200年に漢の高祖を【白登山の戦い】で包囲し、以後、漢は匈奴に対して和親策をとることになります。こうした遊牧国家と中国王朝の対立は、次の時代の大きなテーマです。"]}, {"t": "世界のつながり:三つの統一と東西の交流", "p": ["前4〜前3世紀の世界を横に見ると、ユーラシアの各地で、それまで分立していた地域が大きく統一されたことがわかります。西ではアレクサンドロス大王がギリシアからインダス川に至る大帝国をつくり、南アジアではマウリヤ朝がインド亜大陸の大部分を初めて統一し、東では秦が中国を統一しました。また西地中海では、ローマがイタリア半島を統一したうえでカルタゴとの戦争に勝ち、地中海全体の統一に向けて歩み出しました。", "これらの統一はまったく無関係に起こったわけではありません。アレクサンドロス大王の遠征はインド西北部に混乱をもたらし、マウリヤ朝の成立を促しました。アショーカ王の碑文の中にはギリシア語やアラム語で刻まれたものもあり、ヘレニズム世界とのつながりを示しています。ヘレニズム諸国のあいだでは交易が活発になり、ギリシア風の文化は西アジアから中央アジアまで広がりました。このことは、のちのガンダーラ美術の成立につながります。", "一方、統一国家の支配の仕方には違いもありました。秦は法と刑罰による画一的な支配を行いましたが、急激すぎて短命に終わりました。アショーカ王は武力ではなくダルマによる統治を唱えましたが、その死後に国は弱まりました。アレクサンドロスの帝国は大王の死とともに分裂しました。広大な領土をどう安定して治めるかという課題に対する答えは、次の時代の漢やローマによって示されることになります。", "さらに、仏教がスリランカへ、ギリシア文化が東方へと広がり、北方では匈奴という巨大な遊牧国家が登場しました。文明の中心どうしが、交易・宗教・戦争を通じてつながり始めた時代として、この時期を位置づけておきましょう。"]}], "points": ["カイロネイアの戦い(前338年)→コリントス同盟でポリスの独立が失われた", "東方遠征の戦い:イッソス(前333年)→アルベラ(前331年)→アケメネス朝滅亡(前330年)", "ヘレニズム三国(アンティゴノス朝・セレウコス朝・プトレマイオス朝)とムセイオン、コイネー", "ストア派(ゼノン)とエピクロス派、世界市民主義", "リキニウス・セクスティウス法(前367年)とホルテンシウス法(前287年)の内容の違い", "アショーカ王:カリンガ征服→ダルマの政治、磨崖碑・石柱碑、仏典結集、スリランカ布教", "諸子百家の主張の違い(孟子の性善説と荀子の性悪説、法家・墨家・道家)", "秦の郡県制と前漢の郡国制の違い、陳勝・呉広の乱"], "check": [["前338年、フィリッポス2世がアテネ・テーベ連合軍を破った戦いは?", "カイロネイアの戦い"], ["前333年、アレクサンドロス大王がダレイオス3世を破った戦いは?", "イッソスの戦い"], ["プトレマイオス朝の都アレクサンドリアにおかれた王立研究所は?", "ムセイオン"], ["理性で欲望をおさえることを説いたゼノンの学派は?", "ストア派"], ["平民会の決議が国法となることを認めたローマの法は?", "ホルテンシウス法"], ["第2回ポエニ戦争で、スキピオがハンニバルを破った戦いは?", "ザマの戦い"], ["マウリヤ朝の都は?", "パータリプトラ"], ["人間の本性は悪であると説いた儒家の思想家は?", "荀子"], ["秦で法家思想にもとづく改革を行った人物は?", "商鞅"], ["劉邦が採用した、郡県制と封建制を併用する制度は?", "郡国制"]], "related": ["y_bc6", "y_bc2", "t_gr", "t_ro", "t_ori", "t_ir", "t_in", "t_cn", "t_mn"], "n": 4598}, "y_bc2": {"title": "前2〜前1世紀の世界", "span": "前200年ごろ〜紀元前後", "year": -100, "lead": "ローマは地中海全域を支配下におさめる一方、征服の結果として社会が崩れ、約100年の内乱をへて帝政へと移りました。東では前漢の武帝が匈奴と戦って西域へ進出し、ユーラシアの東西をつなぐ交易路が本格的に動き始めます。", "flow": ["前200年 漢の高祖が白登山の戦いで匈奴に包囲される→和親策", "前2世紀 ローマが東地中海へ進出→前146年カルタゴとコリントスを破壊", "前154年 呉楚七国の乱→鎮圧後、漢の中央集権化が進む", "前141年 前漢で武帝が即位→郷挙里選、儒学の重視、匈奴への攻勢", "前139年ごろ 張騫が大月氏へ派遣される→西域の事情が中国に伝わる", "前133年 ティベリウス=グラックスの改革→挫折し「内乱の1世紀」へ", "前111年・前108年 武帝が南越と衛氏朝鮮を滅ぼす→南海9郡・楽浪郡など朝鮮4郡", "前91年 同盟市戦争→全イタリアの自由民にローマ市民権", "前73年 スパルタクスの反乱", "前60年 第1回三頭政治→カエサルのガリア遠征→前44年暗殺", "前53年 カルラエの戦いでクラッススがパルティアに敗死", "前31年 アクティウムの海戦→前30年プトレマイオス朝滅亡→前27年オクタウィアヌスがアウグストゥスの称号"], "sync": [["ヨーロッパ・地中海", "ローマの地中海制覇、ラティフンディアと中小農民の没落、グラックス兄弟、内乱の1世紀→帝政の開始"], ["西アジア", "パルティアがメソポタミアまで拡大しローマと対立、セレウコス朝の滅亡"], ["南アジア", "マウリヤ朝滅亡後の分裂、ギリシア人・サカ人の西北インド進出、デカンにサータヴァーハナ朝"], ["東アジア", "前漢の成立と武帝の最盛期、匈奴との戦い、張騫の派遣、南越・衛氏朝鮮の征服"], ["東南アジア", "北ベトナムのドンソン文化(銅鼓)、前漢の支配が南へ広がる"], ["世界のつながり", "オアシスの道(シルクロード)の開通、ローマと漢の東西二大帝国の形成"]], "secs": [{"t": "ローマ:地中海の覇者へ", "p": ["第2回ポエニ戦争に勝ったローマは、その後、東地中海のヘレニズム諸国へと進出しました。マケドニアを属州とし、前146年には第3回ポエニ戦争でカルタゴを滅ぼし、同じ年にギリシアのコリントスも破壊しました。こうしてローマは、イタリア半島の都市国家から、地中海全体にまたがる大国へと成長しました。", "征服によってローマに大きな富が流れこみましたが、それは社会を根本から変えてしまいました。長期の遠征に従軍した中小農民は農地を荒らされ、さらに属州から安い穀物が大量に流入したため、没落して都市ローマに流れこみ、【無産市民】となりました。一方、元老院議員などの有力者や、徴税請負などで富を得た【騎士(エクイテス)】は、農民が手放した土地や公有地を集め、戦争で得た大量の奴隷を使ってオリーブやブドウなどを生産する大農場【ラティフンディア】を経営しました。", "重装歩兵として国を支えてきた中小農民が没落したことは、ローマ軍の力が弱まることを意味しました。また都市に集まった無産市民は、有力者から「パンと見世物」を与えられて、その政治的な支持者となっていきました。共和政を支えてきた市民共同体が、征服の成功によって内側から崩れ始めたのです。"]}, {"t": "ローマ:内乱の1世紀から帝政へ", "p": ["この危機に対して、前133年、護民官の【ティベリウス=グラックス】は、大土地所有を制限して無産市民に土地を分配し、自作農を再建しようとしました。弟の【ガイウス=グラックス】も改革を引きつぎましたが、元老院の保守派の強い反対にあい、兄弟はいずれも命を落としました。【グラックス兄弟】の改革の失敗以降、ローマは約100年にわたる【内乱の1世紀】に入ります。", "政界は、元老院の伝統的な支配を守ろうとする【閥族派】と、平民会を基盤とする【平民派】に分かれて争いました。平民派の【マリウス】は、無産市民を志願兵として募集する【兵制改革】を行い、軍事力を回復させましたが、その結果、兵士は国家よりも給料や土地を与えてくれる将軍個人に忠誠を誓う【私兵】のような性格を持つようになりました。閥族派の【スラ】もまた軍隊を率いてローマに進軍し、両派は血なまぐさい争いをくり返しました。", "前91年には、イタリアの同盟市がローマ市民権を求めて【同盟市戦争】を起こし、その結果、イタリア半島の自由民に市民権が与えられました。前73年には、剣闘士の【スパルタクス】が率いる大規模な奴隷反乱が起こりました。", "こうした混乱のなかで、有力な軍人政治家が台頭します。前60年、【ポンペイウス】【クラッスス】【カエサル】の3人は、元老院に対抗して【第1回三頭政治】を結びました。カエサルは【ガリア遠征】で名声と軍事力を得て、その記録を『ガリア戦記』に残しました。クラッススがパルティアとの戦いで戦死すると、カエサルはポンペイウスを破って権力を握り、【独裁官】となって、エジプトの太陽暦をもとにした【ユリウス暦】を採用するなどの改革を行いました。しかし、共和政を破壊する者とみなされ、前44年に【ブルートゥス】らに暗殺されました。", "その後、カエサルの養子【オクタウィアヌス】は、【アントニウス】【レピドゥス】と【第2回三頭政治】を結び、やがてアントニウスと対立しました。前31年の【アクティウムの海戦】でアントニウスとエジプト女王【クレオパトラ】の連合軍を破り、前30年にプトレマイオス朝が滅びて、ヘレニズム時代は終わりました。前27年、オクタウィアヌスは元老院から【アウグストゥス(尊厳者)】の称号を与えられました。彼は共和政の形式を尊重して【プリンケプス(市民の第一人者)】と称しましたが、実際にはすべての権力を握っていました。この体制を【元首政(プリンキパトゥス)】といい、ここからローマは帝政の時代に入ります。", "この時代のローマは、征服したギリシアの文化を積極的に受け入れました。有力者の家ではギリシア人の奴隷や解放奴隷が家庭教師となり、ギリシア語の教養が重んじられました。政治家で弁論家の【キケロ】は、ギリシア哲学をラテン語で紹介し、共和政を守ろうとしましたが、第2回三頭政治のもとで殺されました。アウグストゥスの時代には、詩人【ウェルギリウス】がローマ建国の叙事詩『アエネイス』を、歴史家【リウィウス】が『ローマ建国史』を著し、【ラテン文学】の黄金時代を迎えます。軍事と政治で地中海を征服したローマが、文化の面ではギリシアに学んだという関係は、「征服されたギリシアが、野蛮な征服者をとりこにした」という言葉でも知られています。"]}, {"t": "西アジア・南アジア:パルティアの拡大とインドの分裂", "p": ["イラン高原のパルティアは、前2世紀にセレウコス朝を圧迫してメソポタミアまで勢力を広げ、ティグリス川のほとりの【クテシフォン】を都としました。パルティアは東西交易の中継地を押さえて栄え、中国では【安息】の名で知られました。衰えたセレウコス朝は、前1世紀前半にローマのポンペイウスによって滅ぼされ、シリアはローマの属州となりました。こうしてユーフラテス川をはさんで、ローマとパルティアが向き合う構図ができあがります。前53年の【カルラエの戦い】では、パルティアの騎兵がローマ軍を破り、三頭政治の一角クラッススが戦死しました。", "インドでは、前2世紀初めごろにマウリヤ朝が滅び、再び分裂の時代に入りました。西北インドには、バクトリアのギリシア人や、中央アジアから移動してきたイラン系の遊牧民【サカ人】などが進出しました。ギリシア人の王のなかには仏教に関心を示した者もいたと伝えられ、インドとヘレニズム世界の交流はこの時期も続いていました。", "南方のデカン高原では、前1世紀ごろに【サータヴァーハナ朝】が成立したとされ、のちにローマとの海上交易で栄えます。北インドの分裂のなかで、各地の勢力が交易の利益をめぐって成長したことが、この時期のインドの特徴です。"]}, {"t": "東アジア:前漢の成立と武帝の時代", "p": ["漢の高祖は郡国制を採用しましたが、地方の諸侯王の力が強くなると、中央はその領地を削ろうとしました。これに反発して前154年に起こったのが【呉楚七国の乱】です。この反乱を鎮圧したことで諸侯王の力は弱まり、事実上、郡県制に近い中央集権体制が実現しました。", "前141年に即位した【武帝】の時代に、前漢は最盛期を迎えます。武帝は、地方長官が人物を推薦して官吏とする【郷挙里選】を整え、【董仲舒】の意見を取り入れて儒学を重視したとされ、儒学の経典を教える【五経博士】をおきました。儒学はこうして国家の学問として重んじられるようになり、以後の中国王朝の政治理念の柱となっていきます。", "対外的には、武帝は高祖以来の和親策を改め、匈奴に対して攻勢に出ました。将軍の【衛青】や【霍去病】が匈奴を破り、河西地方に【敦煌郡】などの4郡をおいて西域への通路を確保しました。また匈奴を挟み撃ちにするための同盟相手を求めて、【張騫】を【大月氏】に派遣しました。同盟は実現しませんでしたが、張騫の旅によって西域の事情が初めて中国に詳しく伝わり、東西交流の道が開かれました。武帝はさらに、名馬【汗血馬】を求めて【大宛(フェルガナ)】に遠征軍を送りました。", "南方では前111年に【南越】を滅ぼしてベトナム北部までを支配し、【日南郡】を含む南海9郡をおきました。東方では前108年に【衛氏朝鮮】を滅ぼし、【楽浪郡】などの4郡をおきました。こうして漢の支配は、中央アジア・ベトナム・朝鮮半島にまで広がりました。", "しかし、たびかさなる遠征は国家財政を苦しめました。武帝は【塩・鉄の専売】を行い、物資の輸送と価格を調整する【均輸】【平準】を実施して財源を確保しました。また【五銖銭】を発行しました。これらの政策は財政を一時的に立て直しましたが、民衆の負担は重くなり、のちには豪族の成長や外戚の台頭をまねくことになります。歴史家【司馬遷】は、この時代に中国最初の通史である『史記』を著し、人物の伝記を中心に歴史を描く【紀伝体】という形式を確立しました。"]}, {"t": "内陸アジア・東南アジア・日本列島", "p": ["匈奴は冒頓単于以来、モンゴル高原を支配する強大な遊牧国家でしたが、武帝の攻撃によって打撃を受け、前1世紀半ばには内紛から東西に分裂しました。このうち東匈奴は漢に服属するようになります。遊牧国家と中国王朝の力関係が、この時代に大きく変化したのです。", "東南アジアの北部ベトナムでは、前4世紀ごろから、青銅製の太鼓【銅鼓】で知られる【ドンソン文化】が栄えていました。銅鼓は東南アジアの広い地域で見つかっており、海や川を通じた交流があったことを示しています。前漢がベトナム北部に郡をおくと、この地域は中国の直接支配のもとに入ることになりました。", "日本列島は弥生時代にあたり、稲作と金属器が広がっていました。中国の歴史書『漢書』地理志には、倭人が100あまりの国に分かれ、定期的に楽浪郡に使いを送っていたことが記されています。武帝による楽浪郡の設置は、日本列島が中国の歴史書に記録されるきっかけとなったのです。"]}, {"t": "世界のつながり:シルクロードと東西二大帝国", "p": ["この時代を横に見ると、ユーラシアの東西の端に、ほぼ同じ時期に二つの大帝国が形づくられたことがわかります。西のローマは前27年に帝政に移り、地中海全体を一つの国家として支配するようになりました。東の前漢は武帝のもとで領土を大きく広げ、中央アジアからベトナム、朝鮮半島に至る広い地域を支配しました。", "そして、この二つの帝国のあいだを結ぶ交易路が、本格的に動き始めました。張騫の派遣と河西4郡の設置によって、中国から中央アジアのオアシス都市をつなぐ【オアシスの道】(いわゆる【シルクロード】)が開かれ、中国の【絹】が西方へ、西方の馬・ブドウ・ウマゴヤシなどが中国へと伝わったとされます。その中間で交易を仲介し、利益を得たのがパルティアでした。ローマとパルティアの対立、漢と匈奴の対立は、いずれもこの東西交易路の支配をめぐる争いという側面を持っていました。", "一方、二つの帝国の内部には共通する問題もありました。ローマでは征服によって大土地所有が広がり中小農民が没落し、漢でも遠征の負担と財政政策のなかで豪族が成長し、農民の没落が進みました。大帝国の繁栄が、同時に社会の不安定さを生み出していたのです。次のページでは、この二大帝国がどのように安定期を迎え、どのような問題を抱えていくのかを見ていきます。", "なお、アメリカ大陸ではこのころ、メキシコ高原でのちの大都市【テオティワカン】の建設が始まり、マヤ地域でも都市の形成が進んでいました。ユーラシアとはまったく別の場所で、独自の都市文明が成長を続けていたことも忘れないようにしましょう。"]}], "points": ["ローマの征服→ラティフンディア・中小農民の没落→グラックス兄弟の改革失敗→内乱の1世紀、という因果の流れ", "マリウスの兵制改革によって軍隊が将軍の私兵化した", "第1回三頭政治(ポンペイウス・クラッスス・カエサル)と第2回三頭政治(オクタウィアヌス・アントニウス・レピドゥス)の区別", "アクティウムの海戦(前31年)→プトレマイオス朝滅亡(前30年)でヘレニズム時代が終わる", "元首政(プリンキパトゥス)は共和政の形式を残した事実上の帝政", "呉楚七国の乱の鎮圧で漢の中央集権化が進んだ", "武帝の政策:郷挙里選・五経博士・張騫の派遣・河西4郡・南海9郡・朝鮮4郡・塩鉄専売・均輸・平準・五銖銭", "司馬遷『史記』は紀伝体"], "check": [["没落した中小農民の土地を集め、奴隷を使って経営された大農場を何という?", "ラティフンディア"], ["大土地所有を制限して自作農を再建しようとした兄弟は?", "グラックス兄弟"], ["無産市民を志願兵とする兵制改革を行った平民派の政治家は?", "マリウス"], ["前31年、オクタウィアヌスがアントニウスとクレオパトラを破った戦いは?", "アクティウムの海戦"], ["前53年、クラッススがパルティア軍に敗れて戦死した戦いは?", "カルラエの戦い"], ["前154年に起こった、諸侯王の反乱は?", "呉楚七国の乱"], ["武帝が匈奴挟撃のために大月氏に派遣した人物は?", "張騫"], ["前108年に衛氏朝鮮を滅ぼして置かれた郡のうち、中心となった郡は?", "楽浪郡"], ["中国最初の通史『史記』の著者は?", "司馬遷"], ["北ベトナムで栄え、銅鼓で知られる文化は?", "ドンソン文化"]], "related": ["y_bc4", "y_1", "t_ro", "t_ir", "t_in", "t_cn", "t_mn", "t_vn", "t_kr", "j_yayoi"], "n": 4278}, "y_1": {"title": "1世紀の世界", "span": "1〜100年", "year": 50, "lead": "ローマ帝国はパクス=ロマーナとよばれる長い平和の時代に入り、その支配下のパレスチナでキリスト教が誕生しました。東では王莽の新をはさんで後漢が成立し、中央アジアから北インドではクシャーナ朝が興り、インド洋では季節風を利用した海の交易が盛んになりました。", "flow": ["8年 前漢の外戚王莽が帝位を奪い新を建てる→復古的な政治が混乱を招く", "18年ごろ 赤眉の乱など各地で反乱→新の滅亡", "25年 劉秀(光武帝)が漢を再興(後漢)→都は洛陽", "30年ごろ イエスがイェルサレムで処刑されたとされる→弟子たちが復活を信じ布教を開始", "40年 ベトナムで徴姉妹が後漢に対して反乱", "1世紀半ば パウロらの伝道でキリスト教がローマ帝国各地へ広がる", "57年 光武帝が倭の奴国に印綬を与える", "64年 ローマ大火→ネロ帝がキリスト教徒を迫害", "1世紀 クシャーナ朝が成立→西北インドから中央アジアを支配", "70年 ローマ軍がイェルサレムを破壊", "79年 ヴェスヴィオ火山の噴火でポンペイが埋没", "91年 班超が西域都護となる→97年部下の甘英を大秦に派遣", "96年 ネルウァが即位→五賢帝時代の始まり"], "sync": [["ヨーロッパ・地中海", "アウグストゥスの元首政→ユリウス=クラウディウス朝(ネロ)→フラウィウス朝→五賢帝時代へ、パクス=ロマーナ"], ["西アジア", "パルティアがローマとアルメニアなどをめぐって対立、パレスチナでキリスト教が成立"], ["南アジア", "クシャーナ朝の成立、デカンのサータヴァーハナ朝、季節風貿易でローマと交易"], ["東南アジア", "メコン川下流に扶南が興る、ベトナム北部は後漢の支配(徴姉妹の反乱)"], ["東アジア・内陸アジア", "王莽の新→後漢の成立、匈奴の南北分裂、班超の西域経営、倭の奴国の朝貢"], ["アメリカ・アフリカ", "テオティワカンの発展、ペルー北部でモチェ文化/エチオピアにアクスム王国が興る"]], "secs": [{"t": "ローマ帝国:パクス=ロマーナの始まり", "p": ["アウグストゥスが始めた元首政のもとで、ローマ帝国はおよそ200年にわたる長い平和の時代を迎えました。これを【パクス=ロマーナ(ローマの平和)】とよびます。アウグストゥスは内乱で疲れた社会を立て直すため、軍隊を国境に配置し、属州の統治を整えました。", "アウグストゥスの死後は、その一族による【ユリウス=クラウディウス朝】が続きました。なかでも【ネロ】は暴君として知られ、64年にローマで大火が起こると、その責任をキリスト教徒に負わせて迫害しました。ネロの死後には帝位をめぐる内乱が起こり、これを収めた【ウェスパシアヌス】が【フラウィウス朝】を開きました。この時代には円形闘技場【コロッセウム】の建設が始められています。", "ローマの支配は、各地に建設された都市を拠点としていました。属州の有力者にも市民権が与えられ、都市には浴場・水道・劇場などが整えられ、ローマ風の生活様式が広まりました。各地を結ぶ道路網も整備され、「すべての道はローマに通ず」という言葉が生まれるほどでした。のちのロンドン、パリ、ウィーンなど、ヨーロッパの多くの都市は、ローマの軍営地や植民都市に起源をもちます。", "79年には南イタリアの【ヴェスヴィオ火山】が噴火し、都市【ポンペイ】が火山灰に埋もれました。『博物誌』を著した【プリニウス】は、このとき救援に向かう途中で亡くなりました。ポンペイの遺跡は、当時のローマ人の暮らしを今に伝えています。96年に即位した【ネルウァ】から、帝国の最盛期とされる【五賢帝】の時代が始まります。"]}, {"t": "西アジア:キリスト教の誕生", "p": ["ローマの支配下に入ったパレスチナでは、ユダヤ人のあいだで、ローマの支配への不満と、救世主の出現を待ち望む気持ちが高まっていました。一方、ユダヤ教の指導層である【パリサイ派】は、律法を形式的に厳しく守ることを重んじていました。", "このような状況のなかで、【イエス】は、神の愛は貧しい人や罪人を含むすべての人に向けられていると説き、律法の形式にとらわれず、神を信じ隣人を愛することの大切さを教えました。イエスはユダヤ教の指導者から危険視され、ローマ総督【ピラト】によって十字架にかけられて処刑されたとされます。しかし弟子たちは、イエスが復活したと信じ、イエスこそが救世主【キリスト】であるとする信仰を広めました。これが【キリスト教】の始まりです。", "最初の弟子の一人【ペテロ】や、もともとはキリスト教徒を迫害していた【パウロ】は、帝国内の各地に伝道しました。とくにパウロは、ユダヤ人以外の人々(異邦人)への伝道を進め、キリスト教がユダヤ民族の枠をこえた【世界宗教】となる道を開きました。帝国内の都市には信徒の共同体である【教会】がつくられていきました。イエスの言行を記した福音書や使徒たちの手紙は、ヘレニズム時代の共通語であるコイネーで書かれ、のちに【『新約聖書』】としてまとめられました。", "キリスト教徒は、唯一の神のみを信じて、ローマの神々や皇帝を礼拝することを拒んだため、国家の秩序に反する者として、たびたび迫害を受けました。しかし、貧しい人々や女性、奴隷のあいだにも信者は増え続けました。", "パレスチナでは、66年にユダヤ人がローマに対して反乱を起こし、70年にはローマ軍がイェルサレムを破壊しました。この結果、ユダヤ人はさらに各地へ離散していくことになります。"]}, {"t": "南アジア・中央アジア:クシャーナ朝の成立", "p": ["前漢の張騫が訪れた大月氏の支配下にあったバクトリア地方では、イラン系の【クシャーン人】が自立し、1世紀に【クシャーナ朝】を建てました。クシャーナ朝は中央アジアから西北インドへと勢力を広げ、インダス川流域から中央アジアにまたがる大国となりました。", "クシャーナ朝の領域は、ローマ・パルティアと結ぶ西方の道、漢と結ぶオアシスの道、そしてインド洋に向かう南の道が交わる交通の要地にありました。このためクシャーナ朝は東西交易の利益で大いに栄え、ローマの金貨を参考にした金貨も発行しました。", "このころ西北インドの【ガンダーラ地方】では、ヘレニズム文化の影響を受けて、それまで表現されなかった仏陀の姿を彫刻で表す【仏像】がつくられ始めました。これが【ガンダーラ美術】です。また仏教の内部では、自分一人の悟りよりも、あらゆる人々の救済をめざす【大乗仏教】の考え方が広まり始めました。修行者は自らの悟りを後回しにしてでも人々を救う【菩薩】を理想としました。これらの動きは、次の2世紀のカニシカ王の時代に大きく花開きます。", "南インドでは、デカン高原の【サータヴァーハナ朝】をはじめ、各地の勢力がローマとの海上交易で利益をあげていました。"]}, {"t": "インド洋の海の道:季節風貿易と扶南", "p": ["インド洋では、夏は南西から、冬は北東から吹く【季節風(モンスーン)】を利用した航海が盛んになりました。季節風を利用すると、アラビア半島やエジプトの紅海沿岸からインドまで、外洋を一気に横断することができます。1世紀にギリシア人の航海者が著したとされる【『エリュトゥラー海案内記』】には、紅海からインド洋に至る港や取引される商品のようすが記されています。", "ローマ帝国からは金貨・ぶどう酒・ガラス器などがインドへ運ばれ、インドからは【香辛料】(とくにコショウ)・綿布・宝石などが運ばれました。南インドではローマの金貨が数多く出土しており、ローマとインドの交易がいかに盛んだったかがわかります。", "この海の道は、東南アジアを経て中国にまでつながっていました。1世紀末ごろ、メコン川の下流域には【扶南】が興りました。扶南の外港【オケオ】の遺跡からは、ローマの金貨やインドの装飾品、中国の鏡などが出土しており、扶南が東西交易の中継地として栄えたことを示しています。東南アジアには、交易とともにインドの文化や宗教が伝わり始め、各地の王権がインドの文化を取り入れていく【インド化】が進んでいきます。", "一方、ベトナム北部は後漢の支配下にあり、40年には【徴姉妹】が漢の支配に反抗して反乱を起こしましたが、後漢の将軍に鎮圧されました。"]}, {"t": "東アジア:新の混乱と後漢の成立", "p": ["前漢の後半には、皇帝の母方の親族である【外戚】や、宮廷に仕える【宦官】が政治に介入するようになりました。外戚の【王莽】は、8年に前漢を倒して【新】を建てました。王莽は、儒学の経典にある周の時代の制度を理想として、土地の国有化や奴隷の売買禁止など、現実を無視した急激な復古政策を進めました。その結果、社会は大混乱し、農民反乱である【赤眉の乱】などが各地で起こって、新はわずか15年ほどで滅びました。", "混乱のなかから、漢の皇族の一族である【劉秀】が、各地の豪族の支持を受けて勢力を広げ、25年に漢を再興しました。これが【後漢】で、劉秀は【光武帝】とよばれます。都は【洛陽】におかれました。後漢は豪族の連合政権という性格を持ち、地方の豪族が大きな力を持っていました。57年、光武帝は日本列島の【倭の奴国】の使いに【印綬】を与えました。福岡県の志賀島で発見された「漢委奴国王」の金印は、このときのものとされています。", "北方では、匈奴が48年に南北に分裂しました。南匈奴は後漢に服属し、北匈奴は後漢の攻撃を受けて西方へと移動していきました。後漢は西域にも進出し、【班超】が【西域都護】となって西域の50あまりの国を服属させたとされます。班超は97年、部下の【甘英】を【大秦国】(ローマ帝国)に派遣しましたが、甘英はパルティアの西の海岸まで達したところで引き返したと伝えられます。", "仏教は、紀元前後から1世紀ごろにかけて、西域を通じて中国に伝わったとされます。朝鮮半島北部では、前1世紀ごろに成立したとされる【高句麗】が勢力を伸ばし始めていました。"]}, {"t": "アメリカ・アフリカ", "p": ["メキシコ高原では、【テオティワカン】が大都市として発展していました。巨大な【太陽のピラミッド】や【月のピラミッド】を中心に、計画的に区画された都市がつくられ、多くの人々が住んでいました。テオティワカンの影響は、メソアメリカの広い地域におよびました。", "南アメリカのペルー北部の海岸では、【モチェ文化】が栄え、すぐれた土器や金属工芸を残しました。ペルー南部の海岸では、地上に巨大な絵を描いたことで知られる【ナスカ文化】も栄えました。アンデスの人々は、乾燥した海岸地帯で灌漑を行い、独自の農耕文明を発展させていました。", "アフリカでは、エチオピア高原に【アクスム王国】が興りました。アクスムは紅海の交易に参加し、ローマ帝国やインドとの交易で栄えました。季節風貿易の広がりは、アフリカ東部の歴史にも大きな影響を与えていたのです。"]}, {"t": "世界のつながり:陸と海の道でつながる帝国", "p": ["1世紀の世界を横に見ると、西のローマ帝国、中央のパルティアとクシャーナ朝、東の後漢という大国がユーラシアに並んでいたことがわかります。これらの国々は、陸の【オアシスの道】と、季節風を利用した海の道によって結ばれていました。班超が甘英を大秦国に派遣したことは、東の後漢が西のローマを意識していたことを示しています。ただし、パルティアは東西交易の仲介による利益を守るため、ローマと漢が直接結びつくことを好まなかったと考えられています。", "この時代は、交易とともに宗教が広がり始めた時代でもあります。ローマ帝国内では、帝国の道路と都市のネットワークにのってキリスト教が広がり、ユーラシア中央部では、クシャーナ朝の繁栄のなかで大乗仏教が育ち、その仏教が中国へと伝わり始めました。海の道を通じては、インドの文化が東南アジアへと伝わり始めていました。つまり、のちの世界宗教が国境をこえて広がる条件が、この1世紀に整い始めたのです。", "また、同じ時期の東西で、国家の性格が似ていることにも注目しましょう。ローマのアウグストゥスは共和政の形式を残しつつ実権を握り、後漢の光武帝は豪族の支持を受けて王朝を再建しました。どちらも、それまでの混乱を収めて安定を実現しましたが、その安定は地方の有力者(ローマでは都市の有力者、後漢では豪族)との協力に支えられていました。この点が、次の2世紀・3世紀にどのような変化をもたらすのかを、続くページで確かめていきましょう。"]}], "points": ["パクス=ロマーナはアウグストゥスから五賢帝時代までのおよそ200年間", "ネロ帝は64年のローマ大火後にキリスト教徒を迫害した", "イエスの処刑→弟子たちの復活信仰→ペテロ・パウロの伝道→世界宗教化、『新約聖書』はコイネーで記された", "クシャーナ朝は東西交易路の交差点で栄え、ガンダーラで仏像が生まれた", "季節風貿易と『エリュトゥラー海案内記』、南インドのローマ金貨、扶南のオケオ", "王莽の新は周を理想とした復古政策で混乱し、赤眉の乱で滅びた", "光武帝(劉秀)による後漢の成立(25年)と、57年の倭の奴国への印綬", "班超の西域経営と甘英の大秦国への派遣(97年)"], "check": [["79年のヴェスヴィオ火山の噴火で埋もれた都市は?", "ポンペイ"], ["64年のローマ大火の後、キリスト教徒を迫害した皇帝は?", "ネロ"], ["ユダヤ人以外の人々への伝道を進め、キリスト教の世界宗教化に貢献した人物は?", "パウロ"], ["1世紀に中央アジアから西北インドにかけて成立した王朝は?", "クシャーナ朝"], ["ヘレニズムの影響を受けて仏像がつくられた西北インドの地方は?", "ガンダーラ地方"], ["1世紀にギリシア人が著したとされる、インド洋交易の案内書は?", "『エリュトゥラー海案内記』"], ["8年に前漢を倒して新を建てた人物は?", "王莽"], ["25年に後漢を建てた人物は?", "劉秀(光武帝)"], ["班超が大秦国に派遣した部下は?", "甘英"], ["エチオピア高原に興り、紅海の交易で栄えた王国は?", "アクスム王国"]], "related": ["y_bc2", "y_2", "t_ro", "t_ps", "t_in", "t_id", "t_vn", "t_cn", "t_af", "t_la", "j_yayoi"], "n": 4064}, "y_2": {"title": "2世紀の世界", "span": "101〜200年", "year": 150, "lead": "ローマ帝国は五賢帝のもとで最大の領土と繁栄を迎え、クシャーナ朝はカニシカ王のもとで仏教文化を花開かせました。ローマの使者とされる人物が後漢の日南郡に至るなど、ユーラシアの東西が最もつながった時代ですが、世紀の後半には後漢で黄巾の乱が起こり、ローマでも動揺の兆しが現れます。", "flow": ["105年 後漢の宦官蔡倫が製紙法を改良したとされる→紙の普及", "117年ごろ トラヤヌス帝のもとでローマ帝国の領土が最大に", "2世紀前半 ハドリアヌス帝が領土拡大をやめ、ブリタニアに長城を築いて防衛を重視", "2世紀 クシャーナ朝のカニシカ王が仏教を保護→ガンダーラ美術と大乗仏教の発展", "2世紀後半 後漢で宦官が官僚を弾圧する党錮の禁→政治の混乱", "166年 大秦王安敦の使者とされる者が日南郡に至る", "2世紀後半 マルクス=アウレリウス=アントニヌス帝の時代に国境での戦いが続く", "180年 マルクス=アウレリウス帝の死→五賢帝時代の終わり", "184年 張角の太平道による黄巾の乱→後漢は群雄割拠の状態に", "2世紀末 ベトナム中部にチャンパー(林邑)が成立したとされる"], "sync": [["ヨーロッパ・地中海", "五賢帝時代(トラヤヌスの最大領土、ハドリアヌスの防衛政策、マルクス=アウレリウスの治世)→180年以降の動揺"], ["西アジア", "ローマとパルティアがメソポタミア・アルメニアをめぐってたびたび戦う"], ["南アジア", "クシャーナ朝カニシカ王の最盛期、ガンダーラ美術、大乗仏教(ナーガールジュナ)、サータヴァーハナ朝の海上交易"], ["東南アジア", "扶南が海の道の中継地として繁栄、2世紀末にチャンパーが成立"], ["東アジア", "後漢の外戚・宦官の専横、党錮の禁、製紙法の改良→184年黄巾の乱、倭国大乱"], ["アメリカ・アフリカ", "テオティワカンの繁栄、マヤ地域の都市の成長/アクスム王国の紅海交易"]], "secs": [{"t": "ローマ帝国:五賢帝時代の繁栄", "p": ["96年のネルウァから180年のマルクス=アウレリウス=アントニヌスまでの5人の皇帝を【五賢帝】とよびます。この時代の皇帝は、血縁ではなく、元老院の議員のなかから有能な人物を養子に迎えて後継者とすることが多く、これが政治の安定をもたらしたとされます。ローマ帝国は、このころ最盛期を迎えました。", "五賢帝の2人目の【トラヤヌス】は、属州出身の最初の皇帝として知られます。彼はドナウ川の北の【ダキア】(現在のルーマニア)を征服し、東方ではパルティアに遠征してメソポタミアにまで進出し、帝国の領土は【最大】となりました。", "しかし、次の【ハドリアヌス】は、広がりすぎた領土を維持することは難しいと判断し、メソポタミアなどの征服地を放棄して、防衛を重視する政策に転じました。ブリタニア(現在のイギリス)北部に築かれた【ハドリアヌスの長城】は、この方針を象徴しています。ハドリアヌスは帝国の各地を視察してまわり、属州の統治に力を注ぎました。", "その次の【アントニヌス=ピウス】の時代は比較的平穏でしたが、5人目の【マルクス=アウレリウス=アントニヌス】の時代になると、ドナウ川方面のゲルマン人の侵入や、東方でのパルティアとの戦いが続きました。ストア派の哲学者でもあった皇帝は、陣中で『自省録』を書き残しました。180年に彼が亡くなると、実子の【コンモドゥス】が後を継ぎましたが、政治は乱れ、帝国は動揺の時代へと向かいます。"]}, {"t": "ローマの文化と社会", "p": ["ローマの文化は、ギリシアの文化を受けつぎながら、法律や土木技術などの実用的な分野ですぐれた成果を生みました。とくに【ローマ法】は、はじめはローマ市民だけに適用される【市民法】でしたが、帝国が拡大するにつれて、帝国内のすべての人々に適用される【万民法】としての性格を強めていきました。ローマ法は、のちに6世紀のユスティニアヌス帝によって集大成され、近代ヨーロッパの法の基礎となります。", "土木技術では、各地に建設された道路・水道橋・浴場・闘技場などが知られています。建築では、ハドリアヌス帝のもとで再建された【パンテオン】(万神殿)が有名です。", "学問では、ギリシア人の学者も活躍しました。2世紀の【プトレマイオス】は、地球が宇宙の中心にあるとする【天動説】を体系化し、その説は中世のヨーロッパやイスラーム世界で長く受け入れられました。また、ギリシア人の【プルタルコス】は、ギリシアとローマの英雄を比べた『対比列伝(英雄伝)』を著しました。ローマ人の歴史家【タキトゥス】は、1世紀末から2世紀初めにかけて活躍し、ゲルマン人の社会を記した『ゲルマニア』を著しました。", "一方、繁栄の陰で社会の変化も進んでいました。パクス=ロマーナのもとで大規模な征服戦争が減ると、新たな奴隷の供給が減り、奴隷を使ったラティフンディアの経営は難しくなっていきました。かわって、土地を小作人に貸して耕作させる方法が広がっていきます。これは3世紀以降の【コロナトゥス】へとつながる変化です。"]}, {"t": "西アジア:ローマとパルティアの抗争", "p": ["ユーフラテス川をはさんで向き合うローマとパルティアは、2世紀にもたびたび戦いました。争いの焦点となったのは、両国のあいだに位置する【アルメニア】と、豊かな【メソポタミア】です。トラヤヌス帝はパルティアに遠征して都クテシフォンを占領し、メソポタミアを一時属州としましたが、次のハドリアヌス帝はこれを放棄しました。2世紀後半にもローマ軍はクテシフォンを攻撃しています。", "この長い戦いは、パルティアの国力を少しずつ奪っていきました。パルティアは各地の有力な貴族の力が強い国家で、王権はもともと強くありませんでした。ローマとの戦いで弱ったパルティアは、3世紀に入ると、イラン南部から興ったササン朝によって倒されることになります。一方、ローマにとっても東方の戦争は大きな負担でした。東方遠征から帰った軍隊が疫病を持ち帰り、帝国内で大流行したとも伝えられています。東西の交易で栄えた両国の争いが、それぞれの衰えにつながっていったのです。"]}, {"t": "南アジア・中央アジア:カニシカ王と仏教文化", "p": ["クシャーナ朝は、2世紀の【カニシカ王】のころ最盛期を迎えました。都は西北インドの【プルシャプラ】(現在のペシャワール付近)におかれ、領土は中央アジアからガンジス川中流域にまでおよびました。カニシカ王は仏教を厚く保護し、仏典の結集(第4回とされる)を支援したと伝えられます。", "この時代、ガンダーラ地方では【ガンダーラ美術】が大きく発展しました。ギリシア・ローマの彫刻の技法の影響を受けた仏像は、彫りの深い顔立ちや、波打つような衣のひだなどに特徴があります。一方、ガンジス川流域の【マトゥラー】でも、インド独自の様式による仏像がつくられました。", "思想の面では、【大乗仏教】が発展しました。大乗とは「大きな乗り物」という意味で、出家者だけでなく、多くの人々を救済することをめざします。大乗仏教の側は、出家者が自分の悟りを求める従来の仏教を、小さな乗り物という意味の【小乗仏教】とよんで批判しました(現在では【上座部仏教】とよぶのが一般的です)。2世紀ごろの【ナーガールジュナ(竜樹)】は、すべてのものには固定した実体がないとする【空】の思想を説き、大乗仏教の理論を確立したとされます。", "大乗仏教はクシャーナ朝の支配する中央アジアを経て、中国・朝鮮・日本へと伝わり、【北伝仏教】ともよばれます。これに対して、スリランカから東南アジアに伝わった上座部仏教は【南伝仏教】ともよばれます。仏教がどの道を通ってどこへ広がったのかは、横の視点で重要なポイントです。"]}, {"t": "東アジア:後漢の動揺と黄巾の乱", "p": ["後漢では、105年に宦官の【蔡倫】が製紙法を改良したとされ、それまでの木簡・竹簡や絹に代わって、紙が書写の材料として普及し始めました。紙はのちにイスラーム世界を経てヨーロッパに伝わり、世界の文化に大きな影響を与えることになります。学問の面では、儒学の経典の字句の意味を詳しく解釈する【訓詁学】が発達し、【鄭玄】が集大成しました。", "しかし、政治の面では、幼い皇帝が続いたこともあり、外戚と宦官が権力を争うようになりました。宦官に対して批判を強めた官僚や学者たちは、2世紀後半に宦官によって弾圧されました。これを【党錮の禁】といいます。政治の腐敗が進む一方で、地方では【豪族】が大土地所有を広げ、多くの農民を支配下においていました。", "重い負担と災害、疫病に苦しむ農民のあいだでは、宗教結社が急速に広まりました。【張角】が開いた【太平道】は、病気の治療などを通じて信者を集め、184年に大規模な反乱を起こしました。信者たちが黄色の頭巾を目印にしたことから、これを【黄巾の乱】といいます。また四川地方では、【五斗米道】とよばれる宗教結社も勢力を持ちました。これらはのちの【道教】の源流となりました。", "黄巾の乱は鎮圧されましたが、その過程で各地の豪族や将軍が軍事力を持って自立し、後漢の皇帝はもはや名目だけの存在となりました。こうした群雄のなかから、華北で勢力を広げたのが【曹操】です。こうして中国は、次の3世紀の三国時代へと進んでいきます。", "後漢の混乱は周辺にも影響しました。中国の歴史書によると、2世紀後半には日本列島で【倭国大乱】とよばれる争いが起こったとされ、その後、【卑弥呼】が女王に立てられたと伝えられます。北方の草原では、北匈奴が西へ去ったあと、【鮮卑】が勢力を広げていました。"]}, {"t": "東南アジア:海の道の発展", "p": ["インド洋から南シナ海にかけての海の道は、2世紀にさらに発展しました。メコン川下流域の【扶南】は、インドと中国を結ぶ中継地として栄えました。当時の船は、マレー半島を陸路で横断するルートなどを利用しながら、インドと中国のあいだを行き来したと考えられています。", "166年には、ローマ皇帝【大秦王安敦】の使者を名乗る者が、ベトナム中部の後漢の【日南郡】に到着したことが、中国の歴史書『後漢書』に記されています。大秦王安敦は、マルクス=アウレリウス=アントニヌス帝のこととされます。この使者がローマ皇帝の正式な使節であったかどうかははっきりせず、商人だった可能性も指摘されていますが、ユーラシアの東西の両端が海の道によってつながっていたことを示す出来事として重要です。", "2世紀の末ごろには、後漢の支配が弱まるなかで、ベトナム中部にチャム人の国【チャンパー】(中国名は【林邑】)が成立したとされます。チャンパーはその後、インド文化を取り入れながら、海上交易で栄えていきます。"]}, {"t": "世界のつながり:最もつながった時代と同時の動揺", "p": ["2世紀の世界を横に見ると、ローマ帝国・パルティア・クシャーナ朝・後漢という4つの大国が、ユーラシアの西から東までを帯のように並んで支配していたことがわかります。陸のオアシスの道と海の道によって、ローマのガラス器や金貨、インドの香辛料や綿布、中国の絹などが行き交いました。大秦王安敦の使者の来訪は、この時代のつながりを象徴する出来事です。", "交易路は宗教や美術の伝播の道でもありました。ヘレニズムの彫刻の技法がガンダーラで仏教と出会って仏像が生まれ、その仏教が中央アジアを経て中国へと伝わりました。東南アジアでは、インドの文化を取り入れた国々が海の道に沿って成長しました。ローマ帝国内では、キリスト教がゆっくりと信者を増やしていました。", "ところが2世紀の後半になると、東西の大帝国はほぼ同じ時期に動揺し始めます。ローマでは国境での戦いが続き、五賢帝時代が終わると政治が乱れました。後漢では宦官の専横と党錮の禁による政治の腐敗、豪族の成長と農民の困窮が重なり、黄巾の乱が起こりました。どちらの帝国でも、中央の支配がゆるんで地方の有力者や軍隊が力をつけていく点が共通しています。この変化は、3世紀に両帝国がそろって大きな危機を迎える前ぶれでした。", "アメリカ大陸では、テオティワカンが大都市として繁栄を続け、マヤ地域でも都市が成長していました。アフリカのアクスム王国は、紅海の交易を通じてローマやインドと結びついていました。ユーラシアの外側でも、それぞれの文明がゆっくりと成熟していった時代でした。"]}], "points": ["五賢帝:ネルウァ→トラヤヌス(最大領土)→ハドリアヌス(防衛重視・長城)→アントニヌス=ピウス→マルクス=アウレリウス=アントニヌス(『自省録』)", "ローマ法は市民法から万民法へ。のちにユスティニアヌス帝が集大成", "プトレマイオスの天動説、プルタルコス『対比列伝』、タキトゥス『ゲルマニア』", "カニシカ王(都プルシャプラ)と仏教の保護、ガンダーラ美術とマトゥラー", "大乗仏教とナーガールジュナの空の思想、北伝仏教と南伝仏教の区別", "166年の大秦王安敦の使者(日南郡)は『後漢書』に記されている", "後漢の衰退:外戚・宦官の争い→党錮の禁→184年黄巾の乱(張角・太平道)", "蔡倫の製紙法の改良(105年)は、のちに西方へ伝わる"], "check": [["ローマ帝国の領土を最大にした五賢帝の皇帝は?", "トラヤヌス"], ["ブリタニア北部に長城を築き、防衛を重視した皇帝は?", "ハドリアヌス"], ["ストア派の哲学者でもあり、『自省録』を著した皇帝は?", "マルクス=アウレリウス=アントニヌス"], ["2世紀に天動説を体系化した学者は?", "プトレマイオス"], ["クシャーナ朝の最盛期の王で、仏教を保護したのは?", "カニシカ王"], ["空の思想を説き、大乗仏教の理論を確立した人物は?", "ナーガールジュナ(竜樹)"], ["166年に日南郡に至った使者を送ったとされる「大秦王安敦」とは誰のことか?", "マルクス=アウレリウス=アントニヌス"], ["2世紀後半、宦官が官僚・学者を弾圧した事件は?", "党錮の禁"], ["184年に張角が起こした農民反乱は?", "黄巾の乱"], ["105年ごろ製紙法を改良したとされる後漢の宦官は?", "蔡倫"]], "related": ["y_1", "y_3", "t_ro", "t_in", "t_id", "t_vn", "t_cn", "t_mn", "t_uk"], "n": 4063}, "y_3": {"title": "3世紀の世界", "span": "201〜300年", "year": 250, "lead": "3世紀は、ユーラシアの東西で大帝国が同時に危機を迎えた時代です。後漢が滅んで中国は三国に分裂し、ローマ帝国は軍人皇帝の乱立と外敵の侵入に苦しみました。その一方で、イランではササン朝が興ってローマに対抗し、メソアメリカではマヤ文明が古典期に入るなど、新しい勢力も成長しました。", "flow": ["208年 赤壁の戦いで曹操が孫権・劉備の連合軍に敗れる→天下三分の形勢", "212年 カラカラ帝が帝国内の全自由民にローマ市民権を与える", "220年 曹丕が後漢を滅ぼして魏を建てる→蜀・呉も成立し三国時代へ", "224年 アルダシール1世がパルティアを倒しササン朝を建てる", "235年 ローマで軍人皇帝時代が始まる→皇帝の乱立と帝国の混乱", "239年 邪馬台国の卑弥呼が魏に使いを送り「親魏倭王」の称号を受ける", "260年 エデッサの戦いでササン朝のシャープール1世がローマ皇帝ウァレリアヌスを捕虜にする", "263年 魏が蜀を滅ぼす→265年司馬炎が魏を倒して晋(西晋)を建てる", "280年 晋が呉を滅ぼして中国を統一", "284年 ディオクレティアヌス帝が即位→専制君主政の始まり"], "sync": [["ヨーロッパ・地中海", "カラカラ帝の市民権拡大→軍人皇帝時代(235〜284年)、ゲルマン人の侵入、コロナトゥスの広まり→ディオクレティアヌスの即位"], ["西アジア", "パルティアの滅亡とササン朝の成立、シャープール1世のローマへの勝利、ゾロアスター教の重視とマニ教の誕生"], ["南アジア", "クシャーナ朝がササン朝に圧迫されて衰退、インドは分裂状態に"], ["東アジア", "後漢の滅亡→魏・呉・蜀の三国時代→西晋の統一、九品中正と屯田制/朝鮮では高句麗が発展"], ["日本列島", "邪馬台国の卑弥呼が魏に朝貢、古墳の出現"], ["アメリカ・アフリカ", "マヤ文明の古典期の始まり、テオティワカンの繁栄/アクスム王国の発展"]], "secs": [{"t": "ローマ帝国:「3世紀の危機」", "p": ["五賢帝時代が終わると、ローマ帝国では軍隊の力が強まり、皇帝の地位も軍隊の支持に左右されるようになりました。212年、【カラカラ帝】は、帝国内の【全自由民にローマ市民権】を与えました。これにより、ローマ市民であることの特別な意味は薄れ、ローマは市民の共同体から、多様な人々を皇帝が支配する帝国へと性格を変えていきました。", "235年からおよそ50年間は、各地の軍隊がそれぞれ自分たちの司令官を皇帝に立てて争った【軍人皇帝時代】とよばれます。この間に20人以上の皇帝が次々と立てられ、その多くは暗殺や戦死によって短期間で姿を消しました。国内が混乱するなかで、北からは【ゲルマン人】がライン川・ドナウ川を越えて侵入し、東からはササン朝が攻めこみました。260年には、皇帝【ウァレリアヌス】がササン朝との戦い(【エデッサの戦い】)で捕虜になるという、前例のない事態も起こりました。", "戦争の費用と軍隊への給与をまかなうため、重い税が課され、質の悪い貨幣が大量に発行されて物価が上がりました。都市の商工業は衰え、有力者は都市を離れて農村の大所領に移っていきました。こうした大所領では、奴隷に代わって、土地を借りて耕作する小作人【コロヌス】が労働力の中心となりました。コロヌスはしだいに土地を離れる自由を失っていきます。この経営の仕組みを【コロナトゥス】といい、のちの中世ヨーロッパの農奴制の源流の一つとされます。", "この危機を収めたのが、284年に即位した【ディオクレティアヌス帝】です。彼は帝国を東西に分け、それぞれに正帝と副帝をおく【四帝分治制(テトラルキア)】をしき、軍隊と官僚制を整えました。また皇帝を神のように崇拝させる儀礼を取り入れ、元首政に代わる【専制君主政(ドミナトゥス)】を始めました。これにより帝国は立ち直りますが、その皇帝崇拝を拒むキリスト教徒は、4世紀初めに大規模な迫害を受けることになります。"]}, {"t": "西アジア:ササン朝の成立", "p": ["イラン高原からメソポタミアを支配していたパルティアは、ローマとの長い戦いで弱まっていました。224年、イラン南部のペルシス地方から興った【アルダシール1世】がパルティアを倒し、【ササン朝】を建てました。都はパルティアと同じ【クテシフォン】です。ササン朝は、かつてのアケメネス朝の後継者であることを強く意識し、イラン人の伝統的な文化の復興をめざしました。", "2代目の【シャープール1世】は、西ではローマと戦い、260年のエデッサの戦いでローマ皇帝ウァレリアヌスを捕虜にしました。この勝利を記念する岩壁の浮き彫りが現在も残っています。東では、クシャーナ朝を攻撃してその領土の一部を支配下に入れました。こうしてササン朝は、ローマと並ぶ西アジアの大国となりました。", "宗教では、ササン朝は【ゾロアスター教】を重んじ、のちに国教としました。ゾロアスター教の教典【『アヴェスター』】がまとめられたのもこの王朝の時代とされます。一方、3世紀には【マニ】が、ゾロアスター教・キリスト教・仏教を融合させた【マニ教】を開きました。マニ教は一時シャープール1世の保護を受けたともいわれますが、のちに弾圧され、マニは処刑されました。しかしマニ教は西は北アフリカ、東は中央アジアや中国にまで広がり、のちにはウイグルでも信仰されました。", "ササン朝の文化は、ガラス器や銀器、織物などの工芸品を通じて東西に伝わりました。のちの時代に日本の【正倉院】に納められた宝物の中にも、ササン朝の様式の影響を受けたとされるものがあり、イランの文化がユーラシアの東の端にまで届いたことがわかります。"]}, {"t": "東アジア:三国時代から西晋の統一へ", "p": ["黄巾の乱のあと、華北で勢力を広げた【曹操】は、天下統一をめざして南へ進みましたが、208年の【赤壁の戦い】で、江南の【孫権】と、漢の皇族を名乗る【劉備】の連合軍に敗れました。この結果、中国を三つの勢力が分け合う形勢が定まりました。", "220年、曹操の子【曹丕(文帝)】は後漢の皇帝から帝位をゆずり受けて【魏】を建て、都を洛陽におきました。これに対して劉備は四川で【蜀】を、孫権は江南で【呉】を建て、【三国時代】が始まりました。魏は、戦乱で荒れた土地に農民や兵士を入植させて耕作させる【屯田制】を行い、また、地方に中正官をおいて人材を9等級に分けて推薦させる【九品中正】を始めました。しかし九品中正は、実際には有力な家柄の子弟が高い官職を独占する結果となり、のちの【門閥貴族】の形成につながりました。", "三国のなかでは、華北を支配する魏が最も強大でした。263年に魏は蜀を滅ぼしましたが、その魏でも有力な家臣の司馬氏が実権を握り、265年に【司馬炎(武帝)】が魏を倒して【晋(西晋)】を建てました。280年、晋は呉を滅ぼし、約100年ぶりに中国を統一しました。司馬炎は、農民に土地を割り当てる【占田・課田法】を行ったとされます。しかし、一族を各地の王に封じたことが、のちに王族どうしの争いである【八王の乱】を招き、統一はわずかな期間で崩れていくことになります。", "この時代の文化では、政治の混乱を避けて、老荘思想にもとづく哲学的な議論にふける【清談】が流行し、【竹林の七賢】が知られます。儒学にかわって道家の思想が知識人の心をとらえたことは、乱世の雰囲気を反映しています。"]}, {"t": "朝鮮半島と日本列島", "p": ["朝鮮半島北部では、【高句麗】が勢力を広げ、中国の郡と争っていました。3世紀の初めには、中国東北地方の公孫氏が楽浪郡の南部を分けて【帯方郡】をおき、これがのちに魏の支配下に入りました。朝鮮半島南部では、【馬韓】【辰韓】【弁韓】の小国の連合が形成されており、のちの百済・新羅・加耶につながっていきます。", "日本列島では、【邪馬台国】の女王【卑弥呼】が、239年に帯方郡を通じて魏に使いを送り、【親魏倭王】の称号と金印、銅鏡などを授けられたことが『魏志』倭人伝に記されています。卑弥呼は、三国のうち魏と結ぶことで、その権威を背景に倭国内での地位を固めようとしたと考えられます。中国の分裂と諸国の対立が、東アジアの周辺地域の外交にも影響していたのです。", "3世紀の中ごろから後半にかけて、日本列島では【前方後円墳】などの大きな古墳が出現し、各地の首長たちが連合する政治的なまとまり(のちのヤマト政権)が形づくられていきました。"]}, {"t": "南アジア・東南アジア", "p": ["インドでは、クシャーナ朝が西からササン朝に圧迫されて衰え、北インドは小国が分立する状態になりました。南インドでは、サータヴァーハナ朝も3世紀には衰退しました。インドで再び大きな統一国家が現れるのは、4世紀のグプタ朝を待たなければなりません。", "東南アジアでは、扶南が引き続き海の道の中継地として栄えていました。3世紀には、中国の三国の一つである呉が、南方の海上交易に関心を持ち、扶南に使者を送ったことが伝えられています。ベトナム中部のチャンパーも成長を続けていました。中国の分裂は、江南の王朝が南海の交易に目を向けるきっかけともなりました。", "このように3世紀の南アジアは、大きな統一国家を欠いた時代でした。しかし、地方の勢力が分立するなかでも、海上交易や仏教の活動は続いていました。南インドの港は引き続きインド洋交易の拠点となり、東南アジアとの結びつきを深めていきました。統一国家がない時代にも、交易と宗教のネットワークが地域どうしをつないでいたことは、インド史を見るうえで重要な視点です。"]}, {"t": "アメリカとアフリカ:マヤ文明の古典期", "p": ["メソアメリカでは、3世紀ごろから、ユカタン半島を中心とする【マヤ文明】が【古典期】に入ったとされます。グアテマラ北部の【ティカル】をはじめとする都市国家が、それぞれ王を頂いて並び立ち、ピラミッド型の神殿を建てました。マヤの人々は、【マヤ文字】とよばれる独自の文字を持ち、【二十進法】と【ゼロの概念】を用いて、きわめて正確な暦をつくりました。マヤ文明は鉄器や車輪を実用化しなかったことも特徴です。", "メキシコ高原では、テオティワカンが大都市として繁栄を続け、その影響はマヤ地域にもおよびました。アフリカでは、エチオピアの【アクスム王国】が紅海交易で勢力を強めていました。", "マヤ文明の都市国家は、互いに同盟を結んだり戦争をしたりしながら並び立ち、王の業績を刻んだ石碑を数多く残しました。マヤ文字が20世紀後半に大きく解読されたことで、王たちの名前や戦争の記録が明らかになってきています。一方、テオティワカンは、マヤのような王の名を記した記録をほとんど残さず、どのような政治の仕組みで治められていたのかは、まだよくわかっていません。同じメソアメリカでも、都市の性格はさまざまだったのです。"]}, {"t": "世界のつながり:東西帝国の同時危機と新勢力", "p": ["3世紀の世界を横に並べると、ユーラシアの東西の大帝国が、ほぼ同じ時期に深刻な危機に陥ったことがはっきりと見えてきます。東では後漢が220年に滅び、中国は三国時代に入りました。西ではローマ帝国が235年から軍人皇帝時代に入り、皇帝の乱立と外敵の侵入に苦しみました。", "両帝国の危機には、共通する原因がありました。第一に、中央の権力が弱まり、軍隊や地方の有力者が自立したことです。後漢では豪族や将軍が、ローマでは各地の軍隊が、それぞれ自分たちの指導者を立てて争いました。第二に、農民の没落と大土地所有の拡大です。後漢では豪族が農民を支配下におき、ローマでは有力者の大所領でコロヌスが働くようになりました。第三に、外部の勢力の圧力です。中国では北方・西方の遊牧民が華北に移り住み始め、ローマにはゲルマン人とササン朝が侵入しました。", "一方で、この時代には新しい勢力も登場しました。ササン朝はローマ皇帝を捕虜にするほどの力を示し、イランの伝統文化とゾロアスター教を重んじる国家をつくりました。宗教の面では、マニ教が生まれ、ローマ帝国内ではキリスト教が迫害にもかかわらず勢力を伸ばしました。社会不安が高まるなかで、人々が救いを求めて新しい宗教にひかれていったことは、東の中国で道教の源流となる宗教結社が広まったことと比べることができます。", "また、両帝国の危機は交易にも影響しました。陸と海の道は途絶えたわけではありませんが、東西の大帝国が安定していた2世紀に比べると、交流の担い手はササン朝やインド・東南アジアの商人へと移っていきます。そして4世紀には、ローマではコンスタンティヌス帝が、中国では遊牧民の諸国家が、それぞれ新しい時代を切り開いていくことになります。"]}], "points": ["カラカラ帝(212年)の全自由民への市民権付与", "軍人皇帝時代(235〜284年)とディオクレティアヌスの専制君主政(ドミナトゥス)・四帝分治制", "コロヌスとコロナトゥスは中世の農奴制の源流の一つ", "ササン朝:224年アルダシール1世が建国、260年シャープール1世がウァレリアヌスを捕虜(エデッサの戦い)", "ゾロアスター教の重視とマニ教(ゾロアスター教・キリスト教・仏教の融合)", "赤壁の戦い(208年)→魏(220年)・蜀・呉の三国→西晋の成立(265年)と統一(280年)", "魏の屯田制と九品中正(門閥貴族の形成につながる)", "239年卑弥呼が魏に遣使し親魏倭王の称号を受けた。マヤ文明は二十進法とゼロの概念"], "check": [["212年、帝国内の全自由民にローマ市民権を与えた皇帝は?", "カラカラ帝"], ["土地を借りて耕作し、しだいに移動の自由を失った小作人を何という?", "コロヌス"], ["284年に即位し、専制君主政を始めた皇帝は?", "ディオクレティアヌス"], ["224年にパルティアを倒してササン朝を建てた人物は?", "アルダシール1世"], ["260年、ローマ皇帝ウァレリアヌスを捕虜にしたササン朝の王は?", "シャープール1世"], ["ゾロアスター教・キリスト教・仏教を融合させた宗教は?", "マニ教"], ["208年、曹操が孫権・劉備の連合軍に敗れた戦いは?", "赤壁の戦い"], ["魏で始まった、人材を9等級に分けて推薦する官吏登用制度は?", "九品中正"], ["265年に魏を倒して晋を建てた人物は?", "司馬炎(武帝)"], ["239年に魏に使いを送った邪馬台国の女王は?", "卑弥呼"]], "related": ["y_2", "y_4", "t_ro", "t_ir", "t_in", "t_cn", "t_kr", "t_la", "j_yayoi", "j_kofun"], "n": 4205}, "y_4": {"title": "4世紀の世界", "span": "301〜400年", "year": 350, "lead": "ローマ帝国はキリスト教を公認し、やがて国教として、東西に分かれていきました。中国では遊牧民の諸勢力が華北に国を建てて西晋が滅び、江南に東晋が成立しました。インドではグプタ朝がふたたび北インドを統一し、ユーラシアの各地で遊牧民の移動と宗教の国家化が同時に進みました。", "flow": ["303年 ディオクレティアヌス帝がキリスト教徒の大迫害を始める", "4世紀初め 西晋で八王の乱→遊牧民の諸勢力が華北で自立", "311年 永嘉の乱で洛陽が陥落→316年西晋滅亡、317年司馬睿が江南に東晋を建てる", "313年 コンスタンティヌス帝がミラノ勅令でキリスト教を公認/高句麗が楽浪郡を滅ぼす", "320年 チャンドラグプタ1世がグプタ朝を建てる", "325年 ニケーア公会議→アタナシウス派を正統、アリウス派を異端とする", "330年 コンスタンティヌス帝がコンスタンティノープルに遷都", "375年 フン人の圧迫で西ゴート人が移動を開始→ゲルマン人の大移動", "378年 アドリアノープルの戦いで西ゴート人がローマ皇帝ウァレンスを敗死させる", "383年 淝水の戦いで前秦が東晋に敗れる→華北が再び分裂", "386年 鮮卑の拓跋氏が北魏を建てる", "392年 テオドシウス帝がキリスト教を国教化→395年帝国が東西に分裂"], "sync": [["ヨーロッパ・地中海", "大迫害→ミラノ勅令→ニケーア公会議→コンスタンティノープル遷都→ゲルマン人の大移動→キリスト教の国教化→東西分裂"], ["西アジア・アフリカ", "ササン朝シャープール2世がローマと抗争/アクスム王国がキリスト教を受容しメロエを滅ぼす"], ["南アジア", "グプタ朝の成立と発展(チャンドラグプタ1世・2世)、ヒンドゥー教の定着"], ["東アジア", "八王の乱→永嘉の乱で西晋滅亡→五胡十六国と東晋の対立、淝水の戦い、北魏の成立"], ["朝鮮半島・日本列島", "高句麗が楽浪郡を滅ぼす、百済・新羅の成立、広開土王の即位/ヤマト政権の発展"], ["アメリカ", "マヤ文明の古典期の都市国家(ティカルなど)、テオティワカンの繁栄"]], "secs": [{"t": "ローマ帝国:キリスト教の公認と帝国の再編", "p": ["ディオクレティアヌス帝は、皇帝崇拝を強めて帝国をまとめようとしたため、それを拒むキリスト教徒に対して、303年から最大規模の迫害を行いました。しかし、キリスト教徒はすでに帝国の各地に広がっており、迫害によってその信仰をなくすことはできませんでした。", "ディオクレティアヌスの退位後、帝位をめぐる争いを勝ち抜いた【コンスタンティヌス帝】は、313年に【ミラノ勅令】を出してキリスト教を公認しました。帝国の統一を保つためには、増え続けるキリスト教徒を敵にまわすより、味方につけるほうが得策だと考えたのです。", "ところが、公認されたキリスト教の内部では、教義をめぐる対立が起こっていました。そこでコンスタンティヌス帝は、325年に【ニケーア公会議】を開き、キリストを神と同質とする【アタナシウス派】を正統とし、キリストを神より下位の存在とする【アリウス派】を異端としました。アタナシウス派の考えは、のちに父なる神・子なるキリスト・聖霊を一体とする【三位一体説】として確立されます。異端とされたアリウス派は、その後、帝国の外のゲルマン人のあいだに広まりました。", "コンスタンティヌス帝は、330年に都を、ギリシア人の植民市であった【ビザンティオン】に移し、【コンスタンティノープル】と改称しました。東方の豊かな地域と、ササン朝やドナウ川方面の国境に近い場所に都をおくことで、帝国を守ろうとしたのです。また【ソリドゥス金貨】を発行して経済を安定させ、コロヌスを土地にしばりつけて、税を確実に取り立てられるようにしました。こうした政策は、のちのビザンツ帝国に受けつがれます。"]}, {"t": "ゲルマン人の大移動とローマ帝国の分裂", "p": ["4世紀後半、黒海の北岸に、アジア系の遊牧民【フン人】が西から進出してきました。375年、フン人に圧迫された【西ゴート人】は、ドナウ川を越えてローマ帝国の領内に移り住み始めました。これが【ゲルマン人の大移動】の始まりとされます。ゲルマン人は、それ以前から傭兵やコロヌスとして帝国内に入っていましたが、ここから集団での大規模な移動が始まりました。", "帝国内に入った西ゴート人は、ローマ側の扱いに不満を持って反乱を起こし、378年の【アドリアノープルの戦い】で、皇帝【ウァレンス】を敗死させました。ローマ軍の敗北は帝国に大きな衝撃を与えました。", "その後に即位した【テオドシウス帝】は、ゲルマン人と協定を結んで帝国内への定住を認めるなどして事態の収拾をはかりました。宗教の面では、392年にキリスト教(アタナシウス派)以外の宗教を禁止し、キリスト教を事実上の【国教】としました。古代オリンピックもこのころ終わりを迎えたとされます。そして395年、テオドシウス帝は死に際して帝国を2人の子に分け与え、ローマ帝国は【東ローマ帝国】と【西ローマ帝国】に分裂しました。以後、両者が再び一つになることはありませんでした。", "キリスト教が国家の宗教となったことで、教会の組織も整えられていきました。とくにローマ・コンスタンティノープル・アレクサンドリア・アンティオキア・イェルサレムの5つの教会が重要な地位を占めました。また、正統の教義を理論づけた学者たちは【教父】とよばれ、その代表である【アウグスティヌス】は、4世紀末から5世紀初めにかけて、『告白録』や『神の国』を著しました。"]}, {"t": "西アジア・アフリカ:ササン朝とアクスム王国", "p": ["ササン朝は、4世紀の【シャープール2世】の時代に、ローマ帝国と長く戦い、メソポタミア北部やアルメニアをめぐって争いました。アルメニアは4世紀初めにキリスト教を受け入れたとされ、キリスト教を受容した最も早い国の一つとして知られます。ローマがキリスト教を公認すると、ササン朝の領内のキリスト教徒はローマに通じる者として疑われ、迫害されることもありました。宗教が、国家どうしの対立と結びついていくようすがうかがえます。", "アフリカでは、エチオピアの【アクスム王国】が4世紀に最盛期を迎え、【エザナ王】のもとでキリスト教を受け入れたとされます。アクスムは4世紀に、ナイル川上流の【メロエ王国】を滅ぼしたとされます。紅海の交易を押さえたアクスムは、ローマ・インドとの交易で栄え、独自の文字や貨幣を持ちました。エチオピアのキリスト教は、その後も独自の伝統を保ち続けます。"]}, {"t": "南アジア:グプタ朝とインド古典文化", "p": ["分裂していた北インドでは、320年に【チャンドラグプタ1世】が、ガンジス川流域の【パータリプトラ】を都として【グプタ朝】を建てました。グプタ朝は、4世紀後半から5世紀初めの【チャンドラグプタ2世】のころ最盛期を迎え、北インドの大部分を統一しました。", "グプタ朝の時代には、バラモン教に民間の信仰が取り入れられて、【ヒンドゥー教】が社会に定着しました。ヒンドゥー教は、創造の神【ブラフマー】、維持の神【ヴィシュヌ】、破壊の神【シヴァ】などを信仰する多神教で、特定の開祖を持ちません。人々の生活の規範を定めた【『マヌ法典』】は、紀元前後に成立したとされますが、この時代のヒンドゥー社会の基礎となりました。一方で仏教もなお保護され、のちに【ナーランダー僧院】が建てられて、仏教の学問の中心となりました。", "文化の面では、公用語として【サンスクリット語】が用いられ、文学では、チャンドラグプタ2世の宮廷で活躍したとされる詩人【カーリダーサ】が、戯曲『シャクンタラー』を著しました。二大叙事詩『マハーバーラタ』と『ラーマーヤナ』も、このころまでに現在の形にまとめられたとされます。美術では、ガンダーラ美術の影響から離れ、インド独自の様式による【グプタ様式】の仏像が生まれました。また、【ゼロの概念】や十進法による数の表し方が発達し、のちにイスラーム世界を経てヨーロッパへと伝わりました。", "グプタ朝の繁栄は、4世紀末に中国から仏典を求めて旅立った東晋の僧【法顕】によっても記録されました。法顕はグプタ朝のインドを訪れ、その見聞を『仏国記』に記しています。"]}, {"t": "東アジア:五胡十六国と東晋", "p": ["西晋では、皇帝の一族が各地で兵を挙げて争う【八王の乱】が起こりました。王たちはこの争いに、華北に移り住んでいた遊牧民の兵力を利用しました。その結果、遊牧民の勢力が力をつけて自立するようになりました。匈奴の勢力は、311年に都の洛陽を攻め落とし(【永嘉の乱】)、316年に西晋は滅びました。", "こののち、華北では、【匈奴】【羯】【鮮卑】【氐】【羌】の5つの民族(【五胡】)と漢人が、次々と国を建てては滅ぼしあう【五胡十六国】の時代に入りました。一方、江南では、317年に晋の皇族【司馬睿】が【建康】(現在の南京)を都として晋を再興しました。これが【東晋】です。華北の戦乱を逃れて多くの漢人が江南に移住したため、江南の開発が進み、経済と文化の中心がしだいに南へ移っていくきっかけとなりました。", "4世紀後半、氐の【前秦】は、【苻堅】のもとで華北を一時統一し、さらに中国全土の統一をめざして東晋に攻めこみました。しかし383年の【淝水の戦い】で東晋に大敗し、前秦は崩壊して、華北は再び分裂しました。その中から、386年に鮮卑の拓跋氏が【北魏】を建て、のちに5世紀に華北を統一することになります。", "この時代、仏教が中国に深く根づきました。西域から来た【仏図澄】は華北で布教し、4世紀末から5世紀初めには【鳩摩羅什】が長安に迎えられて多くの仏典を翻訳しました。遊牧民の君主たちは、中国の伝統に縛られない仏教を積極的に保護したのです。江南の東晋では、門閥貴族を中心とした優雅な貴族文化が栄え、書の【王羲之】は「書聖」とよばれ、絵画では【顧愷之】が「女史箴図」を描いたとされます。"]}, {"t": "朝鮮半島と日本列島", "p": ["朝鮮半島では、中国の混乱を背景に、各地の勢力が自立を強めました。313年、北部の【高句麗】は、400年以上続いた中国の【楽浪郡】を滅ぼしました。南部では、4世紀半ばに、西の馬韓の地域から【百済】が、東の辰韓の地域から【新羅】が成立し、南端の弁韓の地域には【加耶(加羅)】の諸国が残りました。", "4世紀末に即位した高句麗の【広開土王(好太王)】は、領土を大きく広げました。その業績を記した【好太王碑】には、倭の軍が朝鮮半島に進出して高句麗と戦ったことが記されています。日本列島の【ヤマト政権】は、鉄資源などを求めて朝鮮半島南部と深い関わりを持っていました。中国の分裂が、朝鮮半島と日本列島の国家形成を促したことは、東アジアを横に見るうえで大切な視点です。"]}, {"t": "世界のつながり:遊牧民の移動と宗教の国家化", "p": ["4世紀の世界を横に見ると、ユーラシアの東西でよく似た出来事が起こっていることに気づきます。東では、遊牧民の五胡が華北に国を建て、西晋は滅んで江南に追われました。西では、フン人の移動をきっかけにゲルマン人が大移動を始め、ローマ帝国の国境を突き崩していきました。遊牧民や周辺民族の移動が、東西の定住帝国を揺るがした点で、両者は共通しています。なお、ヨーロッパに現れたフン人と、かつての匈奴とが同じ系統の民族かどうかについては、諸説があります。", "また、この時代は、国家と宗教が強く結びついた時代でもありました。ローマ帝国はキリスト教を公認し、ついで国教とし、ササン朝はゾロアスター教を国家の宗教として重んじ、アクスム王国とアルメニアはキリスト教を受け入れ、グプタ朝のもとではヒンドゥー教が社会に定着しました。中国では、遊牧民の君主が仏教を保護しました。広い地域と多様な人々をまとめるために、王権が宗教の力を借りるようになったのです。", "さらに、混乱のなかで、文化の中心が移動していきました。中国では華北から江南へ人と文化が移り、ローマ帝国では政治と経済の重心が西のローマから東のコンスタンティノープルへと移りました。この変化は、5世紀以降、東では南北朝の対立へ、西では西ローマ帝国の滅亡とビザンツ帝国の繁栄へとつながっていきます。", "アメリカ大陸では、マヤ文明の都市国家とテオティワカンが繁栄を続けていました。ユーラシアが大きな変動期を迎えるなかでも、それぞれの文明は独自の発展を続けていたのです。"]}], "points": ["ディオクレティアヌスの大迫害(303年)→ミラノ勅令(313年)→ニケーア公会議(325年)→国教化(392年)の流れ", "ニケーア公会議:アタナシウス派が正統、アリウス派が異端(のちゲルマン人に広まる)", "コンスタンティヌス帝のコンスタンティノープル遷都(330年)とソリドゥス金貨、コロヌスの土地緊縛", "フン人の侵入(375年)→西ゴート人の移動→アドリアノープルの戦い(378年)", "395年テオドシウス帝の死後、帝国が東西に分裂", "グプタ朝(320年、チャンドラグプタ1世)とヒンドゥー教の定着、カーリダーサ、ゼロの概念", "八王の乱→永嘉の乱(311年)→西晋滅亡(316年)→東晋(317年、建康)、五胡十六国、淝水の戦い(383年)", "313年高句麗が楽浪郡を滅ぼす、百済・新羅の成立、広開土王碑"], "check": [["313年にキリスト教を公認した勅令は?", "ミラノ勅令"], ["325年のニケーア公会議で正統とされた説を唱えた人物は?", "アタナシウス"], ["330年にコンスタンティヌス帝がビザンティオンを改称した都は?", "コンスタンティノープル"], ["378年、西ゴート人がローマ皇帝ウァレンスを敗死させた戦いは?", "アドリアノープルの戦い"], ["キリスト教を国教とし、死後に帝国が東西に分裂した皇帝は?", "テオドシウス帝"], ["320年にグプタ朝を建てた人物は?", "チャンドラグプタ1世"], ["グプタ朝の宮廷で活躍し『シャクンタラー』を著した詩人は?", "カーリダーサ"], ["311年に洛陽が陥落した、西晋滅亡のきっかけとなった反乱は?", "永嘉の乱"], ["383年、前秦の苻堅が東晋に敗れた戦いは?", "淝水の戦い"], ["313年に楽浪郡を滅ぼした朝鮮半島北部の国は?", "高句麗"]], "related": ["y_3", "y_5", "t_ro", "t_byz", "t_ir", "t_af", "t_in", "t_cn", "t_mn", "t_kr", "j_kofun"], "n": 4037}, "y_5": {"title": "5世紀の世界", "span": "401〜500年", "year": 450, "lead": "5世紀は、ユーラシアの東西で古代帝国の秩序がくずれ、遊牧民や移動する諸民族が新しい国をつくった世紀です。西ではゲルマン人の大移動のなかで西ローマ帝国が476年に滅び、東では五胡十六国の混乱を北魏が統一して南北朝時代に入りました。ローマと中国という二つの帝国の分裂が同じ時期に進んだことを、横に並べて理解しましょう。", "flow": ["375年 フン人の西進→西ゴート人がドナウ川を越え、ゲルマン人の大移動が本格化", "395年 テオドシウス帝の死→ローマ帝国が東西に分割される", "410年 西ゴート人がローマ市を略奪→西ローマ帝国の弱体化が誰の目にも明らかに", "420年 東晋が倒れ宋が成立→江南に南朝の時代がはじまる", "431年 エフェソス公会議→ネストリウス派が異端とされ、東方へ広がる", "439年 北魏が華北を統一→五胡十六国時代が終わり南北朝時代へ", "451年 カタラウヌムの戦い→アッティラ率いるフン人の西進が止まる", "451年 カルケドン公会議→単性論が異端とされ、東方教会の分立が進む", "476年 オドアケルが西ローマ皇帝を退位させる→西ローマ帝国の滅亡", "481年 クローヴィスがフランク王国を建国→のちに正統派(アタナシウス派)に改宗", "493年 テオドリック大王が東ゴート王国を建てる→イタリアにゲルマン人の王国", "494年 北魏の孝文帝が洛陽へ遷都→漢化政策が進む"], "sync": [["ヨーロッパ", "ゲルマン人の大移動、西ローマ帝国の滅亡(476年)、フランク王国・東ゴート王国などの建国"], ["西アジア・北アフリカ", "ササン朝ペルシアがエフタルの圧迫を受ける。北アフリカにヴァンダル王国が成立"], ["南アジア・東南アジア", "グプタ朝が最盛期を過ぎ、エフタルの侵入で衰える。東南アジアでは扶南などの港市国家が交易で栄える"], ["東アジア・内陸アジア", "北魏の華北統一(439年)と南北朝時代のはじまり。倭の五王が南朝に朝貢。柔然がモンゴル高原を支配"], ["アメリカ・アフリカ", "メソアメリカでテオティワカン文明、マヤ文明の都市が栄える。アフリカではアクスム王国が紅海交易を担う"], ["世界のつながり", "遊牧民(フン人・エフタル・柔然)の動きがユーラシア各地の帝国をゆさぶる。キリスト教の教義論争と仏教の東伝"]], "secs": [{"t": "5世紀を見る視点:遊牧民の動きと帝国の分裂", "p": ["5世紀の世界を横に見ると、ひとつの共通点が浮かびあがります。それは、ユーラシア大陸の草原地帯から移動してきた遊牧民や、その圧力を受けた諸民族が、定住農耕地帯の大帝国をゆさぶったということです。西では【フン人】の西進がゲルマン人を押し出し、ローマ帝国の西半分を崩しました。中央アジアでは【エフタル】が勢力をのばし、東はササン朝ペルシアやインドのグプタ朝を圧迫しました。東では、4世紀から華北に入りこんでいた遊牧系の諸民族(五胡)のなかから鮮卑の【拓跋氏】が台頭し、【北魏】を建てて華北を統一しました。", "つまり、ローマの西半分の崩壊、グプタ朝の衰退、中国の南北分裂は、ばらばらの事件ではなく、遊牧世界と農耕世界がぶつかりあう大きな流れの一部として見ることができます。ただし、遊牧民は破壊者というだけではありません。北魏のように、遊牧系の支配者が農耕地帯の制度や文化を取り入れて新しい国家をつくった例もあり、それが次の隋・唐の土台になりました。ヨーロッパでも、ゲルマン人の王国がローマの制度やキリスト教を受け継ぎ、中世ヨーロッパ世界を形づくっていきます。5世紀は「古代の終わり」であると同時に「中世のはじまり」でもあるのです。"]}, {"t": "ヨーロッパ:ゲルマン人の大移動と西ローマ帝国の滅亡", "p": ["4世紀後半、アジア系とされる【フン人】が黒海北岸に進出すると、そこにいた【西ゴート人】が圧迫され、375年ごろから移動をはじめました。これが【ゲルマン人の大移動】の本格的なはじまりです。西ゴート人はドナウ川を越えてローマ領内に入り、378年のアドリアノープルの戦いではローマ皇帝を戦死させました。395年に【テオドシウス帝】が死去すると、帝国は二人の息子によって東西に分けられ、以後、東西は別々の道を歩むことになります。", "5世紀に入ると、西ローマ帝国はゲルマン人の侵入をおさえられなくなりました。410年には西ゴート人がローマ市を略奪し、人々に大きな衝撃を与えました。西ゴート人はその後、ガリア南部からイベリア半島にかけて【西ゴート王国】を建てます。【ヴァンダル人】はイベリア半島を経て北アフリカに渡り、カルタゴを中心に【ヴァンダル王国】を建てて地中海の海上を脅かしました。ブルグンド人はガリア東南部に、アングロ=サクソン人はブリテン島に渡って小王国をつくりはじめました。", "こうした中、フン人は【アッティラ】のもとで大帝国を築き、ガリアにまで侵入しました。451年の【カタラウヌムの戦い】では、西ローマ軍とゲルマン人の連合軍がフン人を退けました。アッティラの死後、フン人の勢力は急速に衰えます。しかし西ローマ帝国はもはや実権を失っており、ゲルマン人の傭兵隊長が政治を動かすようになっていました。476年、傭兵隊長【オドアケル】が西ローマ皇帝を退位させ、【西ローマ帝国は滅亡】しました。この年は古代と中世を分ける目印としてよく使われます。", "その後、東ローマ皇帝の承認を受けた【テオドリック大王】がひきいる【東ゴート人】がイタリアに入り、オドアケルを倒して493年に【東ゴート王国】を建てました。テオドリックはローマ人の官僚や制度を利用して統治しましたが、ゲルマン人の多くが信仰する【アリウス派】と、ローマ人の信仰する【アタナシウス派】(正統派)の違いが、支配者と住民の間の壁になりました。", "これに対して、ガリア北部でフランク人をまとめた【クローヴィス】は、481年に【メロヴィング朝】の【フランク王国】を開き、496年ごろに正統派のキリスト教に改宗したとされます。この改宗によって、フランク王国はローマ系住民やローマ教会の支持を得ることができ、ほかのゲルマン国家よりも長く続く強い国家に成長しました。のちのカール大帝の時代まで続く、ローマ教会とフランク王国の結びつきの出発点がここにあります。"]}, {"t": "東ローマ帝国とキリスト教会", "p": ["西ローマ帝国が滅んだのに対し、【コンスタンティノープル】を都とする東ローマ帝国(【ビザンツ帝国】)は存続しました。東方は西方よりも都市が多く、商工業や貨幣経済が発達しており、税収も豊かでした。また、首都コンスタンティノープルは三方を海に囲まれ、陸側には堅固な城壁がつくられていたため、外敵の攻撃に強かったのです。ゲルマン人の圧力を西方へそらすことができたことも、東方が生き残った理由のひとつです。", "この時代のキリスト教会では、キリストの神性と人性をどう考えるかをめぐって激しい論争が続きました。431年の【エフェソス公会議】では、キリストの神性と人性を分けて考える【ネストリウス派】が異端とされました。ネストリウス派はその後、ササン朝ペルシアや中央アジアを通って東方に広がり、7世紀の唐では【景教】と呼ばれます。さらに451年の【カルケドン公会議】では、キリストに神性のみを認める【単性論】が異端とされましたが、エジプトのコプト教会やシリアの教会などは単性論の立場を守りました。", "こうした教義論争は宗教上の問題であるだけでなく、帝国の中心であるコンスタンティノープルと、エジプトやシリアといった地方との対立とも結びついていました。のちの7世紀にアラブ人がシリアやエジプトを征服したとき、住民の一部がビザンツ帝国の支配からの解放を受け入れた背景には、こうした宗教的な対立があったと考えられています。また、西方ではローマ司教(教皇)の権威が高まり、教皇【レオ1世】はアッティラとの交渉にあたったと伝えられます。皇帝のいない西方で、教会が社会のまとめ役になっていく流れがはじまっていました。"]}, {"t": "西アジア・南アジア:ササン朝とグプタ朝を圧迫したエフタル", "p": ["イラン高原では、3世紀に成立した【ササン朝ペルシア】が、ゾロアスター教を国教とする強力な国家として続いていました。しかし5世紀には、中央アジアに台頭した遊牧民【エフタル】の攻撃を受け、国王が戦死するなど大きな打撃を受け、一時はエフタルに貢納するほどでした。ササン朝がエフタルを滅ぼして勢力を回復するのは、6世紀の【ホスロー1世】の時代になってからです。", "インドでは、4世紀に成立した【グプタ朝】が5世紀初めの【チャンドラグプタ2世】のころに最盛期を迎えていました。この王の時代に中国の僧【法顕】がインドを訪れ、仏典を求めて旅をし、帰国後に『仏国記』を著しました。グプタ朝の時代には、【サンスクリット語】が公用語とされ、【ヒンドゥー教】が社会に定着し、詩人【カーリダーサ】の『シャクンタラー』などの文学が生まれました。ゼロの概念や十進法の位取りが発達したのもこの時代とされます。仏教の学問寺院として【ナーランダー僧院】が建てられたのもグプタ朝期です。美術では、ガンダーラ美術の影響を消化した純インド的な【グプタ様式】が生まれ、アジャンター石窟寺院の壁画などに見られます。", "しかし5世紀後半になると、エフタルが北西インドに侵入し、グプタ朝は大きく弱まりました。エフタルの動きは、西のササン朝と南のグプタ朝の両方をゆさぶったことになります。東ではのちに柔然や突厥とも関係をもち、5世紀から6世紀の中央ユーラシア情勢のかぎを握る存在でした。"]}, {"t": "東アジア:北魏の華北統一と南北朝時代", "p": ["中国では、4世紀初めの西晋の滅亡後、華北に匈奴・鮮卑などの【五胡】が次々と国を建てる【五胡十六国】の時代が続き、江南には漢人の王朝【東晋】が建てられていました。5世紀に入ると、鮮卑の拓跋氏が建てた【北魏】が力をのばし、【太武帝】のもとで439年に【華北を統一】しました。一方、江南では420年に東晋が倒れて【宋】が成立し、以後、斉・梁・陳と続く【南朝】の時代となります。こうして華北の北朝と江南の南朝が対立する【南北朝時代】がはじまりました。", "北魏は遊牧系の王朝でしたが、広い農耕地帯を治めるために漢人の制度を取り入れていきました。とくに5世紀後半の【孝文帝】は、485年に土地を農民に分け与えて税を確保する【均田制】を実施し、494年には都を平城から【洛陽】へ移しました。さらに鮮卑の服装や言葉を禁じ、漢人との通婚をすすめるなど、徹底した【漢化政策】をおこないました。均田制はのちの隋・唐にも受け継がれ、東アジアの土地制度の基本になります。ただし急激な漢化は、北方の辺境を守る鮮卑系の軍人の不満を高め、6世紀の北魏の分裂の一因になりました。", "宗教・文化の面では、北魏は初め太武帝のもとで道教を重んじ仏教を弾圧しましたが、のちには仏教を保護し、【雲崗】の石窟寺院、洛陽遷都後には【竜門】の石窟寺院がつくられました。これらにはガンダーラやグプタの様式の影響が見られ、インドの仏教美術が中央アジアを経て中国に届いたことがわかります。南朝では、貴族が中心となって華やかな【六朝文化】が栄え、田園詩人の【陶淵明】(陶潜)や書家の【王羲之】(4世紀)のような文化人が活躍しました。", "周辺では、モンゴル高原に遊牧国家【柔然】が勢力をもち、北魏と対立しました。朝鮮半島では高句麗・百済・新羅の三国が争い、高句麗は5世紀に都を平壌に移して南下を進めました。日本列島の倭では、【倭の五王】が南朝の宋に使いを送り、称号を求めました。これは、朝鮮半島での立場を有利にするために中国皇帝の権威を利用しようとしたものと考えられています。東アジアの国々が中国の皇帝と君臣関係を結ぶ【冊封体制】が、この時期にも機能していたことがわかります。"]}, {"t": "アメリカ・アフリカ:独自に発展した文明", "p": ["アメリカ大陸は、ユーラシア・アフリカの世界とは交流のないまま、独自の文明を発展させていました。メキシコ高原では巨大都市【テオティワカン】が栄え、太陽のピラミッドや月のピラミッドに代表される宗教都市として、周辺に大きな影響をおよぼしていました。ユカタン半島からグアテマラにかけては【マヤ文明】の都市国家が栄え、ピラミッド状の神殿、【マヤ文字】、精密な暦、二十進法の数字などが発達しました。アンデス地方でも海岸部や高地でそれぞれの文化が育っていました。これらの文明は鉄器や車輪を実用化しなかったことも特徴です。", "アフリカでは、エチオピア高原の【アクスム王国】が紅海交易の拠点として栄えていました。アクスムは4世紀にキリスト教を受け入れており、地中海世界とインド洋世界を結ぶ中継点として重要でした。北アフリカでは、先に見たようにヴァンダル王国が成立し、ローマの穀倉地帯だった地域がゲルマン人の支配を受けることになりました。"]}, {"t": "世界のつながり:遊牧民・宗教・交易", "p": ["5世紀の世界を横につなぐ第一の糸は、遊牧民の移動です。フン人、エフタル、柔然、鮮卑といった遊牧系の集団は、ユーラシアの草原を舞台に動き、ローマ・ササン朝・グプタ朝・中国の王朝に大きな影響を与えました。とくに西ローマ帝国の滅亡と、北魏による華北統一は、遊牧民の動きが帝国の運命を左右したことを示す東西の代表例です。違いもあります。ヨーロッパではゲルマン人の小王国が分立し、統一帝国は戻りませんでしたが、中国では北魏の系統から隋・唐という統一帝国が再び生まれました。この違いが、のちのヨーロッパと中国の歴史の歩みの違いにつながっていきます。", "第二の糸は、宗教の広がりです。キリスト教はローマ帝国の国教となったあと、ゲルマン人の間に広がり、異端とされたネストリウス派は東方へ伝わりました。仏教はインドから中央アジアを経て中国に入り、法顕のようにインドへ仏典を求める僧も現れ、雲崗・竜門の石窟がつくられました。インドではヒンドゥー教が定着していきます。こうして、のちの中世世界を形づくる宗教の分布が、5世紀におおよそ整いはじめたといえます。", "第三の糸は、海と陸の交易です。陸上では、ソグド人などの商人がオアシスの道を通じて東西を結び、海上では、インド洋から東南アジアを経て中国南部にいたる航路が発達しつつありました。メコン川下流域の【扶南】は、インドと中国を結ぶ中継港として栄え、インドの文化の影響を強く受けていました。東南アジアでは、インドの宗教・文字・王権の考え方を受け入れる【インド化】が進んでいたのです。こうした交易のネットワークは、帝国が崩れても途切れることなく続き、次の時代の文化交流を支えていきました。"]}], "points": ["西ローマ帝国の滅亡は476年、オドアケルが皇帝を退位させた事件。東ローマ帝国(ビザンツ帝国)は存続した点に注意", "フン人の西進→西ゴート人の移動(375年)→ゲルマン人の大移動という因果関係を押さえる", "クローヴィスの正統派(アタナシウス派)への改宗が、フランク王国発展の理由として頻出", "エフェソス公会議(431年)でネストリウス派、カルケドン公会議(451年)で単性論が異端に。ネストリウス派は唐で景教と呼ばれる", "北魏の太武帝の華北統一(439年)、孝文帝の均田制・洛陽遷都(494年)・漢化政策", "エフタルがササン朝とグプタ朝の両方を圧迫したことを横のつながりとして理解する", "グプタ朝の文化:サンスクリット文学(カーリダーサ)、ヒンドゥー教の定着、ナーランダー僧院、法顕の来訪", "倭の五王が南朝の宋に朝貢した=東アジアの冊封体制の一例"], "check": [["476年に西ローマ皇帝を退位させたゲルマン人の傭兵隊長は誰か", "オドアケル"], ["451年、西ローマとゲルマン人の連合軍がアッティラのフン人を退けた戦いは何か", "カタラウヌムの戦い"], ["481年にフランク王国を建て、のちに正統派キリスト教に改宗した王は誰か", "クローヴィス"], ["431年のエフェソス公会議で異端とされ、のちに唐で景教と呼ばれた一派は何か", "ネストリウス派"], ["439年に華北を統一した北魏の皇帝は誰か", "太武帝"], ["均田制を実施し、494年に洛陽に遷都した北魏の皇帝は誰か", "孝文帝"], ["5世紀に中央アジアで台頭し、ササン朝やグプタ朝を圧迫した遊牧民は何か", "エフタル"], ["グプタ朝のチャンドラグプタ2世の時代にインドを訪れ『仏国記』を著した中国の僧は誰か", "法顕"], ["493年にイタリアに東ゴート王国を建てた王は誰か", "テオドリック大王"]], "related": ["y_4", "y_6", "t_ro", "t_byz", "t_fr", "t_cn", "t_in", "t_ir"], "n": 4865}, "y_6": {"title": "6世紀の世界", "span": "501〜600年", "year": 550, "lead": "6世紀は、分裂した世界をもう一度まとめ直そうとする動きが東西で見られた世紀です。西ではビザンツ皇帝ユスティニアヌスが地中海の再統一をめざし、東では隋が589年に約300年ぶりに中国を統一しました。その間の草原では突厥が大遊牧国家を築き、ササン朝はホスロー1世のもとで最盛期を迎えました。", "flow": ["529年 ベネディクトゥスがモンテ=カシノに修道院を開く→「祈り、働け」の修道生活が西欧に広がる", "534年 ビザンツ帝国がヴァンダル王国を滅ぼす→ユスティニアヌスの地中海再統一が進む", "534年 北魏が東魏・西魏に分裂→のち北斉・北周へ", "6世紀半ば ササン朝のホスロー1世が突厥と結んでエフタルを滅ぼす", "552年 突厥がモンゴル高原に建国→柔然にかわって草原を支配", "555年 ビザンツ帝国が東ゴート王国を滅ぼす(イタリア制圧)", "568年 ランゴバルド人が北イタリアに王国を建てる→ビザンツのイタリア支配が後退", "570年ごろ ムハンマドがメッカに生まれる", "581年 楊堅(文帝)が隋を建てる→589年に陳を滅ぼし中国を統一", "583年 突厥が東西に分裂→隋が草原への影響力を強める", "590年 グレゴリウス1世が教皇となる→ゲルマン人への布教とローマ教会の権威の拡大"], "sync": [["ヨーロッパ", "ユスティニアヌス帝の地中海再統一とローマ法大全。ランゴバルド王国の成立(568年)。修道院運動と教皇グレゴリウス1世"], ["西アジア・北アフリカ", "ササン朝のホスロー1世の最盛期。ビザンツ帝国との抗争。アラビア半島ではメッカが商業都市として成長"], ["南アジア・東南アジア", "グプタ朝が滅び北インドは分裂。東南アジアでは扶南が衰え、真臘(カンボジア)が台頭"], ["東アジア・内陸アジア", "北朝の分裂(東魏・西魏→北斉・北周)と南朝の梁・陳。隋の建国(581年)と中国統一(589年)。突厥の成立と東西分裂"], ["アメリカ・アフリカ", "マヤの都市国家が古典期の繁栄を続ける。テオティワカンは衰退に向かったとされる。アクスム王国の紅海交易"], ["世界のつながり", "突厥とソグド商人による内陸交易、ビザンツへの養蚕技術の伝来、仏教の朝鮮半島から日本への伝来"]], "secs": [{"t": "6世紀を見る視点:再統一の試み", "p": ["5世紀にユーラシアの東西で帝国の秩序がくずれたあと、6世紀には各地で「もう一度大きなまとまりをつくろう」とする動きがはっきりしてきます。地中海世界では東ローマ(ビザンツ)帝国の【ユスティニアヌス帝】が、かつてのローマ帝国の領域を取り戻そうと遠征をくり返しました。中国では、北朝の系統から出た【隋】が南朝を滅ぼし、西晋の滅亡以来久しぶりに南北を統一しました。草原地帯では【突厥】がモンゴル高原から中央アジアにまたがる大遊牧国家を築き、ユーラシアの東西を結ぶ位置に立ちました。", "ただし、その結果は地域によって大きく違いました。ユスティニアヌスの再統一は一時的な成功にとどまり、彼の死後まもなくイタリアの大半はランゴバルド人に奪われました。一方、隋の統一は短命でしたが、すぐに唐がそれを受け継ぎ、長く続く統一帝国の時代が開かれました。なぜ地中海では統一が続かず、中国では続いたのか。その理由を考えることが、この世紀を横に見るときの大切な視点になります。"]}, {"t": "ヨーロッパ:ユスティニアヌスの地中海再統一とその限界", "p": ["6世紀のビザンツ帝国で最も重要な人物は、527年に即位した【ユスティニアヌス帝】です。彼は「ローマ帝国の復興」を目標にかかげ、将軍ベリサリウスらを派遣して、534年に北アフリカの【ヴァンダル王国】を、555年には長い戦争の末にイタリアの【東ゴート王国】を滅ぼしました。さらにイベリア半島南部の一部も奪い、地中海はほぼ再びローマの海となりました。", "内政では、法学者トリボニアヌスらに命じて、それまでのローマ法を集大成した【ローマ法大全】(ユスティニアヌス法典)を編纂させました。これはのちに中世ヨーロッパで再発見され、近代の法律にまで影響を与えることになります。また首都コンスタンティノープルには、巨大なドームをもつ【ハギア=ソフィア聖堂】を再建しました。これは円屋根とモザイク壁画を特徴とする【ビザンツ様式】の代表作です。さらに、中国から蚕の卵がひそかに持ちこまれて【養蚕】がはじまったとされ、絹織物をササン朝経由の輸入にたよらずにすむようになりました。", "しかし、度重なる遠征と大規模な建設は、帝国の財政に重い負担をかけました。東方ではササン朝との戦争も続き、6世紀半ばには疫病の大流行も起こったとされます。ユスティニアヌスの死後まもない568年には、【ランゴバルド人】が北イタリアに侵入して【ランゴバルド王国】を建て、ビザンツのイタリア支配は大きく後退しました。地中海再統一は、帝国の力を使いはたす一時的な輝きに終わったのです。", "西ヨーロッパでは、フランク王国のメロヴィング朝が、クローヴィスの死後に分割相続をくり返しながらもガリアに勢力を保っていました。イベリア半島には西ゴート王国、ブリテン島にはアングロ=サクソン人の小王国が並び立っていました。この時期、西ヨーロッパの社会を支える新しい柱となったのが、修道院と教皇です。529年ごろ、【ベネディクトゥス】はイタリアの【モンテ=カシノ】に修道院を開き、清貧・純潔・服従と「【祈り、働け】」を重んじる戒律を定めました。ベネディクト派の修道院は、祈りだけでなく労働や学問の場ともなり、のちに開墾や古典の写本の保存で大きな役割を果たします。", "590年に教皇となった【グレゴリウス1世】は、アングロ=サクソン人への布教のために修道士を送り、ゲルマン人の改宗を進めました。ビザンツ皇帝の力が西方にあまり届かなくなるなかで、ローマ教会は自ら布教と保護を担う存在へと成長し、のちにフランク王国と手を結ぶ方向へ進んでいきます。"]}, {"t": "西アジア:ササン朝の最盛期と突厥", "p": ["イラン高原の【ササン朝ペルシア】は、6世紀の【ホスロー1世】のもとで最盛期を迎えました。ホスロー1世は税制などの改革をおこなって国力を回復し、西ではビザンツ帝国のユスティニアヌス帝と戦って有利な条件で和平を結びました。東では、新たに台頭した遊牧国家【突厥】と同盟し、5世紀以来イランを苦しめてきた【エフタル】を挟み撃ちにして滅ぼしました。これによって中央アジアの勢力図が大きく変わり、エフタルの旧領はササン朝と突厥に分けられました。", "ササン朝の宮廷は文化的にも国際色が豊かで、ユスティニアヌスがアテネのアカデメイアを閉鎖した際に、ギリシアの学者たちがササン朝に身を寄せたとも伝えられます。インドの書物やギリシアの学問も翻訳され、のちのイスラーム文化に受け継がれる知の蓄積が進みました。また、ササン朝の工芸品(ガラス器や銀器)の様式は、シルク=ロードを通じて中国や日本にも伝わり、正倉院の宝物にもその影響が見られます。", "しかしササン朝とビザンツ帝国の抗争は、6世紀末から7世紀初めにかけていっそう激しくなりました。両大国が戦争で疲れきったことが、7世紀にアラビア半島から新しい勢力が急速に広がる条件をつくることになります。その新しい勢力の創始者【ムハンマド】は、570年ごろに商業都市【メッカ】で生まれています。両大国の戦争で従来の交易路が不安定になり、アラビア半島西部を通る隊商路の重要性が増したことも、メッカの繁栄の背景にあったと考えられています。"]}, {"t": "南アジア・東南アジア:グプタ朝の滅亡と真臘の台頭", "p": ["インドでは、エフタルの侵入によって弱まった【グプタ朝】が、6世紀半ばごろに滅亡しました。その後の北インドは小国が分立する状態となり、7世紀前半に【ハルシャ王】(ハルシャ=ヴァルダナ)が北インドを統一するまで、大きな統一勢力は現れませんでした。一方で、グプタ朝の時代に定着した【ヒンドゥー教】は社会の中にますます深く根をおろし、仏教はナーランダー僧院などを拠点に学問として続いていました。", "東南アジアでは、メコン川下流域で栄えた港市国家【扶南】が衰え、そのかわりにメコン川中流域のクメール人の国【真臘】(カンボジア)が台頭し、7世紀には扶南を併合したとされます。ベトナム中部では、チャム人の【チャンパー】(林邑)が海上交易で栄えていました。これらの国々はいずれもインドの文化を受け入れており、サンスクリット語の碑文やヒンドゥー教・仏教の寺院を残しています。真臘はのちのアンコール朝につながっていく国家であり、東南アジア大陸部の歴史の流れを押さえるうえで重要です。"]}, {"t": "東アジア:南北朝の終わりと隋の統一", "p": ["中国の北朝では、北魏が孝文帝の漢化政策に反発した北方の軍人たちの反乱(六鎮の乱)をきっかけに混乱し、534年に【東魏】と【西魏】に分裂しました。その後、東魏は【北斉】に、西魏は【北周】にとってかわられます。西魏では、兵農一致の兵制である【府兵制】が整えられたとされ、これがのちに隋・唐に受け継がれました。北周は577年に北斉を滅ぼして華北を再統一し、強い軍事力をもつ国家となりました。", "江南の南朝では、【梁】の【武帝】が長く在位し、仏教を熱心に保護して、貴族文化が花開きました。武帝の皇子である【昭明太子】が編んだ詩文集『【文選】』は、日本の平安貴族にも愛読されました。しかし梁は武帝の晩年に起きた反乱で大きく乱れ、その後をついだ【陳】は弱体な王朝でした。", "こうした状況の中で、北周の外戚であった【楊堅】が581年に帝位を奪って【隋】を建て、【文帝】となりました。文帝は589年に南朝の陳を滅ぼし、ついに【中国を統一】しました。文帝は北朝の制度を受け継いで【均田制】・【租調庸制】・【府兵制】を整え、中央には三省六部の原型となる官制を置きました。さらに、家柄で官僚を選ぶ【九品中正】を廃止し、学科試験によって人材を選ぶ制度をはじめました。これがのちの【科挙】の起源です。家柄ではなく能力によって官僚を選ぶという考え方は、皇帝の権力を強め、貴族の力をおさえる意味をもっていました。", "北方の草原では、柔然に従属していたトルコ系の【突厥】が552年に独立して柔然を倒し、モンゴル高原から中央アジアにいたる大遊牧国家を築きました。突厥は【突厥文字】をつくったことでも知られ、これは北方遊牧民が残した最古の文字のひとつです。突厥は北朝の北斉・北周から多くの絹を受け取るほどの強大な力をもっていましたが、583年に内紛から【東突厥と西突厥に分裂】しました。隋は突厥の分裂をたくみに利用して北方の脅威を弱めました。", "朝鮮半島では、【新羅】が6世紀に勢力をのばし、加耶(加羅)諸国を併合しました。日本列島には、6世紀前半に百済から【仏教】が公式に伝えられ(仏教公伝)、6世紀末には蘇我氏の主導で飛鳥寺の建立がはじまるなど、仏教文化が根づきはじめました。中国の分裂から統一への動きが、朝鮮半島や日本の国家形成にも大きな影響を与えていくのです。"]}, {"t": "アメリカ・アフリカ", "p": ["メソアメリカでは、【マヤ文明】の都市国家が【古典期】と呼ばれる最盛期を迎え、ティカルなどの都市に神殿ピラミッドや石碑がつくられました。マヤの人々は石碑に王の事績を【マヤ文字】で刻み、長期暦によって日付を記しました。メキシコ高原の【テオティワカン】は、6世紀から7世紀ごろに衰退したとされます。アンデス地方でも各地に地域的な文化が栄えていました。", "アフリカの【アクスム王国】は、紅海をはさんでアラビア半島南部にも影響力を持ち、ビザンツ帝国とも友好関係にありました。キリスト教国のアクスムとビザンツが結びつき、ササン朝と対抗するという構図は、紅海・インド洋交易をめぐる大国の争いが、アフリカやアラビア半島にまでおよんでいたことを示しています。"]}, {"t": "世界のつながり:絹の道と仏教の東伝", "p": ["6世紀のユーラシアを結んだのは、突厥とソグド商人です。突厥が中国の北朝や隋から得た大量の絹は、ソグド人の商人によって西へ運ばれ、ササン朝やビザンツ帝国にまで届きました。突厥は絹の取引をめぐってビザンツ帝国と直接使節を交換したとされ、ユーラシアの東西の大国が草原の遊牧国家を通じてつながっていたことがわかります。ビザンツがひそかに養蚕技術を手に入れようとしたのも、この絹の流れをめぐる争いの一部でした。", "宗教の面では、仏教が中国から朝鮮半島、そして日本列島へと伝わり、東アジアに仏教文化圏が広がりはじめました。西ヨーロッパでは修道院と教皇によってゲルマン人へのキリスト教布教が進みました。ササン朝ではゾロアスター教が国教として保たれ、その中でネストリウス派キリスト教徒も活動していました。6世紀は、7世紀のイスラームの誕生と唐の繁栄を前に、ユーラシアの宗教と交易の舞台が整えられた時代だといえます。", "東西の比較をまとめておきましょう。ビザンツのユスティニアヌスは、古いローマ帝国の姿を武力で取り戻そうとしましたが、財政を傾け、長く続きませんでした。隋の文帝は、北朝で育った新しい制度(均田制・府兵制)と、能力による官吏登用という新しい仕組みで国をまとめ、それを唐が受け継ぎました。古いものの復興をめざしたか、新しい制度で再建したかという違いが、その後の歩みの違いにつながったと考えることができます。"]}], "points": ["ユスティニアヌス帝:ヴァンダル王国(534年)・東ゴート王国(555年)を滅ぼす。ローマ法大全、ハギア=ソフィア聖堂、養蚕技術の導入", "568年ランゴバルド人の北イタリア侵入でビザンツのイタリア支配が後退", "ベネディクトゥスのモンテ=カシノ修道院(529年)と「祈り、働け」、教皇グレゴリウス1世のゲルマン布教", "ササン朝のホスロー1世が突厥と結んでエフタルを滅ぼした=横のつながりの典型", "突厥の建国(552年)と東西分裂(583年)、突厥文字", "隋の文帝(楊堅)が581年に建国、589年に陳を滅ぼして統一。九品中正を廃止し科挙のもとを開いた", "北朝の均田制・府兵制が隋唐に受け継がれる流れ", "東南アジアでは扶南の衰退と真臘の台頭"], "check": [["ローマ法大全の編纂やハギア=ソフィア聖堂の再建をおこなったビザンツ皇帝は誰か", "ユスティニアヌス帝"], ["568年に北イタリアに侵入して王国を建てたゲルマン人は何か", "ランゴバルド人"], ["529年ごろモンテ=カシノに修道院を開いた人物は誰か", "ベネディクトゥス"], ["突厥と結んでエフタルを滅ぼしたササン朝の王は誰か", "ホスロー1世"], ["552年に柔然を倒してモンゴル高原に建国したトルコ系遊牧国家は何か", "突厥"], ["581年に隋を建て、589年に陳を滅ぼして中国を統一した人物は誰か", "楊堅(文帝)"], ["隋の文帝が廃止した、家柄によって官僚を推薦する制度は何か", "九品中正"], ["梁の昭明太子が編んだ詩文集は何か", "文選"], ["扶南にかわってメコン川流域で台頭したクメール人の国は何か", "真臘"]], "related": ["y_5", "y_7", "t_byz", "t_ir", "t_cn", "t_mn", "t_mm", "t_it"], "n": 4375}, "y_7": {"title": "7世紀の世界", "span": "601〜700年", "year": 650, "lead": "7世紀は、アラビア半島に生まれたイスラームが短期間で西アジアから北アフリカに広がり、東アジアでは唐が大帝国を築いた世紀です。ササン朝は滅び、ビザンツ帝国は領土を大きく失って姿を変えました。ユーラシアの西と東に、それぞれ次の時代の中心となる二つの大きな世界、イスラーム世界と唐を中心とする東アジア世界が生まれました。", "flow": ["610年ごろ ムハンマドが神の啓示を受けたとしてイスラームを説きはじめる", "618年 隋が滅び李淵(高祖)が唐を建てる→太宗の貞観の治へ", "622年 ムハンマドがメッカからメディナへ移る(ヒジュラ)→ウンマ(信者の共同体)の成立", "630年 ムハンマドがメッカを征服→632年の死までにアラビア半島の大部分を統合", "630年 唐が東突厥を服属させる→太宗が北方遊牧民から天可汗と呼ばれる", "632年 アブー=バクルが初代カリフに→正統カリフ時代", "642年 ニハーヴァンドの戦い→651年ササン朝が滅亡", "661年 ムアーウィヤがウマイヤ朝を開く(都ダマスクス)→カリフ位の世襲化", "663年 白村江の戦い→唐・新羅が倭・百済の連合軍を破る", "668年 唐・新羅が高句麗を滅ぼす→676年新羅が朝鮮半島を統一", "680年 カルバラーの戦いでフサインが殺される→シーア派の形成が進む", "690年 則天武后が即位し国号を周とする。698年 渤海が建国される"], "sync": [["ヨーロッパ", "ビザンツ帝国がシリア・エジプトを失い、軍管区制(テマ制)とギリシア語化で再編。フランク王国では宮宰が実権をにぎる"], ["西アジア・北アフリカ", "イスラームの成立(622年ヒジュラ)と正統カリフ時代の大征服。ササン朝の滅亡(651年)。ウマイヤ朝の成立(661年)"], ["南アジア・東南アジア", "ハルシャ王が北インドを統一し玄奘が訪れる。スマトラ島にシュリーヴィジャヤが台頭し義浄が滞在"], ["東アジア・内陸アジア", "唐の建国(618年)と太宗の貞観の治。東突厥の服属。新羅の朝鮮半島統一(676年)。吐蕃の成立。則天武后。渤海の建国(698年)"], ["アメリカ・アフリカ", "マヤ文明の古典期の都市が栄える。北アフリカにアラブ人が進出し、イスラーム化がはじまる"], ["世界のつながり", "イスラーム世界と唐が中央アジアで接近しはじめる。玄奘・義浄の旅に見る陸と海の仏教交流"]], "secs": [{"t": "7世紀を見る視点:イスラーム世界と唐の誕生", "p": ["7世紀の世界を横に見ると、ユーラシアの西と東で、ほぼ同時に巨大な新しい世界が生まれたことがわかります。西アジアでは、アラビア半島の商業都市メッカに生まれた【ムハンマド】が【イスラーム】を説き、その死後わずか数十年のうちに、信者たちはササン朝を滅ぼし、ビザンツ帝国からシリアやエジプトを奪いました。東アジアでは、隋のあとを受けた【唐】が、律令に基づく強力な国家をつくり、周辺の遊牧民や朝鮮半島の国々を従えました。", "なぜこの時期に、これほど急速な拡大が起こったのでしょうか。西アジアでは、6世紀から続いたビザンツ帝国とササン朝の長い戦争によって、両大国が疲れきっていました。東アジアでは、隋がいったん中国を統一し、運河や制度をつくっていたことが、唐の繁栄の土台になりました。古い大国が弱ったところに新しい力が生まれる、あるいは前の王朝の遺産を新しい王朝が受け継ぐ、という歴史の動きが、東西で同時に見られるのです。"]}, {"t": "西アジア:イスラームの成立と大征服", "p": ["ムハンマドはメッカの名門【クライシュ族】の出身で、商人として活動していましたが、610年ごろ唯一神【アッラー】の啓示を受けたとして、神の前の平等と偶像崇拝の否定を説きはじめました。しかし、多神教の神殿【カーバ】の巡礼で利益を得ていたメッカの有力者たちから迫害を受けたため、622年、信者とともにメッカの北にある【メディナ】へ移りました。これを【ヒジュラ】(聖遷)といい、この年がのちに【イスラーム暦】(ヒジュラ暦)の元年とされました。メディナでムハンマドは信者の共同体【ウンマ】をつくり、宗教の指導者であると同時に政治・軍事の指導者ともなりました。", "ムハンマドは630年にメッカを征服し、カーバの偶像を破壊してイスラームの聖殿としました。632年にムハンマドが亡くなるまでに、アラビア半島の多くの部族がイスラームに従いました。神の言葉とされる啓示はのちに聖典『【コーラン】』(クルアーン)にまとめられます。", "ムハンマドの死後、共同体の合意によって【アブー=バクル】が【カリフ】(ムハンマドの後継者)に選ばれました。アブー=バクルから第4代の【アリー】までの4人を【正統カリフ】と呼びます。この時代にアラブ人のイスラーム教徒は、【ジハード】(聖戦)の名のもとに大規模な征服活動をおこないました。ビザンツ帝国からシリアやエジプトを奪い、642年の【ニハーヴァンドの戦い】でササン朝を破りました。ササン朝は651年に滅亡します。", "征服地では、異教徒も【ジズヤ】(人頭税)と【ハラージュ】(地租)を支払えば信仰を認められました。ビザンツ帝国の宗教政策に不満をもっていた単性論派のキリスト教徒などにとって、アラブ人の支配は必ずしも抑圧的なものではなかったため、征服は比較的スムーズに進んだと考えられています。アラブ人は征服地に【軍営都市】(ミスル)を建て、そこから支配を広げました。", "しかし、共同体の指導者をめぐる対立が深まり、第3代カリフのウスマーンが暗殺され、第4代カリフのアリーも661年に暗殺されました。シリア総督であったウマイヤ家の【ムアーウィヤ】は、【ダマスクス】を都として【ウマイヤ朝】を開き、以後カリフ位は世襲されるようになりました。アリーとその子孫だけを正しい指導者(イマーム)と考える人々は【シーア派】を形づくり、680年の【カルバラーの戦い】でアリーの子フサインが殺されると、その結びつきはいっそう強まりました。これに対し、共同体の慣行(スンナ)に従う多数派は【スンナ派】と呼ばれるようになります。イスラーム世界の二大宗派の分かれ目は、この7世紀の後継者争いにあるのです。"]}, {"t": "ヨーロッパ:姿を変えたビザンツ帝国とフランク王国", "p": ["7世紀前半のビザンツ帝国では、皇帝【ヘラクレイオス1世】がササン朝との激しい戦争に勝利しましたが、その直後にアラブ人の攻撃を受け、シリアとエジプトを失いました。エジプトは帝国の穀倉、シリアは商工業の中心でしたから、その打撃は大きなものでした。さらにバルカン半島には【スラヴ人】が広く移り住み、7世紀後半にはトルコ系の【ブルガール人】が南下して国をつくりました。", "こうした危機に対応するため、ビザンツ帝国では、帝国を軍管区に分けて司令官に軍事と行政をあわせて任せる【軍管区制】(テマ制)が整えられ、兵士には土地を与えて兵役を義務づける【屯田兵制】がおこなわれたとされます。また、ラテン語にかわって【ギリシア語】が公用語として定着し、帝国はローマ帝国の後継者でありながら、ギリシア正教とギリシア語を中心とする国家へと性格を変えていきました。7世紀後半にはアラブ軍がコンスタンティノープルを包囲しましたが、【ギリシア火】と呼ばれる火炎兵器などで撃退しました。首都が持ちこたえたことは、イスラーム勢力の東ヨーロッパへの進出をくい止める意味をもちました。", "西ヨーロッパでは、フランク王国のメロヴィング朝の王権が弱まり、王家の財産や政治を管理する【宮宰】が実権をにぎるようになりました。とくにカロリング家が宮宰の地位を世襲して力をのばし、8世紀のカール=マルテルやピピンの登場につながります。ブリテン島ではアングロ=サクソン人の小王国が並び立ち、ローマから派遣された修道士の布教によってキリスト教化が進みました。7世紀の西ヨーロッパはまだ小さな勢力が分かれた世界であり、地中海の覇権はビザンツとイスラームの間で争われていました。"]}, {"t": "南アジア・東南アジア:ハルシャ王とシュリーヴィジャヤ", "p": ["北インドでは、グプタ朝滅亡後の分裂を経て、【ハルシャ王】(ハルシャ=ヴァルダナ)が7世紀前半に北インドの大部分を統一しました。ハルシャ王は仏教を保護し、文学にも通じた王でした。この時代に、唐の僧【玄奘】が陸路でインドに入り、【ナーランダー僧院】で学んで多くの仏典を持ち帰りました。玄奘の旅行記『【大唐西域記】』は、当時の中央アジアやインドの様子を伝える貴重な記録です。しかしハルシャ王の死後、北インドは再び分裂し、ラージプートと呼ばれる勢力が各地に分立する時代に入っていきます。", "東南アジアの海域では、スマトラ島のパレンバンを中心に【シュリーヴィジャヤ】が7世紀後半に台頭しました。シュリーヴィジャヤはマラッカ海峡を押さえ、インド洋と南シナ海を結ぶ海上交易の中継地として繁栄しました。唐の僧【義浄】は海路でインドに渡り、その往復の途中でシュリーヴィジャヤに滞在して、大乗仏教が盛んな様子を記録しました(『南海寄帰内法伝』)。大陸部では、【真臘】がメコン川流域で勢力を広げていました。", "玄奘が陸路、義浄が海路でインドに向かったことは、7世紀にアジアを結ぶ交通路が陸と海の二つあったことを示す例として、セットで覚えておくとよいでしょう。"]}, {"t": "東アジア:唐の建国と東アジア世界の形成", "p": ["隋の第2代皇帝【煬帝】は、華北と江南を結ぶ【大運河】を完成させ、南北の経済を結びつけました。大運河はのちの中国の経済を支える大動脈になりましたが、その建設に動員された民衆の負担は重く、さらに3回にわたる【高句麗遠征】が失敗したことで各地に反乱が起こりました。618年、隋の武将であった【李淵】(【高祖】)が長安で【唐】を建て、隋は滅亡しました。", "第2代皇帝【太宗】(李世民)の治世は【貞観の治】と呼ばれ、国内がよく治まった時代とされます。唐は隋の制度を受け継いで【律・令・格・式】の法体系を整え、中央には中書省・門下省・尚書省の【三省】と、尚書省のもとに【六部】を置きました。地方は州県制で治め、農民には【均田制】で土地を与えて【租調庸】を課し、兵役は【府兵制】によって確保しました。官僚の選抜には【科挙】が用いられましたが、唐の時代にはまだ貴族の力が強く、門閥が政治で大きな役割を果たしていました。", "対外的には、太宗は630年に【東突厥】を服属させ、北方の遊牧民の首長たちから【天可汗】の称号を贈られました。唐は征服した地域に【都護府】を置き、現地の首長にある程度の自治を認める【羈縻政策】で治めました。第3代【高宗】の時代には西突厥も破り、唐の勢力は中央アジアにまでおよびました。チベットでは【ソンツェン=ガンポ】が【吐蕃】を建て、唐から公主を迎えるなど、唐と交流しつつ独自の国家を築きました。", "朝鮮半島では、唐は【新羅】と結んで660年に【百済】を滅ぼし、663年には百済の復興を助けようとした倭の軍を【白村江の戦い】で破りました。668年には【高句麗】も滅ぼしました。その後、新羅は唐の勢力を半島から追い出し、676年に【朝鮮半島を統一】しました。旧高句麗の北方には、698年に【大祚栄】が【渤海】を建てます。敗れた倭は、唐の侵攻に備えて国内の防衛を固めるとともに、唐の律令制度を取り入れた中央集権国家づくりを急ぎました。7世紀末には国号として【日本】が用いられるようになったとされます。", "唐の宮廷では、高宗の皇后であった【則天武后】(武則天)が実権をにぎり、690年には自ら皇帝となって国号を【周】と改めました。中国史上唯一の女性皇帝です。則天武后は家柄にとらわれず科挙で新しい人材を登用したため、旧来の貴族の勢力が弱まる一面もありました。"]}, {"t": "アメリカ・アフリカ", "p": ["メソアメリカでは、【マヤ文明】の都市国家が古典期の繁栄を続け、ティカルやパレンケなどの都市で大規模な神殿や宮殿がつくられました。都市どうしは同盟や戦争をくり返し、王の事績が石碑に刻まれました。アンデス地方でも、高地を中心に地域的な国家が発展していました。アメリカ大陸はまだ旧大陸とは交流がなく、イスラームや唐の動きとは無関係に独自の歴史を歩んでいました。", "アフリカでは、7世紀にアラブ人がエジプトを征服し、さらに西へと進んで北アフリカの沿岸部に勢力を広げはじめました。これによって北アフリカのイスラーム化とアラブ化がはじまり、のちのイスラーム世界の西の広がりの土台となりました。紅海の交易を担っていたアクスム王国は、イスラーム勢力の拡大によって交易上の地位を失っていったとされます。"]}, {"t": "世界のつながり:二つの大世界の接近", "p": ["7世紀の終わりには、西アジアから北アフリカにかけてのイスラーム世界と、唐を中心とする東アジア世界という、二つの大きな世界ができあがりました。この二つは、中央アジアでしだいに接近していきます。ササン朝が滅びると、その王族の一部が唐に助けを求めたと伝えられ、唐の都【長安】には、ペルシア人やソグド人の商人、ゾロアスター教(祆教)、マニ教、ネストリウス派キリスト教(景教)など、西方の人々や宗教が集まりました。長安は人口の多い国際都市として繁栄していくのです。この両世界が中央アジアで直接衝突するのは、8世紀の【タラス河畔の戦い】のときです。", "東西を比較すると、どちらの世界にも共通する点があります。イスラーム世界ではカリフのもとに『コーラン』に基づく法と信仰が人々を結びつけ、東アジア世界では、中国の皇帝を中心に【漢字・儒教・仏教・律令】が周辺の国々に広がりました。日本・新羅・渤海は、いずれも唐の制度や文化を取り入れて国家を整えます。宗教や文字、法律を共有する広い「文化圏」が、ユーラシアの西と東で形づくられていったのです。", "一方、西ヨーロッパは地中海の南岸と東岸をイスラームに奪われ、地中海世界の一体性は失われました。歴史家のなかには、これによって西ヨーロッパは内陸に押しこめられ、フランク王国を中心とする独自の世界を形成していくことになったと考える人もいます(ピレンヌの説)。7世紀は、のちの中世世界の三つの柱、すなわちイスラーム世界、ビザンツ世界、西ヨーロッパ世界の分かれ道となった世紀だといえるでしょう。"]}], "points": ["ヒジュラ(622年)がイスラーム暦の元年。メディナでウンマを形成", "正統カリフ時代の大征服:ニハーヴァンドの戦い(642年)でササン朝を破り、ササン朝は651年に滅亡", "ウマイヤ朝の成立(661年、ムアーウィヤ、都ダマスクス)とカリフの世襲化、カルバラーの戦い(680年)とシーア派", "ビザンツ帝国の再編:軍管区制(テマ制)、ギリシア語の公用語化", "唐の制度:三省六部、律令格式、均田制・租調庸制・府兵制、羈縻政策と都護府", "白村江の戦い(663年)→新羅の朝鮮半島統一(676年)、渤海の建国(698年)", "玄奘(陸路・ハルシャ王・ナーランダー僧院・大唐西域記)と義浄(海路・シュリーヴィジャヤ)の比較", "則天武后が690年に即位し国号を周とした"], "check": [["622年、ムハンマドがメッカからメディナへ移ったことを何というか", "ヒジュラ(聖遷)"], ["初代正統カリフは誰か", "アブー=バクル"], ["642年にアラブ軍がササン朝を破った戦いは何か", "ニハーヴァンドの戦い"], ["661年にダマスクスを都としてウマイヤ朝を開いたのは誰か", "ムアーウィヤ"], ["7世紀前半に北インドを統一し、玄奘を迎えた王は誰か", "ハルシャ王(ハルシャ=ヴァルダナ)"], ["7世紀後半にスマトラ島に台頭し、義浄が滞在した国は何か", "シュリーヴィジャヤ"], ["唐の太宗の治世を何というか", "貞観の治"], ["663年に唐・新羅連合軍が倭・百済連合軍を破った戦いは何か", "白村江の戦い"], ["690年に即位し国号を周と改めた中国唯一の女性皇帝は誰か", "則天武后(武則天)"], ["7世紀にチベットで吐蕃を建てた王は誰か", "ソンツェン=ガンポ"]], "related": ["y_6", "y_8", "t_ar", "t_ir", "t_byz", "t_cn", "t_kr", "t_in", "t_id"], "n": 4675}, "y_8": {"title": "8世紀の世界", "span": "701〜800年", "year": 750, "lead": "8世紀は、イスラーム世界がイベリア半島から中央アジアまで広がり、750年にアッバース朝が成立して「アラブ人の帝国」から「イスラーム教徒の帝国」へと変わった世紀です。同じころ唐では安史の乱が起こって律令体制がゆらぎ、西ヨーロッパではフランク王国が教皇と結んで台頭しました。751年のタラス河畔の戦いは、東西の大帝国が中央アジアで直接ぶつかった象徴的なできごとです。", "flow": ["711年 ウマイヤ朝が西ゴート王国を滅ぼす→イベリア半島の大部分がイスラーム支配下に", "726年 ビザンツ皇帝レオン3世が聖像禁止令を出す→ローマ教会との対立", "732年 トゥール・ポワティエ間の戦い→カール=マルテルがイスラーム軍の北上を止める", "744年 ウイグルがモンゴル高原を支配→のち安史の乱で唐を助ける", "750年 アッバース朝の成立→アラブ人の特権がなくなりイスラーム教徒の平等へ", "751年 タラス河畔の戦い→唐軍が敗れ、製紙法が西方へ伝わる契機とされる", "751年 ピピン(小ピピン)がカロリング朝を開く→756年ピピンの寄進で教皇領のはじまり", "755年 安史の乱→節度使の自立が進み、唐の中央集権体制がくずれる", "756年 後ウマイヤ朝がコルドバに成立→イスラーム世界の政治的分裂のはじまり", "762年ごろ アッバース朝がバグダードを建設→国際商業都市として繁栄", "780年 唐が両税法を採用→均田制・租調庸制の崩壊を受けた税制転換", "800年 カール大帝が教皇レオ3世から西ローマ皇帝の帝冠を受ける"], "sync": [["ヨーロッパ", "トゥール・ポワティエ間の戦い(732年)、カロリング朝の成立(751年)とピピンの寄進、カール大帝の戴冠(800年)。ビザンツの聖像禁止令(726年)"], ["西アジア・北アフリカ", "ウマイヤ朝の最大版図からアッバース朝の成立(750年)へ。バグダードの建設。後ウマイヤ朝の成立(756年)"], ["南アジア・東南アジア", "イスラーム勢力がインダス川下流域に進出。ジャワ島にシャイレンドラ朝が台頭しボロブドゥールの造営がはじまる"], ["東アジア・内陸アジア", "玄宗の開元の治から安史の乱(755年)へ。両税法(780年)。ウイグル・吐蕃の強大化。日本の奈良時代と平安遷都"], ["アメリカ・アフリカ", "マヤの古典期の都市が繁栄から衰退へ向かいはじめる。西アフリカにガーナ王国が金の産地として知られる"], ["世界のつながり", "タラス河畔の戦い(751年)と製紙法の西伝。ムスリム商人の海上進出と長安・バグダードという東西の国際都市"]], "secs": [{"t": "8世紀を見る視点:三つの世界の再編", "p": ["8世紀の世界を横に見ると、ユーラシアに並び立つ三つの世界、すなわちイスラーム世界、唐を中心とする東アジア世界、そして西ヨーロッパ世界のそれぞれで、大きな転換が起きていることがわかります。イスラーム世界では、アラブ人が特権をもつウマイヤ朝が倒れ、イスラーム教徒であれば民族を問わず平等とする【アッバース朝】が成立しました。東アジアでは、繁栄の頂点にあった唐が【安史の乱】によって大きくつまずき、律令による支配から新しい仕組みへと移りはじめました。西ヨーロッパでは、フランク王国の【カロリング家】がローマ教皇と手を結び、ビザンツ帝国から自立した新しいキリスト教世界の中心となっていきました。", "しかもこれらの転換は、互いに無関係ではありません。イスラーム勢力の北上をフランク王国が食い止めたことは、フランク王国の威信を高めました。アッバース朝と唐は中央アジアで直接衝突しました。8世紀のちょうど中ごろ、750年前後に、三つの世界のすべてで大きなできごとが集中していることに注目しましょう(750年アッバース朝成立、751年タラス河畔の戦い・カロリング朝成立、755年安史の乱)。"]}, {"t": "西アジア・北アフリカ:ウマイヤ朝からアッバース朝へ", "p": ["【ウマイヤ朝】は8世紀の初めに最大の領域を築きました。西では北アフリカを征服したのち、711年にイベリア半島に渡って【西ゴート王国】を滅ぼし、半島の大部分を支配下に入れました。東では中央アジアのソグディアナやインダス川下流域にまで進出しました。こうしてイスラーム世界は、大西洋岸から中央アジア・インドの入り口にまで広がる大帝国となりました。", "しかし、ウマイヤ朝の支配には大きな不満がありました。ウマイヤ朝はアラブ人を支配者とする国家であり、征服地の住民がイスラームに改宗しても、【マワーリー】(非アラブ人の改宗者)はジズヤ(人頭税)を課されるなど、アラブ人と同じ扱いを受けられませんでした。さらにシーア派の人々もウマイヤ家の支配を認めていませんでした。こうした不満を背景に、ムハンマドの叔父の子孫であるアッバース家が反乱を起こし、750年にウマイヤ朝を倒して【アッバース朝】を開きました。", "アッバース朝では、イスラーム教徒であればアラブ人かどうかを問わずジズヤが免除され、またアラブ人であっても土地をもてばハラージュ(地租)を払うことになりました。これによって、アラブ人の特権に基づく「アラブ帝国」から、信仰を共有する者が平等な「【イスラーム帝国】」へと性格が変わったとされます。行政ではイラン人の官僚が活躍し、ササン朝の統治の伝統が取り入れられました。第2代カリフの【マンスール】は、ティグリス川のほとりに円形の新都【バグダード】を建設しました。バグダードは東西の交易路が交わる位置にあり、8世紀末の【ハールーン=アッラシード】の時代に最盛期を迎えます。", "一方、アッバース家の追及を逃れたウマイヤ家の一族はイベリア半島に渡り、756年に【コルドバ】を都として【後ウマイヤ朝】を建てました。こうしてイスラーム世界は、成立から1世紀あまりで政治的には複数の国家に分かれはじめます。ただし、政治的に分かれても、アラビア語・コーラン・イスラーム法を共有する文化的なまとまりは保たれ、人や商品は自由に行き来しました。"]}, {"t": "ヨーロッパ:フランク王国と教皇の結びつき", "p": ["イスラーム軍はイベリア半島からさらにピレネー山脈を越えてガリアに侵入しましたが、732年の【トゥール・ポワティエ間の戦い】で、フランク王国の宮宰【カール=マルテル】に撃退されました。この勝利によってカロリング家の威信は大いに高まりました。", "一方、東方のビザンツ帝国では、726年に皇帝【レオン3世】が【聖像禁止令】を出しました。偶像崇拝を厳しく否定するイスラームとの対抗や、聖像をあがめる修道院の勢力をおさえることがねらいだったと考えられています。しかし、ゲルマン人への布教に聖像を用いていたローマ教会はこれに強く反発し、東西の教会の対立が深まりました。ビザンツ皇帝とたもとを分かつことになったローマ教皇は、新たな保護者を求めて、西ヨーロッパで最も強い勢力であったフランク王国に接近します。", "カール=マルテルの子【ピピン】(小ピピン)は、教皇の支持を得て751年にメロヴィング朝の王を退け、【カロリング朝】を開きました。その返礼として、ピピンはイタリアに出兵してランゴバルド人から奪ったラヴェンナ地方を教皇に寄進しました(756年、【ピピンの寄進】)。これが【教皇領】のはじまりです。ここで、王権は教会から正統性を得て、教会は王権から保護と領土を得るという、たがいに支えあう関係が成立しました。", "ピピンの子【カール大帝】(シャルルマーニュ)は、ランゴバルド王国を滅ぼし、ザクセン人を征服してキリスト教を強制し、東方では【アヴァール人】を撃退して、西ヨーロッパの大部分を支配下に置きました。地方には【伯】を置いて統治させ、【巡察使】を派遣して監督しました。また宮廷に学者【アルクイン】らを招き、ラテン語や古典の学問を復興させました。これを【カロリング=ルネサンス】といいます。そして800年のクリスマスに、カールは教皇【レオ3世】からローマで【西ローマ皇帝】の帝冠を受けました。", "この戴冠は、ローマ的な伝統・キリスト教・ゲルマン人の三つの要素が結びついた【西ヨーロッパ世界】の成立を示すできごととされます。同時に、ローマ教会がビザンツ皇帝から政治的に自立したことも意味していました。8世紀末には、北方の【ノルマン人】(ヴァイキング)がブリテン島などの沿岸を襲いはじめており、9世紀に本格化する外部勢力の侵入の前ぶれとなりました。"]}, {"t": "東アジア:唐の繁栄と安史の乱", "p": ["唐では、8世紀前半の【玄宗】の治世の前半が【開元の治】と呼ばれる安定期となりました。都の【長安】は国際都市として繁栄し、李白や杜甫といった詩人が活躍しました。しかしその裏では、律令体制の土台が崩れはじめていました。人口の増加と貴族・寺院による大土地所有の広がりで、農民に土地を割り当てる【均田制】が維持できなくなり、重い負担に耐えかねて逃亡する農民が増えました。その結果、農民の兵役による【府兵制】も成り立たなくなり、兵士を雇う【募兵制】に変わりました。辺境の防衛には、軍隊を率いる【節度使】が置かれました。", "755年、北方の三つの節度使を兼ねていたソグド系の武将【安禄山】が、部下の【史思明】とともに反乱を起こしました。これを【安史の乱】といいます。反乱軍は洛陽・長安を占領し、玄宗は四川へ逃れました。唐は遊牧国家【ウイグル】の援軍を得て、ようやく763年に乱を平定しましたが、その後、各地の節度使は軍事・財政・行政の権限をにぎって半ば独立した勢力(藩鎮)となりました。また西方では【吐蕃】が一時長安を占領するなど、唐の対外的な力も大きく後退しました。", "こうした状況の中で、唐は780年に宰相【楊炎】の建議で【両税法】を採用しました。これは、土地を割り当てた農民に一律に課税する租調庸制をやめ、実際に所有している土地や資産に応じて夏と秋の2回、銭で納めさせる税制です。土地の私有と大土地所有を事実上認めたことを意味し、のちの宋代以降の税制の基本となりました。また塩の専売を強化して財源を確保しました。安史の乱は、唐の前期と後期を分ける大きな転換点であり、貴族と律令の時代から、のちの宋の新しい社会へと向かう変化のはじまりでもありました。", "周辺の国々では、モンゴル高原で744年に【ウイグル】が突厥にかわって覇権をにぎり、唐から多くの絹を得て繁栄しました。朝鮮半島の【新羅】は唐の制度を取り入れ、仏教文化が栄えて慶州に仏国寺などが建てられました。日本は710年に【平城京】に都を移し、【遣唐使】を送って唐の制度や文化を学び、天平文化を花開かせました。唐からは僧の鑑真が渡来しています。794年には【平安京】に都が移されました。中国東北部の【渤海】も唐の制度を取り入れ「海東の盛国」と呼ばれました。"]}, {"t": "南アジア・東南アジア・アメリカ・アフリカ", "p": ["インドでは、ハルシャ王の死後、北インドに【ラージプート】と呼ばれる諸勢力が分立する時代が続いていました。8世紀初めには、ウマイヤ朝のアラブ軍がインダス川下流域のシンド地方に進出し、インドにイスラーム勢力が足がかりを得ました。ただし本格的なイスラーム勢力のインド進出は、11世紀以降のことです。南インドでも複数の王朝が並び立ち、ヒンドゥー教の寺院建築が発達しました。", "東南アジアでは、ジャワ島中部で大乗仏教を信仰する【シャイレンドラ朝】が台頭し、8世紀後半から9世紀にかけて巨大な仏教遺跡【ボロブドゥール】が造営されたとされます。スマトラ島の【シュリーヴィジャヤ】はマラッカ海峡の交易を押さえて繁栄を続けていました。", "アメリカ大陸では、マヤの都市国家が8世紀に繁栄の頂点を迎えたのち、まもなく衰退に向かいはじめたとされます。アンデスでも高地の国家が発展していました。西アフリカでは、ニジェール川上流域の金の産地を背景に【ガーナ王国】が栄え、サハラ砂漠を越えて北アフリカのイスラーム商人と【金と塩】を交換する交易がおこなわれていました。この【サハラ縦断交易】によって、のちにイスラームが西アフリカに伝わっていきます。"]}, {"t": "世界のつながり:タラス河畔の戦いと東西の国際都市", "p": ["751年、中央アジアのタラス川のほとりで、唐の軍とアッバース朝の軍が衝突しました。これが【タラス河畔の戦い】で、唐軍は敗れました。このとき捕虜となった唐の兵士の中に紙すき職人がいて、【製紙法】がイスラーム世界に伝わったとされます。その後、サマルカンドやバグダードに製紙工場がつくられ、紙はイスラーム世界の学問や行政を支えました。製紙法はやがてイベリア半島やシチリアを通じてヨーロッパにも伝わります。この戦いの後、唐は中央アジアから後退し、中央アジアのトルコ人の間にはしだいにイスラームが広がっていきました。", "8世紀のユーラシアには、東の【長安】と西の【バグダード】という、二つの巨大な国際都市がありました。長安にはソグド人やペルシア人、アラブ人が集まり、ゾロアスター教(祆教)、マニ教、景教(ネストリウス派キリスト教)の寺院も建てられました。781年に長安に建てられた【大秦景教流行中国碑】は、景教が中国で広まっていた様子を伝えています。バグダードには、インド洋から中国にいたる海の道と、中央アジアを通る陸の道の両方を通じて、各地の商品と人々が集まりました。", "海の道では、【ムスリム商人】がダウ船を使ってインド洋に乗り出し、中国南部の【広州】にまで来航しました。唐は広州に【市舶司】を置いて海上交易を管理しました。陸のシルク=ロードと海の道の両方で、イスラーム世界と東アジアが結ばれていたのです。一方、西ヨーロッパは地中海交易の中心から外れて農業を基盤とする社会となっており、商業の面ではイスラーム世界やビザンツ帝国に比べて遅れた地域でした。8世紀の世界の経済と文化の中心は、まだ東方にあったといえます。"]}], "points": ["711年西ゴート王国滅亡、732年トゥール・ポワティエ間の戦い(カール=マルテル)の流れ", "アッバース朝(750年)でマワーリーへの差別が解消=アラブ帝国からイスラーム帝国へ。マンスールのバグダード建設", "後ウマイヤ朝(756年、コルドバ)の成立=イスラーム世界の政治的分裂のはじまり", "聖像禁止令(726年、レオン3世)→教皇がフランク王国に接近→ピピンの寄進(756年)→カールの戴冠(800年)", "カール大帝:伯と巡察使、アルクインとカロリング=ルネサンス、アヴァール人撃退", "安史の乱(755年)→節度使の自立、ウイグルの援軍。両税法(780年、楊炎)で均田制・租調庸制から転換", "タラス河畔の戦い(751年)と製紙法の西伝", "ガーナ王国の金と塩の交易、シャイレンドラ朝のボロブドゥール"], "check": [["732年、イスラーム軍の北上を食い止めたフランク王国の宮宰は誰か", "カール=マルテル"], ["726年に聖像禁止令を出したビザンツ皇帝は誰か", "レオン3世"], ["ウマイヤ朝で差別を受けた非アラブ人のイスラーム改宗者を何というか", "マワーリー"], ["バグダードを建設したアッバース朝第2代カリフは誰か", "マンスール"], ["756年にコルドバを都として成立した王朝は何か", "後ウマイヤ朝"], ["751年に唐とアッバース朝が戦い、製紙法の西伝の契機となったとされる戦いは何か", "タラス河畔の戦い"], ["ラヴェンナ地方を教皇に寄進し、教皇領のはじまりとなったのは誰か", "ピピン(小ピピン)"], ["800年にカール大帝に帝冠を与えた教皇は誰か", "レオ3世"], ["755年に安禄山と史思明が起こした反乱は何か", "安史の乱"], ["780年、楊炎の建議で唐が採用した税制は何か", "両税法"]], "related": ["y_7", "y_9", "t_ar", "t_fr", "t_byz", "t_cn", "t_es", "t_af"], "n": 4444}, "y_9": {"title": "9世紀の世界", "span": "801〜900年", "year": 850, "lead": "9世紀は、8世紀に頂点を迎えた大帝国が、それぞれ内部から分かれていく世紀です。カール大帝のフランク王国はヴェルダン条約・メルセン条約で三つに分かれ、アッバース朝では地方政権が自立し、唐は黄巣の乱で崩壊寸前となりました。その一方で、ノルマン人の活動やウイグルの西遷のように、人の大移動が新しい国家と文化の地図をつくっていきました。", "flow": ["802年 ジャヤヴァルマン2世がカンボジアを統一→アンコール朝のはじまり", "9世紀前半 アッバース朝のバグダードに知恵の館がつくられ、ギリシア語文献のアラビア語への翻訳が進む", "840年 ウイグルがキルギスに敗れて崩壊→ウイグル人が西へ移りタリム盆地のトルコ化が進む", "843年 ヴェルダン条約→フランク王国が三つに分割される", "843年 ビザンツ帝国で聖像崇拝が最終的に復活", "845年 唐の武宗による会昌の廃仏→仏教をはじめ外来宗教が打撃を受ける", "862年 リューリクがノヴゴロド国を建てたとされる→ロシア国家の起源", "870年 メルセン条約→のちのドイツ・フランス・イタリアのもとになる境界が形づくられる", "875年 黄巣の乱→唐の支配が事実上くずれる", "875年 サーマーン朝が中央アジアに成立→イラン系地方政権の自立", "9世紀後半 イングランドのアルフレッド大王がデーン人の侵入と戦う", "894年 日本が遣唐使の派遣を停止→のちの国風文化の発達へ"], "sync": [["ヨーロッパ", "フランク王国の分裂(843年ヴェルダン条約・870年メルセン条約)。ノルマン人・マジャール人・イスラーム勢力の侵入。ノヴゴロド国の成立"], ["西アジア・北アフリカ", "アッバース朝の文化的最盛期(知恵の館)。トルコ人奴隷兵(マムルーク)の登用と地方政権の自立(サーマーン朝など)"], ["南アジア・東南アジア", "アンコール朝の成立(802年)。ジャワのボロブドゥール完成。南インドでチョーラ朝が再興"], ["東アジア・内陸アジア", "唐の衰退:会昌の廃仏(845年)・黄巣の乱(875年)。ウイグルの崩壊(840年)と西遷。日本の遣唐使停止(894年)"], ["アメリカ・アフリカ", "マヤ南部低地の古典期の都市が衰退し放棄される。西アフリカのガーナ王国の金交易"], ["世界のつながり", "ノルマン人が北海・バルト海と黒海・カスピ海を結ぶ交易路を開く。ギリシアの学問がアラビア語に翻訳され保存される"]], "secs": [{"t": "9世紀を見る視点:大帝国の分裂と人の移動", "p": ["9世紀の世界を横に見ると、前の世紀に大きな版図を築いた国々が、そろって分裂や衰退の道をたどっていることに気づきます。西ヨーロッパのフランク王国、西アジアのアッバース朝、東アジアの唐は、いずれも8世紀に最盛期を迎えた後、9世紀に内部から崩れはじめました。原因はそれぞれ異なりますが、広すぎる領域を一人の支配者が治めることのむずかしさ、地方の有力者の自立、財政のゆきづまりという点では共通しています。", "同時に9世紀は、人の移動が活発な時代でもありました。北ヨーロッパからは【ノルマン人】が海を越えて各地に進出し、東ヨーロッパではスラヴ人の国家が形成されはじめました。モンゴル高原の【ウイグル】は崩壊して西へ移り、中央アジアのトルコ化を進めました。イスラーム世界では、中央アジアのトルコ人が奴隷兵として西アジアに流れこみました。こうした人々の動きが、10世紀以降の新しい国家の地図をつくる原動力となったのです。"]}, {"t": "ヨーロッパ:フランク王国の分裂と外部勢力の侵入", "p": ["814年にカール大帝が亡くなると、その子ルートヴィヒ1世が帝国を受け継ぎましたが、その死後、3人の孫の間で争いが起こりました。843年の【ヴェルダン条約】で、フランク王国は【東フランク】・【西フランク】・【中部フランク】(ロタールの王国)の三つに分けられました。さらに870年の【メルセン条約】で、中部フランクの北部が東西のフランクに分割されました。この結果、東フランクはのちの【ドイツ】、西フランクはのちの【フランス】、残ったイタリア部分はのちの【イタリア】の原型となりました。フランク人には、王国を子どもたちに分ける分割相続の慣習があったことが、分裂の大きな原因でした。", "王権が弱まったところに、外部からの侵入が相次ぎました。北からは【ノルマン人】(ヴァイキング)が、すぐれた航海技術をもつ船で川をさかのぼって内陸の町や修道院を襲いました。東からはアジア系の【マジャール人】が9世紀末にパンノニア(現在のハンガリー)に移り住み、そこから西ヨーロッパに侵入をくり返しました。南からはイスラーム勢力が地中海の島々や沿岸を襲い、シチリア島もしだいにイスラームの支配下に入りました。", "こうした侵入に対して、遠く離れた王の軍隊はほとんど役に立ちませんでした。人々は身近な有力者に保護を求め、有力者はさらに上位の有力者と主従関係を結びました。土地(封土)を与えるかわりに軍事的な奉仕を求める【封建的主従関係】と、領主が農民(【農奴】)を支配する【荘園】の仕組みが組み合わさった【封建社会】は、こうした外部からの圧力のもとで9世紀から10世紀にかけて形づくられていきます。", "ノルマン人の活動は、略奪だけではありませんでした。イングランドでは、デーン人(デンマーク系のノルマン人)の侵入に対し、ウェセックス王の【アルフレッド大王】が9世紀後半に抵抗して王国を守り、学問の振興にもつとめました。東方では、ルーシと呼ばれたスウェーデン系のノルマン人の首長【リューリク】が、862年に【ノヴゴロド国】を建てたとされます。その後、一族はドニエプル川を南下して【キエフ公国】を建て、ここからロシア国家の歴史がはじまります。", "ビザンツ帝国では、843年に【聖像崇拝】が最終的に復活し、聖像をめぐる長い論争が終わりました。9世紀後半には、【キュリロス】(キリル)とメトディオスの兄弟がスラヴ人への布教をおこない、スラヴ語を書き表すための文字をつくりました。これをもとにのちに【キリル文字】がつくられ、ロシアやバルカン半島のスラヴ人の文字として使われることになります。867年には【マケドニア朝】が成立し、ビザンツ帝国は10世紀から11世紀初めにかけて再び勢いを取り戻します。"]}, {"t": "西アジア・北アフリカ:アッバース朝の繁栄と分裂", "p": ["アッバース朝は、8世紀末の【ハールーン=アッラシード】の時代から9世紀前半にかけて、政治的にも文化的にも最盛期を迎えました。都バグダードは人口の多い国際都市となり、『千夜一夜物語』(アラビアン=ナイト)にもその繁栄ぶりが描かれています。第7代カリフ【マームーン】のころには、バグダードに【知恵の館】(バイト=アルヒクマ)と呼ばれる研究・翻訳の機関が整えられたとされ、アリストテレスなどのギリシア語の哲学・医学・天文学の文献が、シリア語やアラビア語に盛んに翻訳されました。", "この翻訳活動のなかから、イスラーム世界独自の学問が生まれました。数学者の【フワーリズミー】は、インドから伝わった数字とゼロの考え方を取り入れて代数学を発展させ、その名はアルゴリズムという言葉の語源になったとされます。イスラーム世界で保存・発展したギリシアの学問は、のちに12世紀のヨーロッパにラテン語訳で伝わり、西ヨーロッパの学問の復興に大きく貢献することになります。", "しかし政治的には、9世紀のアッバース朝はしだいに分裂していきました。カリフは中央アジアから連れてこられたトルコ人の奴隷兵、すなわち【マムルーク】を親衛隊として重用するようになりましたが、やがてトルコ人の軍人たちがカリフの廃立にまで口を出すようになりました。地方では、総督が世襲の政権を立てて自立しはじめ、中央アジアにはイラン系の【サーマーン朝】が875年に成立しました。サーマーン朝はブハラを都とし、ペルシア語の文化を復興させるとともに、トルコ人をマムルークとしてイスラーム世界の中心部に送り出す役割を果たしました。エジプトでも地方政権が自立し、カリフが直接支配する範囲は縮小していきました。", "なぜイスラーム世界は政治的に分かれても、ひとつの世界として続いたのでしょうか。それは、カリフの権威が宗教的な象徴として尊重され続けたこと、アラビア語とイスラーム法が共通の文化と規範を提供したこと、そして商業のネットワークが政治の境界を越えて機能し続けたことによります。この点で、政治の分裂がそのまま社会の分断につながった西ヨーロッパとは違いが見られます。"]}, {"t": "東アジア:唐の衰退とウイグルの西遷", "p": ["安史の乱の後、唐は節度使の自立に悩まされながらも、両税法と塩の専売によって財政を立て直し、9世紀前半まではなんとか命脈を保っていました。しかし宮廷では宦官が権力をにぎって皇帝の廃立にまで関わり、官僚たちの派閥争いも続いて、政治はしだいに乱れていきました。", "845年、道教を信仰した【武宗】は、寺院の財産と僧尼を国家に取り戻すため、大規模な仏教弾圧をおこないました。これを【会昌の廃仏】といいます。このとき仏教だけでなく、景教・マニ教・祆教(ゾロアスター教)などの外来宗教も弾圧され、唐の国際的な文化は大きな打撃を受けました。仏教のなかでは、経典や寺院にあまり依存しない【禅宗】や、念仏による救いを説く【浄土宗】が、その後も民衆や士大夫の間で広まりました。", "9世紀後半になると、重税と塩の専売による塩価の高騰に苦しむ民衆の不満が高まり、塩の密売人であった【黄巣】が875年に反乱を起こしました。これが【黄巣の乱】です。反乱軍は中国各地を転戦して広州や長安を攻め落とし、その過程で広州の外国人商人が多数殺されたとも伝えられます。乱はやがて鎮圧されましたが、唐の支配は事実上崩壊し、反乱軍から唐に寝返った【朱全忠】が実権をにぎりました。唐は907年に滅ぶことになります。", "北方では、モンゴル高原を支配していた【ウイグル】が、840年にキルギスの攻撃を受けて崩壊しました。ウイグル人の多くは西へ移動し、天山山脈周辺やタリム盆地のオアシス都市に定着しました。もともとイラン系の人々が多く住んでいたこの地域では、これを機にトルコ系の言語を話す人々が増え、のちに【トルキスタン】(トルコ人の土地)と呼ばれるようになります。チベットの吐蕃も9世紀半ばに分裂し、唐の周辺の強国が相次いで力を失いました。", "日本では、唐の衰えと航海の危険を理由に、894年に【菅原道真】の建議で【遣唐使】の派遣が停止されました。これ以後、唐の文化を消化したうえで日本の風土や感覚に合った【国風文化】が発達していきます。朝鮮半島の【新羅】も9世紀に入ると王位をめぐる争いで乱れ、地方の豪族が力を強めていきました。"]}, {"t": "南アジア・東南アジア・アメリカ・アフリカ", "p": ["東南アジア大陸部では、802年に【ジャヤヴァルマン2世】がカンボジアを統一し、【アンコール朝】がはじまりました。アンコール朝はヒンドゥー教と仏教を受け入れ、王を神と結びつける考え方で王権を強め、のちに12世紀のアンコール=ワットに代表される壮大な寺院を築きます。ジャワ島中部では【シャイレンドラ朝】のもとで仏教遺跡【ボロブドゥール】が9世紀に完成したとされ、その後同じジャワ中部にヒンドゥー教の寺院も建てられました。南インドでは、9世紀に【チョーラ朝】が再び勢力をのばしはじめ、のちに海上に進出する大国へと成長していきます。", "メソアメリカでは、9世紀にマヤ南部の低地にあった古典期の都市が次々に衰退し、放棄されたとされます。原因については、人口増加による環境の悪化、干ばつ、都市間の戦争など諸説あり、はっきりしたことはわかっていません。その後、マヤ文明の中心はユカタン半島北部へと移っていきます。西アフリカでは、【ガーナ王国】がサハラ縦断交易によって豊かな金を北アフリカへ送り出し、繁栄を続けていました。"]}, {"t": "世界のつながり:ノルマン人の交易路と学問の継承", "p": ["ノルマン人は、略奪者であると同時にすぐれた交易者でもありました。スウェーデン系のルーシは、バルト海からロシアの川をたどって黒海やカスピ海に出る交易路を開き、毛皮や奴隷を運んで、ビザンツ帝国やアッバース朝の銀貨を手に入れました。スカンディナヴィア各地の遺跡からは、イスラーム世界の銀貨が大量に見つかっています。北ヨーロッパは、ノルマン人の活動を通じて、ビザンツやイスラームの経済圏と結びついていたのです。", "文化の面では、9世紀はギリシアの学問の継承という点で重要な世紀です。ビザンツ帝国ではギリシア語の古典が受け継がれ、アッバース朝ではそれがアラビア語に翻訳されて発展しました。一方、西ヨーロッパでは、カロリング=ルネサンスによってラテン語の古典が修道院で写本として保存されました。古代の学問は、ビザンツ・イスラーム・西欧という三つの世界でそれぞれ違った形で受け継がれ、のちにふたたび結びつくことになります。", "東西を比べると、9世紀は、大帝国の分裂がそれぞれの地域の個性を生んだ世紀だといえます。フランク王国の分裂からドイツ・フランス・イタリアの原型が生まれ、アッバース朝の分裂からイラン系やトルコ系の地方政権が生まれ、唐の衰退は日本や朝鮮半島に独自の文化を育てる余地を与えました。帝国の分裂は混乱であると同時に、新しい地域世界の誕生でもあったのです。"]}], "points": ["ヴェルダン条約(843年)とメルセン条約(870年)→ドイツ・フランス・イタリアの原型", "ノルマン人・マジャール人・イスラーム勢力の侵入が封建社会の形成をうながした", "リューリクのノヴゴロド国(862年)→キエフ公国、アルフレッド大王のデーン人との戦い", "ビザンツ:843年聖像崇拝の復活、キュリロスのスラヴ人布教とキリル文字、マケドニア朝の成立(867年)", "アッバース朝:マームーンと知恵の館、フワーリズミー、マムルークの登用、サーマーン朝(875年)", "唐:会昌の廃仏(845年、武宗)、黄巣の乱(875年)、朱全忠", "ウイグルの崩壊(840年、キルギス)と西遷→トルキスタンの形成", "アンコール朝の成立(802年)とボロブドゥール"], "check": [["843年にフランク王国を三分した条約は何か", "ヴェルダン条約"], ["870年に中部フランクの北部を東西フランクで分けた条約は何か", "メルセン条約"], ["862年にノヴゴロド国を建てたとされるノルマン人の首長は誰か", "リューリク"], ["9世紀後半にデーン人の侵入と戦ったイングランドの王は誰か", "アルフレッド大王"], ["アッバース朝で知恵の館を整えたとされるカリフは誰か", "マームーン"], ["中央アジアのトルコ人奴隷兵を何というか", "マムルーク"], ["845年に唐の武宗がおこなった仏教弾圧を何というか", "会昌の廃仏"], ["875年に塩の密売人が起こした反乱は何か", "黄巣の乱"], ["840年にウイグルを滅ぼした遊牧民は何か", "キルギス"], ["802年にカンボジアを統一しアンコール朝を開いた王は誰か", "ジャヤヴァルマン2世"]], "related": ["y_8", "y_10", "t_fr", "t_de", "t_ru", "t_uk", "t_ar", "t_cn", "t_mn", "t_mm"], "n": 4319}, "y_10": {"title": "10世紀の世界", "span": "901〜1000年", "year": 950, "lead": "10世紀は、9世紀に分裂した世界の各地で、新しい国家がいっせいに生まれた世紀です。中国では唐の滅亡後の五代十国の分裂を宋が統一し、北方には遼(契丹)が成立しました。イスラーム世界ではカリフが三人並び立ち、ヨーロッパでは神聖ローマ帝国とカペー朝が成立しました。のちの国の枠組みの多くが、この世紀にかたちを見せはじめます。", "flow": ["907年 朱全忠が唐を滅ぼし後梁を建てる→五代十国時代", "909年 ファーティマ朝が北アフリカに成立→シーア派のカリフを名のる", "911年 ノルマン人の首長ロロがノルマンディー公国を建てる", "916年 耶律阿保機が契丹(遼)を建国→926年渤海を滅ぼす", "918年 王建が高麗を建てる→936年朝鮮半島を統一", "936年 遼が燕雲十六州を獲得→中国北辺の要地が遊牧王朝の支配下に", "946年 ブワイフ朝がバグダードに入る→アッバース朝カリフは実権を失う", "955年 レヒフェルトの戦い→オットー1世がマジャール人を撃退", "960年 趙匡胤(太祖)が宋を建てる→文治主義による中央集権化", "962年 オットー1世が教皇から帝冠を受ける→神聖ローマ帝国のはじまり", "987年 ユーグ=カペーがカペー朝を開く", "988年ごろ キエフ公国のウラディミル1世がギリシア正教に改宗"], "sync": [["ヨーロッパ", "クリュニー修道院(910年)、ノルマンディー公国(911年)、神聖ローマ帝国(962年)、カペー朝(987年)、キエフ公国のギリシア正教受容"], ["西アジア・北アフリカ", "ファーティマ朝(909年)のエジプト征服とカイロ建設。ブワイフ朝のバグダード入城(946年)。三カリフの並立"], ["南アジア・東南アジア", "南インドのチョーラ朝が台頭。アンコール朝が発展し、ベトナムが中国から自立する"], ["東アジア・内陸アジア", "唐の滅亡(907年)と五代十国。遼の建国(916年)と燕雲十六州。高麗の建国(918年)。宋の建国(960年)"], ["アメリカ・アフリカ", "メキシコ高原でトルテカ文明が栄える。マヤの中心がユカタン半島北部へ。西アフリカのガーナ王国、東アフリカ沿岸の港市"], ["世界のつながり", "中央アジアのトルコ人がイスラームを受け入れはじめる。ノルマン人のアイスランド・グリーンランドへの進出"]], "secs": [{"t": "10世紀を見る視点:分裂のあとの新しい国家", "p": ["10世紀の世界を横に見ると、9世紀に分裂・衰退した大帝国のあとに、新しい国家が各地でいっせいに誕生していることがわかります。東アジアでは唐が滅び、半世紀あまりの分裂を経て【宋】が成立しました。北方では遊牧民の【契丹】が【遼】を建て、朝鮮半島では【高麗】が生まれました。ヨーロッパでは東フランクから【神聖ローマ帝国】、西フランクから【カペー朝】のフランス王国が生まれ、東方では【キエフ公国】がギリシア正教を受け入れました。イスラーム世界では、アッバース朝のほかにファーティマ朝と後ウマイヤ朝の君主もカリフを名のり、三つのカリフが並び立ちました。", "もうひとつの特徴は、遊牧民や移動してきた民族が定住し、自らの国家をつくりはじめたことです。遼を建てた契丹、ハンガリーに定着したマジャール人、ノルマンディーに定着したノルマン人、イスラームに改宗した中央アジアのトルコ人などがその例です。彼らは周辺の文明を取り入れながら国家を整え、11世紀以降の歴史で大きな役割を果たしていきます。"]}, {"t": "東アジア:五代十国から宋へ、遼と高麗", "p": ["907年、黄巣の乱で台頭した【朱全忠】が唐を滅ぼして【後梁】を建てました。以後、華北では後梁・後唐・後晋・後漢・後周の五つの王朝が短期間で交代し、華中・華南などには十ほどの地方政権が分立しました。これを【五代十国】の時代といいます。五代の王朝の多くは節度使出身の武人が建てたもので、武力による争いが絶えませんでした。", "この混乱の中で、唐代まで政治の中心にいた門閥貴族は没落しました。かわって台頭したのが、土地を所有して小作人(佃戸)に耕作させる【形勢戸】と呼ばれる新しい地主層です。彼らは儒学を学んで科挙に合格し、官僚となりました。また江南では、十国の政権のもとで開発が進み、経済の重心が南へ移る動きがはっきりしてきました。", "北方では、モンゴル高原東部の遊牧民【契丹】の【耶律阿保機】が諸部族を統合し、916年に国を建てました(のち国号を【遼】とする)。契丹は926年に【渤海】を滅ぼし、936年には五代の後晋の建国を助けた見返りとして【燕雲十六州】(現在の北京や大同を含む地域)を手に入れました。遼は遊牧民を部族制で、農耕民を州県制で治める【二重統治体制】をとり、漢字をもとにした【契丹文字】もつくりました。遼の支配下に入った燕雲十六州は、こののち宋と遼の争いの焦点となります。", "後周の武将であった【趙匡胤】は、960年に皇帝となって【宋】(北宋)を建て、【太祖】となりました。都は大運河と黄河が交わる交通の要地【開封】に置かれました。太祖は、唐末以来の節度使の勢力が王朝を不安定にしてきた反省から、節度使の権力を奪い、軍隊を皇帝直属の【禁軍】に集めました。また科挙を整備して、皇帝自らが最終試験をおこなう【殿試】をはじめ、科挙出身の文人官僚に政治を担わせる【文治主義】をとりました。第2代太宗の時代の979年に中国本土の統一が完成します。文治主義は皇帝の独裁と政治の安定をもたらしましたが、軍事力の弱体化を招き、のちに遼や西夏への対応に苦しむ原因にもなりました。", "朝鮮半島では、新羅の衰退後に地方勢力が争う後三国の時代を経て、918年に【王建】が【高麗】を建て、936年に半島を統一しました。都は開城に置かれ、仏教が保護されました。日本では、律令制がゆるみ藤原氏による【摂関政治】が進み、地方では平将門や藤原純友の反乱が起こるなど、武士の成長が見られました。ベトナムでも10世紀に中国の支配から自立した政権が生まれ、のちの李朝へとつながっていきます。中国の統一王朝が倒れたことが、周辺の国々の自立と独自の国家づくりをうながしたといえるでしょう。"]}, {"t": "西アジア・北アフリカ:三カリフの並立とブワイフ朝", "p": ["10世紀のイスラーム世界は、政治的に大きく分かれました。909年、北アフリカのチュニジアで、シーア派の一派である【イスマーイール派】の指導者がアッバース朝に対抗して【ファーティマ朝】を建て、自らカリフを名のりました。ファーティマ朝は969年にエジプトを征服して新都【カイロ】を建設し、そこに学問の中心となる【アズハル学院】(アズハル=モスク)を建てました。これに対抗して、イベリア半島の【後ウマイヤ朝】の【アブド=アッラフマーン3世】も929年にカリフを名のりました。こうして、バグダード・カイロ・コルドバに三人のカリフが並び立つことになりました。", "本家のアッバース朝では、カリフの力はさらに弱まりました。946年には、イラン系でシーア派の軍事政権【ブワイフ朝】がバグダードに入城し、カリフから【大アミール】の称号を受けて政治の実権をにぎりました。カリフは宗教的な権威としてのみ存続することになります。ブワイフ朝は、軍人に土地の徴税権を与えてその収入で軍事奉仕をさせる【イクター制】をはじめたとされ、この制度はのちのセルジューク朝などに受け継がれ、イスラーム世界の軍事と土地支配の基本となりました。", "中央アジアでは、イラン系の【サーマーン朝】がブハラを中心に栄え、ペルシア語による文学が復興しました。10世紀には、中央アジアのトルコ系の人々がしだいにイスラームを受け入れ、トルコ系で最初のイスラーム王朝とされる【カラハン朝】が成立し、10世紀末にサーマーン朝を滅ぼしました。アフガニスタンでは、サーマーン朝に仕えたトルコ人マムルークが自立して【ガズナ朝】を建てました。ガズナ朝はのちに北インドへの侵入をくり返すことになります。トルコ人がイスラーム世界の主役として登場する準備が、この世紀に進んだのです。", "後ウマイヤ朝の都【コルドバ】は、10世紀に西ヨーロッパ最大の都市とされるほど繁栄し、イスラーム教徒・キリスト教徒・ユダヤ教徒が共存する学問と文化の中心でした。コルドバの繁栄は、同時代のキリスト教世界の西ヨーロッパの都市と比べると際立っていました。"]}, {"t": "ヨーロッパ:神聖ローマ帝国・カペー朝・キエフ公国", "p": ["10世紀の初め、西ヨーロッパはまだ外部からの侵入に苦しんでいました。西フランク王は、セーヌ川下流域を荒らしていたノルマン人の首長【ロロ】に土地を与え、911年に【ノルマンディー公国】が成立しました。ノルマン人はこの地でキリスト教に改宗し、フランス語を話すようになり、のちにイングランドや南イタリアに進出していきます。", "東フランクでは、カロリング家の血統が絶えた後、ザクセン家の王が選ばれました。【オットー1世】は、955年の【レヒフェルトの戦い】でマジャール人を破って侵入を食い止め、イタリアにも遠征して教皇を保護しました。その功績によって、962年に教皇から帝冠を受けました。これが【神聖ローマ帝国】のはじまりとされます(神聖ローマ帝国という名称が定着するのはのちの時代です)。オットー1世は、教会の聖職者を任命して国家の役人として用いる帝国教会政策をとり、諸侯の力を抑えようとしました。しかし、歴代の皇帝がイタリアの支配にこだわったこと(イタリア政策)は、ドイツ国内の統一を遅らせる一因となりました。敗れたマジャール人はハンガリーに定住し、10世紀末から11世紀初めにかけてカトリックを受け入れて【ハンガリー王国】を建てます。", "西フランクでもカロリング家が断絶し、987年に【ユーグ=カペー】が王に選ばれて【カペー朝】が開かれました。ただし、当初のカペー朝の王が直接支配したのはパリ周辺の狭い地域にすぎず、ノルマンディー公などの大諸侯の力の方が強いほどでした。フランス王権が強まるのは12世紀以降のことです。", "910年には、フランス中東部のブルゴーニュ地方に【クリュニー修道院】が創設されました。当時、教会は世俗の領主に支配され、聖職の売買や聖職者の妻帯が問題となっていましたが、クリュニー修道院は世俗の権力から独立して戒律を厳しく守り、教会の刷新を求める運動の中心となりました。この運動が、11世紀の【グレゴリウス7世】の教会改革と叙任権闘争へとつながっていきます。", "東ヨーロッパでは、【キエフ公国】の【ウラディミル1世】が、ビザンツ皇帝の妹と結婚し、988年ごろ【ギリシア正教】に改宗しました。これによってロシアはビザンツ文化圏に入り、キリル文字と正教を受け入れることになりました。一方、西スラヴ人のポーランド人やチェック人、そしてマジャール人は、ローマ=カトリックを受け入れました。東ヨーロッパの宗教の分布が、ギリシア正教とカトリックに分かれる基本形は、この時期に定まったのです。ビザンツ帝国は【マケドニア朝】のもとで勢力を回復し、10世紀末から11世紀初めにかけて最盛期を迎えます。"]}, {"t": "南アジア・東南アジア・アメリカ・アフリカ", "p": ["南インドでは、タミル人の【チョーラ朝】が10世紀後半から勢力を強め、強力な海軍を背景にスリランカや東南アジアにまで進出していきます。東南アジアでは【アンコール朝】が発展し、スマトラのシュリーヴィジャヤ(中国の記録では三仏斉)は宋との朝貢貿易で栄えました。", "アメリカ大陸のメキシコ高原では、10世紀ごろから【トルテカ】の人々が都トゥーラを中心に勢力をもったとされ、軍事的な性格の強い文化を築きました。マヤ文明の中心はユカタン半島北部に移り、【チチェン=イツァ】などの都市が栄えました。", "アフリカでは、西アフリカの【ガーナ王国】がサハラ縦断交易で繁栄を続けていました。東アフリカのインド洋沿岸では、アラブ人やペルシア人の商人が来航し、モガディシュやキルワなどの港市が発展していきました。現地のバントゥー系の言語にアラビア語の語彙が加わって【スワヒリ語】が形成され、イスラームを受け入れた【スワヒリ文化】が育っていきます。ファーティマ朝のもとでカイロが栄えると、紅海を通ってインド洋と地中海を結ぶ交易路の重要性が高まりました。"]}, {"t": "世界のつながり:定住する移動民と海の交易", "p": ["10世紀の世界のつながりを考えるとき、ノルマン人の活動は欠かせません。彼らは西ではノルマンディーに定住し、北大西洋ではアイスランドに移住し、さらにグリーンランドにまで進出しました。東ではキエフ公国がビザンツ帝国と交易し、ギリシア正教を受け入れました。ノルマン人の動きは、北ヨーロッパを西ヨーロッパ・ビザンツ・イスラームの世界と結びつけ、キリスト教世界を北へと広げる役割を果たしました。", "東西を比較すると、宋の太祖と神聖ローマ帝国のオットー1世には興味深い違いがあります。宋の太祖は武人の力をおさえ、科挙出身の文人官僚による中央集権を進めました。一方、オットー1世は教会の聖職者を役人として利用しましたが、世俗の諸侯の力を抑えきれず、ドイツは分権的な国家として歩むことになりました。同じように分裂の後に生まれた国家でも、中国では皇帝独裁の官僚国家、西ヨーロッパでは王権の弱い封建国家という、異なる道が選ばれたのです。", "海の道では、ムスリム商人と中国商人がインド洋と南シナ海で活動し、宋はのちに広州などに【市舶司】を置いて交易を管理しました。中国の陶磁器や絹がイスラーム世界や東アフリカに運ばれ、香辛料や香木が中国にもたらされました。陸上の勢力が分裂していても、海の交易は途切れることなく続き、むしろ発展していきました。この海のネットワークは、11世紀以降の宋の商業の発展とイスラーム世界の繁栄をつなぐものになります。"]}], "points": ["五代十国(907年〜)→宋の建国(960年、趙匡胤)。文治主義、殿試、禁軍", "遼(916年、耶律阿保機):渤海を滅ぼす(926年)、燕雲十六州の獲得(936年)、二重統治体制、契丹文字", "高麗の建国(918年、王建)と朝鮮半島統一(936年)", "ファーティマ朝(909年)・後ウマイヤ朝(929年)・アッバース朝の三カリフ並立。カイロとアズハル学院", "ブワイフ朝のバグダード入城(946年)と大アミール、イクター制", "オットー1世:レヒフェルトの戦い(955年)、962年の戴冠で神聖ローマ帝国", "ノルマンディー公国(911年)、カペー朝(987年)、クリュニー修道院(910年)", "キエフ公国のウラディミル1世のギリシア正教改宗と、東欧の宗教分布"], "check": [["907年に唐を滅ぼし後梁を建てたのは誰か", "朱全忠"], ["916年に契丹を統合して国を建てたのは誰か", "耶律阿保機"], ["936年に遼が後晋から獲得した地域は何か", "燕雲十六州"], ["960年に宋を建てたのは誰か", "趙匡胤(太祖)"], ["宋で皇帝自らがおこなった科挙の最終試験を何というか", "殿試"], ["909年に北アフリカで成立したシーア派の王朝は何か", "ファーティマ朝"], ["946年にバグダードに入城し大アミールの称号を得た王朝は何か", "ブワイフ朝"], ["955年にオットー1世がマジャール人を破った戦いは何か", "レヒフェルトの戦い"], ["987年にカペー朝を開いたのは誰か", "ユーグ=カペー"], ["918年に高麗を建てたのは誰か", "王建"]], "related": ["y_9", "y_11", "t_cn", "t_kr", "t_mn", "t_de", "t_fr", "t_ru", "t_ar", "t_byz"], "n": 4533}, "y_11": {"title": "11世紀の世界", "span": "1001〜1100年", "year": 1050, "lead": "11世紀は、トルコ人のセルジューク朝が西アジアの主役となり、その圧力が西ヨーロッパの十字軍を引き起こした世紀です。西ヨーロッパでは農業生産が伸び、教皇が皇帝と争うほどの力をもつようになりました。東アジアでは宋が経済的に繁栄しつつ、遼・西夏と和約を結んで共存する国際秩序がつくられました。", "flow": ["1004年 宋と遼が澶淵の盟を結ぶ→宋が毎年銀と絹を遼に贈る", "1009年 ベトナムに李朝が成立→大越として長期政権を築く", "1016年 デンマーク王クヌートがイングランド王となる→北海を囲む広い支配", "1038年 李元昊が西夏を建てる→1044年宋と慶暦の和約", "1044年 ビルマにパガン朝が成立→上座部仏教が広まる", "1054年 東西教会が相互に破門→ローマ=カトリック教会とギリシア正教会の分裂", "1055年 セルジューク朝のトゥグリル=ベクがバグダードに入城→スルタンの称号を得る", "1066年 ノルマンディー公ウィリアムがヘースティングズの戦いに勝利→ノルマン=コンクェスト", "1069年 王安石の新法がはじまる→新法党と旧法党の対立", "1071年 マンジケルトの戦い→セルジューク朝がビザンツ帝国を破りアナトリアへ進出", "1077年 カノッサの屈辱→教皇グレゴリウス7世が皇帝ハインリヒ4世を屈服させる", "1095年 クレルモン宗教会議→1096年第1回十字軍、1099年イェルサレム王国の成立"], "sync": [["ヨーロッパ", "農業生産の拡大と人口増加。叙任権闘争(カノッサの屈辱1077年)、東西教会の分裂(1054年)、ノルマン=コンクェスト(1066年)、第1回十字軍(1096年)"], ["西アジア・北アフリカ", "セルジューク朝の成立とバグダード入城(1055年)、マンジケルトの戦い(1071年)。北アフリカにムラービト朝が成立"], ["南アジア・東南アジア", "ガズナ朝の北インド侵入。チョーラ朝の海上進出。パガン朝(1044年)・李朝(1009年)の成立、アンコール朝の発展"], ["東アジア・内陸アジア", "宋と遼の澶淵の盟(1004年)、西夏の建国(1038年)と慶暦の和約(1044年)。王安石の新法。日本の摂関政治の全盛と院政の開始"], ["アメリカ・アフリカ", "マヤのチチェン=イツァ、メキシコ高原のトルテカ。西アフリカのガーナ王国が衰えはじめる"], ["世界のつながり", "セルジューク朝の進出→ビザンツの救援要請→十字軍という連鎖。宋とイスラーム世界を結ぶ海上交易の拡大"]], "secs": [{"t": "11世紀を見る視点:トルコ人の登場と十字軍への連鎖", "p": ["11世紀の世界を横に見るときのかぎとなるのは、中央アジアから西アジアに進出してきた【トルコ人】です。トルコ人は9世紀ごろからマムルーク(奴隷兵)としてイスラーム世界に入っていましたが、10世紀にイスラームを受け入れた集団が、11世紀には自ら大きな王朝を建てるようになりました。その代表が【セルジューク朝】です。セルジューク朝はバグダードに入ってスンナ派のカリフを保護し、さらにビザンツ帝国を破ってアナトリアに進出しました。", "この動きは、遠く西ヨーロッパにまで波及しました。追いつめられたビザンツ皇帝がローマ教皇に救援を求めたことがきっかけとなり、1096年に【十字軍】がはじまったのです。中央アジアのトルコ人の西進が、西アジアの政治地図を変え、さらに西ヨーロッパの大遠征を引き起こすという、ユーラシアの東西を貫く連鎖反応が11世紀に起きたことを押さえておきましょう。一方、東アジアでは、宋が遼・西夏という北方の強国と和約を結び、武力ではなく経済力で平和を保つ独特の国際関係を築いていました。"]}, {"t": "西アジア・北アフリカ:セルジューク朝の台頭", "p": ["セルジューク朝は、中央アジアのトルコ系遊牧民の一派が建てた王朝で、【トゥグリル=ベク】のもとで1038年ごろに成立しました。セルジューク朝はイラン方面に進出してガズナ朝を破り、1055年には【バグダード】に入城して、シーア派のブワイフ朝を追い払いました。トゥグリル=ベクはアッバース朝カリフから【スルタン】(権力者)の称号を与えられました。これによって、カリフが宗教的権威をもち、スルタンが政治・軍事の実権をにぎるという分担の形が確立しました。", "セルジューク朝はスンナ派を保護し、宰相【ニザーム=アルムルク】は各地に【ニザーミーヤ学院】と呼ばれるマドラサ(学院)を建てて、スンナ派の学問を振興し官僚を育てました。また、ブワイフ朝が始めた【イクター制】を受け継いで広く実施し、軍人に土地からの徴税権を与えて軍事力を支えました。イラン系の官僚とトルコ系の軍人が協力して国を治める仕組みは、その後の西アジアの王朝に受け継がれていきます。", "1071年、セルジューク朝は【マンジケルトの戦い】でビザンツ帝国軍を破り、皇帝を捕虜にしました。この勝利によってトルコ人がアナトリア(小アジア)に大量に移り住むようになり、のちに【ルーム=セルジューク朝】が建てられます。アナトリアのトルコ化とイスラーム化はここからはじまり、のちのオスマン帝国の誕生につながります。また、セルジューク朝はシリア・パレスチナにも進出し、ファーティマ朝からイェルサレムを奪いました。", "文化の面では、11世紀初めにイラン出身の【イブン=シーナー】(ラテン名アヴィケンナ)が『医学典範』を著し、ギリシア医学とイスラーム世界の医学を集大成しました。この書はのちにラテン語に翻訳され、ヨーロッパの医学教育で長く用いられました。", "北アフリカでは、ベルベル人の【ムラービト朝】が11世紀半ばに成立し、モロッコに都マラケシュを建てました。ムラービト朝はイベリア半島のイスラーム勢力を助けてキリスト教徒の進出に対抗し、南では西アフリカの【ガーナ王国】を攻撃したとされます。この攻撃をきっかけにガーナ王国は衰え、西アフリカのイスラーム化が進むことになりました。イベリア半島では1031年に後ウマイヤ朝が滅んで小国に分裂し、キリスト教国の【国土回復運動】(レコンキスタ)が進展していきます。1085年にはカスティリャ王国がトレドを占領しました。"]}, {"t": "ヨーロッパ:農業の発展・教皇権の伸張・十字軍", "p": ["11世紀の西ヨーロッパは、ノルマン人やマジャール人の侵入が落ち着いて社会が安定し、大きく成長しはじめた時期です。耕地を春耕地・秋耕地・休耕地の三つに分けて順に使う【三圃制】や、重い土を深く耕せる【重量有輪犂】が普及し、修道院などによる森林や荒れ地の開墾も進みました。その結果、食料生産が増えて人口が増加し、余った生産物を売り買いする商業や都市も再び活発になりはじめました。この成長が、のちの十字軍や東方植民の背景にあるエネルギーとなります。", "教会では、クリュニー修道院を中心とする改革運動の影響で、聖職売買や聖職者の妻帯を禁じ、教会を世俗の権力から自立させようとする動きが強まりました。教皇【グレゴリウス7世】は、聖職者を任命する権利(叙任権)は教会にあると主張し、神聖ローマ皇帝【ハインリヒ4世】と対立しました。これを【叙任権闘争】といいます。教皇に破門されたハインリヒ4世は、ドイツ諸侯が離反するのをおそれ、1077年にイタリアのカノッサで雪の中に立って教皇に許しを請いました。これが【カノッサの屈辱】です。叙任権闘争は1122年の【ヴォルムス協約】で一応の決着を見ますが、この事件は教皇の権威が皇帝をしのぐほどに高まったことを示しています。", "東方では、教皇の首位権や教義をめぐってローマ教会とコンスタンティノープル教会の対立が続き、1054年に双方が相手を破門しました。これによって、西の【ローマ=カトリック教会】と東の【ギリシア正教会】は分裂しました。", "ブリテン島では、1016年にデンマーク王【クヌート】(カヌート)がイングランド王となり、デンマーク・ノルウェーもあわせた北海帝国を築きました。その後、イングランド王位をめぐる争いの中で、ノルマンディー公ウィリアムが1066年に【ヘースティングズの戦い】で勝利して【ウィリアム1世】として即位し、ノルマン朝を開きました。これを【ノルマン=コンクェスト】といいます。ウィリアム1世は全国の土地を調べて【ドゥームズデー=ブック】(土地台帳)をつくらせ、強い王権を築きました。またノルマン人は南イタリアやシチリア島にも進出し、のちの【両シチリア王国】の基礎を築きました。", "マンジケルトの戦いで敗れたビザンツ帝国の皇帝アレクシオス1世は、ローマ教皇に救援を求めました。これにこたえて教皇【ウルバヌス2世】は、1095年に【クレルモン宗教会議】で聖地イェルサレムの回復を呼びかけました。1096年に出発した【第1回十字軍】は、セルジューク朝の分裂にも助けられて1099年にイェルサレムを占領し、【イェルサレム王国】を建てました。十字軍の動機には、宗教的な熱情のほか、教皇の東西教会統一への期待、諸侯や騎士の領土への欲求、イタリア商人の商業上の利益など、さまざまなものが重なっていました。"]}, {"t": "東アジア:宋の繁栄と北方民族との共存", "p": ["宋は文治主義によって国内を安定させましたが、軍事的には北方の強国に押されていました。1004年、遼の大軍が南下すると、宋は遼と【澶淵の盟】を結び、毎年銀と絹を遼に贈るかわりに和平を保つことにしました。また、黄河上流域ではチベット系のタングートの【李元昊】が1038年に【西夏】を建て、宋と戦いました。宋は1044年に【慶暦の和約】を結び、西夏にも毎年銀・絹・茶を贈ることで平和を得ました。西夏は漢字をもとにした【西夏文字】をつくりました。", "このように、宋は北方民族に物を贈ることで平和を「買う」政策をとりました。中国の皇帝を頂点とする伝統的な世界観からすれば屈辱的ですが、宋の豊かな経済力からすれば、戦争を続けるより安上がりだったともいえます。一方で、大軍の維持と贈り物の負担、官僚の増加によって、宋の財政は苦しくなっていきました。", "そこで神宗は、1069年に【王安石】を登用して改革をおこないました。これが【新法】です。農民に低利で資金を貸す【青苗法】、中小商人に低利で融資する【市易法】、農民を訓練して兵とする【保甲法】など、大地主や大商人の利益をおさえ、国家の財政と軍事力を立て直そうとする政策でした。しかし、利益を損なわれた大地主・大商人や保守的な官僚が強く反対し、【司馬光】らの【旧法党】と王安石らの【新法党】の対立が長く続いて、政治は混乱しました。司馬光は歴史書『資治通鑑』を著しています。", "宋の経済は大きく発展しました。江南では日照りに強い【占城稲】が導入され、稲の生産が増えました。商業が盛んになって都市の外にも【草市】と呼ばれる市場が生まれ、商人の同業組合【行】、手工業者の同業組合【作】がつくられました。四川では世界最初期の紙幣とされる【交子】が使われるようになりました。景徳鎮の陶磁器が名産となり、【火薬・羅針盤・木版印刷】の実用化が進みました。また、儒学では宇宙と人間の本質を哲学的に探る【宋学】が生まれ、周敦頤らがその基礎を築きました。", "周辺では、高麗が契丹の侵入を受けながらも独自の文化を発展させました。日本では、11世紀前半に【藤原道長】・【頼通】のもとで【摂関政治】が全盛期を迎え、11世紀後半の1086年には白河上皇による【院政】がはじまりました。ベトナムでは1009年に【李朝】が成立し、国号を【大越】として長く続く王朝を築きました。"]}, {"t": "南アジア・東南アジア:ガズナ朝とチョーラ朝、パガン朝", "p": ["北インドでは、アフガニスタンを拠点とするトルコ系の【ガズナ朝】が、11世紀初めに【マフムード】のもとで北インドにくり返し侵入し、ヒンドゥー教寺院の財宝を奪いました。これはイスラーム勢力の本格的なインド進出のはじまりであり、12世紀のゴール朝、13世紀の奴隷王朝へと続いていきます。ここでも、中央アジアのトルコ人の動きが周辺の地域を変えていることがわかります。", "南インドの【チョーラ朝】は11世紀に最盛期を迎え、強力な海軍でスリランカを攻め、さらにマラッカ海峡の【シュリーヴィジャヤ】にも遠征したとされます。チョーラ朝は宋にも使節を送っており、インド洋交易の主導権をめぐる争いが、インドと東南アジアの間で起きていたことがわかります。", "東南アジア大陸部では、ビルマ人の【パガン朝】が1044年に成立し、【アノーヤター王】のもとでイラワディ川流域を統一しました。パガン朝はスリランカから伝わった【上座部仏教】を受け入れ、多くの仏塔(パゴダ)を建てました。この上座部仏教は、のちにタイやカンボジアにも広がり、東南アジア大陸部の宗教の基本となっていきます。カンボジアのアンコール朝は11世紀に勢力を広げ、ジャワ島ではヒンドゥー教の王国が栄えていました。"]}, {"t": "アメリカ・アフリカと世界のつながり", "p": ["アメリカ大陸では、メキシコ高原のトルテカの影響がユカタン半島の【チチェン=イツァ】にもおよび、この都市が後古典期マヤの中心となりました。アンデスでは各地に地域国家が並び立っていました。アフリカでは、ムラービト朝の攻撃を受けたとされる【ガーナ王国】が衰えに向かい、のちのマリ王国の台頭へとつながっていきます。東アフリカの沿岸では、イスラーム商人の来航によって港市が栄えていました。", "11世紀の世界のつながりの第一は、すでに見た連鎖です。中央アジアのトルコ人がイスラームを受け入れ、セルジューク朝として西アジアに進出し、ビザンツ帝国を破り、その救援要請から十字軍が生まれました。同じトルコ人の動きは、ガズナ朝として北インドにも向かいました。ユーラシアの真ん中から起きた動きが、東は北インド、西はヨーロッパにまで影響をおよぼしたのです。", "第二は、海と商業の発展です。宋の経済の発展は、海上交易の拡大と結びついていました。ムスリム商人や中国商人は、中国の陶磁器や絹をインド洋に運び、香辛料や香木を中国にもたらしました。チョーラ朝やシュリーヴィジャヤはその中継をめぐって争いました。西ヨーロッパでも、ヴェネツィアなどのイタリア都市がビザンツ帝国との取引で力をつけはじめ、十字軍を通じて東方との交易をさらに広げていきます。", "第三は、東西の国家の比較です。宋は武力に頼らず経済力で北方民族と共存し、官僚制による中央集権を保ちました。西ヨーロッパでは王権が弱く、教皇が皇帝を屈服させるほど教会の力が強まりました。イスラーム世界では、カリフの宗教的権威とスルタンの政治的権力が分かれました。宗教的権威と政治権力の関係がそれぞれの世界でどう組み立てられたかを比べると、中世世界の特徴がよく見えてきます。"]}], "points": ["セルジューク朝:トゥグリル=ベクのバグダード入城(1055年)とスルタン、ニザーム=アルムルクのニザーミーヤ学院、イクター制", "マンジケルトの戦い(1071年)→ビザンツの救援要請→クレルモン宗教会議(1095年)→第1回十字軍→イェルサレム王国(1099年)", "叙任権闘争:グレゴリウス7世とハインリヒ4世、カノッサの屈辱(1077年)、ヴォルムス協約(1122年)", "東西教会の分裂(1054年)", "ノルマン=コンクェスト(1066年、ヘースティングズの戦い、ウィリアム1世)、ドゥームズデー=ブック", "宋と北方民族:澶淵の盟(1004年、遼)、慶暦の和約(1044年、西夏)", "王安石の新法(青苗法・市易法・保甲法)と新法党・旧法党の対立", "パガン朝(1044年)の上座部仏教、李朝(1009年)、ガズナ朝のインド侵入"], "check": [["1055年にバグダードに入城しスルタンの称号を得たセルジューク朝の君主は誰か", "トゥグリル=ベク"], ["セルジューク朝の宰相で、各地にマドラサを建てたのは誰か", "ニザーム=アルムルク"], ["1071年にセルジューク朝がビザンツ帝国を破った戦いは何か", "マンジケルトの戦い"], ["1095年にクレルモン宗教会議で十字軍を呼びかけた教皇は誰か", "ウルバヌス2世"], ["1077年、ハインリヒ4世が教皇に許しを請うた事件を何というか", "カノッサの屈辱"], ["1066年にイングランドを征服したノルマンディー公は誰か", "ウィリアム1世"], ["1004年に宋と遼が結んだ和約は何か", "澶淵の盟"], ["1038年に西夏を建てたのは誰か", "李元昊"], ["青苗法・市易法などの新法を実施した宋の宰相は誰か", "王安石"], ["1044年に成立し上座部仏教を受け入れたビルマの王朝は何か", "パガン朝"]], "related": ["y_10", "y_12", "t_tr", "t_byz", "t_uk", "t_de", "t_cn", "t_mm", "t_vn", "t_in"], "n": 4834}, "y_12": {"title": "12世紀の世界", "span": "1101〜1200年", "year": 1150, "lead": "12世紀は、十字軍をきっかけに西ヨーロッパが東方と深く関わり、商業・都市・学問が大きく伸びた世紀です。西アジアではサラーフ=アッディーンがイェルサレムを奪い返し、東アジアでは女真の金が遼と北宋を滅ぼして南宋と南北に並び立ちました。異なる文化どうしの接触と、北方の新しい民族の台頭が、この世紀を横に見るときのかぎです。", "flow": ["1115年 女真の完顔阿骨打が金を建てる→1125年金と宋が遼を滅ぼす", "1122年 ヴォルムス協約→叙任権闘争が決着", "1126〜27年 靖康の変→金が北宋を滅ぼし、高宗が江南で南宋を再建", "1130年 両シチリア王国の成立→ノルマン人の王国でアラビア語文献の翻訳が進む", "1142年 南宋と金が和議を結ぶ→淮河を境に南北が並立", "1143年 ポルトガル王国が成立→国土回復運動の進展", "1154年 ヘンリ2世がプランタジネット朝を開く→フランス西部にも広大な領地", "1169年 サラーフ=アッディーンがエジプトの実権をにぎる→アイユーブ朝", "1187年 サラーフ=アッディーンがイェルサレムを奪回→1189年第3回十字軍", "1192年 源頼朝が征夷大将軍となる(1185年の平氏滅亡後)→日本で武家政権が成立"], "sync": [["ヨーロッパ", "十字軍の継続(第2回・第3回)、都市と商業の復活、大学の誕生と12世紀ルネサンス。プランタジネット朝(1154年)、両シチリア王国(1130年)、ポルトガル王国(1143年)"], ["西アジア・北アフリカ", "セルジューク朝の分裂。アイユーブ朝の成立とサラーフ=アッディーンのイェルサレム奪回(1187年)。北アフリカ・イベリアにムワッヒド朝"], ["南アジア・東南アジア", "ゴール朝が北インドに進出。アンコール=ワットの造営(スールヤヴァルマン2世)"], ["東アジア・内陸アジア", "金の建国(1115年)、遼の滅亡(1125年)と西遼の成立、靖康の変(1126〜27年)と南宋。朱熹の朱子学。日本では平氏政権から鎌倉幕府へ"], ["アメリカ・アフリカ", "メキシコ高原でトルテカが衰える。アンデスで地方国家が栄える。西アフリカでガーナ王国の衰退が進む"], ["世界のつながり", "十字軍とイタリア商人の東方貿易。イスラーム世界の学問のラテン語訳。南宋の海上交易の発展"]], "secs": [{"t": "12世紀を見る視点:接触が生んだ変化", "p": ["12世紀の世界を横に見ると、異なる文化どうしが出会い、その出会いが社会を変えていったことが見えてきます。西ヨーロッパは十字軍を通じて、また地中海の交易やイベリア半島・シチリア島での接触を通じて、ビザンツ帝国とイスラーム世界の進んだ経済と学問にふれました。その結果、イタリア商人の東方貿易が栄え、ギリシアやアラビアの学問がラテン語に翻訳され、大学が生まれました。この学問の復興は【12世紀ルネサンス】と呼ばれます。", "一方、東アジアでは、北方の森林地帯に住んでいた【女真】が【金】を建て、遼と北宋を次々に滅ぼしました。宋は江南に移って【南宋】として再建され、淮河を境に金と南北に並ぶことになりました。遼の王族の一部は中央アジアに逃れて【西遼】(カラキタイ)を建てました。北方から新しい勢力が現れ、古い大国が南へ押し出されるという動きは、次の13世紀のモンゴル帝国の登場を予告するものでもありました。"]}, {"t": "ヨーロッパ:十字軍の展開と商業の復活", "p": ["第1回十字軍がイェルサレム王国などの十字軍国家を建てたあと、イスラーム側の反撃が強まりました。1147年には【第2回十字軍】が送られましたが、成果をあげられませんでした。やがてエジプトとシリアを統一した【サラーフ=アッディーン】(サラディン)が1187年にイェルサレムを奪回すると、1189年に【第3回十字軍】が組織されました。神聖ローマ皇帝【フリードリヒ1世】、フランス王【フィリップ2世】、イングランド王【リチャード1世】が参加しましたが、皇帝は途中で事故死し、フランス王は早々に帰国しました。リチャード1世はサラーフ=アッディーンと戦った末に講和を結び、キリスト教徒の聖地巡礼を認めさせたものの、イェルサレムの回復はできませんでした。", "十字軍は軍事的には期待した成果をあげられませんでしたが、西ヨーロッパの社会には大きな影響を与えました。兵士や物資の輸送を担った【ヴェネツィア】や【ジェノヴァ】などのイタリア諸都市は、東地中海での商業の拠点を得て、香辛料や絹織物などを扱う【東方貿易】(レヴァント貿易)で大きな利益をあげました。北ヨーロッパでも、北海・バルト海沿岸の都市が毛織物や木材、海産物の交易で栄え、のちに【リューベック】を中心とする【ハンザ同盟】へと発展します。フランスの【シャンパーニュ地方】では、南北の商人が集まる大きな定期市が開かれました。", "商業の発展とともに、都市は領主から特許状を得て自治権を獲得し、【ギルド】と呼ばれる同業組合をつくりました。「都市の空気は自由にする」ということわざが示すように、都市は荘園の束縛から逃れた人々の集まる場所となりました。また、修道院の開墾運動も盛んで、11世紀末に創設された【シトー修道会】は荒れ地の開墾に大きな役割を果たしました。エルベ川以東のスラヴ人の土地へのドイツ人の【東方植民】もこの時期から本格化します。", "政治の面では、イングランドで1154年に【ヘンリ2世】が即位して【プランタジネット朝】を開きました。ヘンリ2世はフランス西部にも広大な領地をもっていたため、フランス王と激しく対立し、のちの百年戦争の遠い原因となります。南イタリアとシチリアでは、ノルマン人が1130年に【両シチリア王国】を建て、ギリシア・アラブ・ラテンの文化が混じりあう宮廷が栄えました。イベリア半島では国土回復運動が進み、1143年に【ポルトガル王国】が成立しました。叙任権闘争は1122年の【ヴォルムス協約】で決着し、教皇権はさらに高まって13世紀初めの全盛期へ向かいます。"]}, {"t": "12世紀ルネサンス:イスラーム世界から学んだ西ヨーロッパ", "p": ["12世紀の西ヨーロッパの学問の発展は、イスラーム世界との接触なしには考えられません。国土回復運動で取り戻されたイベリア半島の【トレド】や、両シチリア王国の【パレルモ】では、アラビア語に訳されていたアリストテレスの哲学やエウクレイデスの幾何学、プトレマイオスの天文学、イブン=シーナーの医学などが、次々にラテン語に翻訳されました。こうして、古代ギリシアの学問がイスラーム世界を経由して西ヨーロッパに戻ってきたのです。", "この時代のイスラーム世界では、イベリア半島のコルドバ出身の【イブン=ルシュド】(ラテン名アヴェロエス)がアリストテレスの注釈書を著し、のちにヨーロッパの神学者・哲学者に大きな影響を与えました。", "新しい学問の広がりにこたえて、教師と学生の組合として【大学】が生まれました。法学で有名な【ボローニャ大学】、神学で有名な【パリ大学】、医学で知られる【サレルノ大学】などがその代表です。大学では、神学・法学・医学の専門学部と、その基礎となる教養科目が教えられました。キリスト教の信仰を理性によって説明しようとする【スコラ学】が発達し、普遍(類や種などの一般概念)が実在するかどうかをめぐる【普遍論争】がおこなわれました。この流れは13世紀の【トマス=アクィナス】による集大成へとつながっていきます。", "建築では、半円アーチと厚い壁をもつ【ロマネスク様式】から、尖ったアーチと高い尖塔、ステンドグラスを特徴とする【ゴシック様式】への移行がはじまりました。12世紀半ばにはパリ近郊で初期ゴシックの教会が建てられ、のちにノートルダム大聖堂やシャルトル大聖堂などが建設されます。都市の経済力と教会の権威が結びつき、天に向かってそびえる大聖堂がつくられたのです。"]}, {"t": "西アジア・北アフリカ・南アジア:サラーフ=アッディーンとゴール朝", "p": ["セルジューク朝は12世紀に入ると内部の争いで分裂し、各地に地方政権が並び立ちました。十字軍が第1回で成功を収めた背景には、このイスラーム側の分裂がありました。しかし、シリアのイスラーム勢力がしだいに結束を取り戻し、十字軍国家への反撃を強めていきます。", "その中心となったのが、クルド人の武将【サラーフ=アッディーン】です。彼はエジプトのファーティマ朝に仕えて実権をにぎり、1169年に【アイユーブ朝】を開きました。1171年にはシーア派のファーティマ朝を廃してスンナ派を復活させ、エジプトとシリアを統一しました。そして1187年、ヒッティーンの戦いで十字軍を破り、【イェルサレム】を奪回しました。サラーフ=アッディーンは捕虜となったキリスト教徒を寛大に扱ったと伝えられ、ヨーロッパでも高く評価されました。", "北アフリカからイベリア半島南部では、ムラービト朝にかわってベルベル人の【ムワッヒド朝】が勢力をもち、キリスト教国と対抗しました。中央アジアでは、遼の王族【耶律大石】が西へ逃れて【西遼】(カラキタイ)を建て、セルジューク朝の軍を破るなど勢力を広げました。東アジアの政変が中央アジアの勢力図まで変えたことになります。", "インドでは、アフガニスタンに興った【ゴール朝】が12世紀後半に北インドに進出し、ヒンドゥー教徒のラージプート諸勢力を破りました。ゴール朝の武将アイバクが13世紀初めにデリーで自立し、【奴隷王朝】を開くことで、北インドにイスラーム政権の時代(デリー=スルタン朝)がはじまります。"]}, {"t": "東アジア:金の建国と南宋", "p": ["中国東北部の森林地帯に住んでいた狩猟・農耕民の【女真】は、遼の支配を受けていましたが、【完顔阿骨打】(太祖)のもとで統合され、1115年に【金】を建てました。金は宋と同盟を結んで遼を挟み撃ちにし、1125年に【遼を滅ぼし】ました。ところが、宋が約束を守らなかったことなどから金と宋は対立し、金は南下して1126年から1127年にかけて都の開封を攻め落とし、上皇の徽宗と皇帝の欽宗をはじめ多くの皇族を北方へ連れ去りました。これが【靖康の変】で、北宋はここで滅亡しました。", "欽宗の弟の【高宗】は江南に逃れて即位し、のちに【臨安】(現在の杭州)を都として宋を再建しました。これを【南宋】といいます。南宋の朝廷では、金に徹底抗戦を主張する【岳飛】らの主戦派と、和平を主張する【秦檜】らの和平派が対立しましたが、結局は和平派が勝ち、1142年に金と和議が結ばれました。南宋は金に対して臣下の礼をとり、毎年銀と絹を贈ることになり、両国の国境は【淮河】とされました。", "金は、女真の部族組織をもとにした軍事・行政の制度である【猛安・謀克】で女真人を治め、華北の漢人は州県制で治める二重の統治をおこないました。また【女真文字】をつくって民族の文化を保とうとしました。しかし華北に移り住んだ女真人はしだいに漢人の文化に同化していきました。", "南宋は北方の領土を失いましたが、経済はむしろ発展しました。江南の開発がさらに進み、長江下流域が中国最大の穀倉地帯となって「【蘇湖(江浙)熟すれば天下足る】」といわれました。海上交易も盛んで、泉州や広州には多くのムスリム商人が来航しました。思想の面では、【朱熹】(朱子)が宋学を大成して【朱子学】を確立しました。朱子学は、宇宙の原理である「理」と物質的な「気」によって世界を説明し、『四書』を重んじ、君臣・父子などの秩序と、中華と夷狄の区別(華夷の区別)を強調しました。北方民族に圧迫された南宋の状況が、こうした考え方の背景にあったと考えられます。朱子学はのちに元・明・清の官学となり、朝鮮や日本にも大きな影響を与えました。", "日本では、【平清盛】が武士として初めて太政大臣となり、【日宋貿易】に力を入れました。その後、源平の争乱を経て1185年に平氏が滅び、源頼朝が鎌倉に武家政権を築きました。朝鮮半島の高麗でも、12世紀後半に武臣が実権をにぎる武臣政権が成立しました。東アジアの各地で、武力をもつ新しい勢力が政治の中心に立ちはじめていたのです。"]}, {"t": "東南アジア・アメリカ・アフリカと世界のつながり", "p": ["東南アジアでは、アンコール朝の【スールヤヴァルマン2世】が12世紀前半に、ヒンドゥー教の寺院【アンコール=ワット】を造営しました。12世紀末にはジャヤヴァルマン7世が都アンコール=トムを整え、仏教を重んじました。アメリカ大陸では、メキシコ高原のトルテカが衰え、のちのアステカの人々が北方から移動してくる時代へと向かっていきます。アンデスでは、のちのインカにつながる人々がクスコ周辺で勢力を育てはじめたとされます。アフリカでは、ガーナ王国の衰退が進み、13世紀のマリ王国の台頭を待つことになります。", "12世紀の世界のつながりを東西で比べると、二つの対照的な動きが見られます。西では、十字軍という軍事的な接触が、かえって商業と学問の交流を生み、西ヨーロッパの成長をうながしました。東では、北方民族の金が宋を南に押しやりましたが、南宋は江南の経済と海上交易によってかえって豊かになりました。どちらも、衝突が新しい交流や発展の機会になったという点で共通しています。", "そして、ユーラシアの海の道では、南宋の泉州・広州から東南アジアを経てインド洋、さらにアイユーブ朝のエジプトや紅海を通じて地中海のイタリア商人へと、商品がつながっていました。中国の陶磁器や絹が西へ、香辛料や香料が東へと運ばれました。13世紀にモンゴル帝国が陸の道を統一すると、この海の道と陸の道がひとつの大きな循環を形づくることになります。"]}], "points": ["第3回十字軍(1189年)の参加者:フリードリヒ1世・フィリップ2世・リチャード1世と、相手のサラーフ=アッディーン", "サラーフ=アッディーン:アイユーブ朝(1169年)、ファーティマ朝の廃止、イェルサレム奪回(1187年)", "十字軍の影響:イタリア諸都市の東方貿易、商業と都市の発達、ハンザ同盟の芽ばえ", "12世紀ルネサンス:トレド・パレルモでのアラビア語文献のラテン語訳、大学(ボローニャ・パリ・サレルノ)、スコラ学", "金(1115年、完顔阿骨打)と遼の滅亡(1125年)、西遼(耶律大石)", "靖康の変(1126〜27年)→南宋(高宗、臨安)、岳飛と秦檜、淮河を国境とする和議(1142年)", "猛安・謀克、女真文字", "朱熹の朱子学の大成、アンコール=ワット(スールヤヴァルマン2世)"], "check": [["1187年にイェルサレムを奪回したアイユーブ朝の創始者は誰か", "サラーフ=アッディーン(サラディン)"], ["第3回十字軍に参加したイングランド王は誰か", "リチャード1世"], ["1154年にプランタジネット朝を開いたイングランド王は誰か", "ヘンリ2世"], ["1115年に金を建てた女真の首長は誰か", "完顔阿骨打"], ["1126〜27年に金が開封を攻め北宋を滅ぼした事件は何か", "靖康の変"], ["南宋の都はどこか", "臨安(杭州)"], ["金と和議を結んだ南宋の和平派の宰相は誰か", "秦檜"], ["女真人を治めるために金が用いた軍事・行政組織は何か", "猛安・謀克"], ["宋学を大成した南宋の学者は誰か", "朱熹(朱子)"], ["アンコール=ワットを造営した王は誰か", "スールヤヴァルマン2世"]], "related": ["y_11", "y_13", "t_ar", "t_uk", "t_fr", "t_it", "t_cn", "t_mn", "t_mm"], "n": 4446}, "y_13": {"title": "13世紀の世界", "span": "1201〜1300年", "year": 1250, "lead": "13世紀は、モンゴル帝国がユーラシアの大部分を征服し、東西を一つの交通網で結びつけた世紀です。その征服は金・南宋・アッバース朝を滅ぼし、ロシアや東欧にも大きな傷あとを残しましたが、同時に「モンゴルの平和」のもとで人・物・情報が活発に行き来しました。西ヨーロッパでは教皇権が絶頂を迎えた後に王権が伸び、身分制議会が生まれました。", "flow": ["1204年 第4回十字軍がコンスタンティノープルを占領→ラテン帝国の成立", "1206年 テムジンがチンギス=ハンとして即位→モンゴル帝国の成立。同年インドで奴隷王朝が成立", "1215年 イングランドのジョン王がマグナ=カルタを認める", "1234年 オゴデイが金を滅ぼす→華北がモンゴルの支配下に", "1241年 ワールシュタットの戦い→バトゥの軍がドイツ・ポーランド連合軍を破る", "1250年 エジプトにマムルーク朝が成立→1260年アイン=ジャールートの戦いでモンゴル軍を破る", "1256年 神聖ローマ帝国で大空位時代がはじまる", "1258年 フラグがバグダードを攻略しアッバース朝が滅亡→イル=ハン国の成立", "1260年 フビライが即位→1271年国号を元とし、大都を都とする", "1261年 ニケーア帝国がコンスタンティノープルを奪回→ビザンツ帝国の復活", "1274年・1281年 元が日本に遠征するが失敗(文永の役・弘安の役)", "1279年 元が南宋を滅ぼす→中国全土がモンゴルの支配下に"], "sync": [["ヨーロッパ", "教皇インノケンティウス3世の全盛と第4回十字軍(1204年)。マグナ=カルタ(1215年)、大空位時代(1256年)、模範議会(1295年)。ロシアがキプチャク=ハン国の支配下に"], ["西アジア・北アフリカ", "アッバース朝の滅亡(1258年)とイル=ハン国の成立。マムルーク朝(1250年)がモンゴルを撃退。アナトリアにオスマン国家の起こり"], ["南アジア・東南アジア", "奴隷王朝(1206年)とデリー=スルタン朝のはじまり。スコータイ朝の成立、ベトナム陳朝の元軍撃退、ジャワのマジャパヒト王国(1293年)"], ["東アジア・内陸アジア", "チンギス=ハンの即位(1206年)、金の滅亡(1234年)、元の成立(1271年)と南宋の滅亡(1279年)。高麗の服属、日本への遠征(1274年・1281年)"], ["アメリカ・アフリカ", "アステカの人々がメキシコ盆地に移り住む。アンデスでインカがクスコを中心に力をつける。西アフリカでマリ王国が台頭"], ["世界のつながり", "モンゴルの平和のもとでのジャムチ(駅伝制)による東西交流。プラノ=カルピニ、ルブルック、マルコ=ポーロの来訪"]], "secs": [{"t": "13世紀を見る視点:モンゴル帝国がつないだユーラシア", "p": ["13世紀の世界を横に見るとき、中心にすえるべきは【モンゴル帝国】です。モンゴル高原の遊牧民をまとめた【チンギス=ハン】とその子孫たちは、わずか数十年のうちに、東は中国と朝鮮半島から、西はロシア・イランにいたる広大な領域を支配しました。これは人類史上最大級の陸の帝国です。これまでの世紀では、遊牧民の動きはユーラシアの一部をゆさぶるものでしたが、13世紀には遊牧民の国家がユーラシアそのものを一つに結びつけたのです。", "モンゴルの征服は、各地に大きな破壊をもたらしました。金や南宋、アッバース朝は滅び、ロシアの諸都市やバグダードは大きな被害を受けました。しかし征服が終わると、モンゴルは広い領域に交通網を整え、商人を保護したため、東西の交流はかつてないほど活発になりました。これを【モンゴルの平和】(パクス=モンゴリカ)といいます。この世紀の各地のできごとは、ほとんどがモンゴルとの関係で説明できると言ってよいほどです。モンゴルに征服された地域、モンゴルを撃退した地域、モンゴルと直接ぶつからなかった地域に分けて考えると、整理しやすくなります。"]}, {"t": "東アジア・内陸アジア:モンゴル帝国の成立と元", "p": ["モンゴル高原では、12世紀まで多くの部族が争っていましたが、【テムジン】がそれらを統一し、1206年の【クリルタイ】(部族長会議)で【チンギス=ハン】として即位しました。チンギス=ハンは遊牧民を千戸単位に組織する【千戸制】によって強力な軍隊をつくり、西方に遠征して中央アジアの【ホラズム=シャー朝】を倒し、さらに【西夏】を滅ぼしました。", "チンギス=ハンの死後、第2代の【オゴデイ】(オゴタイ)は1234年に【金】を滅ぼし、モンゴル高原に都【カラコルム】を建設しました。オゴデイの命を受けた【バトゥ】は西方に大遠征をおこない、ロシアの諸都市を攻略したうえ東ヨーロッパに侵入し、1241年の【ワールシュタットの戦い】でドイツ・ポーランドの連合軍を破りました。オゴデイの死の知らせを受けてバトゥは引き返し、南ロシアに【キプチャク=ハン国】を建てました。第4代【モンケ】のもとでは、弟の【フラグ】が西アジアに遠征して1258年にバグダードを攻略し、アッバース朝を滅ぼして【イル=ハン国】を建てました。中央アジアには【チャガタイ=ハン国】がありました。", "モンケの死後、弟の【フビライ】が1260年に即位しましたが、これに反対する一族との争いが起こり、モンゴル帝国はゆるやかな連合体へと変わっていきました。フビライは都を【大都】(現在の北京)に移し、1271年に国号を中国風に【元】と改めました。そして1276年に南宋の都臨安を占領し、1279年に南宋の残存勢力を滅ぼして、中国全土を支配下におきました。", "元は、モンゴル人を最上位に、中央アジア・西アジア出身の【色目人】を財務などに重用し、旧金の支配下にあった人々を【漢人】、旧南宋の人々を【南人】と区別しました。科挙は長く停止され、のちに再開されても規模は小さく、儒学を学んだ知識人は政治から遠ざけられました。そのかわりに庶民の文化が栄え、【元曲】と呼ばれる演劇が盛んになりました。また紙幣の【交鈔】が広く使われました。", "フビライは周辺地域にも遠征をくり返しました。朝鮮半島の【高麗】は長い抵抗の末にモンゴルに服属しました。日本には1274年と1281年の二度にわたって遠征軍を送りましたが(【文永の役】・【弘安の役】)、鎌倉幕府の御家人の抵抗と暴風雨によって失敗しました。ベトナムの【陳朝】も元軍を撃退し、ジャワ遠征も失敗しました。モンゴルの騎馬軍団は陸では圧倒的に強くても、海を越える遠征や熱帯の地域では苦戦したのです。日本では、元の襲来を退けたものの、恩賞を十分に与えられなかったことが御家人の不満を生み、鎌倉幕府の衰えの一因となりました。"]}, {"t": "西アジア・北アフリカ:アッバース朝の滅亡とマムルーク朝", "p": ["1258年、フラグの軍はバグダードを攻略し、カリフを殺害しました。これによって750年から続いた【アッバース朝】は滅亡しました。イスラーム世界の中心であったバグダードが大きな被害を受けたことは、当時のイスラーム教徒に深い衝撃を与えました。フラグが建てた【イル=ハン国】は、はじめはイスラームに敵対的でしたが、13世紀末の【ガザン=ハン】のときにイスラームを国教とし、宰相【ラシード=アッディーン】が歴史書『集史』を編纂するなど、イラン=イスラーム文化が栄えました。", "モンゴルの西進を止めたのは、エジプトの【マムルーク朝】でした。マムルーク朝は、アイユーブ朝のトルコ系マムルーク(奴隷兵)が1250年に実権を奪って成立した王朝です。1260年、マムルーク朝の軍は【アイン=ジャールートの戦い】でモンゴル軍を破りました。この戦いで活躍した【バイバルス】はのちにスルタンとなり、アッバース家の一族をカイロに迎えてカリフとして擁立しました。これによって、カイロがイスラーム世界の新しい中心となりました。マムルーク朝は十字軍の残る拠点も攻め、13世紀末には十字軍国家をシリア・パレスチナから一掃しました。", "アナトリアでは、ルーム=セルジューク朝がモンゴルに服属して衰え、各地にトルコ系の小勢力が分立しました。その中の一つで、ビザンツ帝国との境に位置した勢力から、13世紀末に【オスマン】が自立して、のちの【オスマン帝国】のもとを築いたとされます。モンゴルの支配によって西アジアの政治秩序がくずれたことが、新しい勢力の誕生をうながしたのです。"]}, {"t": "ヨーロッパ:教皇権の絶頂と王権の伸長", "p": ["13世紀初めのヨーロッパでは、教皇【インノケンティウス3世】のもとで教皇権が絶頂に達しました。彼はイングランド王【ジョン】を破門して屈服させ、フランス王フィリップ2世にも圧力をかけました。「教皇は太陽、皇帝は月」という言葉は、この時代の教皇の力を表すものとして知られています。彼が提唱した【第4回十字軍】は、輸送を担ったヴェネツィア商人の意向などから目的を変え、1204年にキリスト教国であるビザンツ帝国の都【コンスタンティノープル】を占領して【ラテン帝国】を建てました。十字軍の宗教的な理想は大きくゆらぎ、ビザンツ帝国は1261年にニケーア帝国によって都を取り戻したものの、往年の力は戻りませんでした。", "教会の内部では、清貧を重んじて都市の民衆に説教する【托鉢修道会】が生まれました。【フランチェスコ修道会】や【ドミニコ修道会】がその代表です。一方で、南フランスの異端【アルビジョワ派】(カタリ派)に対しては十字軍が送られて弾圧され、これを機にフランス王権が南フランスに勢力を広げました。学問では、【トマス=アクィナス】が『神学大全』を著し、アリストテレスの哲学とキリスト教の信仰を調和させて【スコラ学】を大成しました。", "教皇権が頂点にあった一方で、各国では王権が強まりはじめました。フランスでは【フィリップ2世】がジョン王からフランス国内の領地の多くを奪い、1214年の【ブーヴィーヌの戦い】で勝利して王権を強めました。13世紀半ばの【ルイ9世】は第6回・第7回十字軍をおこない、2度目の遠征中にチュニスで亡くなりました。イングランドでは、領地を失い重税を課したジョン王に対し、貴族たちが反抗して、1215年に【マグナ=カルタ】(大憲章)を認めさせました。これは、国王であっても法に従い、新たな課税には貴族らの同意が必要であるという原則を示したもので、のちのイギリス立憲政治の出発点とされます。1265年には【シモン=ド=モンフォール】が貴族・聖職者に加えて州と都市の代表を集めた議会を開き、1295年にはエドワード1世が【模範議会】を招集しました。", "神聖ローマ帝国では、【フリードリヒ2世】が両シチリア王国を拠点に統治し、第5回十字軍では外交交渉によって一時イェルサレムを回復しました(1229年)。しかし彼の死後、ドイツでは事実上皇帝のいない【大空位時代】(1256〜1273年)となり、諸侯や都市の自立が進みました。北ドイツの都市は【ハンザ同盟】を結んでバルト海・北海の交易を支配しました。", "東ヨーロッパでは、ロシアの諸公国がバトゥの遠征によってモンゴルの支配下に入り、キプチャク=ハン国に貢納するようになりました。これを「【タタールのくびき】」といいます。この時期、ノヴゴロドのアレクサンドル=ネフスキーはドイツ騎士団などの西からの侵攻を退けました。モンゴル支配のもとでロシアは西ヨーロッパから切り離され、のちにモスクワ大公国が台頭するまで独自の道を歩むことになります。"]}, {"t": "南アジア・東南アジア:デリー=スルタン朝と新しい国々", "p": ["北インドでは、ゴール朝の武将でマムルーク出身の【アイバク】が1206年にデリーで自立し、【奴隷王朝】を開きました。これ以後、16世紀にムガル帝国が成立するまで、デリーを都とする五つのイスラーム王朝が続き、これらを【デリー=スルタン朝】と呼びます。奴隷王朝は、モンゴル軍のインド侵入を防ぎ、西アジアや中央アジアから逃れてきた学者や職人を受け入れたため、デリーはイスラーム文化の新しい中心のひとつとなりました。チンギス=ハンの即位と奴隷王朝の成立が同じ1206年であることは、横の年号としてよく問われます。", "東南アジアでは、大きな変化が起こりました。タイ人がチャオプラヤ川流域に南下し、13世紀に【スコータイ朝】を建てました。スコータイ朝は上座部仏教を受け入れ、【ラームカムヘーン王】のときにタイ文字がつくられたとされます。ビルマの【パガン朝】は元軍の侵入を受けて衰えました。ベトナムでは1225年に李朝にかわって【陳朝】が成立し、3度にわたって元軍を撃退しました。この時期、漢字をもとにしたベトナム独自の文字【チュノム】(字喃)がつくられたとされます。ジャワ島では、元軍の遠征の混乱の中で、1293年に【マジャパヒト王国】が成立しました。モンゴルの遠征は、東南アジアの国々の興亡にも大きく関わっていたのです。"]}, {"t": "アメリカ・アフリカと世界のつながり", "p": ["アメリカ大陸では、メキシコ高原に北方から移動してきた【アステカ人】が、13世紀ごろにメキシコ盆地に移り住んだとされ、14世紀にテノチティトランを建設していきます。アンデス地方では、【インカ】の人々がクスコを中心に力をつけはじめていました。アフリカでは、西アフリカのニジェール川流域で、ガーナ王国の衰退後に【マリ王国】が13世紀に台頭し、金の交易によって繁栄しました。マリ王国の支配層はイスラームを受け入れ、14世紀には【マンサ=ムーサ】のメッカ巡礼で知られるようになります。", "13世紀の世界のつながりの中心は、モンゴル帝国の交通網です。モンゴルは帝国の各地に一定の距離ごとに駅を置き、通行証(牌符)をもつ使者や商人に馬や食料を提供する【ジャムチ】(駅伝制)を整えました。これによって、ユーラシアを横断する旅が比較的安全におこなえるようになりました。ヨーロッパからは、ローマ教皇の使節【プラノ=カルピニ】や、フランス王ルイ9世の使節【ルブルック】がカラコルムを訪れました。ヴェネツィアの商人【マルコ=ポーロ】はフビライに仕えたとされ、帰国後に口述した『【世界の記述】』(東方見聞録)はヨーロッパ人のアジアへの関心をかきたてました。", "モンゴルの支配のもとで、イスラーム世界の天文学や数学が中国に伝わり、元の郭守敬は【授時暦】をつくりました。中国の火薬や印刷術、羅針盤などの技術も西方へ伝わったと考えられています。陸の道だけでなく、南宋から元にかけて発展した泉州などの港市からインド洋への海の道も、モンゴルの支配のもとで陸の道と結びつき、ユーラシア全体をめぐる大きな交易の循環が生まれました。", "東西を比べると、13世紀は、モンゴルに征服された地域(中国・ロシア・イラン)と、モンゴルを退けた地域(エジプトのマムルーク朝・日本・ベトナム)、そして直接の衝突がほとんどなかった西ヨーロッパとで、その後の歩みが大きく分かれた世紀だといえます。西ヨーロッパは、モンゴルの脅威を受けながらも征服をまぬがれ、モンゴルの平和がもたらした東方の情報や物資の恩恵を受けて、14世紀以降の新しい時代へと向かっていくことになります。"]}], "points": ["1206年:チンギス=ハンの即位と奴隷王朝の成立(同じ年として横で覚える)", "モンゴルの征服:金の滅亡(1234年)、ワールシュタットの戦い(1241年)、アッバース朝の滅亡(1258年)、南宋の滅亡(1279年)", "四ハン国:キプチャク(バトゥ)・イル(フラグ)・チャガタイ、オゴデイ家の勢力。元の成立(1271年、フビライ、大都)", "元の統治:色目人の重用、漢人・南人の区別、交鈔、元曲、授時暦", "モンゴルを撃退した勢力:マムルーク朝(アイン=ジャールートの戦い1260年、バイバルス)、日本(文永・弘安の役)、ベトナム陳朝", "第4回十字軍(1204年)とラテン帝国、インノケンティウス3世の教皇権の絶頂", "イギリス議会の起源:マグナ=カルタ(1215年)→シモン=ド=モンフォールの議会(1265年)→模範議会(1295年)", "ジャムチと東西交流:プラノ=カルピニ、ルブルック、マルコ=ポーロ"], "check": [["1206年のクリルタイでチンギス=ハンとして即位した人物の本名は何か", "テムジン"], ["1234年に金を滅ぼしたモンゴル帝国の第2代君主は誰か", "オゴデイ(オゴタイ)"], ["1241年にバトゥの軍がドイツ・ポーランド連合軍を破った戦いは何か", "ワールシュタットの戦い"], ["1258年にバグダードを攻略しイル=ハン国を建てたのは誰か", "フラグ"], ["1260年にアイン=ジャールートの戦いでモンゴル軍を破った王朝は何か", "マムルーク朝"], ["1271年に国号を元と定めたのは誰か", "フビライ"], ["1204年に第4回十字軍がコンスタンティノープルに建てた国は何か", "ラテン帝国"], ["1215年にジョン王が認めた文書は何か", "マグナ=カルタ(大憲章)"], ["1295年にエドワード1世が招集した議会は何と呼ばれるか", "模範議会"], ["1206年にデリーで奴隷王朝を開いたのは誰か", "アイバク"]], "related": ["y_12", "y_14", "t_mn", "t_cn", "t_ru", "t_uk", "t_ar", "t_tr", "t_in", "t_th", "t_vn"], "n": 4909}, "y_14": {"title": "14世紀の世界", "span": "1301〜1400年", "year": 1350, "lead": "14世紀は、ユーラシアの東西で「危機」と「再編」が同時に進んだ世紀です。モンゴル帝国の諸ハン国が分裂・衰退し、中国では元にかわって明が、西アジアではティムール朝が、アナトリアではオスマン帝国が台頭しました。ヨーロッパでは黒死病・百年戦争・教会大分裂が重なって封建社会がゆらぎ、そのなかからルネサンスの芽が育ちました。", "flow": ["1302年 フランスのフィリップ4世が三部会を招集→1303年アナーニ事件で教皇ボニファティウス8世を屈服させる", "1309年 教皇庁が南フランスのアヴィニョンに移る(教皇のバビロン捕囚、〜1377年)", "1324年 マリ王国のマンサ=ムーサがメッカ巡礼→金の豊かさが地中海世界に知られる", "1336年 南インドにヴィジャヤナガル王国が成立。日本では1338年に室町幕府が開かれる", "1339年 百年戦争がはじまる→クレシーの戦い(1346年)などでイギリスが優勢に", "1347〜51年ごろ 黒死病(ペスト)がヨーロッパで大流行→人口が激減し農奴の地位が向上", "1351年 元で紅巾の乱がおこる。同年タイにアユタヤ朝が成立", "1356年 カール4世が金印勅書を出す→7人の選帝侯が皇帝を選ぶしくみを確定", "1368年 朱元璋(洪武帝)が明を建て、元はモンゴル高原に退く", "1370年 ティムールが中央アジアにティムール朝を建てる", "1378年 教会大分裂(大シスマ)がはじまる。1381年イギリスでワット=タイラーの乱", "1389年 コソヴォの戦い→オスマン帝国がバルカンに勢力を広げる。1392年朝鮮王朝成立"], "sync": [["ヨーロッパ", "アナーニ事件(1303年)と教皇のバビロン捕囚。百年戦争(1339年〜)と黒死病の大流行。ジャックリーの乱・ワット=タイラーの乱、金印勅書(1356年)、教会大分裂(1378年〜)、カルマル同盟(1397年)。イタリアでルネサンスがはじまる"], ["西アジア・北アフリカ", "イル=ハン国の解体とティムール朝の成立(1370年)。オスマン帝国がバルカンへ進出しアドリアノープルに都を移す。マムルーク朝のカイロが繁栄。イブン=ハルドゥーンの活躍"], ["南アジア・東南アジア", "デリー=スルタン朝(トゥグルク朝)の拡大と動揺、ヴィジャヤナガル王国(1336年)。ジャワのマジャパヒト王国の最盛期、タイのアユタヤ朝(1351年)"], ["東アジア・内陸アジア", "元の財政難と交鈔の乱発、紅巾の乱(1351年)。明の成立(1368年)と洪武帝の統治。朝鮮王朝の成立(1392年)。日本は南北朝の動乱、倭寇の活動"], ["アメリカ・アフリカ", "西アフリカのマリ王国が最盛期(マンサ=ムーサ)、トンブクトゥが学問の中心に。メキシコ高原でアステカ人がテノチティトランを建設したとされる"], ["世界のつながり", "モンゴルの交通網を通じてイブン=バットゥータが大旅行。黒死病がユーラシア各地に広がり、各地の社会を動揺させる"]], "secs": [{"t": "モンゴルの時代のたそがれ ― 14世紀をどう見るか", "p": ["13世紀にユーラシアの大部分を結びつけたモンゴル帝国は、14世紀に入ると、元・キプチャク=ハン国・チャガタイ=ハン国・イル=ハン国という諸政権がそれぞれ内紛と財政難に苦しむようになりました。帝国がつくった駅伝制(ジャムチ)や広い交易圏はなお機能し、人や物、情報の往来はさかんでしたが、その同じ道を通って病気も広がりました。14世紀半ばに流行した【黒死病(ペスト)】は、中央アジアから西アジア、ヨーロッパにまで広がったと考えられており、ユーラシア規模のつながりが生んだ災厄でもありました。", "さらにこの時期は、気候が寒冷化に向かい、飢饉がおこりやすかったとされます。人口の減少と社会不安は各地の政権をゆさぶり、モンゴル支配の後退とともに、新しい国家がつぎつぎに生まれました。東では【明】、中央アジアでは【ティムール朝】、アナトリアからバルカンにかけては【オスマン帝国】、朝鮮半島では【朝鮮王朝】です。14世紀は、モンゴルの時代から、15世紀以降の新しい大帝国の時代へと移る「つなぎ目」の世紀と理解するとよいでしょう。"]}, {"t": "ヨーロッパ ― 封建社会の危機と王権の伸長", "p": ["西ヨーロッパでは、13世紀に絶頂をきわめた教皇権が急速に衰えました。フランス王【フィリップ4世】は聖職者への課税をめぐって教皇【ボニファティウス8世】と対立し、1302年に聖職者・貴族・平民の代表からなる【三部会】を開いて国内の支持を集めました。翌1303年には教皇を捕らえる【アナーニ事件】がおこり、教皇は屈辱のうちに亡くなります。1309年からは教皇庁が南フランスの【アヴィニョン】に移され、フランス王の強い影響下におかれました。これを古代のユダヤ人の故事にならって【教皇のバビロン捕囚】とよびます。教皇がローマに戻ったあとも、1378年からはローマとアヴィニョンに教皇が並び立つ【教会大分裂(大シスマ)】がおこり、教会の権威はさらに傷つきました。イギリスの【ウィクリフ】が聖書を信仰の基礎とし、教会の堕落を批判したのは、こうした状況への反発でした。", "政治の面では、英仏間で【百年戦争】(1339〜1453年)がはじまりました。原因は、フランス王位の継承問題と、毛織物産業で結びついたフランドル地方をめぐる対立です。戦争の前半はイギリスが長弓兵を活用してクレシーの戦いやポワティエの戦いで勝利しました。長い戦争は両国の農村を荒廃させ、重税への不満から、フランスでは1358年に【ジャックリーの乱】、イギリスでは1381年に【ワット=タイラーの乱】という大農民反乱がおこりました。後者では、説教師ジョン=ボールの「アダムが耕しイヴが紡いだとき、だれが貴族であったか」という言葉が知られています。", "黒死病の流行によって人口が大きく減ると、働き手が不足し、領主は農民の待遇を改善せざるをえなくなりました。こうして賦役の廃止や地代の金納化が進み、イギリスでは【ヨーマン(独立自営農民)】が成長します。領主層は没落し、かわって国王が常備軍や官僚を整えて権力を集める方向に進みました。封建社会のしくみがゆるむ一方で、国王を中心とする国家づくりがはじまったのです。", "神聖ローマ帝国では、1356年に皇帝【カール4世】が【金印勅書】を発布し、7人の【選帝侯】が皇帝を選ぶ手続きを定めました。これは皇帝権の弱さを制度として認めたものでもあり、ドイツでは諸侯が自立する領邦の分立が続きます。北ヨーロッパでは【ハンザ同盟】が北海・バルト海の交易を握り、1397年にはデンマークの摂政マルグレーテのもとで【カルマル同盟】が結ばれ、北欧3国が同君連合となりました。東ではモスクワ大公国がキプチャク=ハン国の支配下で力をつけはじめます。", "こうした危機のなかで、イタリアの都市では新しい文化が芽ばえていました。【ダンテ】がトスカナ語で『神曲』を著し、【ペトラルカ】は古典を研究して人文主義の先駆けとなり、【ボッカチオ】は『デカメロン』で黒死病の時代を生きる人々の姿を描きました。東方との交易で豊かになったフィレンツェなどの都市が、15世紀に花開く【ルネサンス】の舞台となっていきます。"]}, {"t": "西アジア・北アフリカ ― ティムールとオスマンの台頭", "p": ["イランを支配していた【イル=ハン国】は、13世紀末にガザン=ハンがイスラームを国教として以来、イラン=イスラーム文化の担い手となっていましたが、14世紀半ばには分裂して急速に衰えました。中央アジアのチャガタイ=ハン国も東西に分かれます。この混乱のなかから、西チャガタイ=ハン国出身の武将【ティムール】が台頭し、1370年に【サマルカンド】を都として【ティムール朝】を建てました。ティムールはモンゴル帝国の再興をかかげて西アジアからインド北部まで遠征し、キプチャク=ハン国にも打撃を与えました。", "アナトリア北西部では、13世紀末におこった【オスマン帝国】が14世紀に急成長しました。ビザンツ帝国の内紛につけこんでバルカン半島に渡り、1360年代にはアドリアノープル(エディルネ)を攻略して都を移しました。1389年の【コソヴォの戦い】でセルビアなどを破り、1396年の【ニコポリスの戦い】ではハンガリー王を中心とするヨーロッパ連合軍を撃破しました。征服地の有力者や騎士に軍役と引きかえに土地の徴税権を与える【ティマール制】や、キリスト教徒の子弟を集めて育てる常備歩兵【イェニチェリ】が、この時期から整えられていきます。ビザンツ帝国はコンスタンティノープル周辺に縮小し、滅亡は時間の問題となりました。", "エジプト・シリアを支配した【マムルーク朝】は、モンゴルの侵入をしりぞけた実績を背景に、アッバース家のカリフを保護してスンナ派世界の中心となっていました。都【カイロ】は紅海とインド洋の交易を握って繁栄し、香辛料をヴェネツィアなどのイタリア商人に売りわたしました。北アフリカのチュニス出身の学者【イブン=ハルドゥーン】は、遊牧民と都市民の関係から王朝の興亡を論じた『世界史序説』を著しました。"]}, {"t": "南アジア・東南アジア ― イスラームの広がりと港市の繁栄", "p": ["北インドでは、デリーを都とする【デリー=スルタン朝】の3番目の王朝、トゥグルク朝が一時はインドの大部分に勢力を広げました。しかし、急な遷都や銅貨の強制など無理な政策で反乱が続き、14世紀末にはティムールのデリー侵攻を受けて大きく衰えます。南インドでは、1336年にヒンドゥー教国の【ヴィジャヤナガル王国】が成立し、北のイスラーム勢力と対抗しながら、インド洋交易で栄えました。", "東南アジアでは、ジャワ島東部の【マジャパヒト王国】が14世紀に最盛期を迎え、島々の交易を広く支配しました。大陸部では、13世紀のスコータイ朝にかわって、1351年にタイ人が【アユタヤ朝】を建て、チャオプラヤ川下流の米作地帯と海上交易を基盤に発展していきます。ベトナムでは陳朝が続き、その後の混乱を経て15世紀に黎朝が成立します。", "この時期、ムスリム商人の活動にともなって、スマトラ島北部などの港市からイスラームが東南アジアに広がりはじめました。交易の利益を求める港市の支配者がイスラームを受け入れ、それが商業ネットワークを通じて広がるという流れは、15世紀のマラッカ王国でさらにはっきりします。"]}, {"t": "東アジア・内陸アジア ― 元から明へ", "p": ["中国の【元】では、14世紀に帝位をめぐる争いがくり返され、宮廷のチベット仏教への多額の出費もあって財政が悪化しました。政府は紙幣である【交鈔】を乱発し、物価が上がって民衆の生活は苦しくなります。黄河の氾濫と治水工事への動員も不満を強めました。こうしたなか、1351年に白蓮教徒を中心とする【紅巾の乱】がおこり、各地に反乱が広がりました。", "反乱軍のなかから頭角をあらわした貧農出身の【朱元璋】は、1368年に南京を都として【明】を建て、【洪武帝】となりました(年号を一代に一つとする一世一元の制はこのときはじまります)。同年、明軍が大都に迫ると元の朝廷はモンゴル高原に退き、北元とよばれます。洪武帝は、宰相の職である中書省を廃止して六部を皇帝に直属させ、皇帝独裁の体制をつくりました。農村では110戸を単位とする【里甲制】をしき、租税台帳の【賦役黄冊】や土地台帳の【魚鱗図冊】をつくって支配を固めました。民衆教化のために【六諭】を定め、兵制としては【衛所制】を整えました。対外的には、民間の海上交易を禁じる【海禁】をとり、周辺諸国との交易を朝貢に限ろうとしました。", "日本では、鎌倉幕府の滅亡後に南北朝の動乱が続き、1338年に足利尊氏が室町幕府を開きました。この混乱期に、九州北部などを拠点とする人々が朝鮮半島や中国沿岸で略奪や密貿易をおこない、【倭寇】とよばれておそれられました。朝鮮半島では、倭寇の撃退で名声をあげた武将【李成桂】が高麗を倒し、1392年に【朝鮮王朝】を開いて、のちに漢城(現在のソウル)を都とし、朱子学を重んじる国家をつくりました。明の海禁も、倭寇対策という面をもっていました。東アジアでは、元の崩壊と倭寇の活動が、明を中心とする新しい国際秩序の形成をうながしたといえます。"]}, {"t": "アフリカ・アメリカ ― 金の王国と湖上の都", "p": ["西アフリカでは、サハラ縦断交易で金と岩塩を取引する【マリ王国】が最盛期を迎えました。国王【マンサ=ムーサ】は1324年ごろにメッカ巡礼をおこない、途中のカイロで大量の金を使ったため、金の価格が下がったと伝えられています。この話はマリの豊かさを地中海世界に知らせ、ヨーロッパの地図にもその姿が描かれました。ニジェール川中流の【トンブクトゥ】にはモスクや学院が建てられ、イスラームの学問の中心地となりました。東アフリカの沿岸では、モガディシュやキルワなどの港市がインド洋交易で栄え、アラビア語の影響を受けた【スワヒリ語】が交易の共通語として広がっていました。", "アメリカ大陸は、ユーラシアとはまだ結びついていません。メキシコ高原では、アステカ人が湖の島に都【テノチティトラン】を建てたとされ(14世紀前半)、15世紀にかけて周辺を征服して【アステカ王国】に成長していきます。アンデス地方では、クスコを中心とするインカの勢力が力をたくわえつつありました。"]}, {"t": "世界のつながり ― 大旅行家と疫病の道", "p": ["14世紀のユーラシアのつながりを象徴するのが、モロッコ出身の【イブン=バットゥータ】です。彼は西アジア・インド・東南アジアを経て元の中国にまで旅し、その見聞は『大旅行記(三大陸周遊記)』にまとめられました。デリーでは法官に任じられるなど、各地でイスラーム法学者として歓迎されたことは、イスラーム世界が言語と法を共有する広大なネットワークであったことを示しています。また、ローマ教皇の使節モンテ=コルヴィノが大都でカトリックを布教し、大司教に任じられたことも、モンゴル時代の東西交流の一例です。", "しかし、このつながりは黒死病の拡大という負の側面ももちました。疫病はヨーロッパでは人口の3分の1ほどを失わせたともいわれ、その結果、農奴解放の進行やユダヤ人迫害など、社会のあり方を大きく変えました。モンゴルの支配がゆるんで陸の道が不安定になると、交易の重心は次第に海の道へと移っていきます。15世紀の明の鄭和の大航海や、ヨーロッパの大航海時代は、こうした14世紀の変化を前提としていると考えると、時代の流れがつかみやすくなります。", "同じ時期に、ヨーロッパでは封建社会が動揺して王権が伸び、中国では明が皇帝独裁体制をつくり、西アジアではティムール朝とオスマン帝国が台頭しました。地域ごとに形は違っても、モンゴル帝国後の新しい秩序をつくろうとする動きが、ユーラシアの東西でほぼ同時に進んでいたことに注目しましょう。"]}], "points": ["教皇のバビロン捕囚(1309〜77年)と教会大分裂(1378〜1417年)を区別し、アナーニ事件・フィリップ4世と結びつける", "黒死病→人口減少→農民の地位向上→ジャックリーの乱・ワット=タイラーの乱という因果関係", "百年戦争の原因(王位継承問題とフランドル地方)と、前半はイギリス優勢だったこと", "金印勅書(1356年・カール4世)は7選帝侯による皇帝選出を定めた", "明の洪武帝の政策(中書省廃止・里甲制・賦役黄冊・魚鱗図冊・六諭・衛所制・海禁)", "1392年の朝鮮王朝成立(李成桂)と倭寇の関係", "ティムール朝(1370年・サマルカンド)とオスマン帝国のバルカン進出(コソヴォ・ニコポリス)", "マリ王国のマンサ=ムーサとトンブクトゥ、イブン=バットゥータの旅行"], "check": [["1303年、フランス王フィリップ4世が教皇ボニファティウス8世を捕らえた事件は?", "アナーニ事件"], ["教皇庁が南フランスのアヴィニョンに移されていた状態をなんとよぶか?", "教皇のバビロン捕囚"], ["1381年にイギリスでおこった農民反乱は?", "ワット=タイラーの乱"], ["1356年に7人の選帝侯による皇帝選出を定めた文書は?", "金印勅書"], ["1351年に元でおこった白蓮教徒中心の反乱は?", "紅巾の乱"], ["明を建てた洪武帝の名は?", "朱元璋"], ["明が農村に設けた110戸を単位とする組織は?", "里甲制"], ["1392年に朝鮮王朝を開いた人物は?", "李成桂"], ["1370年にサマルカンドを都として王朝を開いた人物は?", "ティムール"], ["14世紀にメッカ巡礼をおこなったマリ王国の王は?", "マンサ=ムーサ"]], "related": ["y_13", "y_15", "t_cn", "t_kr", "t_tr", "t_uk", "t_fr", "t_mn", "t_af", "t_th", "j_nanboku"], "n": 4671}, "y_15": {"title": "15世紀の世界", "span": "1401〜1500年", "year": 1450, "lead": "15世紀は、海の時代の幕開けです。前半には明の鄭和の艦隊がインド洋を何度も航海し、後半にはポルトガルとスペインが大西洋に乗り出して、喜望峰経由のインド航路とアメリカ大陸への航路を開きました。その間に、オスマン帝国がビザンツ帝国を滅ぼして東地中海を押さえ、ヨーロッパではルネサンスと主権国家の形成が進みました。", "flow": ["1402年 アンカラの戦いでティムールがオスマン軍を破る→オスマン帝国は一時混乱", "1405〜33年 明の永楽帝の命で鄭和が南海遠征→朝貢国が増え、マラッカ王国が成長", "1414〜18年 コンスタンツ公会議→教会大分裂が終わり、フスが処刑される", "1421年 永楽帝が北京に遷都。1428年ベトナムで黎朝が成立", "1429年 ジャンヌ=ダルクがオルレアンを解放→百年戦争はフランスに有利に。同年琉球王国が統一", "1449年 土木の変→明の正統帝がオイラトのエセンに捕らえられる", "1453年 オスマン帝国のメフメト2世がコンスタンティノープルを攻略→ビザンツ帝国滅亡。同年百年戦争が終結", "1455〜85年 イギリスでバラ戦争→テューダー朝成立。1467年日本で応仁の乱", "1480年 モスクワ大公イヴァン3世がキプチャク=ハン国の支配から自立", "1488年 バルトロメウ=ディアスが喜望峰に到達", "1492年 スペインがグラナダを攻略しレコンキスタ完了→同年コロンブスがカリブ海の島に到達", "1494年 トルデシリャス条約。1498年ヴァスコ=ダ=ガマがインドのカリカットに到達"], "sync": [["ヨーロッパ", "コンスタンツ公会議(1414〜18年)とフス戦争。百年戦争の終結(1453年)、バラ戦争とテューダー朝(1485年)。スペイン王国の成立(1479年)とグラナダ攻略(1492年)。イタリア=ルネサンスの最盛期、活版印刷術の改良。モスクワ大公国の自立(1480年)。イタリア戦争の開始(1494年)"], ["西アジア・北アフリカ", "アンカラの戦い(1402年)。オスマン帝国がコンスタンティノープルを攻略(1453年)しイスタンブルと改称。ティムール朝のサマルカンド・ヘラートで学芸が栄える(ウルグ=ベク)"], ["南アジア・東南アジア", "デリー=スルタン朝(ロディー朝)とヴィジャヤナガル王国。マラッカ王国が明の後ろだてで成長しイスラーム化。ベトナムで黎朝成立(1428年)。アユタヤ朝の発展"], ["東アジア・内陸アジア", "永楽帝の北京遷都と鄭和の南海遠征。勘合貿易(日明貿易)。土木の変(1449年)と長城の修築。朝鮮で世宗が訓民正音を制定(1446年)。琉球王国の中継貿易。日本は応仁の乱(1467年)で戦国時代へ"], ["アメリカ・アフリカ", "アステカ王国とインカ帝国の最盛期。ポルトガルがアフリカ西岸を南下。西アフリカでソンガイ王国が台頭"], ["世界のつながり", "鄭和の艦隊がアフリカ東岸まで到達。ヨーロッパ人の大航海がはじまり、15世紀末に大西洋とインド洋の航路が開かれる"]], "secs": [{"t": "海の時代のはじまり ― 15世紀をどう見るか", "p": ["14世紀にモンゴル帝国の秩序がくずれると、ユーラシア各地では新しい国家が力を固め、交易の担い手も変わっていきました。15世紀の世界をつらぬくキーワードは「海」です。前半には、明の永楽帝が【鄭和】に命じて大艦隊をインド洋に送り、東南アジアから西アジア、アフリカ東岸にいたる国々に朝貢をうながしました。後半には、ポルトガルとスペインが大西洋に乗り出し、15世紀の最後の10年間に、アメリカ大陸への航路とアフリカ南端を回るインド航路が開かれました。", "鄭和の航海とヨーロッパの大航海はよく比較されます。鄭和の遠征は、皇帝の威信を示して朝貢国を増やすことが目的で、遠征の終了後、明は海禁を続けて海外進出を拡大しませんでした。一方、ヨーロッパの航海は香辛料や金を求める商業的な動機と、キリスト教の布教という目的をもち、国王の支援を受けて継続的に進められました。同じ「海の時代」でも、その後の歴史への影響は大きく異なったのです。"]}, {"t": "ヨーロッパ ― ルネサンスと主権国家の芽ばえ", "p": ["14世紀以来の教会の混乱は、1414〜18年の【コンスタンツ公会議】でようやく収拾され、教会大分裂は終わりました。しかし同じ会議で、ボヘミア(ベーメン)の【フス】がウィクリフの説を受けついで教会を批判したとして異端とされ、火刑に処されました。これに反発したチェック人は【フス戦争】をおこし、教会改革を求める動きは16世紀の宗教改革へとつながっていきます。", "英仏の【百年戦争】は、15世紀前半にはイギリスがフランス北部を占領して優勢でしたが、1429年に農民の娘【ジャンヌ=ダルク】が包囲されたオルレアンを解放したことで形勢が逆転し、1453年にイギリスはカレーを除く大陸の領土を失って戦争は終わりました。この戦争をつうじて、両国では諸侯や騎士が没落し、国王が常備軍と課税権を手にして中央集権化が進みました。イギリスではその後、王位をめぐってランカスター家とヨーク家が争う【バラ戦争】(1455〜85年)がおこり、これを収めた【ヘンリ7世】が【テューダー朝】を開いて王権を強めました。", "イベリア半島では、カスティリャ王女【イサベル】とアラゴン王子フェルナンドの結婚をきっかけに、1479年に両国が統合して【スペイン王国】が成立しました。スペインは1492年にイスラーム勢力の最後の拠点【グラナダ】を攻略し、【レコンキスタ(国土回復運動)】を完了させます。神聖ローマ帝国では、15世紀半ばからオーストリアの【ハプスブルク家】が皇帝位を事実上世襲するようになり、婚姻政策で領土を広げていきました。1494年にはフランス王シャルル8世がイタリアに侵入して【イタリア戦争】がはじまり、イタリアは列強の争いの舞台となります。", "文化の面では、イタリアの都市を中心に【ルネサンス】が最盛期を迎えました。フィレンツェでは大富豪【メディチ家】が学者や芸術家を保護し、【ブルネレスキ】が大聖堂の大円蓋を築き、【ボッティチェリ】が「ヴィーナスの誕生」を描きました。人間の個性や現世の価値を重んじる人文主義は、こうした都市の富と東方から伝わった古典の知識に支えられていました。ドイツでは【グーテンベルク】が活版印刷術を改良し、書物が大量に出回るようになったことで、知識や思想の広がる速さが大きく変わりました。", "東ヨーロッパでは、【モスクワ大公国】の【イヴァン3世】が、ビザンツ最後の皇帝の姪と結婚してローマ帝国の後継者を自任し、1480年にキプチャク=ハン国の支配から自立しました。彼は「ツァーリ」の称号を用いたとされ、モスクワを「第3のローマ」とする考えが生まれます。"]}, {"t": "西アジア ― オスマン帝国のコンスタンティノープル攻略", "p": ["15世紀初め、ティムールはアナトリアに進攻し、1402年の【アンカラの戦い】でオスマン帝国のスルタン【バヤジット1世】を破って捕虜としました。オスマン帝国は一時分裂の危機におちいりましたが、まもなく再統一を果たします。一方、ティムールは明への遠征の途中で亡くなり、ティムール朝は内紛で分裂していきました。それでも、都の【サマルカンド】や【ヘラート】では学芸が栄え、君主【ウルグ=ベク】は天文台を建てて精密な天文表をつくらせました。イラン文化とトルコ文化がまじりあった【トルコ=イスラーム文化】が発展し、細密画(ミニアチュール)などの芸術が生まれました。", "オスマン帝国の【メフメト2世】は、1453年に大砲などを用いて【コンスタンティノープル】を攻略し、1000年以上続いた【ビザンツ帝国】を滅ぼしました。都は【イスタンブル】と改められ、聖ソフィア聖堂はモスクに改修されました。オスマン帝国は東地中海と黒海の交易路を押さえ、ヨーロッパ人にとって東方の産物は手に入れにくく、高価になったとされます。このことが、ポルトガルやスペインがアジアへの新しい航路を求める理由の一つになったと説明されます。また、ビザンツから亡命した学者がギリシア語の古典をイタリアに伝え、ルネサンスをさらにうながしました。"]}, {"t": "南アジア・東南アジア ― マラッカの繁栄とイスラーム化", "p": ["北インドではデリー=スルタン朝が続き、15世紀後半にはアフガン系の【ロディー朝】が支配していましたが、その力は弱く、16世紀にはバーブルに滅ぼされることになります。南インドの【ヴィジャヤナガル王国】は、インド洋交易で栄え、アラビア半島から馬を輸入して軍事力を整えました。", "東南アジアで最も重要なのは【マラッカ王国】です。マレー半島西岸の港市マラッカは、14世紀末ごろに成立したとされ、15世紀初めに鄭和の艦隊の寄港地となって明の後ろだてを受け、タイのアユタヤ朝の圧力に対抗しました。マラッカ海峡はインド洋と南シナ海を結ぶ要地で、香辛料・綿織物・陶磁器などが集まる中継港として大いに栄えました。やがてマラッカの王はイスラームに改宗し、ムスリム商人が集まって、マレー半島や諸島部へのイスラームの広がりの拠点となりました。ジャワの【マジャパヒト王国】はこのころから衰え、各地のイスラーム港市国家が力をのばしていきます。", "大陸部では、ベトナムで明の一時的な支配を退けた【黎利】が1428年に【黎朝】を開き、明にならった官僚制と朱子学を取り入れました。タイの【アユタヤ朝】はアンコールを攻略してカンボジアを圧迫し、交易国家として発展しました。"]}, {"t": "東アジア ― 明の最盛期と朝貢体制", "p": ["明では、洪武帝の死後、北平(北京)にいた叔父の燕王が甥の建文帝から帝位を奪いました(【靖難の役】)。これが【永楽帝】です。永楽帝はみずからモンゴル高原に遠征し、1421年に都を【北京】に移しました。また、ムスリムの宦官【鄭和】に命じて1405年から南海遠征をおこなわせ、艦隊は東南アジア・インドを経てアラビア半島やアフリカ東岸のマリンディにまで達しました。これにより、多くの国が明に朝貢するようになりました。永楽帝の時代には、皇帝を補佐する【内閣大学士】の制度がはじまり、また朱子学にもとづく『四書大全』などの編纂もおこなわれました。", "明は【朝貢】と【海禁】を組み合わせ、周辺諸国の君主が明の皇帝に朝貢し、その返礼として物品を受け取るかたちでのみ交易を認めました。日本では室町幕府の【足利義満】が明から「日本国王」に封じられ、【勘合】を用いた【日明貿易(勘合貿易)】をはじめました。【琉球】は1429年に中山王の尚巴志によって統一され、明への朝貢で得た中国の産物を日本や東南アジアに運ぶ中継貿易で栄えました。", "しかし15世紀半ばになると、北方でモンゴル系の【オイラト】が強大となり、1449年には指導者【エセン】が明の正統帝を捕らえる【土木の変】がおこりました。明はこれ以降守勢にまわり、北方防衛のために【万里の長城】を大規模に修築しました。現在見られる長城の多くは、明代に整えられたものです。", "朝鮮王朝では第4代の【世宗】が、民衆にも読み書きしやすい文字として【訓民正音(ハングル)】を1446年に公布し、金属活字による出版もさかんにおこなわれました。日本では1467年に【応仁の乱】がおこり、幕府の権威が衰えて戦国時代に入っていきます。"]}, {"t": "アメリカ・アフリカ ― 栄える文明と迫る航海者", "p": ["アメリカ大陸では、ヨーロッパ人の到来の直前に大きな国家が栄えていました。メキシコ高原の【アステカ王国】は、湖上の都【テノチティトラン】を中心に周辺の諸部族から貢納を集め、太陽神への人身供犠をともなう祭祀をおこなっていました。アンデス山中では、【クスコ】を都とする【インカ帝国】が15世紀に急速に領土を広げ、整備された道路網と駅伝で広大な地域を結びました。文字はありませんでしたが、縄の結び目で数量を記録する【キープ】が用いられました。", "アフリカでは、ポルトガルの【エンリケ(航海王子)】の支援のもと、ポルトガル人が西アフリカ沿岸を南下し、金や奴隷の取引をはじめました。1488年には【バルトロメウ=ディアス】がアフリカ南端の【喜望峰】に到達しました。西アフリカの内陸では、マリ王国にかわって【ソンガイ王国】が台頭し、トンブクトゥやガオを中心にサハラ交易を支配しました。"]}, {"t": "世界のつながり ― 1490年代の大転換", "p": ["15世紀最後の10年間は、世界史の大きな転換点です。スペインの支援を受けたジェノヴァ出身の【コロンブス】は、地球球体説にもとづいて西まわりでアジアをめざし、1492年にカリブ海のサンサルバドル島に到達しました。彼はそこをアジアの一部と考えましたが、のちに【アメリゴ=ヴェスプッチ】の探検などから新大陸であることが知られ、「アメリカ」という名がつけられました。1494年にはスペインとポルトガルが【トルデシリャス条約】を結び、海外の領域を分け合う境界線を定めました。1498年には、ポルトガルの【ヴァスコ=ダ=ガマ】が喜望峰を回ってインド西岸の【カリカット】に到達し、香辛料を直接手に入れる道を開きました。", "この航海は、ユーラシア・アフリカとアメリカという、それまで別々に発展してきた世界が結びつくはじまりでした。ただし、15世紀末の時点では、インド洋の交易はなおムスリム商人やアジアの商人が中心で、明やオスマン帝国、ヴィジャヤナガル王国などのアジアの大国のほうが、経済力ではヨーロッパをしのいでいたことも忘れてはなりません。ヨーロッパ人は、すでにあったアジアの豊かな交易網に「新しく参入した」と見るのが正確です。", "同じ1490年代には、スペインのレコンキスタ完了とイタリア戦争の開始がありました。レコンキスタで高まった国家とキリスト教の結びつきが海外進出の原動力となり、イタリア戦争はヨーロッパ諸国が勢力を競い合う主権国家体制のはじまりとなりました。15世紀の終わりに、16世紀の世界を動かす要素がほぼ出そろったのです。"]}], "points": ["コンスタンツ公会議(1414〜18年)で教会大分裂が終わり、フスが処刑された", "1453年は、ビザンツ帝国滅亡と百年戦争終結が重なる年", "永楽帝の政策(靖難の役・北京遷都・鄭和の南海遠征・内閣大学士)と土木の変(1449年・エセン)", "マラッカ王国が鄭和の寄港地として成長し、イスラームの拠点となった", "大航海の順序:ディアス喜望峰(1488年)→コロンブス(1492年)→トルデシリャス条約(1494年)→ヴァスコ=ダ=ガマ(1498年)", "1492年はグラナダ攻略(レコンキスタ完了)とコロンブスの到達が同じ年", "朝鮮の世宗の訓民正音、琉球王国の中継貿易、足利義満の勘合貿易", "イヴァン3世の自立(1480年)とモスクワ=第3のローマの考え"], "check": [["1402年にティムールがオスマン軍を破った戦いは?", "アンカラの戦い"], ["1453年にコンスタンティノープルを攻略したオスマン帝国のスルタンは?", "メフメト2世"], ["永楽帝の命で南海遠征をおこなった宦官は?", "鄭和"], ["1449年に明の正統帝がオイラトに捕らえられた事件は?", "土木の変"], ["1446年に朝鮮の世宗が公布した文字は?", "訓民正音"], ["バラ戦争を収めてテューダー朝を開いた王は?", "ヘンリ7世"], ["1488年に喜望峰に到達したポルトガル人は?", "バルトロメウ=ディアス"], ["1494年にスペインとポルトガルが海外領域の境界を定めた条約は?", "トルデシリャス条約"], ["1498年にインドのカリカットに到達した人物は?", "ヴァスコ=ダ=ガマ"], ["15世紀に明の後ろだてで栄え、イスラームの拠点となった港市国家は?", "マラッカ王国"]], "related": ["y_14", "y_16", "t_tr", "t_byz", "t_cn", "t_es", "t_ru", "t_uk", "t_id", "t_vn", "t_la", "j_muro", "j_sengoku"], "n": 4290}, "y_16": {"title": "16世紀の世界", "span": "1501〜1600年", "year": 1550, "lead": "16世紀は、世界がはじめて一つの交易網で結ばれた「世界の一体化」の出発点です。スペインがアメリカ大陸を征服し、そこで掘り出された大量の銀がヨーロッパとアジアに流れこみました。ヨーロッパでは宗教改革が教会を分裂させ、西アジアからインドにかけてはオスマン帝国・サファヴィー朝・ムガル帝国という3つのイスラーム大国が並び立ちました。", "flow": ["1501年 イランでイスマーイール1世がサファヴィー朝を建てる→シーア派を国教に", "1510年 ポルトガルがゴアを占領→1511年マラッカを占領し、アジア交易に参入", "1517年 ルターが95か条の論題を発表→宗教改革のはじまり。同年オスマン帝国がマムルーク朝を滅ぼす", "1519〜22年 マゼランの艦隊が世界周航。1521年コルテスがアステカ王国を征服", "1526年 モハーチの戦い。同年バーブルがパーニーパットの戦いに勝ちムガル帝国を建てる", "1529年 スレイマン1世が第1次ウィーン包囲→ヨーロッパに大きな衝撃", "1533年 ピサロがインカ帝国を征服。1534年ヘンリ8世が首長法を制定しイギリス国教会成立", "1545年 ポトシ銀山の採掘はじまる→大量の銀がヨーロッパ・アジアへ(価格革命)", "1555年 アウクスブルクの和議→ドイツの諸侯がルター派かカトリックかを選べるように", "1568年 オランダ独立戦争はじまる。1571年レパントの海戦、スペインがマニラを建設", "1588年 イギリスがスペインの無敵艦隊を破る。1592年豊臣秀吉の朝鮮出兵", "1598年 フランスでナントの王令→ユグノー戦争が終わる"], "sync": [["ヨーロッパ", "ルターの宗教改革(1517年)、カルヴァンの改革、イギリス国教会(1534年)、対抗宗教改革(トリエント公会議・イエズス会)。カール5世とフェリペ2世のスペイン、オランダ独立戦争(1568年〜)、無敵艦隊の敗北(1588年)、ユグノー戦争とナントの王令(1598年)。価格革命と商業革命。ロシアのイヴァン4世"], ["西アジア・北アフリカ", "オスマン帝国がマムルーク朝を滅ぼし(1517年)、スレイマン1世のもとで最盛期(モハーチの戦い、第1次ウィーン包囲、プレヴェザの海戦)。サファヴィー朝(1501年)、アッバース1世のイスファハーン"], ["南アジア・東南アジア", "ムガル帝国の成立(1526年)とアクバルの統治。ポルトガルのゴア・マラッカ占領、スペインのマニラ建設(1571年)。ビルマのタウングー朝"], ["東アジア・内陸アジア", "明の北虜南倭(アルタン、後期倭寇)、一条鞭法、張居正の改革。日本銀・アメリカ銀の流入。鉄砲とキリスト教の伝来、豊臣秀吉の全国統一と朝鮮出兵(壬辰・丁酉倭乱)"], ["アメリカ・アフリカ", "コルテスのアステカ征服(1521年)、ピサロのインカ征服(1533年)。エンコミエンダ制と先住民人口の激減、ラス=カサスの批判。ポトシ銀山、ブラジルの砂糖生産と黒人奴隷の導入"], ["世界のつながり", "マゼラン艦隊の世界周航。アメリカ銀がヨーロッパへ、またガレオン貿易でアジアへ流入。イエズス会のアジア布教"]], "secs": [{"t": "世界の一体化と銀の流れ ― 16世紀をどう見るか", "p": ["15世紀末に開かれた大西洋とインド洋の航路は、16世紀に入ると世界の各地を実際に結びつけはじめました。とくに重要なのが【銀】の流れです。スペインはアメリカ大陸を征服し、1545年に採掘のはじまった【ポトシ銀山】などから大量の銀を本国に運びました。この銀はヨーロッパの物価を大きく押し上げ(【価格革命】)、さらに香辛料や絹・陶磁器を買うためにアジアへ流れていきました。同じころ日本でも石見銀山などで銀の生産が増え、日本銀も中国へ向かいました。", "銀を最も多く吸いこんだのは、税を銀で納める制度へ移りつつあった明の中国でした。つまり16世紀には、アメリカの鉱山、ヨーロッパの商人、日本の銀、中国の市場が、銀を通して一つにつながったのです。この時期を「世界の一体化」のはじまりとよぶのはそのためです。一方で、アメリカ大陸の先住民にとっては、征服と疫病によって人口が激減する悲劇の世紀でもありました。"]}, {"t": "ヨーロッパ ― 宗教改革と主権国家の争い", "p": ["1517年、ドイツの神学者【ルター】は、教皇【レオ10世】がサン=ピエトロ大聖堂の建築資金を集めるために売り出した【贖宥状(免罪符)】を批判し、【95か条の論題】を発表しました。ルターは、人は善行ではなく信仰によってのみ救われ、信仰のよりどころは聖書のみであると説きました。活版印刷によって彼の主張は急速に広まり、ローマ教会の重い負担に不満をもっていたドイツの諸侯や民衆の支持を集めました。皇帝【カール5世】は1521年の【ヴォルムス帝国議会】でルターに説の撤回を求めましたが、ルターはザクセン選帝侯に保護されて聖書のドイツ語訳を進めました。1524年にはトマス=ミュンツァーらの指導する【ドイツ農民戦争】がおこりましたが、ルターは諸侯の側に立ちました。長い対立の末、1555年の【アウクスブルクの和議】で、諸侯はカトリックとルター派のどちらかを選ぶことができ、領民はそれに従うことになりました。", "スイスでは【ツヴィングリ】、ついで【カルヴァン】がジュネーヴで改革を進めました。カルヴァンは、救われる人はあらかじめ神によって定められているという【予定説】を説き、勤勉に働いて得た富を肯定的にとらえたため、西ヨーロッパの商工業者に広く受け入れられました。その信者はフランスでは【ユグノー】、イギリスでは【ピューリタン】、オランダではゴイセンとよばれます。イギリスでは国王【ヘンリ8世】が離婚問題で教皇と対立し、1534年の【首長法】で国王を首長とする【イギリス国教会】をつくり、【エリザベス1世】の【統一法】(1559年)で制度が確立しました。カトリック側も、【トリエント公会議】で教義を再確認し、【イグナティウス=ロヨラ】らの【イエズス会】が海外布教を進めるなど【対抗宗教改革】で巻き返しました。", "政治的には、ハプスブルク家の【カール5世】がスペイン王と神聖ローマ皇帝を兼ね、ヨーロッパの広い地域とアメリカ大陸を支配して、フランスと【イタリア戦争】を争いました。こうした争いのなかで、各国が国境と主権をもって競い合う【主権国家体制】が形づくられていきます。カール5世の子【フェリペ2世】のスペインは、1571年の【レパントの海戦】でオスマン艦隊を破り、1580年にはポルトガルを併合して「太陽の沈まぬ国」とよばれました。しかし、カルヴァン派の多いネーデルラントがスペインの重税と宗教弾圧に反発して1568年に【オランダ独立戦争】をおこし、北部7州は1579年に【ユトレヒト同盟】を結んで抵抗を続けました。オランダを支援したイギリスは、1588年にスペインの【無敵艦隊(アルマダ)】を破りました。フランスでは新旧両派が争う【ユグノー戦争】がおこり、1572年の【サンバルテルミの虐殺】などの惨事を経て、ブルボン朝を開いた【アンリ4世】が1598年に【ナントの王令】で個人の信仰の自由を認め、内戦を収めました。", "経済面では、大西洋交易の発展によって商業の中心が地中海からアントウェルペンなどの大西洋沿岸に移り(【商業革命】)、価格革命で固定地代に頼る領主層が打撃を受けました。一方、エルベ川以東の東ヨーロッパでは、西ヨーロッパ向けの穀物を生産するために農奴制が強化される【農場領主制(グーツヘルシャフト)】が広がり、東西の分業が生まれました。ロシアでは【イヴァン4世】がツァーリとして専制政治をおこない、カザン=ハン国を併合してシベリア進出の足がかりをつくりました。"]}, {"t": "西アジア・南アジア ― 3つのイスラーム帝国", "p": ["オスマン帝国は、【セリム1世】が1514年にサファヴィー朝を破り、1517年に【マムルーク朝】を滅ぼしてエジプト・シリアと聖地メッカ・メディナを支配下に入れました。続く【スレイマン1世】の時代に帝国は最盛期を迎えます。1526年の【モハーチの戦い】でハンガリーを破り、1529年には【第1次ウィーン包囲】をおこなってヨーロッパを震撼させました。1538年の【プレヴェザの海戦】でスペイン・ヴェネツィアなどの連合艦隊を破り、地中海の制海権を握りました。オスマン帝国はハプスブルク家と対立するフランスと結び、フランス商人に通商上の特権(のちのカピチュレーション)を認めました。ここには、宗教の違いをこえてヨーロッパの勢力争いに加わるオスマン帝国の姿が見えます。", "イランでは1501年に神秘主義教団の長【イスマーイール1世】が【サファヴィー朝】を建て、【シーア派(十二イマーム派)】を国教としました。これにより、スンナ派のオスマン帝国と対立する構図が生まれ、現在のイランがシーア派の国であることの起源となりました。16世紀末に即位した【アッバース1世】は、オスマン帝国から領土を取り戻し、新都【イスファハーン】を建設して壮麗なモスクを建て、「イスファハーンは世界の半分」とたたえられる繁栄をもたらしました。", "インドでは、ティムールの子孫【バーブル】が中央アジアから進出し、1526年の【パーニーパットの戦い】でロディー朝を破って【ムガル帝国】を建てました。第3代の【アクバル】は、都をアグラにおき、官僚の位階を定める【マンサブダール制】を整えるとともに、ヒンドゥー教徒の協力を得るために非ムスリムに課される人頭税【ジズヤ】を廃止しました。イスラームとヒンドゥーの融合はこの時代の文化の特徴で、ナーナクの開いた【シク教】もその一例です。オスマン・サファヴィー・ムガルという3つの大国は、いずれも火器を用いた強力な軍をもち、ユーラシアの陸の大帝国として繁栄しました。"]}, {"t": "東南アジア ― ポルトガルとスペインの参入", "p": ["ヴァスコ=ダ=ガマの航海のあと、ポルトガルはインド総督【アルブケルケ】のもとで1510年にインド西岸の【ゴア】を占領し、1511年には【マラッカ】を攻略しました。ポルトガルは要地に商館や要塞をおき、香辛料交易に参入しましたが、アジアの交易全体を支配したわけではありません。マラッカを追われたムスリム商人は、スマトラ北部のアチェやジャワのバンテンなど別の港市に拠点を移し、その結果、イスラームはむしろ東南アジア各地にいっそう広がりました。ポルトガルはさらに中国の【マカオ】に居住権を得て、日本との貿易にも乗り出しました。", "スペインは、マゼラン艦隊の到達をきっかけにフィリピンに進出し、1571年に【マニラ】を建設しました。マニラとメキシコの【アカプルコ】を結ぶ【ガレオン貿易】では、アメリカ大陸の銀が太平洋を渡ってマニラに運ばれ、中国商人のもたらす絹や陶磁器と交換されました。こうして、大西洋経由だけでなく太平洋経由でもアメリカ銀が中国に流れこむ道ができました。大陸部では、ビルマの【タウングー朝】が勢力を広げ、アユタヤを一時従属させました。"]}, {"t": "東アジア ― 北虜南倭と銀の時代", "p": ["16世紀の明は、北と南の両方から圧力を受けました。北方ではモンゴルの【アルタン=ハン】がたびたび侵入し、1550年には北京を包囲しました。南方の沿岸では、密貿易を担った武装集団である【後期倭寇】が活動しました。後期倭寇は日本人だけでなく、中国人が多数をしめていたとされます。これらを合わせて【北虜南倭】とよびます。その背景には、海禁によって民間の交易が禁じられていたにもかかわらず、日本銀などを求める交易の需要が非常に大きかったことがありました。明は16世紀後半に海禁をゆるめ、民間の海外交易を認めるようになりました。", "大量の銀の流入は、明の税制を変えました。各種の税や労役を一本化して銀で納めさせる【一条鞭法】が16世紀後半に広く実施されました。万暦帝の初期には首席大学士の【張居正】が財政の立て直しをはかりましたが、その死後、政治は混乱しました。経済面では、長江下流域で綿織物や生糸の生産がさかんになり、穀倉地帯は長江中流域に移って「湖広熟すれば天下足る」といわれるようになりました。徽州商人や山西商人などの大商人も活躍します。", "日本では、1543年ごろにポルトガル人が【鉄砲】を伝え、1549年にはイエズス会の【フランシスコ=ザビエル】がキリスト教を伝えました。南蛮貿易がさかんになり、鉄砲は戦国大名の戦い方を変え、天下統一を早めたとされます。全国を統一した【豊臣秀吉】は、明の征服をめざして1592年と1597年に朝鮮に出兵しました(朝鮮では【壬辰・丁酉倭乱】とよばれます)。朝鮮側は【李舜臣】の水軍や各地の義兵、明の援軍によって抵抗しました。この戦争は朝鮮に大きな被害を与え、明の財政を圧迫し、のちに女真(満州人)が台頭するすきをつくりました。中国では、イエズス会の【マテオ=リッチ】が北京で布教し、世界地図「坤輿万国全図」をつくるなど、ヨーロッパの学問を伝えはじめました。"]}, {"t": "アメリカ・アフリカ ― 征服と大西洋の新しい構造", "p": ["アメリカ大陸では、スペイン人の征服者(コンキスタドール)が先住民の国家をつぎつぎと滅ぼしました。【コルテス】は1521年に【アステカ王国】を、【ピサロ】は1533年に【インカ帝国】を征服しました。少数のスペイン人が大国を倒せたのは、鉄製の武器や馬に加えて、ヨーロッパ人がもちこんだ天然痘などの疫病で先住民が大量に亡くなったこと、支配に不満をもつ部族がスペイン側についたことなどによります。スペインは先住民をキリスト教化することを条件に入植者に先住民の支配を委ねる【エンコミエンダ制】をしき、先住民は鉱山や農園で過酷な労働を強いられました。ドミニコ会士の【ラス=カサス】は、その実態を告発して先住民の保護を訴えました。", "先住民人口が激減すると、労働力を補うためにアフリカから黒人奴隷が運ばれるようになりました。ポルトガル領【ブラジル】では、16世紀後半からサトウキビのプランテーションが広がり、多くの奴隷が導入されました。アフリカ西岸では、ヨーロッパ商人が武器や雑貨と引きかえに奴隷を買い取る取引が拡大し、アフリカ社会に深い傷を残していきます。この大西洋をまたぐ構造は、17〜18世紀の【三角貿易】へと発展します。西アフリカ内陸の【ソンガイ王国】は、16世紀末にモロッコ軍の侵攻を受けて崩壊しました。"]}, {"t": "世界のつながり ― 地球を一周した人・物・信仰", "p": ["スペイン王の支援を受けたポルトガル人【マゼラン(マガリャンイス)】は1519年に西まわりの航海に出発し、南アメリカ南端の海峡を抜けて太平洋を横断しました。彼自身はフィリピンで先住民との戦いで亡くなりましたが、部下が1522年に帰国し、史上初の世界周航が達成されました。これにより、地球が球体であることが実際に証明されました。", "人と物の移動は、生活をも変えました。アメリカ大陸原産のジャガイモ・トウモロコシ・サツマイモ・トウガラシ・タバコなどがヨーロッパやアジアに広まり、のちの人口増加を支えました。逆に、ヨーロッパからは馬や牛、小麦、そして疫病がアメリカに持ちこまれました。これを【コロンブス交換】とよぶことがあります。信仰の面では、イエズス会がインド・日本・中国で布教し、キリスト教が世界宗教としてアジアにも根を下ろしはじめました。", "同時代を横に並べると、ヨーロッパが宗教戦争で分裂していたちょうどそのとき、オスマン帝国はウィーンを包囲し、ムガル帝国はアクバルのもとで繁栄し、明は北虜南倭に苦しみながらも世界の銀を集めていました。16世紀の世界の主役は、まだヨーロッパだけではなかったのです。ヨーロッパの優位がはっきりするのは、さらに後の時代のことです。"]}], "points": ["ルターの95か条の論題(1517年)→ヴォルムス帝国議会(1521年)→ドイツ農民戦争→アウクスブルクの和議(1555年)の流れ", "カルヴァンの予定説と、ユグノー・ピューリタン・ゴイセンという呼び名", "イギリス国教会:ヘンリ8世の首長法(1534年)とエリザベス1世の統一法(1559年)", "スレイマン1世(モハーチの戦い・第1次ウィーン包囲・プレヴェザの海戦)と、フェリペ2世のレパントの海戦(1571年)の区別", "サファヴィー朝のシーア派国教化、ムガル帝国のアクバルによるジズヤ廃止", "アメリカ銀(ポトシ銀山)→価格革命、ガレオン貿易でマニラ経由で中国へ→一条鞭法", "明の北虜南倭(アルタン・後期倭寇)と、豊臣秀吉の朝鮮出兵", "コルテス(アステカ1521年)とピサロ(インカ1533年)、エンコミエンダ制とラス=カサス"], "check": [["1517年に95か条の論題を発表した人物は?", "ルター"], ["1555年、ドイツ諸侯にカトリックかルター派かの選択を認めた取り決めは?", "アウクスブルクの和議"], ["1534年にヘンリ8世が制定し、国王を教会の首長とした法は?", "首長法"], ["1529年に第1次ウィーン包囲をおこなったオスマン帝国のスルタンは?", "スレイマン1世"], ["1501年に成立し、シーア派を国教としたイランの王朝は?", "サファヴィー朝"], ["ムガル帝国でジズヤを廃止した皇帝は?", "アクバル"], ["16世紀に明で実施された、税を銀で一本化して納める制度は?", "一条鞭法"], ["1571年にスペインがフィリピンに建設した拠点は?", "マニラ"], ["インカ帝国を征服したスペイン人は?", "ピサロ"], ["1598年にアンリ4世が出し、ユグノー戦争を終わらせた法令は?", "ナントの王令"]], "related": ["y_15", "y_17", "t_de", "t_es", "t_uk", "t_fr", "t_nl", "t_tr", "t_ir", "t_in", "t_cn", "t_la", "t_ph", "j_shokuho"], "n": 4981}, "y_17": {"title": "17世紀の世界", "span": "1601〜1700年", "year": 1650, "lead": "17世紀は「危機の世紀」とよばれます。寒冷な気候と戦争・反乱が世界各地で重なり、ヨーロッパでは三十年戦争とイギリス革命、中国では明清交代という大きな政治変動がおこりました。その混乱のなかから、ヨーロッパでは主権国家体制と議会政治、アジアでは清と江戸幕府の安定した秩序が生まれ、海上交易の主役はオランダへと移りました。", "flow": ["1600年 イギリス東インド会社設立→1602年オランダ東インド会社設立", "1603年 江戸幕府が開かれる。1607年イギリスが北米にジェームズタウンを建設", "1613年 ロシアでロマノフ朝が成立。1616年ヌルハチが後金を建てる", "1618年 三十年戦争はじまる→ドイツが荒廃", "1623年 アンボイナ事件→イギリスは香辛料諸島から後退しインド経営へ", "1628年 権利の請願→1642年ピューリタン革命→1649年チャールズ1世処刑", "1636年 ホンタイジが国号を清とする→1644年李自成が明を滅ぼし、清が北京に入る", "1648年 ウェストファリア条約→主権国家体制の確立、オランダ・スイスの独立承認", "1651年 航海法→英蘭戦争。1660年王政復古", "1661年 ルイ14世の親政はじまる。同年鄭成功が台湾を拠点とする(1683年清が台湾を領有)", "1683年 オスマン帝国の第2次ウィーン包囲が失敗→1699年カルロヴィッツ条約でハンガリーを失う", "1688〜89年 名誉革命と権利の章典。1689年ネルチンスク条約"], "sync": [["ヨーロッパ", "三十年戦争(1618〜48年)とウェストファリア条約。イギリスのピューリタン革命(1642年〜)・王政復古・名誉革命(1688〜89年)。ルイ14世の絶対王政。オランダの黄金時代。ロシアのロマノフ朝成立とピョートル1世の即位。科学革命(ガリレイ・ニュートン)"], ["西アジア・北アフリカ", "サファヴィー朝のアッバース1世とイスファハーンの繁栄。オスマン帝国の第2次ウィーン包囲失敗(1683年)とカルロヴィッツ条約(1699年)"], ["南アジア・東南アジア", "ムガル帝国のシャー=ジャハーン(タージ=マハル)とアウラングゼーブ(ジズヤ復活、領土最大)。オランダのバタヴィア建設とアンボイナ事件(1623年)、日本町の盛衰"], ["東アジア・内陸アジア", "後金(1616年)から清(1636年)へ、明の滅亡(1644年)と清の中国支配、三藩の乱と台湾の領有、康熙帝の安定。ネルチンスク条約(1689年)。江戸幕府の成立と鎖国体制"], ["アメリカ・アフリカ", "イギリス(ヴァージニア・ニューイングランド)、フランス(ケベック)、オランダ(ニューアムステルダム)の北米植民。カリブ海の砂糖プランテーションと奴隷貿易の拡大"], ["世界のつながり", "オランダ・イギリスの東インド会社によるアジア交易。大西洋三角貿易の形成。イエズス会による東西の学問交流"]], "secs": [{"t": "危機の世紀 ― 17世紀をどう見るか", "p": ["17世紀の世界は、気候の寒冷化が進み、凶作や飢饉、疫病がくり返されたとされます。16世紀に急増した人口と経済の拡大が行きづまり、各地で戦争や反乱がおこりました。ヨーロッパの【三十年戦争】やイギリス革命、フランスのフロンドの乱、ロシアの農民反乱、中国の李自成の乱と明の滅亡、オスマン帝国の混乱など、ユーラシアの東西でほぼ同時に大きな政治変動がおきたことから、この時代は「17世紀の危機」とよばれます。", "しかし危機は、新しい秩序の出発点にもなりました。ヨーロッパでは戦争を経て【主権国家体制】が確立し、イギリスでは議会が王権をおさえる体制ができ、フランスでは国王が強大な権力をもつ【絶対王政】が完成しました。東アジアでは【清】と【江戸幕府】が安定した支配を築き、18世紀の繁栄につながります。交易の面では、スペイン・ポルトガルにかわって【オランダ】が世界の海を舞台に活躍し、やがてイギリスがこれに挑みました。"]}, {"t": "ヨーロッパ(1) ― 三十年戦争と主権国家体制", "p": ["1618年、ベーメン(ボヘミア)の新教徒が、ハプスブルク家によるカトリック化の強制に反発して反乱をおこしました。これが【三十年戦争】のはじまりです。当初は神聖ローマ帝国内の新旧両派の争いでしたが、デンマーク、さらにスウェーデン王【グスタフ=アドルフ】が新教側で参戦し、ついにはカトリック国のフランスが、宰相【リシュリュー】のもとでハプスブルク家に対抗するため新教側について参戦しました。宗教の違いよりも国家の利益が優先されたことは、この戦争が宗教戦争から国家間の勢力争いへと性格を変えたことを示しています。戦場となったドイツは傭兵の略奪や疫病で荒廃し、人口が大きく減ったとされます。", "1648年の【ウェストファリア条約】で戦争は終わりました。ドイツの約300の領邦はほぼ完全な主権を認められ、神聖ローマ帝国は事実上解体状態となりました。また、【オランダ(ネーデルラント連邦共和国)】と【スイス】の独立が正式に認められ、フランスはアルザスの一部を得ました。この条約は、主権をもつ国家どうしが対等な立場で外交をおこなうという【主権国家体制】を確立したものとして重視されます。", "フランスでは、幼い【ルイ14世】のもとで宰相【マザラン】が王権強化を進めましたが、これに貴族や高等法院が反発して【フロンドの乱】がおきました。乱の鎮圧後、1661年からルイ14世は親政をはじめ、「朕は国家なり」の言葉で知られる絶対王政を完成させました。王権神授説を背景に、財務総監【コルベール】の【重商主義】政策で国内産業を育て、壮大な【ヴェルサイユ宮殿】を建てました。しかし、1685年の【ナントの王令の廃止】で多くのユグノーの商工業者が国外に逃れ、また度重なる対外戦争によって財政は悪化していきました。"]}, {"t": "ヨーロッパ(2) ― イギリス革命とオランダの繁栄、東欧の変化", "p": ["イギリスでは、エリザベス1世の死後スコットランドからむかえられた【ジェームズ1世】がステュアート朝を開き、王権神授説をとなえて議会を軽視しました。つぎの【チャールズ1世】に対し、議会は1628年に【権利の請願】を出して、議会の同意のない課税などをやめるよう求めました。国王が議会を開かずに専制を続け、やがて内戦がはじまります(【ピューリタン革命】、1642年〜)。ピューリタンの【クロムウェル】の率いる議会派が勝利し、1649年に国王は処刑され、共和政が成立しました。クロムウェルは、オランダの中継貿易に打撃を与えるため1651年に【航海法】を制定し、これをきっかけに【イギリス=オランダ(英蘭)戦争】がおこりました。のちにクロムウェルは【護国卿】となって独裁を強めたため、その死後の1660年に【王政復古】がおこなわれます。", "しかし、復活した国王がカトリックの復活と専制をはかると、議会は1688年にオランダから【ウィリアム3世とメアリ2世】をむかえ、国王【ジェームズ2世】は亡命しました。血を流さずに実現したことから【名誉革命】とよばれます。翌1689年の【権利の章典】によって、議会の同意なしに法律の停止や課税ができないことが確認され、議会が主権を担う立憲君主政の基礎がつくられました。議会では、王権を重んじる【トーリ党】と議会の権利を重んじる【ホイッグ党】という政党の原型も生まれていました。【ロック】は、人民は抵抗権をもつという社会契約説を説き、名誉革命を理論的に正当化しました。", "17世紀前半のヨーロッパ経済の中心は【オランダ】でした。1602年に設立された【オランダ東インド会社】は、世界初の本格的な株式会社とされ、アジア交易で巨額の利益をあげました。首都【アムステルダム】は国際金融と商業の中心となり、【レンブラント】らの絵画も市民の豊かさを映しています。しかし英蘭戦争やフランスとの戦争を経て、17世紀後半にはその地位はしだいにイギリスへと移っていきました。", "東ヨーロッパでは、ロシアで動乱期を経て1613年に【ロマノフ朝】が成立し、農奴制を強化しました。これに反発した【ステンカ=ラージン】の農民反乱がおこりましたが鎮圧されます。1682年に即位した【ピョートル1世】は、みずから西欧を視察して近代化を進めました。プロイセンでは【ホーエンツォレルン家】が力をのばし、オーストリアはオスマン帝国からハンガリーを取り戻して大国化しました。", "学問の面では、【ガリレイ】が地動説を支持し、【ニュートン】が万有引力の法則を発表するなど、自然を観察と実験、数学によって説明する【科学革命】が進みました。【デカルト】の合理主義や【フランシス=ベーコン】の経験論もこの時代の哲学です。"]}, {"t": "西アジア・南アジア ― イスラーム大国の繁栄と転機", "p": ["イランのサファヴィー朝では、【アッバース1世】の時代(16世紀末〜17世紀初め)に最盛期を迎えました。都【イスファハーン】には「王のモスク」などの壮麗な建築が並び、「世界の半分」とたたえられました。ポルトガル人をホルムズ島から追い出すなど、ペルシア湾の交易にも力を入れました。", "オスマン帝国は、17世紀には軍事的な拡大がとまり、イェニチェリの反乱などで政治が乱れることもありましたが、大宰相の活躍で立て直しをはかりました。1683年には大軍を送って【第2次ウィーン包囲】をおこないましたが、ポーランドなどの救援軍に敗れて失敗します。これをきっかけにオーストリアなどとの戦争に敗れ、1699年の【カルロヴィッツ条約】で【ハンガリー】などをオーストリアに割譲しました。これはオスマン帝国がヨーロッパに対して大規模に領土を失った最初の条約であり、以後、攻守が逆転していきます。", "ムガル帝国では、第5代【シャー=ジャハーン】が亡き妃のための墓廟【タージ=マハル】をアグラに建て、インド=イスラーム建築の代表作となりました。第6代【アウラングゼーブ】は南インドまで遠征して帝国の領土を最大にしましたが、厳格なスンナ派の信仰にもとづいて1679年に【ジズヤ】を復活させ、ヒンドゥー教徒の反発をまねきました。デカン地方ではヒンドゥー勢力の【マラーター】が、北西部では【シク教徒】が抵抗し、アウラングゼーブの死後、帝国は急速に分裂へ向かいます。この衰退が、18世紀にイギリス・フランスがインドに勢力をのばす条件となりました。"]}, {"t": "東南アジア ― オランダの覇権と日本町", "p": ["17世紀初め、東南アジアの香辛料交易の主導権を握ったのはオランダでした。オランダ東インド会社はジャワ島の【バタヴィア】(現在のジャカルタ)を拠点とし、香辛料の産地であるモルッカ(マルク)諸島の支配を強めました。1623年の【アンボイナ事件】でイギリス商館員らを殺害し、イギリスの勢力を東南アジアの香辛料交易から締め出しました。イギリスはこれ以降、インドの経営に力を注ぐことになります。オランダはさらに、ポルトガルからマラッカを奪い(1641年)、台湾にも拠点をおき、アフリカ南端に【ケープ植民地】を建設してアジア航路の中継地としました。", "17世紀初めには、日本の朱印船貿易がさかんで、アユタヤやマニラ、ホイアンなどに【日本町】がつくられました。アユタヤの日本町では山田長政が活躍したことが知られています。しかし、江戸幕府が日本人の海外渡航を禁じると、日本町は衰えていきました。タイのアユタヤ朝は、オランダ・イギリス・フランスなどの商人も受け入れる国際交易都市として繁栄していました。"]}, {"t": "東アジア ― 明清交代と江戸幕府", "p": ["中国東北地方では、女真(のち満州人と称す)の【ヌルハチ】が諸部族を統一し、1616年に【後金】を建てました。ヌルハチは軍事・行政組織である【八旗】を整えました。その子【ホンタイジ】は内モンゴルを支配下に入れ、1636年に国号を【清】と改め、朝鮮も服属させました。一方、明は朝鮮出兵への援軍や北方防衛の費用で財政が悪化し、重税と飢饉に苦しむ農民の反乱が広がりました。1644年、反乱軍の指導者【李自成】が北京を攻略し、明は滅亡しました。このとき山海関で清を防いでいた明の武将【呉三桂】は清に降り、清軍を導いて李自成を破りました。こうして清は北京に入り、中国支配をはじめました。", "清は少数の満州人で多数の漢人を支配するため、科挙を続けて漢人の官僚を登用し、中央官庁の要職には満州人と漢人を同数おく【満漢併用制】をとる一方、満州人の髪形である【辮髪】を漢人の男性に強制し、反清的な言論は【文字の獄】で厳しく取りしまりました。南方では、明の遺臣や反清勢力の抵抗が続きました。【鄭成功】はオランダ人を追い出して台湾を拠点とし、清に抵抗しました。また、清の中国征服に協力した漢人の武将が南方で起こした【三藩の乱】(1673年〜)もおこりましたが、【康熙帝】はこれを鎮圧し、1683年には台湾を領有して中国全土の支配を固めました。", "北方では、シベリアを東に進んできたロシアと国境紛争がおこり、1689年に康熙帝とピョートル1世の間で【ネルチンスク条約】が結ばれ、アルグン川と外興安嶺(スタノヴォイ山脈)が国境と定められました。これは清がヨーロッパの国と対等な形式で結んだ条約として注目されます。", "日本では1603年に徳川家康が【江戸幕府】を開き、キリスト教の禁止と貿易統制を進めて、オランダ・中国との交易を長崎に限定するいわゆる鎖国体制をつくりました。ただし、朝鮮との交流は対馬を通じて、琉球とは薩摩を通じて、アイヌとは松前を通じて続いており、まったく国を閉ざしたわけではありません。朝鮮王朝は、清に二度侵攻されて服属したのち、明を正統とみなす意識を強め、みずからを中華文明の継承者とする考えをもつようになりました。"]}, {"t": "アメリカ・アフリカと世界のつながり ― 大西洋経済の形成", "p": ["北アメリカでは、17世紀にヨーロッパ諸国の本格的な植民がはじまりました。イギリスは1607年に【ヴァージニア】に最初の恒久的植民地ジェームズタウンを建設し、タバコ栽培で経営を軌道に乗せました。1620年には、国教会の圧迫をのがれたピューリタンの一団【ピルグリム=ファーザーズ】がメイフラワー号でプリマスに上陸し、ニューイングランド植民地の基礎を築きました。フランスは1608年にケベックを建設してカナダに進出し、オランダはハドソン川の河口にニューアムステルダムを建設しましたが、これは1664年にイギリスに奪われて【ニューヨーク】と改められました。", "カリブ海の島々では、イギリスやフランスがサトウキビのプランテーションを拡大し、アフリカから多数の黒人奴隷を運びこみました。ヨーロッパから武器や綿織物をアフリカに運び、アフリカから奴隷をアメリカに運び、アメリカから砂糖やタバコをヨーロッパに運ぶという【三角貿易】の構造がこの時期に形づくられます。ヨーロッパで砂糖やコーヒー、茶を楽しむ生活が広がる一方で、その裏では奴隷とされたアフリカの人々の苦しみがあったことを忘れてはなりません。", "アジアでは、オランダとイギリスの東インド会社が、香辛料に加えてインドの綿織物(キャラコ)や中国の茶・生糸、日本の銀や銅を取引しました。17世紀の世界は、ヨーロッパの勢力がアジア・アメリカ・アフリカを結ぶ交易網の中心を握りはじめた時代ですが、アジアではなお清・ムガル帝国・江戸幕府などの強力な国家が交易の条件を決めていました。両者の力関係がはっきり変わるのは、産業革命を経た19世紀のことです。"]}], "points": ["三十年戦争の性格の変化(宗教戦争→国家間戦争)と、ウェストファリア条約の内容(主権国家体制、オランダ・スイス独立承認)", "イギリス革命の順序:権利の請願(1628年)→ピューリタン革命→航海法(1651年)→王政復古(1660年)→名誉革命(1688年)→権利の章典(1689年)", "ルイ14世の絶対王政(コルベールの重商主義、ナントの王令の廃止1685年)", "アンボイナ事件(1623年)でイギリスがインド経営へ転じたこと", "明清交代:後金(1616年)→清(1636年)→明の滅亡(1644年、李自成)→呉三桂の降伏と清の北京入城", "康熙帝の三藩の乱鎮圧・台湾領有(1683年)・ネルチンスク条約(1689年)", "第2次ウィーン包囲失敗(1683年)とカルロヴィッツ条約(1699年)でハンガリー割譲", "アウラングゼーブのジズヤ復活とマラーター・シク教徒の抵抗"], "check": [["三十年戦争を終わらせた1648年の条約は?", "ウェストファリア条約"], ["1628年にイギリス議会がチャールズ1世に提出した文書は?", "権利の請願"], ["1651年にクロムウェルが制定し、英蘭戦争の原因となった法は?", "航海法"], ["名誉革命の翌年に制定され、議会の権利を確認した法は?", "権利の章典"], ["ルイ14世のもとで重商主義政策を進めた財務総監は?", "コルベール"], ["1623年にオランダがイギリス商館員を殺害した事件は?", "アンボイナ事件"], ["1616年に後金を建てた人物は?", "ヌルハチ"], ["1644年に北京を攻略して明を滅ぼした反乱指導者は?", "李自成"], ["1689年に清とロシアの国境を定めた条約は?", "ネルチンスク条約"], ["タージ=マハルを建てたムガル帝国の皇帝は?", "シャー=ジャハーン"]], "related": ["y_16", "y_18", "t_de", "t_uk", "t_fr", "t_nl", "t_ru", "t_tr", "t_in", "t_id", "t_cn", "t_us", "j_edo1"], "n": 4953}, "y_18": {"title": "18世紀の世界", "span": "1701〜1800年", "year": 1750, "lead": "18世紀は、イギリスとフランスが世界の各地で植民地をめぐって争い、その勝敗が世界の構造を変えた世紀です。勝ったイギリスでは産業革命がはじまり、戦費に苦しんだ英仏の両国からは、アメリカ独立革命とフランス革命という2つの市民革命が生まれました。アジアでは清が最大の版図を築いて繁栄を誇る一方、ムガル帝国は衰えてイギリスのインド支配がはじまりました。", "flow": ["1701〜13年 スペイン継承戦争→ユトレヒト条約でイギリスがジブラルタルや北米の領土を獲得", "1707年 イングランドとスコットランドが合同しグレートブリテン王国が成立", "1721年 ロシアが北方戦争に勝ちバルト海に進出。イギリスでウォルポールが首相となり責任内閣制が形成へ", "1740〜48年 オーストリア継承戦争→プロイセンがシュレジエンを獲得", "1756〜63年 七年戦争(北米ではフレンチ=インディアン戦争)。1757年プラッシーの戦い", "1757年 清が西洋船との交易を広州1港に限定", "1763年 パリ条約→イギリスが北米・インドでフランスに対して優位を確立", "1760年代〜 イギリスで産業革命がはじまる(綿工業の機械化、ワットの蒸気機関改良)", "1776年 アメリカ独立宣言→1783年パリ条約でアメリカ合衆国の独立承認", "1772〜95年 3回のポーランド分割→ポーランド国家の消滅", "1789年 フランス革命はじまる(バスティーユ牢獄襲撃・人権宣言)→1793年ルイ16世処刑", "1799年 ブリュメール18日のクーデタでナポレオンが実権を握る"], "sync": [["ヨーロッパ", "スペイン継承戦争とユトレヒト条約(1713年)。ウォルポールの責任内閣制。プロイセンのフリードリヒ2世とオーストリアのマリア=テレジア、七年戦争。ロシアのピョートル1世とエカチェリーナ2世、ポーランド分割。啓蒙思想。イギリス産業革命。フランス革命(1789年)"], ["西アジア・北アフリカ", "オスマン帝国の後退(キュチュク=カイナルジャ条約1774年でクリミアの宗主権を失う)。アラビア半島のワッハーブ運動。サファヴィー朝滅亡後のイランの混乱とガージャール朝の成立"], ["南アジア・東南アジア", "ムガル帝国の衰退と英仏の抗争(カーナティック戦争・プラッシーの戦い)、イギリスのベンガル支配。ビルマのコンバウン朝、タイのラタナコーシン朝(1782年)、ベトナムの西山の乱"], ["東アジア・内陸アジア", "清の康熙帝・雍正帝・乾隆帝の最盛期(軍機処、地丁銀制、ジュンガル征服と新疆)。広州1港限定(1757年)、マカートニーの来訪(1793年)。日本は享保・寛政の改革"], ["アメリカ・アフリカ", "フレンチ=インディアン戦争、アメリカ独立革命(1775〜83年)と合衆国憲法(1787年)。ハイチの黒人奴隷の反乱(1791年〜)。大西洋奴隷貿易が最盛期"], ["世界のつながり", "大西洋三角貿易の最盛期。英仏の第2次英仏百年戦争。啓蒙思想と革命思想の大西洋をこえた伝播。イギリス東インド会社による茶・綿織物の取引"]], "secs": [{"t": "英仏の世界戦争と2つの革命 ― 18世紀をどう見るか", "p": ["18世紀の国際政治の軸は、イギリスとフランスの対立です。両国はヨーロッパでの戦争に連動して、北アメリカやインドでも植民地をめぐって戦いました。スペイン継承戦争から七年戦争、さらにナポレオン戦争までのこの長い抗争を、【第2次英仏百年戦争】とよぶことがあります。", "この争いの結果を整理すると、18世紀の流れが見えてきます。第一に、イギリスは1763年の【パリ条約】で北米とインドでの優位を固め、その広大な市場と資源を背景に、世界で最初の【産業革命】を進めました。第二に、戦費で財政が苦しくなったイギリスは植民地への課税を強め、これが【アメリカ独立革命】をまねきました。第三に、フランスも戦争とアメリカ独立戦争への支援で財政が破綻し、その立て直しをめぐる対立から【フランス革命】がおこりました。つまり、英仏の世界戦争は、産業革命と市民革命という近代の2つの大変革(しばしば【二重革命】とよばれます)を生む原因となったのです。"]}, {"t": "ヨーロッパ ― 絶対王政から啓蒙と革命へ", "p": ["スペインのハプスブルク家が断絶すると、ルイ14世が孫をスペイン王に立てようとしたことから【スペイン継承戦争】(1701〜13年)がおこりました。1713年の【ユトレヒト条約】で、フランスとスペインは合同しないことを条件にブルボン家のスペイン王位継承が認められましたが、イギリスはスペインから【ジブラルタル】を、フランスから北米の【ニューファンドランド・アカディア・ハドソン湾地方】を得て、海外発展の足場を広げました。イギリスでは1707年にスコットランドと合同して【グレートブリテン王国】が成立し、ドイツからむかえた【ジョージ1世】のもとで、首相【ウォルポール】が議会の多数派にもとづいて政治をおこなう【責任内閣制】が形づくられました。「王は君臨すれども統治せず」という原則が生まれていきます。", "中・東ヨーロッパでは、【プロイセン】と【オーストリア】が争いました。プロイセンの【フリードリヒ2世(大王)】は、オーストリアでマリア=テレジアがハプスブルク家を継いだことに異議を唱えて【オーストリア継承戦争】(1740〜48年)をおこし、豊かな【シュレジエン】を奪いました。【マリア=テレジア】はシュレジエン奪回のため、長年の敵であったフランスと手を結び(【外交革命】)、【七年戦争】(1756〜63年)をおこしましたが、イギリスの支援を受けたプロイセンが持ちこたえ、シュレジエンを確保しました。フリードリヒ2世は「君主は国家第一の僕」と述べて、啓蒙思想の影響を受けた【啓蒙専制君主】として上からの改革を進めました。", "ロシアでは【ピョートル1世(大帝)】が西欧化を進め、スウェーデンとの【北方戦争】に勝ってバルト海に進出し、新都【ペテルブルク】を建設しました。18世紀後半の【エカチェリーナ2世】も啓蒙専制君主として知られますが、【プガチョフの農民反乱】を鎮圧したあとは農奴制を強めました。彼女はオスマン帝国から【クリミア半島】を奪って黒海に進出し、さらにプロイセン・オーストリアとともに3回にわたる【ポーランド分割】(1772・93・95年)をおこない、ポーランドは地図から消えました。コシューシコの抵抗も実りませんでした。", "思想の面では、理性によって社会の不合理を批判する【啓蒙思想】が広がりました。【モンテスキュー】は『法の精神』で三権分立を、【ルソー】は『社会契約論』で人民主権を説き、【ヴォルテール】は宗教的不寛容を批判し、ディドロらは『百科全書』を編纂しました。経済学では、【アダム=スミス】が『国富論』(1776年)で自由放任の経済を主張しました。これらの思想が、アメリカとフランスの革命を支える理念となりました。", "1789年、財政難に苦しむ【ルイ16世】は特権身分への課税を議論するため、長く開かれていなかった三部会を招集しました。しかし議決方法をめぐって対立がおこり、第三身分の代表は【国民議会】をつくって【球戯場(テニスコート)の誓い】を立てました。7月14日にパリの民衆が【バスティーユ牢獄】を襲撃すると、議会は【封建的特権の廃止】を決め、【人権宣言】を採択して、自由・平等、国民主権、私有財産の不可侵を宣言しました。国王一家の【ヴァレンヌ逃亡事件】で王への信頼が失われ、オーストリア・プロイセンとの戦争がはじまると、1792年に王政が廃止されて第一共和政が成立し、翌1793年にルイ16世は処刑されました。【ロベスピエール】ら【ジャコバン派】は、【公安委員会】を中心に反対派を弾圧する恐怖政治をおこないましたが、1794年の【テルミドールの反動】で倒されました。その後の【総裁政府】は不安定で、1799年に【ナポレオン】が【ブリュメール18日のクーデタ】で【統領政府】を立て、革命は新しい段階に入りました。"]}, {"t": "イギリスの産業革命 ― なぜイギリスで最初におこったか", "p": ["産業革命は、道具から機械へ、手工業から工場制機械工業への生産のしかたの大変革です。イギリスで最初におこった理由として、次の条件がよくあげられます。第一に、海外植民地とアジア・アメリカとの貿易で資本が蓄積され、また広い市場をもっていたこと。第二に、【第2次囲い込み】と【ノーフォーク農法】などの【農業革命】で食料生産が増える一方、土地を失った農民が都市の労働力となったこと。第三に、石炭や鉄鉱石の資源にめぐまれていたこと。第四に、名誉革命以後の政治の安定と、自然科学・技術を重んじる風土があったことです。", "変革は、インドから輸入されて人気を集めた綿織物を国内で安く大量に生産するための、【綿工業】の機械化からはじまりました。【ジョン=ケイ】の飛び杼、【ハーグリーヴズ】のジェニー紡績機、【アークライト】の水力紡績機、【クロンプトン】のミュール紡績機、【カートライト】の力織機などが次々に発明されました。【ワット】が改良した蒸気機関が動力として使われるようになると、工場は川の近くでなくても建てられるようになり、マンチェスターなどの工業都市が成長しました。こうしてイギリスは、19世紀に「世界の工場」とよばれる地位に向かっていきます。一方で、インドの手織りの綿布産業は、のちにイギリスの機械製綿布に押されて打撃を受けることになり、産業革命は世界の分業の構造をも変えていきました。"]}, {"t": "アメリカ ― 独立革命と新しい共和国", "p": ["北米東岸には、18世紀前半までにイギリスの【13植民地】が形成され、植民地議会による自治が進んでいました。七年戦争と並行しておこなわれた【フレンチ=インディアン戦争】でイギリスがフランスに勝つと、フランスの脅威はなくなりましたが、イギリスは戦費を補うため植民地への課税を強めました。1765年の【印紙法】に対し、植民地側は「【代表なくして課税なし】」と主張して反対し、1773年には茶の販売をめぐって【ボストン茶会事件】がおこりました。", "1775年、【レキシントン・コンコードの戦い】で独立戦争がはじまりました。トマス=ペインの『【コモン=センス】』が独立の世論を高め、1776年7月4日、【トマス=ジェファソン】らが起草した【アメリカ独立宣言】が発表されました。ここでは、ロックの思想をもとに、人間の平等、生命・自由・幸福追求の権利、圧政に対する革命の権利がうたわれました。植民地軍は総司令官【ワシントン】のもとで戦い、【サラトガの戦い】の勝利をきっかけにフランスやスペインが植民地側で参戦し、ロシアの提唱による【武装中立同盟】もイギリスを孤立させました。1781年の【ヨークタウンの戦い】で勝敗が決し、1783年の【パリ条約】でアメリカ合衆国の独立が承認され、ミシシッピ川以東の地も得ました。", "1787年に制定された【アメリカ合衆国憲法】は、人民主権、連邦主義、三権分立を原則とし、初代大統領にはワシントンが選ばれました。ただし、黒人奴隷制は維持され、先住民の権利も認められていなかったことには注意が必要です。アメリカ独立革命はフランス革命に影響を与え、さらにカリブ海のフランス領サン=ドマング(のちのハイチ)では、1791年に【トゥサン=ルヴェルチュール】らの指導する黒人奴隷の反乱がおこり、19世紀初めの独立につながりました。"]}, {"t": "西アジア・南アジア ― イスラーム大国の後退とイギリスのインド支配", "p": ["オスマン帝国は18世紀に入ると、ロシアとオーストリアの圧迫を受けて後退を続けました。1774年の【キュチュク=カイナルジャ条約】では、ロシアに黒海北岸の領土と黒海での商船の航行権を認め、クリミア=ハン国への宗主権を失い、その後ロシアはクリミア半島を併合しました。ロシアの【南下政策】がここに本格化し、19世紀の「東方問題」の出発点となります。アラビア半島では、預言者の時代の純粋なイスラームへの回帰を説く【ワッハーブ運動】がおこり、豪族【サウード家】と結んでワッハーブ王国を建てました。これはのちのサウジアラビアにつながります。イランでは、1736年にサファヴィー朝が滅んだあと混乱が続き、18世紀末にトルコ系の【ガージャール朝】が成立しました。", "インドでは、アウラングゼーブの死後ムガル帝国が衰え、各地の地方勢力が自立しました。この混乱に乗じて、イギリス東インド会社(拠点はマドラス・ボンベイ・カルカッタ)とフランス東インド会社(拠点はポンディシェリなど)が勢力を争い、南インドで【カーナティック戦争】をくり広げました。1757年の【プラッシーの戦い】で、イギリス東インド会社の【クライヴ】がフランスと結んだベンガル太守の軍を破り、イギリスの優位が決まりました。1765年に東インド会社はベンガルなどの徴税権(ディーワーニー)を獲得し、商業会社から領土を支配する統治機関へと性格を変えていきます。その後も南インドの【マイソール戦争】やデカン高原の【マラーター戦争】を通じて、イギリスは支配地域を広げました。"]}, {"t": "東南アジア・東アジア ― 清の最盛期と繁栄の影", "p": ["中国では、【康熙帝・雍正帝・乾隆帝】の3代、約130年にわたって清の最盛期が続きました。雍正帝は皇帝直属の政策決定機関として【軍機処】を設け、人頭税を土地税に組みこんで一本化する【地丁銀制】を全国に広げました。乾隆帝は【ジュンガル】を滅ぼして東トルキスタンを征服し、この地を【新疆】と名づけました。モンゴル・チベット・新疆は【藩部】として【理藩院】が管轄し、現地の支配者や宗教指導者を通じた間接的な統治がおこなわれました。清の版図は史上最大となり、現在の中国の領域の原型がつくられました。", "経済の面では、人口が急増したとされ、アメリカ大陸原産のトウモロコシやサツマイモが山地の開墾を支えました。ヨーロッパでは中国の茶・生糸・陶磁器の人気が高く、ロココ様式の流行のなかで中国趣味(シノワズリ)も広がりました。清は1757年に西洋船との交易を【広州】1港に限定し、特許商人の組合である【公行】に取引を独占させました。この制限に不満をもったイギリスは1793年に【マカートニー】を派遣して自由な貿易を求めましたが、乾隆帝はこれを拒否しました。イギリスは茶の輸入で大量の銀を支払う貿易赤字を抱えることになり、これが19世紀のアヘン密輸とアヘン戦争の伏線となります。また、学問では考証学が発達し、乾隆帝のもとで大叢書『【四庫全書】』が編纂されました。中国の典礼を認めるかをめぐる【典礼問題】から、雍正帝はキリスト教の布教を禁止しました。", "東南アジアでは、ビルマに【コンバウン朝】が成立し、1767年にタイのアユタヤ朝を滅ぼしました。タイではその後、1782年に【ラタナコーシン朝(チャクリ朝)】が成立し、バンコクを都としました。ベトナムでは【西山(タイソン)の乱】がおこり、黎朝などを倒しましたが、まもなくフランス人宣教師の支援を受けた阮福暎が統一を進めます(1802年阮朝)。日本では江戸幕府のもとで【享保の改革】や【寛政の改革】がおこなわれ、ロシアの【ラクスマン】が根室に来航するなど、北方から欧米の接近がはじまっていました。"]}], "points": ["ユトレヒト条約(1713年)でイギリスが得た地域(ジブラルタル、ニューファンドランド・アカディア・ハドソン湾地方)", "オーストリア継承戦争と七年戦争の関係(シュレジエン、外交革命)と、北米のフレンチ=インディアン戦争・インドのプラッシーの戦いとの連動", "パリ条約(1763年)と、それが産業革命・アメリカ独立革命・フランス革命につながる因果関係", "産業革命の条件(資本・労働力・資源・市場)と綿工業の発明の順序", "アメリカ独立の流れ:印紙法→ボストン茶会事件→独立宣言(1776年)→ヨークタウン→パリ条約(1783年)→合衆国憲法(1787年)", "フランス革命の流れ:三部会→国民議会→バスティーユ→人権宣言→第一共和政→ルイ16世処刑→テルミドールの反動→総裁政府→ブリュメール18日", "清の雍正帝(軍機処・地丁銀制)と乾隆帝(新疆・広州1港限定・マカートニー拒否)", "キュチュク=カイナルジャ条約(1774年)とロシアの南下、ワッハーブ運動"], "check": [["1713年に結ばれ、スペイン継承戦争を終わらせた条約は?", "ユトレヒト条約"], ["イギリスで責任内閣制の形成に貢献した首相は?", "ウォルポール"], ["オーストリアが七年戦争の前にフランスと結んだ同盟の転換をなんとよぶか?", "外交革命"], ["1757年、イギリス東インド会社がベンガル太守とフランスの軍を破った戦いは?", "プラッシーの戦い"], ["ワットが改良した動力機関は?", "蒸気機関"], ["アメリカ独立宣言の起草の中心となった人物は?", "トマス=ジェファソン"], ["1789年にフランス国民議会が採択した、自由・平等や国民主権を宣言した文書は?", "人権宣言"], ["清の雍正帝が設けた皇帝直属の政策決定機関は?", "軍機処"], ["1793年に清に自由貿易を求めて派遣されたイギリスの使節は?", "マカートニー"], ["1774年にオスマン帝国がロシアと結び、クリミアの宗主権を失った条約は?", "キュチュク=カイナルジャ条約"]], "related": ["y_17", "y_19", "t_uk", "t_fr", "t_de", "t_ru", "t_pl", "t_us", "t_in", "t_cn", "t_tr", "t_th", "j_edo2", "j_edo3"], "n": 4829}, "y_19": {"title": "19世紀の世界", "span": "1801〜1900年", "year": 1850, "lead": "19世紀は、産業革命を成しとげた欧米諸国が圧倒的な力をもち、世界の大部分を自分たちの経済と政治の仕組みに組みこんでいった世紀です。ヨーロッパでは自由主義とナショナリズムが広がって国民国家がつくられ、アジア・アフリカではその圧力に対して改革や抵抗がくり返されました。世紀の末には、列強が植民地を奪い合う帝国主義の時代に入ります。", "flow": ["1804年 ナポレオンが皇帝に即位。同年ハイチが独立→1810〜20年代にラテンアメリカ諸国が独立", "1814〜15年 ウィーン会議→正統主義にもとづくウィーン体制", "1830年 フランスで七月革命。1832年イギリスで第1回選挙法改正", "1840〜42年 アヘン戦争→南京条約で清が開港", "1848年 フランス二月革命・ドイツやオーストリアの三月革命(諸国民の春)→ウィーン体制崩壊", "1851〜64年 太平天国。1853〜56年クリミア戦争", "1857年 インド大反乱→1858年ムガル帝国滅亡、イギリスの直接統治へ", "1861年 イタリア王国成立、ロシアの農奴解放令。1861〜65年アメリカ南北戦争", "1868年 日本で明治維新。1869年スエズ運河開通、アメリカ大陸横断鉄道開通", "1871年 ドイツ帝国成立→ビスマルク外交", "1878年 ベルリン会議→ロシアの南下を阻止。1884〜85年ベルリン会議(ベルリン=コンゴ会議)→アフリカ分割が加速", "1894〜95年 日清戦争。1898年米西戦争・ファショダ事件、清で戊戌の政変"], "sync": [["ヨーロッパ", "ナポレオン帝国とウィーン体制。七月革命・二月革命・三月革命。イギリスのヴィクトリア時代(選挙法改正、自由貿易)。クリミア戦争、イタリア・ドイツの統一、ロシアの農奴解放令。ビスマルク体制と第2次産業革命、社会主義の発展"], ["西アジア・北アフリカ", "エジプトのムハンマド=アリーの自立。オスマン帝国のタンジマート(1839年〜)とミドハト憲法(1876年)、ロシア=トルコ戦争。スエズ運河開通とウラービー運動(イギリスのエジプト占領)。イランのタバコ=ボイコット運動"], ["南アジア・東南アジア", "インド大反乱(1857年)とインド帝国(1877年)、インド国民会議(1885年)。オランダの強制栽培制度、イギリスの海峡植民地・ビルマ併合、フランス領インドシナ、タイの独立維持(ラーマ5世)、フィリピン革命"], ["東アジア・内陸アジア", "アヘン戦争・アロー戦争と不平等条約、太平天国と洋務運動。日本の開国と明治維新。日清戦争(1894〜95年)、列強の中国分割と変法運動。ロシアのシベリア・中央アジア進出"], ["アメリカ・アフリカ", "ラテンアメリカ諸国の独立(ボリバル、サン=マルティン)とモンロー教書。アメリカ合衆国の西部開拓と南北戦争、大陸横断鉄道。アフリカ探検とアフリカ分割、南アフリカ戦争(1899年〜)"], ["世界のつながり", "蒸気船・鉄道・電信による交通と通信の革命。移民の大量移動(ヨーロッパ→アメリカ、中国・インド→各地)。国際赤十字・万国郵便連合など国際組織、近代オリンピック"]], "secs": [{"t": "欧米の時代 ― 19世紀をどう見るか", "p": ["19世紀の世界を動かしたのは、18世紀末にはじまった2つの変革、すなわち【産業革命】と【市民革命】の広がりでした。産業革命は、蒸気機関と工場、鉄道と蒸気船によって、欧米の生産力と軍事力を他の地域と比べて飛躍的に高めました。市民革命は、身分制にかわって、法の前の平等や議会政治を重んじる【自由主義】と、同じ言語や歴史をもつ「国民」が一つの国家をつくるべきだとする【ナショナリズム(国民主義)】を広めました。", "ヨーロッパでは、この2つの思想が古い君主政と衝突しながら、19世紀を通じて【国民国家】がつくられていきます。一方、アジア・アフリカの多くの地域は、工業製品の市場や原料の供給地として欧米の経済に組みこまれ、不平等条約や植民地支配のもとにおかれました。それに対して、オスマン帝国のタンジマート、清の洋務運動、日本の明治維新、タイの改革など、欧米に対抗するために近代化を進める動きがおこりました。19世紀の後半には、列強が競って植民地を広げる【帝国主義】の時代に入り、20世紀の世界大戦への道が準備されていきます。"]}, {"t": "ヨーロッパ(1) ― ナポレオンからウィーン体制の崩壊まで", "p": ["【ナポレオン】は1804年に【ナポレオン法典(フランス民法典)】を公布して、法の前の平等や私有財産の不可侵など革命の成果を法律に定め、同年に皇帝に即位しました。1805年の【トラファルガーの海戦】ではイギリスに敗れましたが、同年の【アウステルリッツの戦い(三帝会戦)】でオーストリア・ロシアを破り、翌1806年に【ライン同盟】を結成させて【神聖ローマ帝国】を消滅させました。さらに【大陸封鎖令】でイギリスと大陸諸国との通商を禁じましたが、これはかえって大陸諸国の経済を苦しめました。ナポレオンの支配は征服地に革命の理念を広める一方で、各地の人々の民族意識を目覚めさせ、スペインの反乱やプロイセンの改革をまねきました。1812年の【ロシア遠征】の失敗をきっかけに、1813年の【ライプツィヒの戦い(諸国民戦争)】で敗れ、エルバ島に流されます。", "戦後処理のため、1814〜15年に【ウィーン会議】が開かれました。オーストリアの外相【メッテルニヒ】が主導し、フランス革命前の王朝と国境を正統とする【正統主義】が原則とされました。「会議は踊る、されど進まず」と評されるなか、ナポレオンがエルバ島を脱出しましたが、1815年の【ワーテルローの戦い】で敗れて【セントヘレナ島】に流されます。こうして成立した【ウィーン体制】は、【神聖同盟】や【四国同盟】によって自由主義とナショナリズムの運動をおさえこもうとしました。", "しかし、運動はおさまりませんでした。ドイツの学生組合【ブルシェンシャフト】、イタリアの【カルボナリ】、ロシアの【デカブリストの乱】はいずれも鎮圧されましたが、【ギリシア独立戦争】ではイギリス・フランス・ロシアがギリシアを支援して独立を実現させ、ラテンアメリカ諸国の独立もイギリスやアメリカの立場によって守られました。1830年、フランスで【七月革命】がおこってシャルル10世が倒れ、【ルイ=フィリップ】の七月王政が成立すると、その影響で【ベルギー】が独立しました。1848年には、フランスで【二月革命】がおこって第二共和政が成立し、その波がドイツ・オーストリアの【三月革命】に広がり、メッテルニヒは失脚しました。各地で民族の自立を求める運動がおこったこの年は「【諸国民の春】」とよばれ、ウィーン体制は崩壊しました。同じ年にマルクスとエンゲルスは『【共産党宣言】』を発表しています。"]}, {"t": "ヨーロッパ(2) ― 国民国家の形成と帝国主義", "p": ["イギリスは、19世紀半ばに「世界の工場」として繁栄の頂点を迎えました。1832年の【第1回選挙法改正】で産業資本家などの都市の中産階級が選挙権を得、労働者は選挙権を求めて【チャーティスト運動】をおこしました。1846年に【穀物法】が廃止され、1849年に【航海法】が廃止されると、イギリスは【自由貿易】体制に転換しました。【ヴィクトリア女王】の時代には、保守党の【ディズレーリ】と自由党の【グラッドストン】が交互に政権を担当する二大政党制が定着し、1851年にはロンドンで第1回万国博覧会が開かれました。", "フランスでは、二月革命後に大統領となった【ルイ=ナポレオン】が1852年に皇帝【ナポレオン3世】となり、積極的な対外政策をとりましたが、1870年の【プロイセン=フランス(普仏)戦争】で捕虜となって第二帝政は崩壊しました。1871年の【パリ=コミューン】の鎮圧を経て、【第三共和政】が定着します。", "イタリアでは、【サルデーニャ王国】の首相【カヴール】が、フランスの支援を得てオーストリアと戦い北イタリアを獲得し、【ガリバルディ】が両シチリア王国を征服してサルデーニャ王にゆずりました。こうして1861年に【イタリア王国】が成立しました。ドイツでは、プロイセン首相【ビスマルク】が「鉄と血」によって統一を進める【鉄血政策】をとり、デンマーク戦争、【プロイセン=オーストリア(普墺)戦争】、普仏戦争に勝利して、1871年にヴェルサイユ宮殿で【ドイツ帝国】の成立を宣言しました。フランスは【アルザス・ロレーヌ】を失い、ドイツへの復讐心を強めます。ビスマルクは、フランスを孤立させる同盟網(三帝同盟・三国同盟など)をつくり、ヨーロッパの勢力均衡を保とうとしました。", "ロシアは南下政策を進め、オスマン帝国と【クリミア戦争】(1853〜56年)を戦いましたが、イギリス・フランスの介入で敗れました。敗北で後進性を思い知らされた皇帝【アレクサンドル2世】は、1861年に【農奴解放令】を出して近代化に着手しました。1877年の【ロシア=トルコ(露土)戦争】に勝って【サン=ステファノ条約】でブルガリアを保護下におきましたが、これに反対するイギリス・オーストリアの意向を受けて、ビスマルクが【ベルリン会議】(1878年)を開き、ロシアの南下は再び阻まれました。", "19世紀後半には、電気や石油を動力とし、化学・鉄鋼などの重化学工業を中心とする【第2次産業革命】が進み、ドイツとアメリカがイギリスに追いつきました。巨大企業と銀行が結びついた資本は、原料と市場、投資先を海外に求め、列強は競って植民地を広げる【帝国主義】政策をとるようになりました。一方、労働者の生活改善を求める【社会主義】運動も広がり、【第2インターナショナル】が結成されました。"]}, {"t": "西アジア・南アジア ― 改革と抵抗", "p": ["オスマン帝国では、エジプト総督【ムハンマド=アリー】が近代化を進めて事実上自立し、2度にわたって帝国と戦いました。危機感を強めた帝国は、1839年から【タンジマート】とよばれる西欧化改革をはじめ、法の前でのムスリムと非ムスリムの平等などを打ち出しました。1876年には大宰相【ミドハト=パシャ】のもとでアジア初の憲法とされる【ミドハト憲法】が制定されましたが、翌年のロシア=トルコ戦争を口実にスルタン【アブデュルハミト2世】が憲法を停止し、専制政治にもどりました。エジプトでは、フランス人【レセップス】が建設した【スエズ運河】が1869年に開通しましたが、財政難からエジプトは運河会社の株をイギリスに売却し、外国の財政管理を受けました。これに反発した【ウラービー運動】(1881〜82年)はイギリス軍に鎮圧され、エジプトは事実上イギリスの保護下に入りました。イランのガージャール朝では、イギリス人へのタバコ利権の譲渡に反対する【タバコ=ボイコット運動】(1891年)がおこり、利権を撤回させました。", "インドでは、イギリス東インド会社がシク王国などを征服して支配を全土に広げました。イギリスの機械製綿布の流入でインドの綿織物業は打撃を受け、インドは綿花などの原料を輸出する地域に変えられていきました。1857年、東インド会社のインド人傭兵【シパーヒー】の反乱をきっかけに、北インドの広い地域で【インド大反乱】がおこりました。イギリスはこれを鎮圧して1858年にムガル皇帝を廃し、東インド会社を解散してインドを直接統治下におき、1877年には【ヴィクトリア女王】を皇帝とする【インド帝国】を成立させました。1885年には、イギリスの協力を得てインド人の知識人層による【インド国民会議】が開かれ、やがて民族運動の中心となっていきます。"]}, {"t": "東南アジア・東アジア ― 不平等条約と近代化の試み", "p": ["東南アジアでは、19世紀にタイ以外のほぼ全域が植民地とされました。イギリスはシンガポールなどを【海峡植民地】とし、3度の戦争で【ビルマ】を併合してインド帝国に組みこみました。オランダはジャワで、コーヒーやサトウキビなどの作物を農民に強制的に栽培させる【強制栽培制度】を実施しました。フランスは阮朝のベトナムに進出し、清仏戦争で清の宗主権を否定させて、1887年に【フランス領インドシナ連邦】を成立させました。スペイン領フィリピンでは、【ホセ=リサール】の言論活動を経て1896年に【フィリピン革命】がはじまりましたが、米西戦争後はアメリカの支配下に入りました。タイの【ラーマ5世(チュラロンコン)】は、近代化改革を進め、イギリス領とフランス領の緩衝地帯という位置もいかして独立を保ちました。", "中国では、イギリスが茶の代金として流出する銀を取りもどすため、インド産の【アヘン】を清に密輸する【三角貿易】をおこないました。清の【林則徐】がアヘンを没収すると、イギリスは【アヘン戦争】(1840〜42年)をおこし、1842年の【南京条約】で香港島の割譲と上海などの5港の開港、公行の廃止を認めさせました。続く【アロー戦争】(1856〜60年)の結果、【北京条約】で天津の開港やキリスト教布教の自由が認められ、ロシアは沿海州を獲得しました。国内では、洪秀全の率いる【太平天国】(1851〜64年)が「滅満興漢」をかかげて南京を占領しましたが、漢人官僚の【曽国藩】・【李鴻章】らの郷勇と外国の軍隊によって鎮圧されました。その後、彼らは西洋の技術を取り入れる【洋務運動】を進めましたが、「中体西用」にとどまり、政治体制の改革には踏みこみませんでした。", "日本は、1853年のペリー来航を経て開国し、1868年の【明治維新】で近代国家の建設をはじめました。日本は朝鮮に開国を迫り、朝鮮をめぐって清と対立して、1894年の【甲午農民戦争】をきっかけに【日清戦争】がおこりました。敗れた清は1895年の【下関条約】で朝鮮の独立を認め、台湾などを日本に割譲しました。清の弱体ぶりが明らかになると、列強は租借地や鉄道敷設権を求めて中国分割を進めました。危機感を強めた【康有為】らは、日本の明治維新にならって立憲君主政をめざす【変法運動】を進めましたが、1898年の【戊戌の政変】で西太后らの保守派に弾圧されました。アメリカは中国分割に出遅れたため、【門戸開放宣言】を出して機会均等を求めました。"]}, {"t": "アメリカ・アフリカと世界のつながり", "p": ["ラテンアメリカでは、フランス革命とナポレオンの影響を受けて、19世紀初めに独立運動が広がりました。1804年にはハイチが世界初の黒人共和国として独立し、本国生まれの白人に不満をもつ植民地生まれの白人【クリオーリョ】が中心となって、【シモン=ボリバル】が南米北部を、【サン=マルティン】が南部を解放しました。ブラジルはポルトガルの王子を皇帝として独立しました。アメリカ合衆国は1823年に【モンロー教書(宣言)】を出し、ヨーロッパとアメリカ大陸の相互不干渉を主張しました。ただし、独立後も大土地所有制とヨーロッパへの原料輸出に頼る経済構造が残りました。", "アメリカ合衆国は、【ルイジアナ】を購入し、メキシコとの戦争でカリフォルニアを得るなど、「【明白な天命(マニフェスト=デスティニー)】」をとなえて西へ領土を広げましたが、その過程で先住民は強制移住させられました。新しく加わる州で奴隷制を認めるかをめぐって北部と南部が対立し、奴隷制拡大に反対する共和党の【リンカン】が大統領に当選すると、南部諸州は【アメリカ連合国】をつくって分離し、【南北戦争】(1861〜65年)がおこりました。リンカンは1863年に【奴隷解放宣言】を出し、北部が勝利して国家の統一が保たれました。1869年の【大陸横断鉄道】の開通後、アメリカは急速に工業化を進め、19世紀末には世界一の工業国となります。1890年ごろに【フロンティア】の消滅が宣言されると、1898年の【アメリカ=スペイン(米西)戦争】でフィリピン・グアム・プエルトリコを獲得し、同年ハワイを併合して、海外へ進出しました。", "アフリカでは、【リヴィングストン】や【スタンリー】の探検によって内陸の事情が知られるようになると、列強は植民地化を急ぎました。1884〜85年の【ベルリン会議(ベルリン=コンゴ会議)】で、先に実効支配した国が領有できるという原則が決まり、20世紀初めまでにエチオピアとリベリアを除くほぼ全土が分割されました。イギリスはカイロとケープタウンを結ぶ【アフリカ縦断政策】を進め、ケープ植民地首相【セシル=ローズ】が活躍しました。これがフランスの【アフリカ横断政策】と衝突したのが1898年の【ファショダ事件】で、フランスが譲歩して決着しました。南部では、イギリスがオランダ系移民の子孫(ブール人)の国を征服するため【南アフリカ戦争】(1899〜1902年)をおこしました。", "19世紀は、蒸気船・鉄道・【電信】によって世界の距離が一気に縮まった時代でもありました。ヨーロッパからアメリカへは数千万人規模の移民が渡り、中国やインドからも多くの労働者(苦力など)が東南アジアやアメリカに移動しました。国際的な協力の仕組みとして【国際赤十字】や万国郵便連合がつくられ、1896年にはアテネで第1回【近代オリンピック】が開かれました。世界が一つにつながる度合いは、それまでとは比べものにならないほど強まったのです。"]}], "points": ["ウィーン体制の原則(正統主義)と、その崩壊(1830年七月革命→1848年二月革命・三月革命)", "イタリア統一(カヴール・ガリバルディ・1861年)とドイツ統一(ビスマルク・普墺戦争・普仏戦争・1871年)", "クリミア戦争の敗北→農奴解放令(1861年)、露土戦争→サン=ステファノ条約→ベルリン会議(1878年)", "アヘン戦争と南京条約(1842年)、アロー戦争と北京条約(1860年)の内容の区別", "太平天国→洋務運動(中体西用)→日清戦争→変法運動・戊戌の政変の流れ", "インド大反乱(1857年)→ムガル帝国滅亡・東インド会社解散→インド帝国(1877年)→インド国民会議(1885年)", "タンジマート(1839年)、ミドハト憲法(1876年)、ウラービー運動とイギリスのエジプト占領", "アフリカ分割:ベルリン会議(1884〜85年)、縦断政策と横断政策の衝突=ファショダ事件(1898年)"], "check": [["ウィーン会議を主導したオーストリアの外相は?", "メッテルニヒ"], ["1848年のヨーロッパ各地での革命と民族運動の高まりをなんとよぶか?", "諸国民の春"], ["1861年に農奴解放令を出したロシア皇帝は?", "アレクサンドル2世"], ["1842年、アヘン戦争の講和として結ばれた条約は?", "南京条約"], ["洪秀全が指導し、南京を都とした反乱勢力は?", "太平天国"], ["1839年にオスマン帝国ではじまった西欧化改革は?", "タンジマート"], ["1857年にインドでおこった大規模な反乱は?", "インド大反乱(シパーヒーの反乱)"], ["独立を維持したタイで近代化を進めた国王は?", "ラーマ5世(チュラロンコン)"], ["1863年に奴隷解放宣言を出したアメリカ大統領は?", "リンカン"], ["1898年にアフリカでイギリスとフランスが衝突した事件は?", "ファショダ事件"]], "related": ["y_18", "y_20a", "t_fr", "t_uk", "t_de", "t_it", "t_ru", "t_tr", "t_ar", "t_in", "t_th", "t_vn", "t_cn", "t_us", "t_la", "t_af", "j_bakumatsu", "j_meiji1", "j_meiji2"], "n": 5632}, "y_20a": {"title": "20世紀前半の世界(1900〜1945年)", "span": "1900〜1945年", "year": 1920, "lead": "20世紀前半は、帝国主義列強の対立が2度の世界大戦となって爆発した時代です。第一次世界大戦はロシア革命とアメリカの台頭、アジア・アフリカの民族運動をうながし、戦後の国際協調は世界恐慌で崩れました。ファシズム諸国の侵略から第二次世界大戦へと進み、その終わりには国際連合と米ソ2大国を中心とする新しい世界の枠組みが生まれました。", "flow": ["1900年 清で義和団事件→8か国連合軍が出兵", "1904〜05年 日露戦争→1905年ロシア第1次革命。1907年英露協商で三国協商が成立", "1911年 辛亥革命→1912年中華民国成立、清の滅亡", "1914年 サライェヴォ事件→第一次世界大戦(〜1918年)", "1917年 ロシア革命(二月革命・十月革命)、アメリカの参戦", "1919年 パリ講和会議・ヴェルサイユ条約。朝鮮で三・一独立運動、中国で五・四運動", "1920年 国際連盟発足。1921〜22年ワシントン会議", "1922年 イタリアでムッソリーニがローマ進軍、ソ連成立。1923年トルコ共和国成立", "1929年 世界恐慌→ニューディールとブロック経済、ファシズムの台頭", "1931年 満州事変。1933年ヒトラーが首相となりナチス独裁へ。1937年日中戦争", "1939年 ドイツがポーランドに侵攻→第二次世界大戦。1941年独ソ戦・太平洋戦争", "1945年 ドイツ・日本が降伏し大戦終結、国際連合の成立"], "sync": [["ヨーロッパ", "三国同盟と三国協商の対立、第一次世界大戦(1914〜18年)とヴェルサイユ体制。ロシア革命とソ連成立。ヴァイマル共和国、ロカルノ条約。世界恐慌後のナチス=ドイツとファシズム、スペイン内戦、第二次世界大戦"], ["西アジア・北アフリカ", "オスマン帝国の敗戦と解体、フセイン・マクマホン協定・サイクス・ピコ協定・バルフォア宣言。トルコ共和国(1923年、ムスタファ=ケマル)。エジプト王国、イランのパフレヴィー朝、サウジアラビア王国。パレスチナ問題のはじまり"], ["南アジア・東南アジア", "インドのガンディーによる非暴力・不服従運動、プールナ=スワラージ、塩の行進。ベトナム・インドネシアの民族運動(ホー=チ=ミン、スカルノ)、タイの立憲革命(1932年)。日本の東南アジア占領"], ["東アジア・内陸アジア", "日露戦争と韓国併合(1910年)、辛亥革命と中華民国。二十一か条要求、五・四運動、国共合作と北伐、満州事変・日中戦争。モンゴル人民共和国の成立"], ["アメリカ・アフリカ", "アメリカの台頭(パナマ運河、第一次世界大戦参戦)、1920年代の繁栄と世界恐慌、ニューディールと善隣外交。メキシコ革命(1910年〜)。アフリカのほぼ全域が植民地支配下、エチオピアのイタリアによる併合"], ["世界のつながり", "総力戦と大量殺戮。国際連盟・不戦条約と国際協調の試み。世界恐慌の世界的広がり。大西洋憲章から国際連合へ"]], "secs": [{"t": "世界戦争の時代 ― 20世紀前半をどう見るか", "p": ["19世紀末から、列強は植民地と勢力圏を求めて激しく争うようになりました。工業化が進んだドイツは、先に植民地を得ていたイギリス・フランスに対抗して「世界政策」をとり、ヨーロッパは【三国同盟】(ドイツ・オーストリア・イタリア)と【三国協商】(イギリス・フランス・ロシア)の2つの陣営に分かれました。この対立が、1914年の【第一次世界大戦】として爆発します。", "2度の世界大戦は、国民の全体と経済のすべてを戦争につぎこむ【総力戦】となり、それまでにない規模の犠牲を生みました。その一方で、大戦は世界の構造を大きく変えました。第一に、ヨーロッパの地位が下がり、【アメリカ合衆国】と【ソ連】が大きな力をもつようになりました。第二に、アジア・アフリカの民族運動が高まり、植民地支配がゆらぎはじめました。第三に、戦争を防ぐための国際機構として【国際連盟】、ついで【国際連合】がつくられました。この3つの変化に注目すると、20世紀前半の流れが整理しやすくなります。"]}, {"t": "ヨーロッパ ― 2つの大戦とその間", "p": ["バルカン半島は、オスマン帝国の衰退後、スラヴ民族の統一をめざすロシアの【パン=スラヴ主義】と、ドイツ・オーストリアの【パン=ゲルマン主義】がぶつかり合い、「ヨーロッパの火薬庫」とよばれていました。1908年にオーストリアが【ボスニア・ヘルツェゴヴィナ】を併合するとセルビアは強く反発し、1914年6月、オーストリアの帝位継承者【フランツ=フェルディナント】夫妻がセルビア人青年に暗殺される【サライェヴォ事件】がおこりました。オーストリアがセルビアに宣戦すると、同盟関係を通じて列強が次々と参戦し、【第一次世界大戦】となりました。ドイツは【シュリーフェン=プラン】にもとづいてフランスを短期で倒そうとしましたが、【マルヌの戦い】で阻まれ、西部戦線は塹壕戦となって長期化しました。戦車・飛行機・毒ガスなどの新兵器が使われ、【ヴェルダン要塞攻防戦】などで膨大な死者が出ました。ドイツの【無制限潜水艦作戦】をきっかけに1917年にアメリカが参戦し、1918年にドイツで【キール軍港の水兵反乱】から革命がおこって皇帝が退位し、休戦が成立しました。", "1917年、戦争で疲弊したロシアでは【二月革命(三月革命)】で皇帝【ニコライ2世】が退位し、ついで【レーニン】の率いるボリシェヴィキが【十月革命(十一月革命)】で権力を握りました。ソヴィエト政権は「【平和に関する布告】」を出し、1918年に【ブレスト=リトフスク条約】でドイツと単独講和を結びました。列強の【対ソ干渉戦争】や内戦を乗りこえ、1922年に【ソヴィエト社会主義共和国連邦(ソ連)】が成立しました。レーニンの死後、権力を握った【スターリン】は【五か年計画】で重工業化と【農業の集団化】を強行し、反対派を大量に粛清しました。", "1919年の【パリ講和会議】では、アメリカ大統領【ウィルソン】の【十四か条】が原則とされましたが、ドイツに対する【ヴェルサイユ条約】は、全植民地の放棄、アルザス・ロレーヌの返還、軍備制限、巨額の賠償金など厳しいものとなりました。東欧では【民族自決】の原則でポーランドなどが独立しましたが、アジア・アフリカには適用されませんでした。1920年には【国際連盟】が発足しましたが、アメリカは上院の反対で加盟しませんでした。ドイツでは民主的な【ヴァイマル憲法】をもつ共和国が生まれましたが、賠償問題とインフレに苦しみました。1920年代後半には、【ロカルノ条約】や【不戦条約】が結ばれ、国際協調の時代となりました。", "しかし1929年の【世界恐慌】がすべてを変えました。ドイツでは失業者が急増し、【ヒトラー】の率いる【ナチ党】が支持を集めて1933年に政権を握り、全権委任法で独裁体制をつくりました。イタリアではすでに1922年に【ムッソリーニ】のファシスト党が【ローマ進軍】で政権を得ていました。ドイツは国際連盟を脱退し、再軍備を宣言し、ラインラントに進駐しました。イタリアはエチオピアを併合し、スペイン内戦ではドイツ・イタリアがフランコを支援しました。イギリス・フランスは【宥和政策】をとってドイツの要求を受け入れましたが(ミュンヘン会談)、1939年に独ソ不可侵条約を結んだドイツが【ポーランド】に侵攻すると、両国はドイツに宣戦し、【第二次世界大戦】がはじまりました。ドイツはフランスを降伏させ、1941年には【独ソ戦】をはじめましたが、スターリングラードの戦いを転機に後退し、1945年5月に降伏しました。ナチスはユダヤ人などを強制収容所で大量に殺害する【ホロコースト】をおこないました。"]}, {"t": "西アジア・南アジア ― 民族運動の高まり", "p": ["第一次世界大戦でドイツ側についた【オスマン帝国】は敗れ、解体されました。大戦中、イギリスはアラブ人に独立を約束する【フセイン・マクマホン協定】、英仏露で領土の分割を決めた【サイクス・ピコ協定】、ユダヤ人にパレスチナでの民族的郷土の建設を支持する【バルフォア宣言】という、たがいに矛盾する約束をしていました。戦後、シリアはフランス、イラク・パレスチナはイギリスの委任統治領となり、これが現在まで続くパレスチナ問題の起源となりました。", "トルコでは、連合国による分割に抵抗した【ムスタファ=ケマル】がギリシア軍を撃退し、スルタン制を廃止して、1923年に【トルコ共和国】を建てました。彼はローザンヌ条約で新しい国境を認めさせ、カリフ制の廃止、政教分離、ローマ字の採用、女性参政権など、近代化と世俗化の改革を進めました。イランではパフレヴィー朝が成立し、アラビア半島ではイブン=サウードがサウジアラビア王国を建てました。", "インドは大戦でイギリスに協力すれば自治が得られると期待しましたが、戦後イギリスは令状なしの逮捕を認める【ローラット法】で弾圧を強めました。【ガンディー】は【非暴力・不服従】運動を指導して民衆を広く動員し、インド国民会議派は【ネルー】らのもとで1929年に完全独立(【プールナ=スワラージ】)を決議しました。1930年には、ガンディーがイギリスの塩の専売に抗議する【塩の行進】をおこないました。一方、ムスリムの間では全インド=ムスリム連盟がパキスタン建設をめざすようになり、宗教による対立が深まっていきました。"]}, {"t": "東南アジア・東アジア ― 日本の膨張と中国の革命", "p": ["東アジアでは、【日露戦争】(1904〜05年)で日本がロシアに勝ち、アジアの民族運動を勇気づける一方、日本自身が列強の一員として大陸に進出しました。1910年には【韓国併合】をおこない、朝鮮を植民地としました。中国では、1900年の【義和団事件】の敗北後、清が立憲制の準備などの改革をはじめましたが、【孫文】の中国同盟会などの革命運動が広がり、1911年の【辛亥革命】で翌1912年に【中華民国】が成立し、清は滅びました。しかし実権は軍閥の【袁世凱】に握られ、その後も軍閥の割拠が続きました。", "第一次世界大戦中、日本は中国に【二十一か条要求】を突きつけ、山東省のドイツ権益の継承などを認めさせました。パリ講和会議でこれが承認されると、1919年に北京の学生を中心とする【五・四運動】がおこりました。同年、朝鮮では日本からの独立を求める【三・一独立運動】がおこりました。中国では、1921年に中国共産党が結成され、孫文は【中国国民党】を改組して共産党と【第1次国共合作】を結びました。孫文の死後、【蔣介石】は【北伐】を進めましたが、途中で共産党を弾圧し、1928年に中国を統一しました。", "1931年、日本の関東軍は【満州事変】をおこし、翌年に【満州国】を建てました。国際連盟がリットン調査団の報告にもとづいてこれを認めなかったため、日本は国際連盟を脱退しました。共産党は長征で拠点を移し、西安事件を経て、1937年に【日中戦争】がはじまると【第2次国共合作】が成立して抗日民族統一戦線がつくられました。日本は資源を求めて東南アジアに進出し、1941年12月にマレー半島に上陸し、ハワイの真珠湾を攻撃して【太平洋戦争】がはじまりました。", "東南アジアでは、ベトナムで【ホー=チ=ミン】がインドシナ共産党を結成し、インドネシアでは【スカルノ】がインドネシア国民党を率いて民族運動を進めました。タイでは1932年の立憲革命で立憲君主政に移行しました。日本の占領は欧米の植民地支配を打ち破る一方で、資源の収奪や強制労働をともない、現地の人々の抵抗をまねきました。こうした経験が、戦後の独立運動の土台となりました。"]}, {"t": "アメリカ・アフリカ ― アメリカの世紀のはじまり", "p": ["アメリカ合衆国は、20世紀初めにセオドア=ローズヴェルト大統領のもとでカリブ海への進出を強め(【棍棒外交】)、パナマ運河を建設しました。第一次世界大戦では連合国に物資と資金を提供して債務国から【債権国】に転じ、戦後は世界最大の経済大国となりました。1920年代には自動車や家電製品が普及する大衆消費社会が生まれましたが、一方で【移民法】による移民制限や禁酒法など、保守的な傾向も強まりました。", "1929年10月、ニューヨーク株式市場の株価が大暴落して【世界恐慌】がはじまりました。民主党の【フランクリン=ローズヴェルト】大統領は【ニューディール】政策をとり、【テネシー川流域開発公社(TVA)】などの公共事業や、労働者の団結権を認める【ワグナー法】などで経済の立て直しをはかりました。ラテンアメリカに対しては内政干渉をひかえる【善隣外交】をとりました。イギリス・フランスは本国と植民地で排他的な経済圏をつくる【ブロック経済】を進め、植民地の少ない国々との対立が深まりました。ラテンアメリカでは、1910年にはじまった【メキシコ革命】が土地改革などを進めました。", "アフリカは、エチオピアとリベリアを除くほぼ全域が植民地とされていましたが、1936年にはエチオピアもイタリアに併合されました。アメリカ大陸やヨーロッパに住むアフリカ系の人々の間では、アフリカの解放と連帯をめざす【パン=アフリカ会議】が開かれ、戦後の独立運動の思想的な源流となりました。"]}, {"t": "世界のつながり ― 戦争から国際連合へ", "p": ["第二次世界大戦中の1941年、ローズヴェルトとイギリス首相【チャーチル】は【大西洋憲章】を発表し、領土不拡大や民族自決、国際協力などの戦後の原則を示しました。1943年の【カイロ会談】では日本の領土問題が、1945年2月の【ヤルタ会談】では戦後のドイツ処理やソ連の対日参戦が話し合われ、7月の【ポツダム会談】で日本に無条件降伏を求めるポツダム宣言が出されました。8月、アメリカは広島と長崎に原子爆弾を投下し、ソ連が日本に宣戦すると、日本は降伏しました。", "戦争の終わりに向けて、1944年の【ダンバートン=オークス会議】で国際連合憲章の原案がつくられ、1945年の【サンフランシスコ会議】で【国際連合憲章】が採択され、同年10月に国際連合が発足しました。国際連盟の失敗を反省して、大国を常任理事国とする【安全保障理事会】に強い権限を与え、軍事的な制裁も可能としました。経済面では、恐慌とブロック経済が戦争をまねいた反省から、【国際通貨基金(IMF)】や【国際復興開発銀行(世界銀行)】を柱とするブレトン=ウッズ体制がつくられ、ドルを基軸とする国際経済の仕組みが整えられました。", "1900年と1945年を比べると、世界の姿は大きく変わっています。ヨーロッパの列強が世界を分割していた時代は終わりに近づき、アメリカとソ連という2つの超大国が並び立ちました。植民地の人々は独立への意志を強め、戦後まもなく次々と独立を果たしていきます。20世紀前半は、19世紀的な世界が崩れて、20世紀後半の冷戦と脱植民地化の時代を準備した時期だといえます。"]}], "points": ["三国同盟と三国協商の対立→サライェヴォ事件(1914年)→第一次世界大戦", "ロシア革命の流れ:二月革命→十月革命→平和に関する布告→ブレスト=リトフスク条約→ソ連成立(1922年)", "ヴェルサイユ条約の内容と、民族自決が東欧にのみ適用されたこと", "イギリスの矛盾した約束(フセイン・マクマホン協定、サイクス・ピコ協定、バルフォア宣言)とパレスチナ問題", "1919年に同時におこった三・一独立運動と五・四運動", "世界恐慌への対応の違い(ニューディール、ブロック経済、ファシズム、ソ連の五か年計画)", "ムスタファ=ケマルのトルコ共和国(1923年)とガンディーの非暴力・不服従", "大西洋憲章→ヤルタ会談→ダンバートン=オークス会議→サンフランシスコ会議→国際連合"], "check": [["1914年、オーストリア帝位継承者が暗殺された事件は?", "サライェヴォ事件"], ["十月革命を指導し、ソヴィエト政権を樹立した人物は?", "レーニン"], ["パリ講和会議の原則とされた十四か条を発表したアメリカ大統領は?", "ウィルソン"], ["1917年、イギリスがユダヤ人のパレスチナでの民族的郷土建設を支持した宣言は?", "バルフォア宣言"], ["1923年にトルコ共和国を建てた人物は?", "ムスタファ=ケマル"], ["1911年の辛亥革命の翌年に成立した国家は?", "中華民国"], ["1919年に北京の学生を中心におこった反日・反帝国主義運動は?", "五・四運動"], ["世界恐慌に対しフランクリン=ローズヴェルトがおこなった政策は?", "ニューディール"], ["1941年にローズヴェルトとチャーチルが発表した戦後構想は?", "大西洋憲章"], ["1945年に国際連合憲章が採択された会議は?", "サンフランシスコ会議"]], "related": ["y_19", "y_20b", "t_de", "t_ru", "t_uk", "t_fr", "t_it", "t_tr", "t_ps", "t_in", "t_cn", "t_kr", "t_us", "t_la", "j_taisho", "j_showa1", "j_war"], "n": 4740}, "y_20b": {"title": "20世紀後半の世界(1945〜2000年)", "span": "1945〜2000年", "year": 1970, "lead": "20世紀後半は、アメリカを中心とする資本主義陣営とソ連を中心とする社会主義陣営が対立した冷戦の時代であり、同時にアジア・アフリカの植民地が次々と独立した脱植民地化の時代です。冷戦は核兵器による緊張と、朝鮮・ベトナムなどでの「熱い戦争」を生みましたが、1989年の東欧革命と1991年のソ連解体で終わりました。その後の世界は、グローバル化と地域統合、そして民族紛争の時代に入ります。", "flow": ["1947年 トルーマン=ドクトリン・マーシャル=プラン→冷戦の本格化。インド・パキスタンが分離独立", "1948年 ベルリン封鎖、イスラエル建国と第1次中東戦争", "1949年 NATO結成、東西ドイツの分立、中華人民共和国の成立", "1950〜53年 朝鮮戦争→日本の独立回復と日米安全保障条約(1951年)", "1955年 アジア=アフリカ会議(バンドン会議)、ワルシャワ条約機構の成立", "1956年 スターリン批判→ハンガリー事件。スエズ戦争(第2次中東戦争)", "1960年 アフリカの年(17か国が独立)。1962年キューバ危機", "1965年 アメリカの北爆→ベトナム戦争の本格化。1966年中国で文化大革命", "1973年 第1次石油危機→先進国の高度成長が終わる。ベトナム和平協定", "1978年 中国の改革・開放政策。1979年イラン革命、ソ連のアフガニスタン侵攻", "1989年 東欧革命・ベルリンの壁崩壊・マルタ会談→冷戦の終結。中国で天安門事件", "1990年 ドイツ統一。1991年湾岸戦争・ソ連解体。1993年EU発足"], "sync": [["ヨーロッパ", "東西の分断(鉄のカーテン)、マーシャル=プランとコメコン、NATOとワルシャワ条約機構。西欧の統合(ECSC→EEC→EC→EU)。東欧の反ソ運動(ハンガリー事件、プラハの春)。東欧革命(1989年)、ドイツ統一(1990年)、ソ連解体(1991年)、ユーゴスラヴィア内戦"], ["西アジア・北アフリカ", "イスラエル建国(1948年)と4次にわたる中東戦争、PLO。ナセルのスエズ運河国有化。石油危機とOPEC。イラン革命(1979年)、イラン=イラク戦争、湾岸戦争(1991年)。オスロ合意(1993年)"], ["南アジア・東南アジア", "インド・パキスタンの分離独立(1947年)、ネルーの非同盟外交。インドシナ戦争とベトナム戦争、カンボジアのポル=ポト政権。インドネシア独立とスカルノ、ASEAN結成(1967年)、アジアNIES・アジア通貨危機(1997年)"], ["東アジア・内陸アジア", "中華人民共和国成立(1949年)、朝鮮戦争、大躍進と文化大革命、中ソ対立、改革・開放(1978年)と天安門事件(1989年)、香港返還(1997年)。日本の高度経済成長。韓国・台湾の経済成長と民主化"], ["アメリカ・アフリカ", "アメリカの冷戦外交と公民権運動、ベトナム反戦運動。キューバ革命(1959年)とキューバ危機(1962年)。アフリカの年(1960年)、アフリカ統一機構(1963年)、南アフリカのアパルトヘイト撤廃とマンデラ大統領(1994年)"], ["世界のつながり", "国際連合と核軍縮の取り組み(部分的核実験禁止条約、核拡散防止条約)。南北問題。サミット。冷戦後のグローバル化とWTO(1995年)"]], "secs": [{"t": "冷戦と脱植民地化 ― 20世紀後半をどう見るか", "p": ["第二次世界大戦後の世界を理解するカギは、2つの大きな流れです。一つは、アメリカとソ連という2つの超大国が、資本主義と社会主義という体制の違いをかけて対立した【冷戦】です。両国は直接戦うことはありませんでしたが、核兵器の開発を競い、世界中で同盟国をつくり、各地の戦争や内戦に介入しました。もう一つは、アジア・アフリカの植民地が独立を果たし、多数の新しい国家が生まれた【脱植民地化】です。", "この2つの流れは深く結びついています。独立したばかりの国々は、米ソどちらの陣営につくかを迫られ、朝鮮やベトナムのように国が分断されて戦場となる場合もありました。一方、インドやインドネシアなどは、どちらの陣営にも属さない【非同盟】の立場をとり、「第三世界」として発言力を強めました。冷戦の終わりとともに、世界は市場経済を軸とするグローバル化の時代に入っていきます。"]}, {"t": "ヨーロッパとソ連 ― 東西の分断から統合へ", "p": ["大戦後、ソ連は東欧諸国に社会主義政権を成立させ、イギリスの前首相チャーチルはこれを「【鉄のカーテン】」と表現しました。アメリカは1947年に【トルーマン=ドクトリン】でギリシア・トルコへの援助を表明して共産主義の【封じ込め政策】をはじめ、ヨーロッパの経済復興を援助する【マーシャル=プラン】を発表しました。ソ連はこれに対抗して【コミンフォルム】や【経済相互援助会議(コメコン)】をつくりました。ドイツは米英仏ソの4か国に分割占領されていましたが、西側の通貨改革に反発したソ連が1948年に【ベルリン封鎖】をおこない、1949年に【ドイツ連邦共和国(西ドイツ)】と【ドイツ民主共和国(東ドイツ)】が成立して分断が固定しました。同年、西側は【北大西洋条約機構(NATO)】を結成し、1955年に東側は【ワルシャワ条約機構】をつくりました。", "1953年にスターリンが死去すると、【フルシチョフ】は1956年に【スターリン批判】をおこない、西側との【平和共存】を唱えました。しかし、これに刺激されて東欧で自由化を求める動きがおこると、ソ連は【ハンガリー事件】を軍事介入で鎮圧し、1968年にはチェコスロヴァキアの民主化運動「【プラハの春】」もワルシャワ条約機構軍で押しつぶしました。1961年には東ドイツが【ベルリンの壁】を建設し、冷戦の象徴となりました。", "西ヨーロッパでは、戦争をくり返さないために経済統合が進みました。1952年の【ヨーロッパ石炭鉄鋼共同体(ECSC)】にはじまり、1958年のヨーロッパ経済共同体(EEC)を経て、1967年に【ヨーロッパ共同体(EC)】が発足しました。1973年にはイギリスも加盟し、1993年のマーストリヒト条約の発効で【ヨーロッパ連合(EU)】となりました。西ドイツでは【ブラント】首相が東側諸国との関係改善をはかる【東方外交】を進めました。", "1980年代、ソ連は経済の停滞とアフガニスタン侵攻の負担に苦しみ、1986年の【チェルノブイリ】原子力発電所事故は体制の硬直性を明らかにしました。1985年に書記長となった【ゴルバチョフ】は、【ペレストロイカ(改革)】と【グラスノスチ(情報公開)】を進め、【新思考外交】で東欧への干渉をやめました。すると1989年、ポーランドの自主管理労組【連帯】の勝利をはじめとして東欧諸国で共産党政権が次々と倒れ(【東欧革命】)、11月には【ベルリンの壁】が開放されました。同年12月の【マルタ会談】で米ソ首脳が冷戦の終結を宣言し、1990年にドイツが統一され、1991年にはソ連が解体して【独立国家共同体(CIS)】が生まれました。一方、多民族国家だった【ユーゴスラヴィア】では民族対立から激しい内戦がおこりました。"]}, {"t": "東アジア ― 中国の革命と分断された朝鮮", "p": ["中国では、日本の降伏後に国民党と共産党の内戦が再開され、勝利した共産党の【毛沢東】は1949年に【中華人民共和国】の成立を宣言しました。蔣介石の国民党政府は【台湾】に逃れました。翌年、中国はソ連と【中ソ友好同盟相互援助条約】を結びました。朝鮮半島は、日本の植民地支配から解放されたものの、北緯38度線を境に米ソに分割占領され、1948年に南に大韓民国、北に朝鮮民主主義人民共和国が成立しました。1950年、北朝鮮が南に侵攻して【朝鮮戦争】がはじまり、国連軍(主にアメリカ軍)と中国の人民義勇軍が参戦して激戦となりましたが、1953年に【板門店】で休戦協定が結ばれ、分断は固定されました。朝鮮戦争をきっかけに、アメリカは日本を西側陣営の拠点とする方針を強め、1951年に【サンフランシスコ平和条約】と日米安全保障条約が結ばれました。日本は朝鮮戦争の特需をきっかけに復興し、【高度経済成長】をとげました。", "中国では、毛沢東が1958年から【大躍進】政策を進めましたが失敗し、多くの餓死者を出したとされます。スターリン批判以降、ソ連との路線対立が深まり(【中ソ対立】)、1969年には国境の【珍宝島(ダマンスキー島)】で軍事衝突がおこりました。1966年からは毛沢東が権力の回復をめざして【プロレタリア文化大革命】をおこし、紅衛兵による知識人や幹部への迫害で社会は大混乱しました。ソ連との対立は中国をアメリカに接近させ、1971年に中国は国連代表権を得て、1972年には【ニクソン】大統領が訪中しました。毛沢東の死後、【鄧小平】は1978年から【改革・開放政策】をはじめ、市場経済を取り入れて急速な経済成長を実現しました。しかし政治の民主化は認められず、1989年の【天安門事件】では民主化を求める学生や市民が武力で弾圧されました。1997年にはイギリスから【香港】が、1999年にはポルトガルから【マカオ】が返還されました。韓国と台湾は、権威主義的な体制のもとで経済成長をとげ、1980年代後半に民主化を進めました。"]}, {"t": "南アジア・東南アジア ― 独立と戦争", "p": ["インドは1947年に独立しましたが、ヒンドゥー教徒を中心とするインドと、ムスリムを中心とする【パキスタン】に分かれ、その過程で大規模な暴動と難民が生まれ、【ガンディー】も急進的なヒンドゥー教徒に暗殺されました。カシミール地方の帰属をめぐる対立は、現在も続いています。インドの首相【ネルー】は中国の周恩来と【平和五原則】を発表し、1955年にはインドネシアの【スカルノ】らとともに【アジア=アフリカ会議(バンドン会議)】を開き、反植民地主義と平和共存を訴えました。1961年には、ユーゴスラヴィアの【ティトー】らを中心に第1回非同盟諸国首脳会議が開かれました。", "ベトナムでは、1945年に【ホー=チ=ミン】がベトナム民主共和国の独立を宣言しましたが、復帰をはかるフランスとの【インドシナ戦争】がおこりました。1954年の【ディエンビエンフーの戦い】でフランスは敗れ、【ジュネーヴ休戦協定】で北緯17度線を暫定的な境界としました。しかしアメリカは共産主義の拡大をおそれて南のベトナム共和国を支援し、南では【南ベトナム解放民族戦線】が抵抗しました。1964年の【トンキン湾事件】を口実に、アメリカは1965年から北ベトナムへの爆撃(北爆)と大規模な地上軍の派遣をおこない、【ベトナム戦争】が本格化しました。戦争は長期化し、世界中で反戦運動がおこり、1973年の【ベトナム(パリ)和平協定】でアメリカ軍は撤退しました。1975年にサイゴンが陥落し、1976年に南北統一が実現しました。カンボジアでは【ポル=ポト】政権が多くの国民を虐殺しました。", "インドネシアでは、オランダとの戦争を経て独立が実現し、スカルノが指導しましたが、1965年の【九・三〇事件】をきっかけに軍の【スハルト】が実権を握り、開発独裁を進めました。1967年には反共的な立場から【東南アジア諸国連合(ASEAN)】が結成され、のちに地域協力の機構へと発展しました。1970年代以降、韓国・台湾・香港・シンガポールは【アジアNIES】とよばれる急成長をとげ、東南アジアにも工業化が広がりましたが、1997年には【アジア通貨危機】がおこりました。"]}, {"t": "西アジア・アフリカ ― 中東問題と「アフリカの年」", "p": ["パレスチナでは、国連のパレスチナ分割案をもとに1948年に【イスラエル】が建国を宣言し、これに反対するアラブ諸国との【第1次中東戦争(パレスチナ戦争)】がおこりました。イスラエルが勝利し、多くのパレスチナ人が難民となりました。エジプトでは、王政を倒した【ナセル】が1956年に【スエズ運河の国有化】を宣言すると、イギリス・フランス・イスラエルが侵攻して【第2次中東戦争(スエズ戦争)】がおこりましたが、米ソや国連の圧力で3国は撤退し、ナセルはアラブ民族主義の英雄となりました。1967年の【第3次中東戦争(6日戦争)】でイスラエルはシナイ半島・ガザ地区・ヨルダン川西岸などを占領しました。1973年の【第4次中東戦争】では、アラブの産油国が石油を武器とする戦略をとり、【第1次石油危機(オイル=ショック)】がおこって、先進国の高度経済成長は終わりを告げました。その後、【キャンプ=デーヴィッド合意】でエジプトとイスラエルは和解し、1993年にはイスラエルと【パレスチナ解放機構(PLO)】が【パレスチナ暫定自治協定(オスロ合意)】を結びましたが、和平はその後も困難が続いています。", "イランでは、1950年代にモサッデグ首相の石油国有化が挫折したのち、国王の上からの近代化(白色革命)が進められましたが、1979年に【ホメイニ】の指導する【イラン革命(イスラーム革命)】で王政が倒れ、イスラーム共和国が成立しました。これは第2次石油危機をまねき、翌年には【イラン=イラク戦争】がはじまりました。1990年にはイラクがクウェートに侵攻し、1991年にアメリカ中心の多国籍軍がイラクを攻撃する【湾岸戦争】がおこりました。", "アフリカでは、1957年に【ガーナ】が【エンクルマ】の指導で独立し、1960年には17か国が独立して「【アフリカの年】」とよばれました。1963年には【アフリカ統一機構(OAU)】が結成されました。アルジェリアはフランスとの激しい戦争の末に1962年に独立しました。しかし、植民地時代に引かれた国境は民族の分布と一致せず、独立後の【コンゴ動乱】のように内戦や紛争が続き、モノカルチャー経済からの脱却も困難でした。南アフリカでは白人政権による人種隔離政策【アパルトヘイト】が続きましたが、国際的な非難と国内の抵抗を受けて1991年に撤廃され、1994年には長く投獄されていた【マンデラ】が黒人として初めて大統領に就任しました。"]}, {"t": "アメリカ大陸と世界のつながり ― 核の時代と南北問題", "p": ["アメリカでは、冷戦下で共産主義者を排除する【赤狩り(マッカーシズム)】が広がりました。1950〜60年代には、【キング牧師】らの指導で黒人差別の撤廃を求める【公民権運動】が高まり、1964年に【公民権法】が成立しました。ベトナム戦争の泥沼化は国内を分裂させ、【ニクソン】大統領は1971年にドルと金の交換停止を発表し、ドルを中心とした戦後の国際通貨体制はゆらぎました。ラテンアメリカでは、1959年に【カストロ】らが【キューバ革命】をおこし、キューバはやがて社会主義を宣言しました。1962年、ソ連がキューバにミサイル基地を建設していることが明らかになると、【ケネディ】大統領は海上封鎖をおこない、核戦争の寸前まで緊張が高まりました(【キューバ危機】)。ソ連がミサイルを撤去して危機は回避され、米ソは直通通信回線を設けました。", "キューバ危機の教訓から、核軍縮の取り組みが進みました。1963年の【部分的核実験禁止条約】、1968年の【核拡散防止条約(NPT)】、1970年代の【戦略兵器制限交渉(SALT)】、1987年の【中距離核戦力(INF)全廃条約】などです。1970年代には米ソの緊張が緩和し(デタント)、1975年には【全欧安全保障協力会議(CSCE)】が開かれました。経済面では、先進工業国と発展途上国の経済格差である【南北問題】が国際的な課題となり、石油危機後には先進国が【先進国首脳会議(サミット)】で経済政策を調整するようになりました。1980年代には、イギリスの【サッチャー】やアメリカの【レーガン】が、政府の役割を小さくして市場を重んじる新自由主義的な政策をとりました。", "冷戦が終わると、旧社会主義国も市場経済に加わり、1995年には【世界貿易機関(WTO)】が発足して、ヒト・モノ・カネ・情報が国境をこえて行き来する【グローバル化】が急速に進みました。一方で、冷戦の重しがなくなったことで、ユーゴスラヴィアやアフリカなどでは民族や宗教の対立による紛争が表面化しました。20世紀の終わりの世界は、統合と分裂という2つの方向が同時に進む、21世紀の課題を先取りした姿を見せていたのです。"]}], "points": ["冷戦の形成:トルーマン=ドクトリン・マーシャル=プラン(1947年)→ベルリン封鎖(1948年)→NATOと東西ドイツ(1949年)→ワルシャワ条約機構(1955年)", "1949年の中華人民共和国成立と朝鮮戦争(1950〜53年)、日本の独立回復との関係", "アジア=アフリカ会議(1955年)と平和五原則、非同盟諸国首脳会議", "4次にわたる中東戦争と、第4次中東戦争→第1次石油危機(1973年)", "ベトナム:インドシナ戦争→ジュネーヴ休戦協定(1954年)→トンキン湾事件・北爆→パリ和平協定(1973年)→統一(1976年)", "キューバ危機(1962年)後の核軍縮条約の順序(部分的核実験禁止条約→NPT→SALT→INF全廃条約)", "中国:大躍進→中ソ対立→文化大革命→ニクソン訪中→改革・開放(1978年)→天安門事件(1989年)", "冷戦の終結:ゴルバチョフの改革→東欧革命・マルタ会談(1989年)→ドイツ統一(1990年)→ソ連解体(1991年)"], "check": [["1947年にアメリカが発表した、共産主義の封じ込めを表明した宣言は?", "トルーマン=ドクトリン"], ["1949年に西側諸国が結成した軍事同盟は?", "北大西洋条約機構(NATO)"], ["1955年にインドネシアで開かれた、反植民地主義と平和共存を訴えた会議は?", "アジア=アフリカ会議(バンドン会議)"], ["1956年にスエズ運河の国有化を宣言したエジプトの大統領は?", "ナセル"], ["17か国のアフリカの国が独立した1960年はなんとよばれるか?", "アフリカの年"], ["1962年、ソ連のミサイル基地建設をめぐって米ソが核戦争の危機に直面した事件は?", "キューバ危機"], ["1978年に中国で鄧小平が開始した政策は?", "改革・開放政策"], ["1979年にイランで王政を倒した革命の指導者は?", "ホメイニ"], ["1989年12月、米ソ首脳が冷戦の終結を宣言した会談は?", "マルタ会談"], ["1994年に南アフリカで黒人初の大統領となった人物は?", "マンデラ"]], "related": ["y_20a", "y_21", "t_us", "t_ru", "t_de", "t_cn", "t_kr", "t_vn", "t_in", "t_ps", "t_ir", "t_af", "t_la", "j_occ", "j_growth", "j_modern"], "n": 5187}, "y_21": {"title": "21世紀の世界", "span": "2001年〜現在", "year": 2010, "lead": "21世紀は、冷戦後に進んだグローバル化がさらに深まる一方で、その矛盾がさまざまな形であらわれている時代です。同時多発テロにはじまる「テロとの戦い」、世界金融危機、中国など新興国の台頭、アラブの春と中東の混乱、ロシアのウクライナ侵攻、気候変動や感染症といった地球規模の課題が、世界の各地域をかつてないほど強く結びつけています。", "flow": ["2001年 アメリカで同時多発テロ事件→アフガニスタン攻撃。同年中国がWTOに加盟", "2002年 ユーロの現金流通がはじまる。アフリカ連合(AU)が発足", "2003年 イラク戦争→フセイン政権の崩壊、その後の混乱", "2004年 EUが中・東欧諸国などに拡大", "2008年 世界金融危機(リーマン=ショック)→G20首脳会議の開始", "2010〜11年 アラブの春→チュニジア・エジプトなどで長期政権が倒れ、シリアは内戦へ", "2011年 東日本大震災と福島第一原子力発電所事故", "2014年 ロシアがクリミアを併合", "2015年 国連でSDGs(持続可能な開発目標)採択、気候変動に関するパリ協定", "2020年 イギリスがEUを離脱。新型コロナウイルス感染症の世界的流行", "2022年 ロシアがウクライナに侵攻→国際秩序とエネルギー・食料市場に大きな影響"], "sync": [["ヨーロッパ", "ユーロの流通(2002年)とEUの東方拡大(2004年)、ユーロ危機、難民問題、イギリスのEU離脱(2020年)。ロシアのクリミア併合(2014年)とウクライナ侵攻(2022年)"], ["西アジア・北アフリカ", "アフガニスタン攻撃(2001年)とイラク戦争(2003年)。アラブの春(2010〜11年)とシリア内戦、過激派組織の台頭、大量の難民。パレスチナ問題の継続"], ["南アジア・東南アジア", "インドの経済成長と人口大国化。ASEAN共同体の発足(2015年)と東南アジアの経済成長。ミャンマーの民政移管とその後の軍事クーデタ(2021年)"], ["東アジア・内陸アジア", "中国のWTO加盟(2001年)と経済大国化、北京オリンピック(2008年)、一帯一路構想。香港の民主化運動と統制強化。北朝鮮の核・ミサイル開発。日本の東日本大震災(2011年)"], ["アメリカ・アフリカ", "アメリカの「テロとの戦い」、オバマ政権(初の黒人大統領)、世界金融危機。ラテンアメリカの左派政権の拡大。アフリカ連合の発足と資源をめぐる経済成長、南スーダンの独立(2011年)"], ["世界のつながり", "インターネットとSNSの普及、G20の役割拡大、新興国(BRICS)の台頭。気候変動(パリ協定)、SDGs、感染症の世界的流行"]], "secs": [{"t": "グローバル化の光と影 ― 21世紀をどう見るか", "p": ["冷戦が終わった1990年代、多くの人は、市場経済と民主主義が世界中に広がり、平和で豊かな時代が来ると期待しました。実際、21世紀に入ると、インターネットや携帯電話、のちにはスマートフォンとSNSが急速に普及し、情報は瞬時に世界中を駆けめぐるようになりました。企業は国境をこえて生産と販売の拠点を配置し、中国やインドなどの新興国は世界経済の成長のエンジンとなりました。", "しかし、グローバル化はさまざまな影も生みました。一つは、国と国の間、また一国の内部での経済格差の拡大です。もう一つは、ヒト・モノ・カネが自由に動くことで、金融危機やテロ、感染症などの危険も国境をこえて一気に広がるようになったことです。さらに、グローバル化に取り残されたと感じる人々の不満は、移民や自由貿易への反発、自国第一主義の主張として各国の政治に影響を与えています。21世紀の世界史は、統合へ向かう力と分断へ向かう力のせめぎ合いとして見ると理解しやすくなります。なお、この時代はまだ評価が定まっていない「現在進行形の歴史」であることにも注意しましょう。"]}, {"t": "テロとの戦いと中東の混乱", "p": ["2001年9月11日、イスラーム過激派組織アル=カーイダのメンバーが旅客機を乗っ取り、ニューヨークの世界貿易センタービルなどに突入する【同時多発テロ事件】がおこりました。アメリカのブッシュ(子)政権は「テロとの戦い」をかかげ、アル=カーイダをかくまっていたとしてアフガニスタンのターリバーン政権を攻撃して崩壊させました。さらに2003年には、大量破壊兵器を保有しているとして、国連安全保障理事会の明確な承認がないままイギリスとともに【イラク戦争】をおこし、サダム=フセイン政権を倒しました。しかし大量破壊兵器は見つからず、イラクではその後も宗派対立とテロが続き、アメリカの単独行動主義は国際的な批判を受けました。", "2010年末、チュニジアで青年の焼身自殺をきっかけに反政府デモが広がり、長期政権が倒れました。この動きはSNSを通じて各地に伝わり、エジプトのムバーラク政権やリビアのカダフィ政権も崩壊しました。これを【アラブの春】とよびます。しかし多くの国で民主化は定着せず、とくに【シリア】では政府と反政府勢力の内戦が泥沼化し、周辺国やロシア・アメリカなども関与しました。混乱のなかで過激派組織「イスラム国(IS)」が一時イラクとシリアの広い地域を支配し、大量の難民がヨーロッパに向かいました。パレスチナ問題も解決の見通しが立たず、イスラエルとパレスチナの武力衝突がくり返されています。中東の混乱は、20世紀前半の列強による国境線の画定や、冷戦期の大国の介入、石油資源をめぐる利害など、長い歴史的背景をもっていることを理解しておきましょう。"]}, {"t": "ヨーロッパとロシア ― 統合の深化と新たな対立", "p": ["ヨーロッパでは、1999年に導入された共通通貨【ユーロ】の現金の流通が2002年にはじまり、2004年には旧社会主義国だったポーランドやバルト3国などの中・東欧諸国を中心に10か国がEUに加盟しました(【EUの東方拡大】)。冷戦期に東西に分かれていたヨーロッパは、一つの経済圏へと統合が進みました。しかし、2009年ごろからギリシアの財政危機をきっかけに【ユーロ危機】がおこり、通貨は共通でも財政は各国ばらばらという統合の弱点が明らかになりました。2015年ごろには中東などからの難民が大量に流入し、受け入れをめぐって加盟国の対立が深まりました。", "こうしたなかで、移民の増加やEUの規制への不満が強まったイギリスでは、2016年の国民投票でEU離脱派が多数をしめ、2020年に【イギリスのEU離脱】が実現しました。これはヨーロッパ統合の歴史で初めて加盟国が去る事態でした。", "ロシアでは、2000年に大統領となった【プーチン】のもとで、石油・天然ガスの輸出による経済の回復と、中央集権的な体制の強化が進みました。ロシアはNATOの東方拡大に強く反発し、2014年にはウクライナの政変をきっかけに【クリミア】を併合しました。さらに2022年、ロシアは【ウクライナ侵攻】をおこない、第二次世界大戦後のヨーロッパで最大規模の戦争となりました。欧米諸国はロシアに経済制裁を科し、ウクライナを軍事的に支援しました。この戦争は、エネルギーや穀物の価格上昇を通じて世界中の人々の生活に影響を与え、フィンランドなどがNATOに加盟するなど、ヨーロッパの安全保障の構図を大きく変えています。"]}, {"t": "アジア ― 中国の台頭と多極化", "p": ["21世紀の世界でもっとも大きな変化の一つが、【中国】の台頭です。改革・開放政策を進めた中国は、2001年に【世界貿易機関(WTO)】に加盟し、「世界の工場」として輸出を急増させました。2008年には北京オリンピックを開催し、2010年ごろには国内総生産(GDP)で日本を抜いて世界第2位の経済大国となりました。習近平政権は、アジアからヨーロッパ・アフリカに至る経済圏をつくる【一帯一路】構想をかかげ、各国のインフラ建設に資金を提供して影響力を広げています。その一方で、南シナ海での海洋進出、香港での民主化運動への統制強化、新疆ウイグル自治区での人権問題などが国際的な批判を受け、アメリカとの対立が深まっています。", "インドも情報技術(IT)産業などで経済成長をとげ、人口は中国に並ぶ規模となり、国際社会での発言力を強めています。東南アジアでは、ASEANが2015年に経済統合を進める【ASEAN共同体】を発足させ、多くの国が製造業の拠点として成長しました。ミャンマーではアウン=サン=スー=チーの率いる勢力による民政が実現しましたが、2021年に軍がクーデタをおこしました。朝鮮半島では北朝鮮が核実験とミサイル開発を続け、東アジアの安全保障上の大きな課題となっています。日本では2011年に【東日本大震災】がおこり、原子力発電所の事故はエネルギー政策を見直すきっかけとなりました。", "こうした新興国の台頭によって、世界はアメリカ一国が突出した状態から、複数の大国が並び立つ【多極化】の方向に進んでいるといわれます。ブラジル・ロシア・インド・中国・南アフリカの頭文字をとった【BRICS】は、新興国の連携の場として注目されています。"]}, {"t": "アメリカ・アフリカ・ラテンアメリカ", "p": ["アメリカ合衆国では、2008年に住宅ローン(サブプライムローン)の焦げつきから大手証券会社リーマン=ブラザーズが破綻し、【世界金融危機(リーマン=ショック)】がおこりました。危機は瞬く間に世界中に広がり、各国の景気が急激に悪化しました。この対策を話し合うため、先進国に新興国を加えた【G20(20か国・地域)首脳会議】が開かれるようになり、世界経済の運営に新興国の参加が欠かせなくなったことを示しました。同じ年の大統領選挙では、【オバマ】がアフリカ系として初めて大統領に選ばれました。その後、2016年の選挙では「アメリカ第一」をかかげるトランプが当選し、国内の分断の深まりが注目されました。", "アフリカでは、2002年にアフリカ統一機構を発展させた【アフリカ連合(AU)】が発足しました。資源価格の上昇などにより経済成長する国が増え、2011年にはスーダンから【南スーダン】が独立しました。しかし、内戦や貧困、感染症などの課題は今も多く残っています。ラテンアメリカでは、2000年代に貧困層の支持を受けた左派政権がベネズエラ・ブラジル・ボリビアなどで相次いで誕生し、アメリカの影響力から距離をとる動きを見せました。2015年にはアメリカとキューバが国交を回復しています。"]}, {"t": "技術と社会の変化 ― 情報革命の時代", "p": ["21世紀の社会を大きく変えたのは、情報通信技術の急速な発達です。2000年代後半からスマートフォンが普及すると、世界中の人々がいつでもインターネットにつながるようになり、SNSを通じて個人が直接情報を発信できるようになりました。アラブの春で人々がSNSを使ってデモを呼びかけたように、情報技術は政治の動きにも大きな影響を与えています。一方で、誤った情報や意図的な偽情報が短時間で広がる問題、巨大なIT企業への富と情報の集中、個人情報の保護といった新しい課題も生まれました。", "近年では、人工知能(AI)の発達が産業や働き方を変えつつあります。こうした技術の変化は、18〜19世紀の産業革命が人々の暮らしと世界の力関係を大きく変えたことと比べられることがあります。産業革命が工業国と農業・原料生産地域との格差を生んだように、情報技術を使いこなせるかどうかによる格差(デジタル=デバイド)も課題となっています。技術の進歩がどのような社会をつくるのかは、これからの世界の大きな問いの一つです。"]}, {"t": "世界のつながり ― 地球規模の課題", "p": ["21世紀には、一つの国だけでは解決できない地球規模の課題がますます重要になっています。その代表が気候変動です。1997年の京都議定書に続き、2015年には【パリ協定】が採択され、先進国だけでなく発展途上国も含むすべての国が温室効果ガスの削減目標を立てることになりました。同じ2015年、国連は貧困・飢餓・教育・ジェンダー平等・環境など17の目標からなる【持続可能な開発目標(SDGs)】を採択しました。", "2020年には【新型コロナウイルス感染症】が世界的に流行(パンデミック)しました。各国が国境を閉ざし、人の移動が止まったことで、グローバルな生産と物流の網がいかに世界の生活を支えていたかが明らかになりました。ワクチンの開発と配分をめぐっては、先進国と発展途上国の格差も問題となりました。14世紀の黒死病や16世紀のアメリカ大陸での疫病のように、交流の拡大が感染症の拡大を招くという構図は、歴史のなかでくり返されてきたものです。", "21世紀の世界を横に並べて見ると、どの地域のできごとも他の地域と深くつながっていることがわかります。アメリカの金融危機がヨーロッパとアジアの景気を落ちこませ、中東の内戦がヨーロッパの政治を動かし、ウクライナの戦争がアフリカの食料価格を押し上げます。過去の世紀で学んだ交易・移民・宗教・技術・疫病の広がりという視点は、今の世界を理解するうえでもそのまま役に立つのです。"]}], "points": ["同時多発テロ事件(2001年)→アフガニスタン攻撃→イラク戦争(2003年)の流れと、アメリカの単独行動主義への批判", "EUの深化と拡大(ユーロ流通2002年、東方拡大2004年)と、ユーロ危機・イギリスのEU離脱(国民投票2016年、離脱2020年)", "世界金融危機(2008年)とG20の役割拡大", "アラブの春(2010〜11年)とシリア内戦、難民問題", "中国のWTO加盟(2001年)と経済大国化、一帯一路", "ロシアのクリミア併合(2014年)とウクライナ侵攻(2022年)", "パリ協定とSDGs(ともに2015年)など地球規模の課題への取り組み", "情報通信技術の発達と、新興国(BRICS)の台頭による世界の多極化"], "check": [["2001年9月11日にアメリカでおこった事件は?", "同時多発テロ事件"], ["2003年にアメリカ・イギリスがフセイン政権を倒した戦争は?", "イラク戦争"], ["2002年に現金の流通がはじまったEUの共通通貨は?", "ユーロ"], ["2008年、リーマン=ブラザーズの破綻をきっかけにおこった危機は?", "世界金融危機(リーマン=ショック)"], ["2010年末からチュニジアを起点に広がった中東・北アフリカの民主化運動は?", "アラブの春"], ["2014年にロシアが併合したウクライナ南部の半島は?", "クリミア半島"], ["2015年に採択された、気候変動対策の国際的な枠組みは?", "パリ協定"], ["2015年に国連で採択された17の目標からなる国際目標は?", "持続可能な開発目標(SDGs)"], ["2002年にアフリカ統一機構を発展させて発足した組織は?", "アフリカ連合(AU)"], ["2001年にWTOに加盟し、その後世界第2位の経済大国となった国は?", "中国"]], "related": ["y_20b", "t_us", "t_ru", "t_cn", "t_ps", "t_ar", "t_uk", "t_af", "t_in", "j_modern"], "n": 4097}});
